INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの上に広がっておおうこと。", "primary_collocate": null, "pronunciation": "おおう", "ipa": "oːɯ", "syllable_count": 3, "sentences": [{"text": "荷物が濡れないように、シートで覆った。", "target_word": "覆った", "complexity_tier": "T3", "furigana": "荷物[にもつ]が濡[ぬ]れないように、シートで覆[おお]った。", "sentence_source": "generated"}, {"text": "空を覆う黒い雲から、大粒の雨が降り出した。", "target_word": "覆う", "complexity_tier": "T3", "furigana": "空[そら]を覆[おお]う黒[くろ]い雲[くも]から、大粒[おおつぶ]の雨[あめ]が降[ふ]り出[だ]した。", "sentence_source": "generated"}, {"text": "池の水面を、蓮の葉が覆っている。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "池[いけ]の水面[すいめん]を、蓮[はす]の葉[は]が覆[おお]っている。", "sentence_source": "generated"}, {"text": "畑に霜が降りないよう、わらで覆っておいた。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "畑[はたけ]に霜[しも]が降[お]りないよう、わらで覆[おお]っておいた。", "sentence_source": "generated"}, {"text": "砂ぼこりが車の窓を覆って、前が見えにくい。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "砂[すな]ぼこりが車[くるま]の窓[まど]を覆[おお]って、前[まえ]が見[み]えにくい。", "sentence_source": "generated"}, {"text": "山の斜面は、一面の花に覆われていた。", "target_word": "覆わ", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]は、一面[いちめん]の花[はな]に覆[おお]われていた。", "sentence_source": "generated"}, {"text": "泥が足元を覆い、靴が重くなった。", "target_word": "覆い", "complexity_tier": "T3", "furigana": "泥[どろ]が足元[あしもと]を覆[おお]い、靴[くつ]が重[おも]くなった。", "sentence_source": "generated"}, {"text": "煙が部屋を覆ってきたので、急いで窓を開けた。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "煙[けむり]が部屋[へや]を覆[おお]ってきたので、急[いそ]いで窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "傷口をガーゼで覆うと、痛みが少し和らいだ。", "target_word": "覆う", "complexity_tier": "T3", "furigana": "傷口[きずぐち]をガーゼで覆[おお]うと、痛[いた]みが少[すこ]し和[やわ]らいだ。", "sentence_source": "generated"}, {"text": "新雪が屋根を覆い、家は白い帽子をかぶったようだ。", "target_word": "覆い", "complexity_tier": "T3", "furigana": "新雪[しんせつ]が屋根[やね]を覆[おお]い、家[いえ]は白[しろ]い帽子[ぼうし]をかぶったようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆う", "label": "終止形"}, {"form": "覆わ", "label": "未然形"}, {"form": "覆い", "label": "連用形"}, {"form": "覆って", "label": "て形"}, {"form": "覆った", "label": "た形"}], "register": "標準", "sense_fingerprint": "ものの上に何かを広げたり、広がったりしてかぶせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 砂ぼこり (Zipf 1.59)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覆った", "is_correct": true, "explanation": "た形。「シートで覆った」で、過去の完了を表す。"}, {"text": "覆い", "is_correct": false, "explanation": "連用形。「シートで覆い。」と文を終えられない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。「シートで覆わ。」は成り立たない。"}, {"text": "覆わせ", "is_correct": false, "explanation": "使役形の連用形で、文を終えられない。「シートで覆わせ。」は成り立たない。"}], "explanations": {"覆った": "た形。「シートで覆った」で、過去の完了を表す。", "覆い": "連用形。「シートで覆い。」と文を終えられない。", "覆わ": "未然形。「シートで覆わ。」は成り立たない。", "覆わせ": "使役形の連用形で、文を終えられない。「シートで覆わせ。」は成り立たない。"}, "sentence_index": 0, "correct_answer": "覆った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はすぐに悩みを覆った。", "explanation": "ここは〈解決する〉の意味。悩みを片づける動作は解決するで、覆うは物の面をおおう動作。"}, {"text": "靴ひもを覆った。", "explanation": "ここは〈ほどく〉の意味。結んだひもを解く動作は覆うでは表せない。"}, {"text": "急須にお茶を覆った。", "explanation": "ここは〈注ぐ〉の意味。容器に液体を入れる動作は注ぐで、覆うは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覆い", "is_correct": true, "explanation": "連用形。「足元を覆い、」と後ろに続ける形。"}, {"text": "覆う", "is_correct": false, "explanation": "終止形。「覆う、」と続けられない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。「覆わ、」は文として続かない。"}, {"text": "覆おう", "is_correct": false, "explanation": "意志形。「覆おう、」は続かない。"}], "explanations": {"覆い": "連用形。「足元を覆い、」と後ろに続ける形。", "覆う": "終止形。「覆う、」と続けられない。", "覆わ": "未然形。「覆わ、」は文として続かない。", "覆おう": "意志形。「覆おう、」は続かない。"}, "sentence_index": 6, "correct_answer": "覆い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一時間を覆った。", "explanation": "ここは〈費やす〉の意味。時間を使う動作は費やすで、覆うは面をおおう動作。"}, {"text": "子どもの機嫌を覆った。", "explanation": "ここは〈直す〉の意味。機嫌を元に戻す動作は直すで、覆うは面をおおう動作。"}, {"text": "ちぎった紙を細かく覆った。", "explanation": "ここは〈ちぎる〉の意味。手で紙を裂く動作は覆うでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓をシートで覆うた。", "corrected_sentence": "窓をシートで覆った。", "error_description": "た形の誤り。五段動詞「覆う」の過去形は「覆った」で、「覆うた」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覆う", "is_correct": true, "explanation": "連体形。名詞「雲」を修飾する形で、この文の正解。"}, {"text": "覆って", "is_correct": false, "explanation": "て形。名詞を修飾する形にはならない。"}, {"text": "覆おう", "is_correct": false, "explanation": "意志形。名詞「雲」を直接修飾できず、「空を覆おう黒い雲」は成り立たない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。名詞を直接修飾できない。"}], "correct_form": "覆う", "base_form": "覆う", "form_label": "連体形", "sentence_index": 1, "explanations": {"覆う": "連体形。名詞「雲」を修飾する形で、この文の正解。", "覆って": "て形。名詞を修飾する形にはならない。", "覆おう": "意志形。名詞「雲」を直接修飾できず、「空を覆おう黒い雲」は成り立たない。", "覆わ": "未然形。名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨雲が町に覆っている。", "corrected_sentence": "雨雲が町を覆っている。", "error_description": "助詞の誤り。「覆う」は目的語に「を」を取る。「町に覆う」は誤りで、「町を覆う」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覆って", "is_correct": true, "explanation": "て形。「覆ってきた」の形で、この文の正解。"}, {"text": "覆う", "is_correct": false, "explanation": "終止形。「覆うてきた」とは続かない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。「覆わてきた」は誤り。"}, {"text": "覆い", "is_correct": false, "explanation": "連用形。「覆いてきた」とは続かない。"}], "correct_form": "覆って", "base_form": "覆う", "form_label": "て形", "sentence_index": 7, "explanations": {"覆って": "て形。「覆ってきた」の形で、この文の正解。", "覆う": "終止形。「覆うてきた」とは続かない。", "覆わ": "未然形。「覆わてきた」は誤り。", "覆い": "連用形。「覆いてきた」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
