INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52406, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "表面をすっかりおおうこと。全体に広がって上からおおう。", "primary_collocate": null, "pronunciation": "おおう", "ipa": "oːɯ", "syllable_count": 3, "sentences": [{"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "覆わ", "complexity_tier": "T3", "furigana": "しかし、窓辺[まどべ]に佇[たたず]む幼[おさな]き我[わ]が子[こ]の瞳[ひとみ]は、白銀[はくぎん]に覆[おお]われた庭先[にわさき]へと注[そそ]がれ、抑[おさ]えきれない生命[せいめい]の衝動[しょうどう]に駆[か]られていた。", "sentence_source": "mined"}, {"text": "雪が畑の全体をすっかり覆っていた。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "雪[ゆき]が畑[はたけ]の全体[ぜんたい]をすっかり覆[おお]っていた。", "sentence_source": "generated"}, {"text": "厚い雲が空を覆って、昼なのに暗くなった。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "厚[あつ]い雲[くも]が空[そら]を覆[おお]って、昼[ひる]なのに暗[くら]くなった。", "sentence_source": "generated"}, {"text": "机の上を白い布ですっかり覆った。", "target_word": "覆った", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]を白[しろ]い布[ぬの]ですっかり覆[おお]った。", "sentence_source": "generated"}, {"text": "霧が谷をすっかり覆い、何も見えない。", "target_word": "覆い", "complexity_tier": "T3", "furigana": "霧[きり]が谷[たに]をすっかり覆[おお]い、何[なに]も見[み]えない。", "sentence_source": "generated"}, {"text": "地面は一面の落ち葉に覆われていた。", "target_word": "覆わ", "complexity_tier": "T3", "furigana": "地面[じめん]は一面[いちめん]の落[お]ち葉[ば]に覆[おお]われていた。", "sentence_source": "generated"}, {"text": "灰が町全体を覆う前に、人々は避難した。", "target_word": "覆う", "complexity_tier": "T3", "furigana": "灰[はい]が町[まち]全体[ぜんたい]を覆[おお]う前[まえ]に、人々[ひとびと]は避難[ひなん]した。", "sentence_source": "generated"}, {"text": "緑のつたが古い壁をすっかり覆っている。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "緑[みどり]のつたが古[ふる]い壁[かべ]をすっかり覆[おお]っている。", "sentence_source": "generated"}, {"text": "顔を両手で覆って、彼は泣き出した。", "target_word": "覆って", "complexity_tier": "T3", "furigana": "顔[かお]を両手[りょうて]で覆[おお]って、彼[かれ]は泣[な]き出[だ]した。", "sentence_source": "generated"}, {"text": "夜になると、闇が森全体を覆う。", "target_word": "覆う", "complexity_tier": "T3", "furigana": "夜[よる]になると、闇[やみ]が森[もり]全体[ぜんたい]を覆[おお]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆う", "label": "終止形"}, {"form": "覆わ", "label": "未然形"}, {"form": "覆い", "label": "連用形"}, {"form": "覆って", "label": "て形"}, {"form": "覆った", "label": "た形"}], "register": "標準", "sense_fingerprint": "表面の全体をすっかり上から隠すように広がっておおう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 窓辺 (Zipf 2.97), 佇む (Zipf 2.76), 幼き (Zipf 2.71), 白銀 (Zipf 3.03), 庭先 (Zipf 2.68)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52406, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覆わ", "is_correct": true, "explanation": "れる（受身）の前に来る未然形。「白銀に覆われた」で正しい。"}, {"text": "覆い", "is_correct": false, "explanation": "連用形。「覆いれた」とは続かず、受身の文が成り立たない。"}, {"text": "覆う", "is_correct": false, "explanation": "終止形。「覆うれた」とは続かず、受身の形を作れない。"}, {"text": "覆った", "is_correct": false, "explanation": "た形。「覆ったれた」となり、受身の形にならない。"}], "explanations": {"覆わ": "れる（受身）の前に来る未然形。「白銀に覆われた」で正しい。", "覆い": "連用形。「覆いれた」とは続かず、受身の文が成り立たない。", "覆う": "終止形。「覆うれた」とは続かず、受身の形を作れない。", "覆った": "た形。「覆ったれた」となり、受身の形にならない。"}, "sentence_index": 0, "correct_answer": "覆わ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "帽子を覆って出かけた。", "explanation": "ここは〈被る〉の意味。頭にかぶるものには被るを使い、覆うは面を広く上からおおうときに使う。"}, {"text": "裁判所が一審の判決を覆った。", "explanation": "ここは〈覆す〉（くつがえす）の意味。判決をひっくり返すのは覆すで、覆うは物の表面をおおうこと。"}, {"text": "コーヒーで眠気を覆った。", "explanation": "ここは〈払う〉の意味。眠気を追い払う動作は払うで、覆うは面をおおう動作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52406, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覆う", "is_correct": true, "explanation": "終止形。「覆う前に」で、時を表す節の述語として正しい。"}, {"text": "覆い", "is_correct": false, "explanation": "連用形。「覆い前に」とは続けられない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。「覆わ前に」は文として成り立たない。"}, {"text": "覆って", "is_correct": false, "explanation": "て形。「覆って前に」とは続かない。"}], "explanations": {"覆う": "終止形。「覆う前に」で、時を表す節の述語として正しい。", "覆い": "連用形。「覆い前に」とは続けられない。", "覆わ": "未然形。「覆わ前に」は文として成り立たない。", "覆って": "て形。「覆って前に」とは続かない。"}, "sentence_index": 6, "correct_answer": "覆う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ハンカチで額の汗を覆った。", "explanation": "ここは〈ぬぐう〉の意味。汗を拭き取る動作には覆うは使わず、覆うは物の表面をおおう動作。"}, {"text": "ポットに湯を覆った。", "explanation": "ここは〈注ぐ〉の意味。容器に液体を入れる動作は注ぐで、覆うは合わない。"}, {"text": "夕食でようやく空腹を覆った。", "explanation": "ここは〈満たす〉の意味。空腹を満たす動作は満たすで、覆うは面をおおう動作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52406, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪が屋根をすっかり覆うて、家が白くなった。", "corrected_sentence": "雪が屋根をすっかり覆って、家が白くなった。", "error_description": "て形の誤り。五段動詞「覆う」のて形は「覆って」で、語尾の「う」が「って」に変わる。「覆うて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覆って", "is_correct": true, "explanation": "て形。「覆っていた」の形で、この文の正解。"}, {"text": "覆う", "is_correct": false, "explanation": "終止形。「覆う」は「ていた」と続けられない。"}, {"text": "覆わ", "is_correct": false, "explanation": "未然形。「覆わていた」とは続かない。"}, {"text": "覆い", "is_correct": false, "explanation": "連用形。「覆いていた」とは続かない。"}], "correct_form": "覆って", "base_form": "覆う", "form_label": "て形", "sentence_index": 1, "explanations": {"覆って": "て形。「覆っていた」の形で、この文の正解。", "覆う": "終止形。「覆う」は「ていた」と続けられない。", "覆わ": "未然形。「覆わていた」とは続かない。", "覆い": "連用形。「覆いていた」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52406, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧が谷に覆っている。", "corrected_sentence": "霧が谷を覆っている。", "error_description": "助詞の誤り。「覆う」は目的語に「を」を取る他動詞。「谷に覆う」は誤りで、「谷を覆う」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覆って", "is_correct": true, "explanation": "て形。「覆っている」の形で、この文の正解。"}, {"text": "覆った", "is_correct": false, "explanation": "た形。「覆ったている」とは続かず、「覆っている」の形にならない。"}, {"text": "覆おう", "is_correct": false, "explanation": "意志形。「覆おうている」とは続かず、状態を表せない。"}, {"text": "覆え", "is_correct": false, "explanation": "仮定・命令の形。「覆えている」とは続かず、この文に合わない。"}], "correct_form": "覆って", "base_form": "覆う", "form_label": "て形", "sentence_index": 7, "explanations": {"覆って": "て形。「覆っている」の形で、この文の正解。", "覆った": "た形。「覆ったている」とは続かず、「覆っている」の形にならない。", "覆おう": "意志形。「覆おうている」とは続かず、状態を表せない。", "覆え": "仮定・命令の形。「覆えている」とは続かず、この文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す。遊ぶ場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「庭先が遊んでいる」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用を示すが、「庭先と遊んでいる」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「庭先より遊んでいる」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す。遊ぶ場所を表す。", "が": "主格を示すが、「庭先が遊んでいる」は文が成り立たない。", "と": "共同・引用を示すが、「庭先と遊んでいる」は意味が通らない。", "より": "比較を示すが、「庭先より遊んでいる」は意味が通らない。"}, "error_tags": {"が": "主格", "と": "共同・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "到達の範囲を示す。入ってきた先の限度を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「庭先が入ってきて」は主語が二つ重なり成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示すが、「庭先で入ってきて」は移動の到達点として合わない。"}, {"text": "の", "is_correct": false, "explanation": "所有・修飾を示すが、「庭先の入ってきて」は文が成り立たない。"}], "correct_answer": "まで", "explanations": {"まで": "到達の範囲を示す。入ってきた先の限度を表す。", "が": "主格を示すが、「庭先が入ってきて」は主語が二つ重なり成り立たない。", "で": "場所・手段を示すが、「庭先で入ってきて」は移動の到達点として合わない。", "の": "所有・修飾を示すが、「庭先の入ってきて」は文が成り立たない。"}, "error_tags": {"が": "主格", "で": "場所・手段", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の外の、庭の入り口の近くの場所。", "primary_collocate": null, "pronunciation": "にわさき", "ipa": "niwasaki", "syllable_count": 4, "sentences": [{"text": "庭先に出ると、冷たい風が頬にあたった。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に出[で]ると、冷[つめ]たい風[かぜ]が頬[ほお]にあたった。", "sentence_source": "generated"}, {"text": "子どもたちは庭先でシャボン玉を飛ばして遊んでいる。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "子[こ]どもたちは庭先[にわさき]でシャボン玉[だま]を飛[と]ばして遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "犬が庭先につないであるので、吠えられた。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "犬[いぬ]が庭先[にわさき]につないであるので、吠[ほ]えられた。", "sentence_source": "generated"}, {"text": "庭先に咲いた桜を、家族みんなで見た。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に咲[さ]いた桜[さくら]を、家族[かぞく]みんなで見[み]た。", "sentence_source": "generated"}, {"text": "玄関を出て庭先を歩くと、土の匂いがした。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "玄関[げんかん]を出[で]て庭先[にわさき]を歩[ある]くと、土[つち]の匂[にお]いがした。", "sentence_source": "generated"}, {"text": "庭先に干した布団が、日に当たって温かい。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に干[ほ]した布団[ふとん]が、日[ひ]に当[あ]たって温[あたた]かい。", "sentence_source": "generated"}, {"text": "父は庭先で野菜に水をやっている。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "父[ちち]は庭先[にわさき]で野菜[やさい]に水[みず]をやっている。", "sentence_source": "generated"}, {"text": "郵便屋さんが庭先まで入ってきて、手紙を渡した。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "郵便屋[ゆうびんや]さんが庭先[にわさき]まで入[はい]ってきて、手紙[てがみ]を渡[わた]した。", "sentence_source": "generated"}, {"text": "庭先に小さなベンチを置いて、夕涼みをした。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に小[ちい]さなベンチを置[お]いて、夕涼[ゆうすず]みをした。", "sentence_source": "generated"}, {"text": "夏の夜、庭先で花火をした。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]、庭先[にわさき]で花火[はなび]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "庭先", "label": "基本形"}], "register": "標準", "sense_fingerprint": "家のすぐ外にある、庭の入口に近い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庭先", "is_correct": true, "explanation": "「庭先に出ると」で、家の外の場所を表す名詞。"}, {"text": "鍵", "is_correct": false, "explanation": "道具の名詞。「鍵に出ると」は場所として成り立たない。"}, {"text": "布団", "is_correct": false, "explanation": "寝具。「布団に出ると」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "書状。「手紙に出ると」は場所として成り立たない。"}], "explanations": {"庭先": "「庭先に出ると」で、家の外の場所を表す名詞。", "鍵": "道具の名詞。「鍵に出ると」は場所として成り立たない。", "布団": "寝具。「布団に出ると」は成り立たない。", "手紙": "書状。「手紙に出ると」は場所として成り立たない。"}, "sentence_index": 0, "correct_answer": "庭先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ホテルの客室の庭先で、ゆっくり寝た。", "explanation": "ここは〈室内〉の意味。庭先は家の外の場所なので、ホテルの客室（屋内）には使えない。"}, {"text": "エレベーターの中の庭先で、人と話した。", "explanation": "ここは〈車内〉の意味。庭先は屋外の場所なので、エレベーターの中には使えない。"}, {"text": "地下鉄の庭先で、電車を待った。", "explanation": "ここは〈駅のホーム〉の意味。庭先は家の外の庭の入口を指すので、地下の駅には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庭先", "is_correct": true, "explanation": "「父は庭先で野菜に水をやっている」で、作業をする場所を表す名詞。"}, {"text": "寝言", "is_correct": false, "explanation": "夢の中での発声。「寝言で野菜に水をやっている」は意味が通らない。"}, {"text": "髪", "is_correct": false, "explanation": "身体の部位。「髪で野菜に水をやっている」は成り立たない。"}, {"text": "額", "is_correct": false, "explanation": "身体の部位。「額で野菜に水をやっている」は意味が通らない。"}], "explanations": {"庭先": "「父は庭先で野菜に水をやっている」で、作業をする場所を表す名詞。", "寝言": "夢の中での発声。「寝言で野菜に水をやっている」は意味が通らない。", "髪": "身体の部位。「髪で野菜に水をやっている」は成り立たない。", "額": "身体の部位。「額で野菜に水をやっている」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "庭先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室の庭先で、授業を受けた。", "explanation": "ここは〈校舎〉の意味。庭先は家の外の庭の入口を指すので、校舎の中の場所には使えない。"}, {"text": "船の甲板の庭先で、釣りをした。", "explanation": "ここは〈海上〉の意味。庭先は家の外の庭の入口付近を指すので、海の上の甲板には使えない。"}, {"text": "机の上の庭先に、本を置いた。", "explanation": "ここは〈家具の上〉の意味。庭先は家の外の庭の入口を指すので、机の上には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫が庭先へ寝ていた。", "corrected_sentence": "猫が庭先で寝ていた。", "error_description": "助詞の誤り。寝ている場所は「で」で示す。「庭先へ」は方向を表すので、ここでは「庭先で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52407, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭先より子どもが遊んでいた。", "corrected_sentence": "庭先で子どもが遊んでいた。", "error_description": "助詞の誤り。遊ぶ場所は「で」で示す。「庭先より」は比較の意味になり、ここでは「庭先で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「庭先まで」は到達の範囲を示し、迎えに出た先の限度を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「庭先を迎えに出た」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示すが、「庭先で迎えに出た」は到達点として合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用を示すが、「庭先と迎えに出た」は意味が通らない。"}], "correct_answer": "まで", "explanations": {"まで": "「庭先まで」は到達の範囲を示し、迎えに出た先の限度を表す。", "を": "目的語を示すが、「庭先を迎えに出た」は文が成り立たない。", "で": "場所・手段を示すが、「庭先で迎えに出た」は到達点として合わない。", "と": "共同・引用を示すが、「庭先と迎えに出た」は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す。荷物を渡した場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「庭先が荷物を渡して」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「庭先より荷物を渡して」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "二つ目の「を」が重なり、「庭先を荷物を渡して」は成り立たない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す。荷物を渡した場所を表す。", "が": "主格を示すが、「庭先が荷物を渡して」は文が成り立たない。", "より": "比較を示すが、「庭先より荷物を渡して」は意味が通らない。", "を": "二つ目の「を」が重なり、「庭先を荷物を渡して」は成り立たない。"}, "error_tags": {"が": "主格", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "庭の入口付近、または庭の手前の部分。", "primary_collocate": null, "pronunciation": "にわさき", "ipa": "niwasaki", "syllable_count": 4, "sentences": [{"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "しかし、窓辺[まどべ]に佇[たたず]む幼[おさな]き我[わ]が子[こ]の瞳[ひとみ]は、白銀[はくぎん]に覆[おお]われた庭先[にわさき]へと注[そそ]がれ、抑[おさ]えきれない生命[せいめい]の衝動[しょうどう]に駆[か]られていた。", "sentence_source": "mined"}, {"text": "客が来たので、庭先まで迎えに出た。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "客[きゃく]が来[き]たので、庭先[にわさき]まで迎[むか]えに出[で]た。", "sentence_source": "generated"}, {"text": "庭先に小さな自転車が置いてある。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に小[ちい]さな自転車[じてんしゃ]が置[お]いてある。", "sentence_source": "generated"}, {"text": "朝、庭先で近所の人と挨拶を交わした。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "朝[あさ]、庭先[にわさき]で近所[きんじょ]の人[ひと]と挨拶[あいさつ]を交[か]わした。", "sentence_source": "generated"}, {"text": "庭先の花壇に、赤いチューリップが咲いている。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]の花壇[かだん]に、赤[あか]いチューリップが咲[さ]いている。", "sentence_source": "generated"}, {"text": "雨が降りそうなので、庭先の洗濯物を急いで取り込んだ。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうなので、庭先[にわさき]の洗濯物[せんたくもの]を急[いそ]いで取[と]り込[こ]んだ。", "sentence_source": "generated"}, {"text": "猫が庭先まで来て、じっとこちらを見ていた。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "猫[ねこ]が庭先[にわさき]まで来[き]て、じっとこちらを見[み]ていた。", "sentence_source": "generated"}, {"text": "配達の人は庭先で荷物を渡して帰っていった。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "配達[はいたつ]の人[ひと]は庭先[にわさき]で荷物[にもつ]を渡[わた]して帰[かえ]っていった。", "sentence_source": "generated"}, {"text": "庭先に車を止めると、隣の人に迷惑がかかる。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "庭先[にわさき]に車[くるま]を止[と]めると、隣[となり]の人[ひと]に迷惑[めいわく]がかかる。", "sentence_source": "generated"}, {"text": "祖母は庭先に座って、のんびりお茶を飲んでいる。", "target_word": "庭先", "complexity_tier": "T3", "furigana": "祖母[そぼ]は庭先[にわさき]に座[すわ]って、のんびりお茶[ちゃ]を飲[の]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "庭先", "label": "基本形"}], "register": "標準", "sense_fingerprint": "庭の入口に近い、道や玄関に面した手前の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庭先", "is_correct": true, "explanation": "「白銀に覆われた庭先へと注がれ」で、視線が向かう場所を表す名詞。"}, {"text": "溜息", "is_correct": false, "explanation": "息の名詞。「溜息へと注がれ」は視線の行き先にならない。"}, {"text": "衝動", "is_correct": false, "explanation": "感情の名詞。「覆われた衝動へと注がれ」は場所として成り立たない。"}, {"text": "生命", "is_correct": false, "explanation": "抽象名詞。「覆われた生命へと注がれ」は場所を表せない。"}], "explanations": {"庭先": "「白銀に覆われた庭先へと注がれ」で、視線が向かう場所を表す名詞。", "溜息": "息の名詞。「溜息へと注がれ」は視線の行き先にならない。", "衝動": "感情の名詞。「覆われた衝動へと注がれ」は場所として成り立たない。", "生命": "抽象名詞。「覆われた生命へと注がれ」は場所を表せない。"}, "sentence_index": 0, "correct_answer": "庭先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山頂の庭先で、日の出を見た。", "explanation": "ここは〈山頂〉の意味。庭先は家の外の庭の入口付近を指す語で、山頂の景色には使えない。"}, {"text": "居間の庭先で、テレビを見た。", "explanation": "ここは〈室内〉の意味。庭先は屋外の場所を指す語で、屋内の居間には使えない。"}, {"text": "海の庭先で、貝を拾った。", "explanation": "ここは〈浜辺〉の意味。庭先は家の庭の入口を指す語なので、海辺には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庭先", "is_correct": true, "explanation": "「猫が庭先まで来て」で、来た場所を表す名詞。"}, {"text": "寝言", "is_correct": false, "explanation": "夢の中での発声。「寝言まで来て」は場所として成り立たない。"}, {"text": "髪", "is_correct": false, "explanation": "身体の部位。「髪まで来て」は場所として意味が通らない。"}, {"text": "歌", "is_correct": false, "explanation": "音楽の一種。「歌まで来て」は場所として成り立たない。"}], "explanations": {"庭先": "「猫が庭先まで来て」で、来た場所を表す名詞。", "寝言": "夢の中での発声。「寝言まで来て」は場所として成り立たない。", "髪": "身体の部位。「髪まで来て」は場所として意味が通らない。", "歌": "音楽の一種。「歌まで来て」は場所として成り立たない。"}, "sentence_index": 6, "correct_answer": "庭先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空港の庭先で、飛行機を待った。", "explanation": "ここは〈ターミナル〉の意味。庭先は家の外の庭の入口を指すので、空港の施設には使えない。"}, {"text": "池の底の庭先に、魚が泳いでいる。", "explanation": "ここは〈水中〉の意味。庭先は地上の家の近くを指す語で、池の底のような水中の場所には使えない。"}, {"text": "ビルの最上階の庭先で、仕事をした。", "explanation": "ここは〈オフィス〉の意味。庭先は家の外の庭を指すので、ビルの最上階の仕事場には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭先を椅子を置いた。", "corrected_sentence": "庭先に椅子を置いた。", "error_description": "助詞の誤り。「を」が二つ重なっている。置く場所は「に」で示すので「庭先に椅子を置いた。」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52408, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭先を車が止まっている。", "corrected_sentence": "庭先に車が止まっている。", "error_description": "助詞の誤り。「止まっている」の場所は「に」で示す。「庭先を」は止まる文には成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「衝動」が「がまんした」の対象であることを示す、他動詞の目的語の格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞。「衝動へがまんした」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表す。「衝動とがまんした」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す。「衝動よりがまんした」は不自然で文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「衝動」が「がまんした」の対象であることを示す、他動詞の目的語の格助詞。", "へ": "方向を表す助詞。「衝動へがまんした」では意味が通らない。", "と": "並列や引用を表す。「衝動とがまんした」は成り立たない。", "より": "比較を表す。「衝動よりがまんした」は不自然で文に合わない。"}, "error_tags": {"へ": "方向", "と": "並列・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "したいことが、とめられない気もち。", "primary_collocate": null, "pronunciation": "しょうどう", "ipa": "ɕoːdoː", "syllable_count": 4, "sentences": [{"text": "ケーキを見て、すぐに食べたい衝動に駆られた。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "ケーキを見[み]て、すぐに食[た]べたい衝動[しょうどう]に駆[か]られた。", "sentence_source": "generated"}, {"text": "大きな声で笑いたい衝動を、授業中だったのでがまんした。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で笑[わら]いたい衝動[しょうどう]を、授業中[じゅぎょうちゅう]だったのでがまんした。", "sentence_source": "generated"}, {"text": "新しいゲームがほしくて、買いたい衝動が止まらない。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "新[あたら]しいゲームがほしくて、買[か]いたい衝動[しょうどう]が止[と]まらない。", "sentence_source": "generated"}, {"text": "彼は先生に文句を言いたい衝動をぐっと抑えた。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "彼[かれ]は先生[せんせい]に文句[もんく]を言[い]いたい衝動[しょうどう]をぐっと抑[おさ]えた。", "sentence_source": "generated"}, {"text": "雪を見ると、外へ走り出したい衝動が起こる。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "雪[ゆき]を見[み]ると、外[そと]へ走[はし]り出[だ]したい衝動[しょうどう]が起[お]こる。", "sentence_source": "generated"}, {"text": "眠いのに、スマホを見たい衝動に負けて夜ふかしした。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "眠[ねむ]いのに、スマホを見[み]たい衝動[しょうどう]に負[ま]けて夜[よる]ふかしした。", "sentence_source": "generated"}, {"text": "海を見ていたら、泳ぎたい衝動が急に強くなった。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "海[うみ]を見[み]ていたら、泳[およ]ぎたい衝動[しょうどう]が急[きゅう]に強[つよ]くなった。", "sentence_source": "generated"}, {"text": "弟はおもちゃをさわりたい衝動をがまんできず、棚に手をのばした。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "弟[おとうと]はおもちゃをさわりたい衝動[しょうどう]をがまんできず、棚[たな]に手[て]をのばした。", "sentence_source": "generated"}, {"text": "泣きたい衝動をこらえて、最後まで笑顔で話した。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "泣[な]きたい衝動[しょうどう]をこらえて、最後[さいご]まで笑顔[えがお]で話[はな]した。", "sentence_source": "generated"}, {"text": "友だちに会いたい衝動で、夜なのに電話をかけてしまった。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "友[とも]だちに会[あ]いたい衝動[しょうどう]で、夜[よる]なのに電話[でんわ]をかけてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝動", "label": "基本形"}], "register": "標準", "sense_fingerprint": "やりたいと思って止められない気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衝動", "is_correct": true, "explanation": "「食べたい」に続き、止められない気持ちを表す語。「駆られた」ともつながる。"}, {"text": "規則", "is_correct": false, "explanation": "守るべき決まりのこと。「食べたい規則に駆られた」とは言えない。"}, {"text": "寸法", "is_correct": false, "explanation": "長さや大きさのこと。「食べたい寸法」は文に合わない。"}, {"text": "請求", "is_correct": false, "explanation": "代金などを求めること。「食べたい請求に駆られた」は不自然で文に合わない。"}], "explanations": {"衝動": "「食べたい」に続き、止められない気持ちを表す語。「駆られた」ともつながる。", "規則": "守るべき決まりのこと。「食べたい規則に駆られた」とは言えない。", "寸法": "長さや大きさのこと。「食べたい寸法」は文に合わない。", "請求": "代金などを求めること。「食べたい請求に駆られた」は不自然で文に合わない。"}, "sentence_index": 0, "correct_answer": "衝動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は衝動を固めて、受験に挑んだ。", "explanation": "ここは〈決意〉の意味。衝動は止められない気持ちで、自分で固める決意とは違うので合わない。"}, {"text": "彼女は衝動を込めて、クラスの皆に説明した。", "explanation": "ここは〈熱意〉の意味。衝動は抑えられない気持ちで、込めて伝える熱意とは違うので合わない。"}, {"text": "彼は衝動を示そうと、深く頭を下げた。", "explanation": "ここは〈誠意〉の意味。衝動は止められない気持ちで、誠実な思いを示す誠意とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衝動", "is_correct": true, "explanation": "「泳ぎたい」に続き、急に強くなる気持ちを表す語。文の主語として合う。"}, {"text": "報酬", "is_correct": false, "explanation": "働きに対して受け取るもの。「泳ぎたい報酬が強くなった」とは言えない。"}, {"text": "形式", "is_correct": false, "explanation": "決まった型のこと。「泳ぎたい形式が強くなった」は文の意味を成さない。"}, {"text": "料金", "is_correct": false, "explanation": "代金のこと。「泳ぎたい料金が急に強くなった」は不自然で、この文に合わない。"}], "explanations": {"衝動": "「泳ぎたい」に続き、急に強くなる気持ちを表す語。文の主語として合う。", "報酬": "働きに対して受け取るもの。「泳ぎたい報酬が強くなった」とは言えない。", "形式": "決まった型のこと。「泳ぎたい形式が強くなった」は文の意味を成さない。", "料金": "代金のこと。「泳ぎたい料金が急に強くなった」は不自然で、この文に合わない。"}, "sentence_index": 6, "correct_answer": "衝動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は衝動を心がけ、毎月の出費を減らした。", "explanation": "ここは〈節約〉の意味。衝動は抑えられない欲求で、計画して出費を減らす節約とは違うので合わない。"}, {"text": "衝動を築くには、時間がかかる。", "explanation": "ここは〈信頼〉の意味。衝動は一時的な気持ちで、時間をかけて築くものではないので合わない。"}, {"text": "その知らせには大きな衝動を受けた。", "explanation": "ここは〈衝撃〉の意味。衝動は内側から起こる抑えきれない気持ちで、外から受ける衝撃とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな声で笑いたい衝動を駆られて、思わず席を立った。", "corrected_sentence": "大きな声で笑いたい衝動に駆られて、思わず席を立った。", "error_description": "「駆られる」は「〜に駆られる」と助詞「に」を取る。「を」は誤りで、正しくは「衝動に駆られて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52409, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泳ぎたい衝動が駆られて、思わず海に飛び込んだ。", "corrected_sentence": "泳ぎたい衝動に駆られて、思わず海に飛び込んだ。", "error_description": "「駆られる」は「〜に駆られる」と助詞「に」を取る。「が」は誤りで、正しくは「衝動に駆られて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52410, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「衝動」が「わき上がってきた」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に使う。「わき上がる」は自動詞なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞。「衝動へわき上がる」では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「衝動に」は原因や対象を示すが、わき上がる動作の主語にはならず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「衝動」が「わき上がってきた」の主語を示す格助詞。", "を": "「を」は他動詞の目的語に使う。「わき上がる」は自動詞なので合わない。", "へ": "方向を表す助詞。「衝動へわき上がる」では意味が通らない。", "に": "「衝動に」は原因や対象を示すが、わき上がる動作の主語にはならず文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "位置・対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52410, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「衝動」が「あった」の主語を示す格助詞。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表す。「衝動とあった」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す。「衝動よりあった」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す。「衝動からあった」は不自然で文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「衝動」が「あった」の主語を示す格助詞。", "と": "並列や引用を表す。「衝動とあった」は成り立たない。", "より": "比較を表す。「衝動よりあった」は意味が通らない。", "から": "起点を表す。「衝動からあった」は不自然で文に合わない。"}, "error_tags": {"と": "並列・引用", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52410, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の気持ちや行動を、とめられないくらい強く動かす力。", "primary_collocate": null, "pronunciation": "しょうどう", "ipa": "ɕoːdoː", "syllable_count": 4, "sentences": [{"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "衝動", "complexity_tier": "T4", "furigana": "しかし、窓辺[まどべ]に佇[たたず]む幼[おさな]き我[わ]が子[こ]の瞳[ひとみ]は、白銀[はくぎん]に覆[おお]われた庭先[にわさき]へと注[そそ]がれ、抑[おさ]えきれない生命[せいめい]の衝動[しょうどう]に駆[か]られていた。", "sentence_source": "mined"}, {"text": "突然、大声で叫びたいという衝動が胸の奥からわき上がってきた。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "突然[とつぜん]、大声[おおごえ]で叫[さけ]びたいという衝動[しょうどう]が胸[むね]の奥[おく]からわき上[あ]がってきた。", "sentence_source": "generated"}, {"text": "彼は買いたい衝動を抑えられず、給料の半分を使ってしまった。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "彼[かれ]は買[か]いたい衝動[しょうどう]を抑[おさ]えられず、給料[きゅうりょう]の半分[はんぶん]を使[つか]ってしまった。", "sentence_source": "generated"}, {"text": "高い所から下を見ると、飛び降りたくなるような衝動を覚える人もいる。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "高[たか]い所[ところ]から下[した]を見[み]ると、飛[と]び降[お]りたくなるような衝動[しょうどう]を覚[おぼ]える人[ひと]もいる。", "sentence_source": "generated"}, {"text": "怒りの衝動に任せて手を上げれば、後で必ず後悔することになる。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "怒[いか]りの衝動[しょうどう]に任[まか]せて手[て]を上[あ]げれば、後[あと]で必[かなら]ず後悔[こうかい]することになる。", "sentence_source": "generated"}, {"text": "彼女は創作への衝動に突き動かされ、一晩で十枚の絵を描き上げた。", "target_word": "衝動", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は創作[そうさく]への衝動[しょうどう]に突[つ]き動[うご]かされ、一晩[ひとばん]で十枚[じゅうまい]の絵[え]を描[か]き上[あ]げた。", "sentence_source": "generated"}, {"text": "その衝動が収まるまで深呼吸をして、返信を送るのを待った。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "その衝動[しょうどう]が収[おさ]まるまで深呼吸[しんこきゅう]をして、返信[へんしん]を送[おく]るのを待[ま]った。", "sentence_source": "generated"}, {"text": "子どもの頃、虫を捕まえたいという強い衝動があった。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]、虫[むし]を捕[つか]まえたいという強[つよ]い衝動[しょうどう]があった。", "sentence_source": "generated"}, {"text": "旅に出たい衝動が日に日に強まり、とうとう仕事を辞めた。", "target_word": "衝動", "complexity_tier": "T3", "furigana": "旅[たび]に出[で]たい衝動[しょうどう]が日[ひ]に日[ひ]に強[つよ]まり、とうとう仕事[しごと]を辞[や]めた。", "sentence_source": "generated"}, {"text": "心理学の授業で、人間の衝動はどこから生まれるのかを学んだ。", "target_word": "衝動", "complexity_tier": "T4", "furigana": "心理学[しんりがく]の授業[じゅぎょう]で、人間[にんげん]の衝動[しょうどう]はどこから生[う]まれるのかを学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝動", "label": "基本形"}], "register": "標準", "sense_fingerprint": "気持ちや行動を強く突き動かす内側の力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 窓辺 (Zipf 2.97), 佇む (Zipf 2.76), 幼き (Zipf 2.71), 白銀 (Zipf 3.03), 庭先 (Zipf 2.68)']::text[], '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52410, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衝動", "is_correct": true, "explanation": "「生命の」に続き、抑えきれない強い力で動かされる状態を表す語。「駆られていた」ともつながる。"}, {"text": "報酬", "is_correct": false, "explanation": "働きに対して受け取るもの。「生命の報酬に駆られる」とは言えず、文の状態に合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "事実と違う理解のこと。「誤解に駆られていた」は不自然で、この文の意味を成さない。"}, {"text": "手順", "is_correct": false, "explanation": "物事を進める順序のこと。「手順に駆られていた」とは言えず、この文に入らない。"}], "explanations": {"衝動": "「生命の」に続き、抑えきれない強い力で動かされる状態を表す語。「駆られていた」ともつながる。", "報酬": "働きに対して受け取るもの。「生命の報酬に駆られる」とは言えず、文の状態に合わない。", "誤解": "事実と違う理解のこと。「誤解に駆られていた」は不自然で、この文の意味を成さない。", "手順": "物事を進める順序のこと。「手順に駆られていた」とは言えず、この文に入らない。"}, "sentence_index": 0, "correct_answer": "衝動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい仕事に衝動をもって取り組んでいる。", "explanation": "ここは〈意欲〉の意味。衝動は突然生まれて止められない力で、落ち着いて続ける意欲とは違うので合わない。"}, {"text": "彼は衝動を曲げず、最後まで反対意見を貫いた。", "explanation": "ここは〈信念〉の意味。衝動は一時的に突き動かす力で、長く変わらない信念とは違うので合わない。"}, {"text": "彼は衝動を守って、甘い物を控えている。", "explanation": "ここは〈節制〉の意味。衝動は抑えきれない力で、自分で保つ節制とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52410, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衝動", "is_correct": true, "explanation": "「その」に続き、収まるまで待つ対象として文に合う。"}, {"text": "名簿", "is_correct": false, "explanation": "人の名前を並べた帳面。「収まる」とは結びつかず、文の意味に合わない。"}, {"text": "料金", "is_correct": false, "explanation": "代金のこと。「料金が収まる」は不自然で、この文に合わない。"}, {"text": "規則", "is_correct": false, "explanation": "守るべき決まりのこと。「規則が収まる」とは言えず、文に合わない。"}], "explanations": {"衝動": "「その」に続き、収まるまで待つ対象として文に合う。", "名簿": "人の名前を並べた帳面。「収まる」とは結びつかず、文の意味に合わない。", "料金": "代金のこと。「料金が収まる」は不自然で、この文に合わない。", "規則": "守るべき決まりのこと。「規則が収まる」とは言えず、文に合わない。"}, "sentence_index": 6, "correct_answer": "衝動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は衝動を達成するために、毎日勉強を重ねた。", "explanation": "ここは〈目標〉の意味。衝動は突き動かされる力で、達成の対象になる目標とは違うので合わない。"}, {"text": "会社は新しい衝動を社員に示した。", "explanation": "ここは〈方針〉の意味。衝動は一時的な気持ちで、社員に示すような方針とは違うので合わない。"}, {"text": "十分な衝動を経て、結論を出した。", "explanation": "ここは〈検討〉の意味。衝動は考えずに動かされる力で、慎重に検討する過程とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
