INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「全力を注ぐ」で、注ぐ対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「全力が注いでいる」は目的語の位置に主語を置くことになり、合わない。"}, {"text": "と", "is_correct": false, "explanation": "「全力と注いでいる」は相手や並列を示すが、注ぐ対象には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「全力の注いでいる」は名詞を修飾する形になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「全力を注ぐ」で、注ぐ対象を示す。", "が": "「全力が注いでいる」は目的語の位置に主語を置くことになり、合わない。", "と": "「全力と注いでいる」は相手や並列を示すが、注ぐ対象には合わない。", "の": "「全力の注いでいる」は名詞を修飾する形になり、文が成り立たない。"}, "error_tags": {"が": "主語を示すが、目的語の位置に合わない", "と": "並列や相手を示し、注ぐ対象には合わない", "の": "名詞修飾になり、述語が成り立たない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「視線を注いでいた」で、注ぐ対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「視線へ注いでいた」は注ぐ対象の示し方として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「視線から注いでいた」は起点を示すが、注ぐ対象には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「視線より注いでいた」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「視線を注いでいた」で、注ぐ対象を示す。", "へ": "「視線へ注いでいた」は注ぐ対象の示し方として不自然。", "から": "「視線から注いでいた」は起点を示すが、注ぐ対象には合わない。", "より": "比較の助詞で、「視線より注いでいた」は文が成り立たない。"}, "error_tags": {"へ": "方向を示すが、注ぐ対象には合わない", "から": "起点を示すが、注ぐ対象には合わない", "より": "比較の助詞で、目的語には使えない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目や気持ちを、あるものに向けること。", "primary_collocate": null, "pronunciation": "そそぐ", "ipa": "sosogɯ", "syllable_count": 3, "sentences": [{"text": "母は子どもに深い愛情を注いで育てた。", "target_word": "注いで", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもに深[ふか]い愛情[あいじょう]を注[そそ]いで育[そだ]てた。", "sentence_source": "generated"}, {"text": "彼は研究に全力を注いでいる。", "target_word": "注いで", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]に全力[ぜんりょく]を注[そそ]いでいる。", "sentence_source": "generated"}, {"text": "観客は舞台の主役に熱い視線を注いだ。", "target_word": "注いだ", "complexity_tier": "T3", "furigana": "観客[かんきゃく]は舞台[ぶたい]の主役[しゅやく]に熱[あつ]い視線[しせん]を注[そそ]いだ。", "sentence_source": "generated"}, {"text": "先生は新しい教材づくりに心血を注いでいる。", "target_word": "注いで", "complexity_tier": "T3", "furigana": "先生[せんせい]は新[あたら]しい教材[きょうざい]づくりに心血[しんけつ]を注[そそ]いでいる。", "sentence_source": "generated"}, {"text": "彼女は犬のしつけに、毎日心を注いでいる。", "target_word": "注いで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は犬[いぬ]のしつけに、毎日[まいにち]心[こころ]を注[そそ]いでいる。", "sentence_source": "generated"}, {"text": "選手は最後の試合に、すべての力を注いだ。", "target_word": "注いだ", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は最後[さいご]の試合[しあい]に、すべての力[ちから]を注[そそ]いだ。", "sentence_source": "generated"}, {"text": "祖父は庭の花に愛情を注ぎ、毎朝世話をしている。", "target_word": "注ぎ", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]の花[はな]に愛情[あいじょう]を注[そそ]ぎ、毎朝[まいあさ]世話[せわ]をしている。", "sentence_source": "generated"}, {"text": "子どもたちは、手品師の手に視線を注いでいた。", "target_word": "注いで", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、手品師[てじなし]の手[て]に視線[しせん]を注[そそ]いでいた。", "sentence_source": "generated"}, {"text": "社長は新しい商品の開発に力を注ぐと発表した。", "target_word": "注ぐ", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は新[あたら]しい商品[しょうひん]の開発[かいはつ]に力[ちから]を注[そそ]ぐと発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "彼は夢をかなえるために、ありったけの情熱を注いだ。", "target_word": "注いだ", "complexity_tier": "T3", "furigana": "彼[かれ]は夢[ゆめ]をかなえるために、ありったけの情熱[じょうねつ]を注[そそ]いだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "注ぐ", "label": "辞書形"}, {"form": "注ぎ", "label": "連用形"}, {"form": "注いだ", "label": "た形"}, {"form": "注がない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "視線や愛情、力などをあるものに集中して向ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注いで", "is_correct": true, "explanation": "正解。「愛情を注いで育てる」で、心を向けて育てる意味になる。"}, {"text": "失って", "is_correct": false, "explanation": "「愛情を失って」は意味が合わず、育てる文脈にも合わない。"}, {"text": "断って", "is_correct": false, "explanation": "「愛情を断って」は不自然で、育てる行為の説明にならない。"}, {"text": "数えて", "is_correct": false, "explanation": "「愛情を数えて」は文脈に合わず、育てる行為を表さない。"}], "explanations": {"注いで": "正解。「愛情を注いで育てる」で、心を向けて育てる意味になる。", "失って": "「愛情を失って」は意味が合わず、育てる文脈にも合わない。", "断って": "「愛情を断って」は不自然で、育てる行為の説明にならない。", "数えて": "「愛情を数えて」は文脈に合わず、育てる行為を表さない。"}, "sentence_index": 0, "correct_answer": "注いで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は友人に感謝の言葉を注いだ。", "explanation": "ここは〈述べる〉の意味。感謝は言葉で述べるものなので「述べる」を使い、注ぐは目や気持ちを向ける意味で合わない。"}, {"text": "彼は選手たちに厳しい声を注いだ。", "explanation": "ここは〈かける〉の意味。声を向ける動作には「声をかける」を使い、注ぐは目や気持ちを向ける意味で合わない。"}, {"text": "夜になると、冷たい風が注いできた。", "explanation": "ここは〈吹く〉の意味。風は吹くもので、注ぐとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注ぎ", "is_correct": true, "explanation": "正解。「愛情を注ぎ、世話をしている」と並ぶ連用形で、愛情を向ける意味になる。"}, {"text": "尋ね", "is_correct": false, "explanation": "「愛情を尋ね」は意味が通らず、世話の文脈に合わない。"}, {"text": "怠り", "is_correct": false, "explanation": "「愛情を怠り」は文脈と逆の意味になり、毎朝の世話と合わない。"}, {"text": "逃し", "is_correct": false, "explanation": "「愛情を逃し」は意味が通らず、世話を続ける文脈に合わない。"}], "explanations": {"注ぎ": "正解。「愛情を注ぎ、世話をしている」と並ぶ連用形で、愛情を向ける意味になる。", "尋ね": "「愛情を尋ね」は意味が通らず、世話の文脈に合わない。", "怠り": "「愛情を怠り」は文脈と逆の意味になり、毎朝の世話と合わない。", "逃し": "「愛情を逃し」は意味が通らず、世話を続ける文脈に合わない。"}, "sentence_index": 6, "correct_answer": "注ぎ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町中にチラシを注いだ。", "explanation": "ここは〈配る〉の意味。紙を人々に渡す動作には「配る」を使い、注ぐとは言わないので合わない。"}, {"text": "庭に種を注いだ。", "explanation": "ここは〈撒く〉の意味。種をまく動作には「撒く」を使い、注ぐは液体や気持ちを向ける意味で合わない。"}, {"text": "トラックの荷台に荷物を注いだ。", "explanation": "ここは〈乗せる〉の意味。荷物を置く動作には「乗せる」を使い、注ぐとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫に深い愛情に注いで育てた。", "corrected_sentence": "祖母は孫に深い愛情を注いで育てた。", "error_description": "誤りは「愛情に」の「に」。「注ぐ」は目的語を「を」で示すので、「に」は合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "注いで", "is_correct": true, "explanation": "正解。「注いでいる」の形で、継続の状態を表す。"}, {"text": "注ぐ", "is_correct": false, "explanation": "辞書形は「注ぐいる」と続かず、文に入らない。"}, {"text": "注ぎ", "is_correct": false, "explanation": "連用形は「注ぎいる」と続かず、て形の位置に合わない。"}, {"text": "注いだ", "is_correct": false, "explanation": "た形は「注いだいる」と続かず、継続の形にならない。"}], "correct_form": "注いで", "base_form": "注ぐ", "form_label": "て形", "sentence_index": 1, "explanations": {"注いで": "正解。「注いでいる」の形で、継続の状態を表す。", "注ぐ": "辞書形は「注ぐいる」と続かず、文に入らない。", "注ぎ": "連用形は「注ぎいる」と続かず、て形の位置に合わない。", "注いだ": "た形は「注いだいる」と続かず、継続の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は犬の散歩に、毎日心を注ぐでいる。", "corrected_sentence": "彼女は犬の散歩に、毎日心を注いでいる。", "error_description": "誤りは「注ぐで」。「注ぐ」の継続形は「注いでいる」の「注いで」で、「注ぐで」は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "注いで", "is_correct": true, "explanation": "正解。「注いでいた」の「注いで」で、て形に「いる」が続いて継続を表す。"}, {"text": "注がない", "is_correct": false, "explanation": "ない形は「注がないいた」と続かず、文が成り立たない。"}, {"text": "注げば", "is_correct": false, "explanation": "仮定形は「注げば」と条件を表し、「注げばいた」と続かないので文に入らない。"}, {"text": "注げ", "is_correct": false, "explanation": "命令形は相手に命じる形で、過去の出来事を述べる文には合わない。"}], "correct_form": "注いで", "base_form": "注ぐ", "form_label": "て形", "sentence_index": 7, "explanations": {"注いで": "正解。「注いでいた」の「注いで」で、て形に「いる」が続いて継続を表す。", "注がない": "ない形は「注がないいた」と続かず、文が成り立たない。", "注げば": "仮定形は「注げば」と条件を表し、「注げばいた」と続かないので文に入らない。", "注げ": "命令形は相手に命じる形で、過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「意」が「決めて」の目的語であることを示す格助詞。「意を決める」の形になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞。「意へ決めて」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表す。「意と決めて」は不自然で文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す。「意より決めて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「意」が「決めて」の目的語であることを示す格助詞。「意を決める」の形になる。", "へ": "方向を表す助詞。「意へ決めて」は成り立たない。", "と": "並列や引用を表す。「意と決めて」は不自然で文に合わない。", "より": "比較を表す。「意より決めて」は意味が通らない。"}, "error_tags": {"へ": "方向", "と": "並列・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「反対の意」が「示す」の目的語であることを示す格助詞。「意を示す」の形になる。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す。「意に示す」は不自然で、「示す」は「を」を取る。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表す。「反対の意の示すため」は「示す」に続かず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す。「意から示す」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「反対の意」が「示す」の目的語であることを示す格助詞。「意を示す」の形になる。", "に": "位置や相手を示す。「意に示す」は不自然で、「示す」は「を」を取る。", "の": "連体修飾を表す。「反対の意の示すため」は「示す」に続かず文が成り立たない。", "から": "起点を表す。「意から示す」は成り立たない。"}, "error_tags": {"に": "位置・相手", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "こころで おもう こと。", "primary_collocate": null, "pronunciation": "い", "ipa": "i", "syllable_count": 1, "sentences": [{"text": "友だちにおわびの意を伝えるために、手紙を書いた。", "target_word": "意", "complexity_tier": "T3", "furigana": "友[とも]だちにおわびの意[い]を伝[つた]えるために、手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "私は意を決して、みんなの前で歌った。", "target_word": "意", "complexity_tier": "T3", "furigana": "私[わたし]は意[い]を決[けっ]して、みんなの前[まえ]で歌[うた]った。", "sentence_source": "generated"}, {"text": "母の意に反して、兄は遠くの大学へ行った。", "target_word": "意", "complexity_tier": "T3", "furigana": "母[はは]の意[い]に反[はん]して、兄[あに]は遠[とお]くの大学[だいがく]へ行[い]った。", "sentence_source": "generated"}, {"text": "駅員さんに感謝の意を表して、頭を下げた。", "target_word": "意", "complexity_tier": "T3", "furigana": "駅員[えきいん]さんに感謝[かんしゃ]の意[い]を表[あらわ]して、頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "子どもたちは先生の意を理解して、静かに座った。", "target_word": "意", "complexity_tier": "T3", "furigana": "子[こ]どもたちは先生[せんせい]の意[い]を理解[りかい]して、静[しず]かに座[すわ]った。", "sentence_source": "generated"}, {"text": "祝福の意を込めて、友人に小さな花束を渡した。", "target_word": "意", "complexity_tier": "T3", "furigana": "祝福[しゅくふく]の意[い]を込[こ]めて、友人[ゆうじん]に小[ちい]さな花束[はなたば]を渡[わた]した。", "sentence_source": "generated"}, {"text": "彼は自分の意のままに、旅の予定を決めた。", "target_word": "意", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の意[い]のままに、旅[たび]の予定[よてい]を決[き]めた。", "sentence_source": "generated"}, {"text": "反対の意を示すため、彼女は会議で静かに首を横に振った。", "target_word": "意", "complexity_tier": "T3", "furigana": "反対[はんたい]の意[い]を示[しめ]すため、彼女[かのじょ]は会議[かいぎ]で静[しず]かに首[くび]を横[よこ]に振[ふ]った。", "sentence_source": "generated"}, {"text": "多くの人に支持され、彼は意を強くした。", "target_word": "意", "complexity_tier": "T3", "furigana": "多[おお]くの人[ひと]に支持[しじ]され、彼[かれ]は意[い]を強[つよ]くした。", "sentence_source": "generated"}, {"text": "相手の意に沿わない返事をして、気まずくなった。", "target_word": "意", "complexity_tier": "T3", "furigana": "相手[あいて]の意[い]に沿[そ]わない返事[へんじ]をして、気[き]まずくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意", "label": "基本形"}], "register": "文語的", "sense_fingerprint": "心で思うこと、気持ち（感謝の意・意を決するなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意", "is_correct": true, "explanation": "「おわびの」に続き、伝える対象として文に合う。心で思うことを表す。"}, {"text": "報酬", "is_correct": false, "explanation": "働きへの対価のこと。「おわびの報酬を伝える」とは言えない。"}, {"text": "寸法", "is_correct": false, "explanation": "長さや大きさのこと。「おわびの寸法を伝える」は文の意味を成さない。"}, {"text": "名簿", "is_correct": false, "explanation": "人の名前を並べた帳面のこと。「おわびの名簿を伝える」は不自然で文に合わない。"}], "explanations": {"意": "「おわびの」に続き、伝える対象として文に合う。心で思うことを表す。", "報酬": "働きへの対価のこと。「おわびの報酬を伝える」とは言えない。", "寸法": "長さや大きさのこと。「おわびの寸法を伝える」は文の意味を成さない。", "名簿": "人の名前を並べた帳面のこと。「おわびの名簿を伝える」は不自然で文に合わない。"}, "sentence_index": 0, "correct_answer": "意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は意をかぶって、外へ出た。", "explanation": "ここは〈帽子〉の意味。意は心の中の思いで、頭にかぶる物ではないので合わない。"}, {"text": "彼は机の上の意を整理して、計画を立てた。", "explanation": "ここは〈書類〉の意味。意は心の中の思いで、机の上に置いて整理する物ではないので合わない。"}, {"text": "彼は意を完成させるため、毎晩遅くまで描いた。", "explanation": "ここは〈作品〉の意味。意は心の中の思いで、完成させて仕上げるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意", "is_correct": true, "explanation": "「自分の」に続き、「意のままに」で心の思いに従う意味になり文に合う。"}, {"text": "請求書", "is_correct": false, "explanation": "代金を求める書類のこと。「自分の請求書のままに」は意味が通らない。"}, {"text": "生地", "is_correct": false, "explanation": "布のこと。「自分の生地のままに」は文に合わない。"}, {"text": "出店", "is_correct": false, "explanation": "店を出すこと。「自分の出店のままに」は文の意味を成さない。"}], "explanations": {"意": "「自分の」に続き、「意のままに」で心の思いに従う意味になり文に合う。", "請求書": "代金を求める書類のこと。「自分の請求書のままに」は意味が通らない。", "生地": "布のこと。「自分の生地のままに」は文に合わない。", "出店": "店を出すこと。「自分の出店のままに」は文の意味を成さない。"}, "sentence_index": 6, "correct_answer": "意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は屋根の意を落とすため、朝からスコップを使った。", "explanation": "ここは〈雪〉の意味。意は心の中の思いで、屋根から落として取り除く物ではないので合わない。"}, {"text": "彼は意を釣るため、朝早く港へ行った。", "explanation": "ここは〈魚〉の意味。意は心の中の思いで、釣り上げる生き物ではないので合わない。"}, {"text": "彼は意に乗るため、駅で待った。", "explanation": "ここは〈列車〉の意味。意は心の中の思いで、乗り物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は意に強くして、大会に出場した。", "corrected_sentence": "彼は意を強くして、大会に出場した。", "error_description": "「意を強くする」は助詞「を」を取る。「に」は誤りで、正しくは「意を強くして」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52413, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の意を従い、新しい班に加わった。", "corrected_sentence": "先輩の意に従い、新しい班に加わった。", "error_description": "「従う」は「〜に従う」と助詞「に」を取る。「を」は誤りで、正しくは「意に従い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
