INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「意」に「介さず」が続く「意に介さず」の格助詞。「介する」は「に」を取る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「意を介さず」は誤りで、「介する」は「に」を取る。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表す。「意の介さず」は「介さず」に続かず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す。「意から介さず」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「意」に「介さず」が続く「意に介さず」の格助詞。「介する」は「に」を取る。", "を": "目的語を示す。「意を介さず」は誤りで、「介する」は「に」を取る。", "の": "連体修飾を表す。「意の介さず」は「介さず」に続かず文が成り立たない。", "から": "起点を表す。「意から介さず」は意味が通らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心に思うこと。考え。気持ち。", "primary_collocate": null, "pronunciation": "い", "ipa": "i", "syllable_count": 1, "sentences": [{"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "意", "complexity_tier": "T4", "furigana": "厳冬[げんとう]の冷[つめ]たさなど意[い]に介[かい]さず、ただ純粋[じゅんすい]に外[そと]で遊[あそ]ぶための準備[じゅんび]に余念[よねん]がないのだ。", "sentence_source": "mined"}, {"text": "彼は周囲の反対にもかかわらず、独立する意を固めた。", "target_word": "意", "complexity_tier": "T4", "furigana": "彼[かれ]は周囲[しゅうい]の反対[はんたい]にもかかわらず、独立[どくりつ]する意[い]を固[かた]めた。", "sentence_source": "generated"}, {"text": "先生の意に沿う形で、発表の内容を書き直した。", "target_word": "意", "complexity_tier": "T4", "furigana": "先生[せんせい]の意[い]に沿[そ]う形[かたち]で、発表[はっぴょう]の内容[ないよう]を書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "長年の感謝の意を込めて、両親に花を贈った。", "target_word": "意", "complexity_tier": "T3", "furigana": "長年[ながねん]の感謝[かんしゃ]の意[い]を込[こ]めて、両親[りょうしん]に花[はな]を贈[おく]った。", "sentence_source": "generated"}, {"text": "部長は私の提案に賛成の意を示してくれた。", "target_word": "意", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は私[わたし]の提案[ていあん]に賛成[さんせい]の意[い]を示[しめ]してくれた。", "sentence_source": "generated"}, {"text": "彼女は相手の意を汲んで、何も言わずに席を譲った。", "target_word": "意", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は相手[あいて]の意[い]を汲[く]んで、何[なに]も言[い]わずに席[せき]を譲[ゆず]った。", "sentence_source": "generated"}, {"text": "本人の意に反して、転勤が決まってしまった。", "target_word": "意", "complexity_tier": "T4", "furigana": "本人[ほんにん]の意[い]に反[はん]して、転勤[てんきん]が決[き]まってしまった。", "sentence_source": "generated"}, {"text": "彼は周りの批判を意に介さず、自分の研究を続けた。", "target_word": "意", "complexity_tier": "T4", "furigana": "彼[かれ]は周[まわ]りの批判[ひはん]を意[い]に介[かい]さず、自分[じぶん]の研究[けんきゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は意を決して、社長に直接話しに行った。", "target_word": "意", "complexity_tier": "T3", "furigana": "彼[かれ]は意[い]を決[けっ]して、社長[しゃちょう]に直接[ちょくせつ]話[はな]しに行[い]った。", "sentence_source": "generated"}, {"text": "私は彼女の意を尊重して、旅行先を決めた。", "target_word": "意", "complexity_tier": "T3", "furigana": "私[わたし]は彼女[かのじょ]の意[い]を尊重[そんちょう]して、旅行先[りょこうさき]を決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意", "label": "基本形"}], "register": "文語的", "sense_fingerprint": "心の中の考えや気持ち（意に沿う・意を決するなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 厳冬 (Zipf 2.45), 冷た (Zipf 3.17), 介さ (Zipf 3.09), 余念 (Zipf 2.8)']::text[], '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意", "is_correct": true, "explanation": "「〜に介さず」は「気にしない」の意の表現で、「意に介さず」として文に合う。"}, {"text": "報酬", "is_correct": false, "explanation": "働きへの対価のこと。「報酬に介さず」は成り立たない。"}, {"text": "誤解", "is_correct": false, "explanation": "事実と違う理解のこと。「誤解に介さず」は不自然で文に合わない。"}, {"text": "寸法", "is_correct": false, "explanation": "長さや大きさのこと。「寸法に介さず」とは言えない。"}], "explanations": {"意": "「〜に介さず」は「気にしない」の意の表現で、「意に介さず」として文に合う。", "報酬": "働きへの対価のこと。「報酬に介さず」は成り立たない。", "誤解": "事実と違う理解のこと。「誤解に介さず」は不自然で文に合わない。", "寸法": "長さや大きさのこと。「寸法に介さず」とは言えない。"}, "sentence_index": 0, "correct_answer": "意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝から意が痛くて、薬を飲んだ。", "explanation": "ここは〈胃〉の意味。意は心の中の思いで、体の臓器を指さないので『痛い』とは言わない。"}, {"text": "彼は意が豊富で、質問に何でも答えられる。", "explanation": "ここは〈知識〉の意味。意は心の中の考えで、知っている情報の多さを表す語ではない。"}, {"text": "彼は朝から意が悪かった。", "explanation": "ここは〈機嫌〉の意味。意は心に思うことで、気分の良し悪しを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意", "is_correct": true, "explanation": "「〜に反して」の名詞で、「本人の意に反して」として文に合う。"}, {"text": "料金", "is_correct": false, "explanation": "代金のこと。「本人の料金に反して」は意味が通らない。"}, {"text": "請求書", "is_correct": false, "explanation": "代金を求める書類のこと。「本人の請求書に反して」とは言えない。"}, {"text": "生地", "is_correct": false, "explanation": "布のこと。「本人の生地に反して」は文の意味を成さない。"}], "explanations": {"意": "「〜に反して」の名詞で、「本人の意に反して」として文に合う。", "料金": "代金のこと。「本人の料金に反して」は意味が通らない。", "請求書": "代金を求める書類のこと。「本人の請求書に反して」とは言えない。", "生地": "布のこと。「本人の生地に反して」は文の意味を成さない。"}, "sentence_index": 6, "correct_answer": "意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は去年から意が急に伸びた。", "explanation": "ここは〈身長〉の意味。意は心の中の思いで、体の大きさを表す語ではないので合わない。"}, {"text": "彼は意を塗るため、週末に店を借りた。", "explanation": "ここは〈壁〉の意味。意は心の中の思いで、塗る物ではないので合わない。"}, {"text": "この品は意が安い。", "explanation": "ここは〈値段〉の意味。意は心の中の思いで、物の価格を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族の意を従って、進路を決めた。", "corrected_sentence": "家族の意に従って、進路を決めた。", "error_description": "「従う」は「〜に従う」と助詞「に」を取る。「を」は誤りで、正しくは「意に従って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52414, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "誰の意をも背かないよう、慎重に動いた。", "corrected_sentence": "誰の意にも背かないよう、慎重に動いた。", "error_description": "「背く」は「〜に背く」と助詞「に」を取る。「を」は誤りで、正しくは「意にも背かないよう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
