INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「厳冬の夜」で、季節と時間を名詞でつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「厳冬を夜」は名詞どうしを目的語でつなぐ形になり、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「厳冬が夜」は季節が夜と並ぶ主語にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「厳冬と夜」は季節と時間を並べる文脈にならず、後の文と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「厳冬の夜」で、季節と時間を名詞でつなぐ「の」が正しい。", "を": "「厳冬を夜」は名詞どうしを目的語でつなぐ形になり、不自然。", "が": "「厳冬が夜」は季節が夜と並ぶ主語にならず、文が成り立たない。", "と": "「厳冬と夜」は季節と時間を並べる文脈にならず、後の文と結びつかない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "冬の寒さが特に厳しいこと。また、そのような冬。", "primary_collocate": null, "pronunciation": "げんとう", "ipa": "ɡentoː", "syllable_count": 4, "sentences": [{"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]の冷[つめ]たさなど意[い]に介[かい]さず、ただ純粋[じゅんすい]に外[そと]で遊[あそ]ぶための準備[じゅんび]に余念[よねん]がないのだ。", "sentence_source": "mined"}, {"text": "今年は厳冬で、毎朝、川に氷が張っている。", "target_word": "厳冬", "complexity_tier": "T3", "furigana": "今年[ことし]は厳冬[げんとう]で、毎朝[まいあさ]、川[かわ]に氷[こおり]が張[は]っている。", "sentence_source": "generated"}, {"text": "厳冬の北海道では、気温が氷点下二十度を下回る日もある。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]の北海道[ほっかいどう]では、気温[きおん]が氷点下[ひょうてんか]二十度[にじゅうど]を下回[したまわ]る日[ひ]もある。", "sentence_source": "generated"}, {"text": "厳冬に備えて、早めにストーブと灯油を用意した。", "target_word": "厳冬", "complexity_tier": "T3", "furigana": "厳冬[げんとう]に備[そな]えて、早[はや]めにストーブと灯油[とうゆ]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "厳冬のため、山小屋に向かう道は雪で閉ざされた。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]のため、山小屋[やまごや]に向[む]かう道[みち]は雪[ゆき]で閉[と]ざされた。", "sentence_source": "generated"}, {"text": "厳冬を乗り越えた梅の木が、春になって花を咲かせた。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]を乗[の]り越[こ]えた梅[うめ]の木[き]が、春[はる]になって花[はな]を咲[さ]かせた。", "sentence_source": "generated"}, {"text": "昨年の厳冬で水道管が凍り、多くの家で水が出なくなった。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "昨年[さくねん]の厳冬[げんとう]で水道管[すいどうかん]が凍[こお]り、多[おお]くの家[いえ]で水[みず]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "厳冬の夜、登山隊は寒さに耐えながら朝を待った。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]の夜[よる]、登山隊[とざんたい]は寒[さむ]さに耐[た]えながら朝[あさ]を待[ま]った。", "sentence_source": "generated"}, {"text": "気象台は、今年の冬は厳冬になるだろうと予想している。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "気象台[きしょうだい]は、今年[ことし]の冬[ふゆ]は厳冬[げんとう]になるだろうと予想[よそう]している。", "sentence_source": "generated"}, {"text": "厳冬だった去年に比べ、今年の冬は暖かくて過ごしやすい。", "target_word": "厳冬", "complexity_tier": "T4", "furigana": "厳冬[げんとう]だった去年[きょねん]に比[くら]べ、今年[ことし]の冬[ふゆ]は暖[あたた]かくて過[す]ごしやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳冬", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "寒さが特に厳しい冬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳冬", "is_correct": true, "explanation": "「厳冬の冷たさ」は寒さが特に厳しい冬を表し、文の冷たさの話に合う。"}, {"text": "猛暑", "is_correct": false, "explanation": "暑さの厳しさを表す語で、「冷たさ」と矛盾する。"}, {"text": "残暑", "is_correct": false, "explanation": "夏の終わりに残る暑さを表す語で、「冷たさ」と合わない。"}, {"text": "夏至", "is_correct": false, "explanation": "一年で昼が最も長い日を指す語で、冷たさの話には当てはまらない。"}], "explanations": {"厳冬": "「厳冬の冷たさ」は寒さが特に厳しい冬を表し、文の冷たさの話に合う。", "猛暑": "暑さの厳しさを表す語で、「冷たさ」と矛盾する。", "残暑": "夏の終わりに残る暑さを表す語で、「冷たさ」と合わない。", "夏至": "一年で昼が最も長い日を指す語で、冷たさの話には当てはまらない。"}, "sentence_index": 0, "correct_answer": "厳冬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は材料の厳冬にこだわって仕入れている。", "explanation": "ここは〈厳選〉（よいものを選び抜くこと）の意味。厳冬は冬の寒さを表すので、材料を選ぶ意味では使えない。"}, {"text": "校則が厳冬で、髪の色まで決められている。", "explanation": "ここは〈厳格〉（決まりがきびしいこと）の意味。厳冬は寒さのきびしさを表すので、校則の厳しさには使えない。"}, {"text": "審査が厳冬で、合格者はわずかだった。", "explanation": "ここは〈厳正〉（公正にきびしく行うこと）の意味。厳冬は寒さを表すので、審査のきびしさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳冬", "is_correct": true, "explanation": "「昨年の厳冬で水道管が凍り」は寒さの厳しい冬が原因という意味で、文の内容に合う。"}, {"text": "盛夏", "is_correct": false, "explanation": "真夏のことで、水道管が凍る原因にはならず文の内容と合わない。"}, {"text": "初夏", "is_correct": false, "explanation": "夏の初めを指し、凍結の原因として成り立たない。"}, {"text": "熱帯夜", "is_correct": false, "explanation": "夜も気温が下がらない暑い夜のことで、水道管の凍結と矛盾する。"}], "explanations": {"厳冬": "「昨年の厳冬で水道管が凍り」は寒さの厳しい冬が原因という意味で、文の内容に合う。", "盛夏": "真夏のことで、水道管が凍る原因にはならず文の内容と合わない。", "初夏": "夏の初めを指し、凍結の原因として成り立たない。", "熱帯夜": "夜も気温が下がらない暑い夜のことで、水道管の凍結と矛盾する。"}, "sentence_index": 6, "correct_answer": "厳冬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まだ厳冬の入り口なのに、池の水面がもう凍っている。", "explanation": "ここは〈初冬〉（冬の初め）の意味。厳冬は寒さが最も厳しい時期を指すので、冬の入り口には使えない。"}, {"text": "空港の警備は厳冬で、手荷物を全部検査された。", "explanation": "ここは〈厳重〉（守りや取り締まりがきびしいこと）の意味。厳冬は寒さのきびしさを表すので、警備には使えない。"}, {"text": "館内での飲食は厳冬とされている。", "explanation": "ここは〈厳禁〉（決して許されないこと）の意味。厳冬は寒さを表し、禁止の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北の町では毎年、厳冬を長く続く。", "corrected_sentence": "北の町では毎年、厳冬が長く続く。", "error_description": "「続く」は主語に「が」をとる自動詞。「厳冬を」は誤りで、正しくは「厳冬が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厳冬の暑さに耐えながら、小屋で春を待った。", "corrected_sentence": "厳冬の寒さに耐えながら、小屋で春を待った。", "error_description": "「厳冬」に続く語は「寒さ」が正しい。「暑さ」は厳冬の性質と矛盾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「準備のため」で、名詞「準備」を「ため」につなぐ「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「準備がため」は「ため」が名詞に続く形として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「準備をため」は「ため」に目的語をつなぐ形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「準備にため」は「ため」と結ぶには不自然。"}], "correct_answer": "の", "explanations": {"の": "「準備のため」で、名詞「準備」を「ため」につなぐ「の」が正しい。", "が": "「準備がため」は「ため」が名詞に続く形として成り立たない。", "を": "「準備をため」は「ため」に目的語をつなぐ形にならない。", "に": "「準備にため」は「ため」と結ぶには不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを始める前に、必要なものをそろえること。", "primary_collocate": null, "pronunciation": "じゅんび", "ipa": "dʑɯmbi", "syllable_count": 3, "sentences": [{"text": "先生は授業を始める前に、教室で教材の準備をした。", "target_word": "準備", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]を始[はじ]める前[まえ]に、教室[きょうしつ]で教材[きょうざい]の準備[じゅんび]をした。", "sentence_source": "generated"}, {"text": "祭りの準備のため、町の人たちが朝から広場に集まった。", "target_word": "準備", "complexity_tier": "T3", "furigana": "祭[まつ]りの準備[じゅんび]のため、町[まち]の人[ひと]たちが朝[あさ]から広場[ひろば]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "準備ができていないのに、試合が始まってしまった。", "target_word": "準備", "complexity_tier": "T3", "furigana": "準備[じゅんび]ができていないのに、試合[しあい]が始[はじ]まってしまった。", "sentence_source": "generated"}, {"text": "母は夕食の準備を始めたので、私は皿を並べた。", "target_word": "準備", "complexity_tier": "T3", "furigana": "母[はは]は夕食[ゆうしょく]の準備[じゅんび]を始[はじ]めたので、私[わたし]は皿[さら]を並[なら]べた。", "sentence_source": "generated"}, {"text": "彼は留学の準備として、毎日英語を勉強している。", "target_word": "準備", "complexity_tier": "T3", "furigana": "彼[かれ]は留学[りゅうがく]の準備[じゅんび]として、毎日[まいにち]英語[えいご]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "旅行の準備をしていたら、パスポートがないことに気づいた。", "target_word": "準備", "complexity_tier": "T3", "furigana": "旅行[りょこう]の準備[じゅんび]をしていたら、パスポートがないことに気[き]づいた。", "sentence_source": "generated"}, {"text": "準備に時間がかかったせいで、電車に乗り遅れた。", "target_word": "準備", "complexity_tier": "T3", "furigana": "準備[じゅんび]に時間[じかん]がかかったせいで、電車[でんしゃ]に乗[の]り遅[おく]れた。", "sentence_source": "generated"}, {"text": "結婚式の準備は、半年前から少しずつ進めてきた。", "target_word": "準備", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の準備[じゅんび]は、半年[はんとし]前[まえ]から少[すこ]しずつ進[すす]めてきた。", "sentence_source": "generated"}, {"text": "山に登る前に、地図や水などを準備しておこう。", "target_word": "準備", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]る前[まえ]に、地図[ちず]や水[みず]などを準備[じゅんび]しておこう。", "sentence_source": "generated"}, {"text": "準備を整えた選手たちは、静かに開始の合図を待っていた。", "target_word": "準備", "complexity_tier": "T3", "furigana": "準備[じゅんび]を整[ととの]えた選手[せんしゅ]たちは、静[しず]かに開始[かいし]の合図[あいず]を待[ま]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "準備", "label": "終止形(名詞)"}, {"form": "準備する", "label": "動詞(辞書形)"}, {"form": "準備した", "label": "過去形"}, {"form": "準備して", "label": "て形"}, {"form": "準備しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "始める前に必要なものをそろえる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "準備", "is_correct": true, "explanation": "「教材の準備をした」は、授業の前に教材をそろえたという意味で、文に合う。"}, {"text": "運転", "is_correct": false, "explanation": "車などを動かすことで、「教材の運転」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かけることで、教材の話には当てはまらない。"}, {"text": "昼寝", "is_correct": false, "explanation": "眠ることで、教材を扱う文脈とは合わない。"}], "explanations": {"準備": "「教材の準備をした」は、授業の前に教材をそろえたという意味で、文に合う。", "運転": "車などを動かすことで、「教材の運転」は意味が通らない。", "散歩": "歩いて出かけることで、教材の話には当てはまらない。", "昼寝": "眠ることで、教材を扱う文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "準備"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食が終わったので、食器の準備を始めた。", "explanation": "ここは〈後片付け〉（使い終えた物を片づけること）の意味。準備は使う前にそろえることで、食べ終えたあとには合わない。"}, {"text": "イベントが終わって、機材の準備を始めた。", "explanation": "ここは〈撤収〉（片づけて引き上げること）の意味。準備は使う前にそろえることで、終わったあとの撤収には使えない。"}, {"text": "大会の得点を準備して、順位を発表した。", "explanation": "ここは〈集計〉（数や点を合わせること）の意味。準備は事前に必要なものを整えることで、点を合わせる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "準備", "is_correct": true, "explanation": "「準備に時間がかかった」は、事前の用意に時間がかかったという意味で、文に合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめに振る舞うことで、時間がかかったという文脈には合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝過ごすことで、「寝坊に時間がかかった」は意味が通らない。"}, {"text": "仮眠", "is_correct": false, "explanation": "短く眠ることで、電車に乗り遅れた原因の文脈には合わない。"}], "explanations": {"準備": "「準備に時間がかかった」は、事前の用意に時間がかかったという意味で、文に合う。", "遠慮": "控えめに振る舞うことで、時間がかかったという文脈には合わない。", "寝坊": "寝過ごすことで、「寝坊に時間がかかった」は意味が通らない。", "仮眠": "短く眠ることで、電車に乗り遅れた原因の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "準備"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議でようやく準備が出た。", "explanation": "ここは〈結論〉（話し合いの最後の答え）の意味。準備は事前に整えることで、答えを出す意味はない。"}, {"text": "試合は途中で準備された。", "explanation": "ここは〈中断〉（途中で止めること）の意味。準備は物事を始める前の整えを指すので、途中で止める意味はない。"}, {"text": "テストが終わったので、答案の準備を採点して、結果を発表した。", "explanation": "ここは〈採点〉（答案に点をつけること）の意味。準備は事前に必要なものをそろえることで、点をつける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの準備が進めるため、町の人たちが集まった。", "corrected_sentence": "祭りの準備を進めるため、町の人たちが集まった。", "error_description": "「準備を進める」の「を」が正しい。「準備が進める」の「が」は誤りで、目的語には「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52417, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "準備を断って、家族は旅立ちの日を待った。", "corrected_sentence": "準備を整えて、家族は旅立ちの日を待った。", "error_description": "「準備を整える」が正しい組み合わせ。「断る」は準備の対象にならず、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
