INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "よけいなことを考えないこと。", "primary_collocate": "ない", "pronunciation": "よねん", "ipa": "joneɴ", "syllable_count": 3, "sentences": [{"text": "彼は本を読むことに余念がなく、周りの音も聞こえない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "彼[かれ]は本[ほん]を読[よ]むことに余念[よねん]がなく、周[まわ]りの音[おと]も聞[き]こえない。", "sentence_source": "generated"}, {"text": "余念なく仕事に打ち込んだ結果、予定より早く終わった。", "target_word": "余念", "complexity_tier": "T3", "furigana": "余念[よねん]なく仕事[しごと]に打[う]ち込[こ]んだ結果[けっか]、予定[よてい]より早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "弟はゲームに余念がなくて、呼んでも返事をしない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "弟[おとうと]はゲームに余念[よねん]がなくて、呼[よ]んでも返事[へんじ]をしない。", "sentence_source": "generated"}, {"text": "彼女は静かな部屋で、絵を描くことに余念がない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は静[しず]かな部屋[へや]で、絵[え]を描[えが]くことに余念[よねん]がない。", "sentence_source": "generated"}, {"text": "職人は余念なく刃を研ぎ続けた。", "target_word": "余念", "complexity_tier": "T3", "furigana": "職人[しょくにん]は余念[よねん]なく刃[は]を研[と]ぎ続[つづ]けた。", "sentence_source": "generated"}, {"text": "子どもは砂遊びに余念がなく、日が暮れても帰ろうとしない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "子[こ]どもは砂遊[すなあそ]びに余念[よねん]がなく、日[ひ]が暮[く]れても帰[かえ]ろうとしない。", "sentence_source": "generated"}, {"text": "先生は授業の準備に余念がないので、生徒からの信頼が厚い。", "target_word": "余念", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]の準備[じゅんび]に余念[よねん]がないので、生徒[せいと]からの信頼[しんらい]が厚[あつ]い。", "sentence_source": "generated"}, {"text": "猫は毛づくろいに余念がなく、私が近づいても気にしない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "猫[ねこ]は毛[け]づくろいに余念[よねん]がなく、私[わたし]が近[ちか]づいても気[き]にしない。", "sentence_source": "generated"}, {"text": "彼は釣りに余念がなかったから、雨が降り出したのに気づかなかった。", "target_word": "余念", "complexity_tier": "T3", "furigana": "彼[かれ]は釣[つ]りに余念[よねん]がなかったから、雨[あめ]が降[ふ]り出[だ]したのに気[き]づかなかった。", "sentence_source": "generated"}, {"text": "祖父は盆栽の世話に余念がなく、毎日何時間も眺めている。", "target_word": "余念", "complexity_tier": "T3", "furigana": "祖父[そふ]は盆栽[ぼんさい]の世話[せわ]に余念[よねん]がなく、毎日[まいにち]何時間[なんじかん]も眺[なが]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余念", "label": "名詞"}, {"form": "余念がない", "label": "慣用表現(終止形)"}, {"form": "余念がなかった", "label": "過去形"}, {"form": "余念がなく", "label": "連用形"}, {"form": "余念なく", "label": "連用形(が省略)"}], "register": "neutral", "sense_fingerprint": "「余念がない」で、よけいなことを考えず没頭している", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52419, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余念", "is_correct": true, "explanation": "「本を読むことに＿がなく」の空欄に入るのは「余念」だけで、「余念がなく」になる。"}, {"text": "天気", "is_correct": false, "explanation": "「本を読むことに天気がなく」は意味が通らず、空欄に入らない。"}, {"text": "寝床", "is_correct": false, "explanation": "「本を読むことに寝床がなく」は文脈に合わず、空欄に入らない。"}, {"text": "手袋", "is_correct": false, "explanation": "「本を読むことに手袋がなく」は意味が通らず、空欄に入らない。"}], "explanations": {"余念": "「本を読むことに＿がなく」の空欄に入るのは「余念」だけで、「余念がなく」になる。", "天気": "「本を読むことに天気がなく」は意味が通らず、空欄に入らない。", "寝床": "「本を読むことに寝床がなく」は文脈に合わず、空欄に入らない。", "手袋": "「本を読むことに手袋がなく」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "余念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は絵が完成せず、余念を残して部屋を出た。", "explanation": "ここは〈無念〉の意味。余念は「余念がない」の形で使い、「余念を残す」とは言わない。"}, {"text": "静かな部屋でも余念が浮かんで、絵が描けない。", "explanation": "ここは〈雑念〉の意味。余念は雑念がない状態を表し、頭に浮かぶものではない。"}, {"text": "彼女は絵の具の余念を集めて、もう一枚の絵を描いた。", "explanation": "ここは〈余り〉の意味。余念は他のことに気を取られない状態を表し、物の余りは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52419, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余念", "is_correct": true, "explanation": "「授業の準備に＿がないので」の空欄に入るのは「余念」だけで、「余念がないので」になる。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「授業の準備に夕焼けがないので」は意味が通らず、空欄に入らない。"}, {"text": "風鈴", "is_correct": false, "explanation": "「授業の準備に風鈴がないので」は意味が通らず、空欄に入らない。"}, {"text": "雨粒", "is_correct": false, "explanation": "「授業の準備に雨粒がないので」は文脈に合わず、空欄に入らない。"}], "explanations": {"余念": "「授業の準備に＿がないので」の空欄に入るのは「余念」だけで、「余念がないので」になる。", "夕焼け": "「授業の準備に夕焼けがないので」は意味が通らず、空欄に入らない。", "風鈴": "「授業の準備に風鈴がないので」は意味が通らず、空欄に入らない。", "雨粒": "「授業の準備に雨粒がないので」は文脈に合わず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "余念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は盆栽の世話に余念を使い、家計が苦しくなった。", "explanation": "ここは〈余計な金〉の意味。余念は他のことに気を取られない状態を表し、金銭の余りは指さない。"}, {"text": "祖父は盆栽の世話を早めに終えて、余念を持て余し、午後はずっと昼寝をした。", "explanation": "ここは〈余暇〉の意味。余念は他のことを考えない状態で、空いた時間は指さない。"}, {"text": "祖父は盆栽の世話に余念を惜しまず、毎日何時間も眺めている。", "explanation": "ここは〈努力〉の意味。余念は「余念がない」の形で使い、惜しむ対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52419, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は絵を描くことを余念がなく、食事を忘れた。", "corrected_sentence": "彼女は絵を描くことに余念がなく、食事を忘れた。", "error_description": "「余念がない」は「〜に余念がない」の形を取る。「を」は誤りで、「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52419, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は宿題に余念がないで、呼んでも返事をしない。", "corrected_sentence": "弟は宿題に余念がなくて、呼んでも返事をしない。", "error_description": "「余念がない」の中止の形は「なくて」。「ないで」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不器用", "is_correct": true, "explanation": "不器用は器用の対義語で、手先の巧みさがないことを表す。"}, {"text": "丁寧", "is_correct": false, "explanation": "丁寧は仕事ぶりの細やかさを表し、器用の反対語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "慎重は用心深さを表し、器用の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速は動作の速さを表し、器用の反対語ではない。"}], "correct_answer": "不器用", "explanations": {"不器用": "不器用は器用の対義語で、手先の巧みさがないことを表す。", "丁寧": "丁寧は仕事ぶりの細やかさを表し、器用の反対語ではない。", "慎重": "慎重は用心深さを表し、器用の反対語ではない。", "迅速": "迅速は動作の速さを表し、器用の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不器用", "is_correct": true, "explanation": "不器用は器用の対義語で、手先の巧みさがないことを表す。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は思い切りのよさを表し、器用の反対語ではない。"}, {"text": "寛大", "is_correct": false, "explanation": "寛大は心が広いことを表し、器用の反対語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は動きが盛んなことを表し、器用の反対語ではない。"}], "correct_answer": "不器用", "explanations": {"不器用": "不器用は器用の対義語で、手先の巧みさがないことを表す。", "大胆": "大胆は思い切りのよさを表し、器用の反対語ではない。", "寛大": "寛大は心が広いことを表し、器用の反対語ではない。", "活発": "活発は動きが盛んなことを表し、器用の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "手や体をうまく使って、物をじょうずに作ったり、動かしたりできること。", "primary_collocate": null, "pronunciation": "きよう", "ipa": "kijoː", "syllable_count": 3, "sentences": [{"text": "器用な職人が、木を削って小さな人形を作った。", "target_word": "器用", "complexity_tier": "T3", "furigana": "器用[きよう]な職人[しょくにん]が、木[き]を削[けず]って小[ちい]さな人形[にんぎょう]を作[つく]った。", "sentence_source": "generated"}, {"text": "彼は足先でボールを器用に操り、観客を沸かせた。", "target_word": "器用", "complexity_tier": "T3", "furigana": "彼[かれ]は足先[あしさき]でボールを器用[きよう]に操[あやつ]り、観客[かんきゃく]を沸[わ]かせた。", "sentence_source": "generated"}, {"text": "猿は器用に木の枝をつかんで、高い所へ登っていった。", "target_word": "器用", "complexity_tier": "T3", "furigana": "猿[さる]は器用[きよう]に木[き]の枝[えだ]をつかんで、高[たか]い所[ところ]へ登[のぼ]っていった。", "sentence_source": "generated"}, {"text": "姉は器用な指で、髪を美しい三つ編みにした。", "target_word": "器用", "complexity_tier": "T3", "furigana": "姉[あね]は器用[きよう]な指[ゆび]で、髪[かみ]を美[うつく]しい三[み]つ編[あ]みにした。", "sentence_source": "generated"}, {"text": "器用な大工さんのおかげで、古い家が新しくなった。", "target_word": "器用", "complexity_tier": "T3", "furigana": "器用[きよう]な大工[だいく]さんのおかげで、古[ふる]い家[いえ]が新[あたら]しくなった。", "sentence_source": "generated"}, {"text": "彼女は箸を器用に使って、豆を一粒ずつ皿に移した。", "target_word": "器用", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は箸[はし]を器用[きよう]に使[つか]って、豆[まめ]を一粒[ひとつぶ]ずつ皿[さら]に移[うつ]した。", "sentence_source": "generated"}, {"text": "手先が器用な子どもは、粘土で動物を上手に作る。", "target_word": "器用", "complexity_tier": "T3", "furigana": "手先[てさき]が器用[きよう]な子[こ]どもは、粘土[ねんど]で動物[どうぶつ]を上手[じょうず]に作[つく]る。", "sentence_source": "generated"}, {"text": "彼は片手で器用にコーヒーを注ぎ、もう片方の手で電話を持っていた。", "target_word": "器用", "complexity_tier": "T3", "furigana": "彼[かれ]は片手[かたて]で器用[きよう]にコーヒーを注[そそ]ぎ、もう片方[かたほう]の手[て]で電話[でんわ]を持[も]っていた。", "sentence_source": "generated"}, {"text": "祖母は器用にセーターを編んで、孫にプレゼントした。", "target_word": "器用", "complexity_tier": "T3", "furigana": "祖母[そぼ]は器用[きよう]にセーターを編[あ]んで、孫[まご]にプレゼントした。", "sentence_source": "generated"}, {"text": "あの料理人は器用な動きで、魚をあっという間にさばいた。", "target_word": "器用", "complexity_tier": "T3", "furigana": "あの料理人[りょうりにん]は器用[きよう]な動[うご]きで、魚[さかな]をあっという間[ま]にさばいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "器用だ", "label": "終止形"}, {"form": "器用な", "label": "連体形"}, {"form": "器用に", "label": "連用形"}, {"form": "器用で", "label": "て形"}, {"form": "器用ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "手や体を巧みに使って物を作ったり動かしたりできる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "器用", "is_correct": true, "explanation": "「器用な職人」は、木を削って人形を作るという技術の話に合う。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は物の華やかさを表し、職人の技術を述べる文脈に合わない。"}, {"text": "莫大", "is_correct": false, "explanation": "「莫大な職人」は規模の大きさを表し、職人の技術の説明には合わない。"}, {"text": "盛大", "is_correct": false, "explanation": "盛大は催しの規模を表し、職人の技術には合わない。"}], "explanations": {"器用": "「器用な職人」は、木を削って人形を作るという技術の話に合う。", "豪華": "豪華は物の華やかさを表し、職人の技術を述べる文脈に合わない。", "莫大": "「莫大な職人」は規模の大きさを表し、職人の技術の説明には合わない。", "盛大": "盛大は催しの規模を表し、職人の技術には合わない。"}, "sentence_index": 0, "correct_answer": "器用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は器用な声で、客席の隅まで響く大声を出した。", "explanation": "ここは〈声量〉の話。器用は手わざの巧みさを指し、声の大きさには使わない。"}, {"text": "彼は器用な知識で、歴史の質問に何でも答える。", "explanation": "ここは〈博識〉の意味。器用は手や体の技の巧みさを指し、知っていることの多さには使わない。"}, {"text": "彼の器用な体は、どんな厳しい練習にも耐える。", "explanation": "ここは〈強靭〉の意味。器用は技の巧みさを指し、体の丈夫さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器用", "is_correct": true, "explanation": "「手先が器用な子ども」は、粘土で動物を作る話と合う。"}, {"text": "寡黙", "is_correct": false, "explanation": "寡黙は口数が少ないことを表し、手先の話に合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るい性格を表し、手先の器用さの説明に合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "頑固は意地を張る性格を表し、粘土で動物を作る話に合わない。"}], "explanations": {"器用": "「手先が器用な子ども」は、粘土で動物を作る話と合う。", "寡黙": "寡黙は口数が少ないことを表し、手先の話に合わない。", "陽気": "陽気は明るい性格を表し、手先の器用さの説明に合わない。", "頑固": "頑固は意地を張る性格を表し、粘土で動物を作る話に合わない。"}, "sentence_index": 6, "correct_answer": "器用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は器用に正確で、一日一分も狂わない。", "explanation": "ここは〈精密さ〉の話。器用は人の手わざの巧みさを指し、機械の正確さには使わない。"}, {"text": "彼は器用な態度で、大勢の前でも堂々と話した。", "explanation": "ここは〈冷静〉の意味。器用は手わざの巧みさを指し、心の落ち着きは指さない。"}, {"text": "彼は器用な笑いで、部屋中を沸かせた。", "explanation": "ここは〈豪快〉の意味。器用は手わざの巧みさを指し、笑いの大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は足先でボールを器用操り、ゴールを決めた。", "corrected_sentence": "彼は足先でボールを器用に操り、ゴールを決めた。", "error_description": "「器用」は形容動詞で、動詞「操り」を修飾するには連用形「に」が必要。「に」が抜けている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "器用", "is_correct": true, "explanation": "「足先でボールを＿に操り」の空欄に入るのは語幹の「器用」。"}, {"text": "器用な", "is_correct": false, "explanation": "連体形で、「に操り」の前には入らない。"}, {"text": "器用で", "is_correct": false, "explanation": "て形で、「に操り」と続かない。"}, {"text": "器用ではない", "is_correct": false, "explanation": "否定形で、「に操り」の文脈に合わない。"}], "correct_form": "器用", "base_form": "器用だ", "form_label": "語幹（に の前）", "sentence_index": 1, "explanations": {"器用": "「足先でボールを＿に操り」の空欄に入るのは語幹の「器用」。", "器用な": "連体形で、「に操り」の前には入らない。", "器用で": "て形で、「に操り」と続かない。", "器用ではない": "否定形で、「に操り」の文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は手先が器用くて、ボールを正確に投げた。", "corrected_sentence": "彼は手先が器用で、ボールを正確に投げた。", "error_description": "「器用」は形容動詞なので、中止の形は「器用で」。「器用くて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "器用", "is_correct": true, "explanation": "「片手で＿にコーヒーを注ぎ」の空欄に入るのは語幹の「器用」。"}, {"text": "器用だ", "is_correct": false, "explanation": "終止形で、「にコーヒー」とは続かない。空欄には語幹の「器用」が入る。"}, {"text": "器用だった", "is_correct": false, "explanation": "過去形で、「に注ぎ」の前には入らない。"}, {"text": "器用じゃない", "is_correct": false, "explanation": "否定形で、「にコーヒー」と続く文脈に合わない。"}], "correct_form": "器用", "base_form": "器用だ", "form_label": "語幹（に の前）", "sentence_index": 7, "explanations": {"器用": "「片手で＿にコーヒーを注ぎ」の空欄に入るのは語幹の「器用」。", "器用だ": "終止形で、「にコーヒー」とは続かない。空欄には語幹の「器用」が入る。", "器用だった": "過去形で、「に注ぎ」の前には入らない。", "器用じゃない": "否定形で、「にコーヒー」と続く文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不器用", "is_correct": true, "explanation": "不器用は器用の対義語で、手先の巧みさがないことを表す。"}, {"text": "丁寧", "is_correct": false, "explanation": "丁寧は仕事ぶりの細やかさを表し、手先の巧みさの反対語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は思い切りのよさを表し、器用の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速は動作の速さを表し、器用の反対語ではない。"}], "correct_answer": "不器用", "explanations": {"不器用": "不器用は器用の対義語で、手先の巧みさがないことを表す。", "丁寧": "丁寧は仕事ぶりの細やかさを表し、手先の巧みさの反対語ではない。", "大胆": "大胆は思い切りのよさを表し、器用の反対語ではない。", "迅速": "迅速は動作の速さを表し、器用の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不器用", "is_correct": true, "explanation": "不器用は器用の対義語で、「器用にこなす」の反対の意味を表す。"}, {"text": "慎重", "is_correct": false, "explanation": "慎重は用心深さを表し、器用の反対語ではない。"}, {"text": "寛大", "is_correct": false, "explanation": "寛大は心が広いことを表し、器用の反対語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は動きが盛んなことを表し、器用の反対語ではない。"}], "correct_answer": "不器用", "explanations": {"不器用": "不器用は器用の対義語で、「器用にこなす」の反対の意味を表す。", "慎重": "慎重は用心深さを表し、器用の反対語ではない。", "寛大": "寛大は心が広いことを表し、器用の反対語ではない。", "活発": "活発は動きが盛んなことを表し、器用の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "手先が器用で、物事を巧みに行うことができる様子。また、そのような能力があること。", "primary_collocate": null, "pronunciation": "きよう", "ipa": "kijoː", "syllable_count": 3, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "器用", "complexity_tier": "T4", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "妹は手先が器用で、折り紙で何でも作ってしまう。", "target_word": "器用", "complexity_tier": "T3", "furigana": "妹[いもうと]は手先[てさき]が器用[きよう]で、折[お]り紙[がみ]で何[なん]でも作[つく]ってしまう。", "sentence_source": "generated"}, {"text": "彼は器用な人だから、料理も修理も一人でこなす。", "target_word": "器用", "complexity_tier": "T3", "furigana": "彼[かれ]は器用[きよう]な人[ひと]だから、料理[りょうり]も修理[しゅうり]も一人[ひとり]でこなす。", "sentence_source": "generated"}, {"text": "祖父は器用に包丁を使って、りんごの皮を長くむいた。", "target_word": "器用", "complexity_tier": "T3", "furigana": "祖父[そふ]は器用[きよう]に包丁[ほうちょう]を使[つか]って、りんごの皮[かわ]を長[なが]くむいた。", "sentence_source": "generated"}, {"text": "私は器用ではないので、細かい作業は苦手だ。", "target_word": "器用", "complexity_tier": "T3", "furigana": "私[わたし]は器用[きよう]ではないので、細[こま]かい作業[さぎょう]は苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "器用に立ち回る兄は、どんな職場でもすぐに慣れる。", "target_word": "器用", "complexity_tier": "T3", "furigana": "器用[きよう]に立[た]ち回[まわ]る兄[あに]は、どんな職場[しょくば]でもすぐに慣[な]れる。", "sentence_source": "generated"}, {"text": "あの子は器用で、一度見ただけでダンスを覚えてしまった。", "target_word": "器用", "complexity_tier": "T3", "furigana": "あの子[こ]は器用[きよう]で、一度[いちど]見[み]ただけでダンスを覚[おぼ]えてしまった。", "sentence_source": "generated"}, {"text": "彼女は器用な手つきで、小さなボタンを縫いつけた。", "target_word": "器用", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は器用[きよう]な手[て]つきで、小[ちい]さなボタンを縫[ぬ]いつけた。", "sentence_source": "generated"}, {"text": "器用なだけでなく、仕事も丁寧なので、みんなに信頼されている。", "target_word": "器用", "complexity_tier": "T3", "furigana": "器用[きよう]なだけでなく、仕事[しごと]も丁寧[ていねい]なので、みんなに信頼[しんらい]されている。", "sentence_source": "generated"}, {"text": "弟は何でも器用にこなすが、本人は努力しているそうだ。", "target_word": "器用", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なん]でも器用[きよう]にこなすが、本人[ほんにん]は努力[どりょく]しているそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "器用だ", "label": "終止形"}, {"form": "器用な", "label": "連体形"}, {"form": "器用に", "label": "連用形"}, {"form": "器用で", "label": "て形"}, {"form": "器用ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "手先や要領がよく、物事を巧みにこなせる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "器用", "is_correct": true, "explanation": "「彼は＿な手つきで」の空欄に入るのは「器用」だけで、器用な手つきになる。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な手つき」は明るい性格を表し、手先の技術の説明には合わない。"}, {"text": "寡黙", "is_correct": false, "explanation": "「寡黙な手つき」は口数の少なさを表し、手の動きには合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "「頑固な手つき」は意地を張る性格を表し、修理の技術には合わない。"}], "explanations": {"器用": "「彼は＿な手つきで」の空欄に入るのは「器用」だけで、器用な手つきになる。", "陽気": "「陽気な手つき」は明るい性格を表し、手先の技術の説明には合わない。", "寡黙": "「寡黙な手つき」は口数の少なさを表し、手の動きには合わない。", "頑固": "「頑固な手つき」は意地を張る性格を表し、修理の技術には合わない。"}, "sentence_index": 0, "correct_answer": "器用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は器用なので、重いベンチプレスを百回も上げられる。", "explanation": "ここは〈力の強さ〉の話。器用は手先や技の巧みさを指し、筋力には使わない。"}, {"text": "彼は器用が大きいので、どんな大役も任せられる。", "explanation": "ここは〈器量〉（人の能力や度量）の意味。器用は技の巧みさを指し、人の度量の大きさには使わない。"}, {"text": "彼は器用なので、いつも会議に遅刻してくる。", "explanation": "ここは〈時間にルーズ〉の意味。器用は手わざの巧みさを指し、時間の管理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器用", "is_correct": true, "explanation": "「器用で」は、一度見ただけで覚えた話と合う。"}, {"text": "臆病", "is_correct": false, "explanation": "臆病は怖がりな性格を表し、一度見ただけで覚えたという文脈に合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "退屈は飽きている様子を表し、ダンスを覚えた話に合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "頑固は意地を張る性格を表し、すぐ覚えた話に合わない。"}], "explanations": {"器用": "「器用で」は、一度見ただけで覚えた話と合う。", "臆病": "臆病は怖がりな性格を表し、一度見ただけで覚えたという文脈に合わない。", "退屈": "退屈は飽きている様子を表し、ダンスを覚えた話に合わない。", "頑固": "頑固は意地を張る性格を表し、すぐ覚えた話に合わない。"}, "sentence_index": 6, "correct_answer": "器用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の天気は器用に晴れるでしょう。", "explanation": "ここは〈天候〉の話。器用は人の手わざの巧みさを指し、天候には使わない。"}, {"text": "このテーブルは器用で、大人が乗っても壊れない。", "explanation": "ここは〈頑丈〉の意味。器用は手先や技の巧みさを指し、物の丈夫さには使わない。"}, {"text": "この部屋は器用で、物音ひとつしない。", "explanation": "ここは〈静けさ〉の意味。器用は手わざの巧みさを指し、物音の少なさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は器用の手で、家族のために料理を作った。", "corrected_sentence": "彼は器用な手で、家族のために料理を作った。", "error_description": "「器用」は形容動詞なので、名詞「手」を修飾するときは「な」を使う。「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "器用", "is_correct": true, "explanation": "「手先が＿で」の空欄に入るのは語幹の「器用」。"}, {"text": "器用な", "is_correct": false, "explanation": "連体形で、「手先が＿で」の「で」の前には入らない。"}, {"text": "器用に", "is_correct": false, "explanation": "連用形で、「で」の位置には合わない。"}, {"text": "器用ではない", "is_correct": false, "explanation": "否定形で、「手先が＿で」の文には入らない。"}], "correct_form": "器用", "base_form": "器用だ", "form_label": "語幹（で の前）", "sentence_index": 1, "explanations": {"器用": "「手先が＿で」の空欄に入るのは語幹の「器用」。", "器用な": "連体形で、「手先が＿で」の「で」の前には入らない。", "器用に": "連用形で、「で」の位置には合わない。", "器用ではない": "否定形で、「手先が＿で」の文には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52421, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの選手は足を器用な使って、ボールを正確に運んだ。", "corrected_sentence": "あの選手は足を器用に使って、ボールを正確に運んだ。", "error_description": "「器用」は後の動詞「使って」を修飾するので連用形「に」が必要。「な」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "器用", "is_correct": true, "explanation": "「彼女は＿な手つき」の空欄に入るのは語幹の「器用」。"}, {"text": "器用に", "is_correct": false, "explanation": "連用形で、「な手つき」の前には入らない。"}, {"text": "器用で", "is_correct": false, "explanation": "て形で、「＿な手つき」とは続かない。"}, {"text": "器用だ", "is_correct": false, "explanation": "終止形で、「な手つき」の前には入らない。"}], "correct_form": "器用", "base_form": "器用だ", "form_label": "語幹（な の前）", "sentence_index": 7, "explanations": {"器用": "「彼女は＿な手つき」の空欄に入るのは語幹の「器用」。", "器用に": "連用形で、「な手つき」の前には入らない。", "器用で": "て形で、「＿な手つき」とは続かない。", "器用だ": "終止形で、「な手つき」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
