INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52422, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他のことに気を取られず、一つのことに集中していること。特に「余念がない」の形で用いられる。", "primary_collocate": "ない", "pronunciation": "よねん", "ipa": "joneɴ", "syllable_count": 3, "sentences": [{"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "余念", "complexity_tier": "T4", "furigana": "厳冬[げんとう]の冷[つめ]たさなど意[い]に介[かい]さず、ただ純粋[じゅんすい]に外[そと]で遊[あそ]ぶための準備[じゅんび]に余念[よねん]がないのだ。", "sentence_source": "mined"}, {"text": "兄は試験が近いので、勉強に余念がない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "兄[あに]は試験[しけん]が近[ちか]いので、勉強[べんきょう]に余念[よねん]がない。", "sentence_source": "generated"}, {"text": "彼女は新しい店の開店準備に余念がなかった。", "target_word": "余念", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新[あたら]しい店[みせ]の開店[かいてん]準備[じゅんび]に余念[よねん]がなかった。", "sentence_source": "generated"}, {"text": "選手たちは大会に向けて、練習に余念がない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは大会[たいかい]に向[む]けて、練習[れんしゅう]に余念[よねん]がない。", "sentence_source": "generated"}, {"text": "母は庭の花の手入れに余念がなく、毎朝早く起きている。", "target_word": "余念", "complexity_tier": "T3", "furigana": "母[はは]は庭[にわ]の花[はな]の手入[ていれ]れに余念[よねん]がなく、毎朝[まいあさ]早[はや]く起[お]きている。", "sentence_source": "generated"}, {"text": "秋になり、農家の人たちは収穫の作業に余念がない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "秋[あき]になり、農家[のうか]の人[ひと]たちは収穫[しゅうかく]の作業[さぎょう]に余念[よねん]がない。", "sentence_source": "generated"}, {"text": "彼は発表の資料作りに余念がなく、昼食も取らなかった。", "target_word": "余念", "complexity_tier": "T3", "furigana": "彼[かれ]は発表[はっぴょう]の資料[しりょう]作[づく]りに余念[よねん]がなく、昼食[ちゅうしょく]も取[と]らなかった。", "sentence_source": "generated"}, {"text": "犬は骨をかじることに余念がなく、呼んでも振り向かない。", "target_word": "余念", "complexity_tier": "T3", "furigana": "犬[いぬ]は骨[ほね]をかじることに余念[よねん]がなく、呼[よ]んでも振[ふ]り向[む]かない。", "sentence_source": "generated"}, {"text": "店長は客を迎える飾りつけに余念がなかった。", "target_word": "余念", "complexity_tier": "T3", "furigana": "店長[てんちょう]は客[きゃく]を迎[むか]える飾[かざ]りつけに余念[よねん]がなかった。", "sentence_source": "generated"}, {"text": "子どもたちは雪だるま作りに余念がなく、寒さも忘れていた。", "target_word": "余念", "complexity_tier": "T3", "furigana": "子[こ]どもたちは雪[ゆき]だるま作[づく]りに余念[よねん]がなく、寒[さむ]さも忘[わす]れていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余念", "label": "名詞"}, {"form": "余念がない", "label": "慣用表現(終止形)"}, {"form": "余念がなかった", "label": "過去形"}, {"form": "余念がなく", "label": "連用形"}, {"form": "余念なく", "label": "連用形(が省略)"}], "register": "neutral", "sense_fingerprint": "「余念がない」で、他に気を取られず一つのことに没頭している", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84b054-da4c-44f2-903a-49bbf539d1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余念", "is_correct": true, "explanation": "「準備に＿がないのだ」の空欄に入るのは「余念」だけで、「余念がない」の形になる。"}, {"text": "天気", "is_correct": false, "explanation": "「準備に天気がない」は意味が通らず、空欄に入らない。"}, {"text": "寝床", "is_correct": false, "explanation": "「準備に寝床がない」は文脈に合わず、空欄に入らない。"}, {"text": "手袋", "is_correct": false, "explanation": "「準備に手袋がない」は意味が通らず、空欄に入らない。"}], "explanations": {"余念": "「準備に＿がないのだ」の空欄に入るのは「余念」だけで、「余念がない」の形になる。", "天気": "「準備に天気がない」は意味が通らず、空欄に入らない。", "寝床": "「準備に寝床がない」は文脈に合わず、空欄に入らない。", "手袋": "「準備に手袋がない」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "余念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は余念の資金で、新しい工場を建てた。", "explanation": "ここは〈余分〉の意味。余念は他のことに気を取られない状態を表し、金銭の余りは指さない。"}, {"text": "彼は仕事が早く終わったので、余念ができて映画を見に行った。", "explanation": "ここは〈余暇〉の意味。余念は一つのことに集中する状態で、空いた時間は指さない。"}, {"text": "選手たちは大会の後、余念に浸って、勝利の喜びを味わった。", "explanation": "ここは〈余韻〉の意味。余念は一つのことに集中する状態で、残った感情の響きは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余念", "is_correct": true, "explanation": "「資料作りに＿がなく」の空欄に入るのは「余念」だけで、「余念がなく」になる。"}, {"text": "雨粒", "is_correct": false, "explanation": "「資料作りに雨粒がなく」は意味が通らず、空欄に入らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「資料作りに夕焼けがなく」は文脈に合わず、空欄に入らない。"}, {"text": "風鈴", "is_correct": false, "explanation": "「資料作りに風鈴がなく」は意味が通らず、空欄に入らない。"}], "explanations": {"余念": "「資料作りに＿がなく」の空欄に入るのは「余念」だけで、「余念がなく」になる。", "雨粒": "「資料作りに雨粒がなく」は意味が通らず、空欄に入らない。", "夕焼け": "「資料作りに夕焼けがなく」は文脈に合わず、空欄に入らない。", "風鈴": "「資料作りに風鈴がなく」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "余念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食の余念を冷蔵庫に入れ、翌日の弁当に使った。", "explanation": "ここは〈残り物〉の意味。余念は他のことに気を取られない状態を表し、食べ物の余りには使わない。"}, {"text": "この紙は余念が少なくて、文字が詰まっている。", "explanation": "ここは〈余白〉の意味。余念は一つのことに集中する状態で、紙の空いた部分は指さない。"}, {"text": "オーブンの余念で、パンがさらに焼けた。", "explanation": "ここは〈余熱〉の意味。余念は一つのことに集中する状態で、残った熱は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は勉強で余念がなく、夜遅くまで本を読んだ。", "corrected_sentence": "彼は勉強に余念がなく、夜遅くまで本を読んだ。", "error_description": "「余念がない」は「〜に余念がない」と「に」で対象を示す。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は車の整備に余念がなかで、休日も工具を握っている。", "corrected_sentence": "父は車の整備に余念がなく、休日も工具を握っている。", "error_description": "「余念がない」の連用形は「なく」。「なかで」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45341808-9bc2-4590-b18a-2def7e2d25ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "厚みが小さいことを表し、〈分厚く〉切るの対義語として辞書に載る。"}, {"text": "明るい", "is_correct": false, "explanation": "明るいは光の多さを表し、厚みの反対語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "軽いは重さが少ないことを表し、厚みとは別の性質を指す。"}, {"text": "狭い", "is_correct": false, "explanation": "狭いは面積や間隔が小さいことを表し、厚みの反対語ではない。"}], "correct_answer": "薄い", "explanations": {"薄い": "厚みが小さいことを表し、〈分厚く〉切るの対義語として辞書に載る。", "明るい": "明るいは光の多さを表し、厚みの反対語ではない。", "軽い": "軽いは重さが少ないことを表し、厚みとは別の性質を指す。", "狭い": "狭いは面積や間隔が小さいことを表し、厚みの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。"}, {"text": "明るい", "is_correct": false, "explanation": "明るいは光の多さを表し、厚みの反対語ではない。"}, {"text": "固い", "is_correct": false, "explanation": "固いは硬さを表し、厚さの反対語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広いは面積や幅が大きいことを表し、厚さとは別の性質を指す。"}], "correct_answer": "薄い", "explanations": {"薄い": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。", "明るい": "明るいは光の多さを表し、厚みの反対語ではない。", "固い": "固いは硬さを表し、厚さの反対語ではない。", "広い": "広いは面積や幅が大きいことを表し、厚さとは別の性質を指す。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ものがとてもあついこと。", "primary_collocate": null, "pronunciation": "ぶあつい", "ipa": "bɯ.a.tsɯ.i", "syllable_count": 4, "sentences": [{"text": "彼女は分厚い封筒を受け取り、中に入った書類の多さに驚いた。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は分厚[ぶあつ]い封筒[ふうとう]を受[う]け取[と]り、中[なか]に入[はい]った書類[しょるい]の多[おお]さに驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "寒い朝は、分厚い靴下を二枚はいて学校へ行く。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、分厚[ぶあつ]い靴下[くつした]を二枚[にまい]はいて学校[がっこう]へ行[い]く。", "sentence_source": "generated"}, {"text": "兄は分厚い手袋をはめて、雪かきを始めた。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "兄[あに]は分厚[ぶあつ]い手袋[てぶくろ]をはめて、雪[ゆき]かきを始[はじ]めた。", "sentence_source": "generated"}, {"text": "このハムは分厚く切ってあるので、食べごたえがある。", "target_word": "分厚く", "complexity_tier": "T3", "furigana": "このハムは分厚[ぶあつ]く切[き]ってあるので、食[た]べごたえがある。", "sentence_source": "generated"}, {"text": "古い城の門は分厚い木でできていて、簡単には壊せない。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]の門[もん]は分厚[ぶあつ]い木[き]でできていて、簡単[かんたん]には壊[こわ]せない。", "sentence_source": "generated"}, {"text": "分厚い布団をかけて寝たら、暑くて夜中に目が覚めた。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "分厚[ぶあつ]い布団[ふとん]をかけて寝[ね]たら、暑[あつ]くて夜中[よなか]に目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "彼の分厚い胸は、毎日の訓練で鍛えられたものだ。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "彼[かれ]の分厚[ぶあつ]い胸[むね]は、毎日[まいにち]の訓練[くんれん]で鍛[きた]えられたものだ。", "sentence_source": "generated"}, {"text": "母は分厚い雑誌をテーブルに置き、旅行の記事を探した。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "母[はは]は分厚[ぶあつ]い雑誌[ざっし]をテーブルに置[お]き、旅行[りょこう]の記事[きじ]を探[さが]した。", "sentence_source": "generated"}, {"text": "パンを分厚く切りすぎて、トースターに入らなかった。", "target_word": "分厚く", "complexity_tier": "T3", "furigana": "パンを分厚[ぶあつ]く切[き]りすぎて、トースターに入[はい]らなかった。", "sentence_source": "generated"}, {"text": "この本は分厚いわりに、文字が大きくて読みやすい。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "この本[ほん]は分厚[ぶあつ]いわりに、文字[もじ]が大[おお]きくて読[よ]みやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分厚い", "label": "終止形・連体形"}, {"form": "分厚く", "label": "連用形"}, {"form": "分厚かった", "label": "過去形"}, {"form": "分厚くない", "label": "否定形"}, {"form": "分厚ければ", "label": "仮定形"}], "register": "中立（普通体）", "sense_fingerprint": "封筒・靴下・木・布団などの物が非常に厚い様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "書類が多い状況に合う、厚みのある封筒を表す。"}, {"text": "薄い", "is_correct": false, "explanation": "薄い封筒では書類の多さに驚く理由がなく、文脈と矛盾する。"}, {"text": "軽い", "is_correct": false, "explanation": "軽い封筒は書類が多い状況と合わず、驚きの理由にならない。"}, {"text": "冷たい", "is_correct": false, "explanation": "冷たさは封筒の中身の量と関係なく、驚きの文脈に合わない。"}], "explanations": {"分厚い": "書類が多い状況に合う、厚みのある封筒を表す。", "薄い": "薄い封筒では書類の多さに驚く理由がなく、文脈と矛盾する。", "軽い": "軽い封筒は書類が多い状況と合わず、驚きの理由にならない。", "冷たい": "冷たさは封筒の中身の量と関係なく、驚きの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "分厚い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は分厚い考えを持って、決断した。", "explanation": "ここは〈深い〉の意味（思考が深いこと）。考えの深さには分厚いを使わず、分厚いは物の厚みに限られる。"}, {"text": "彼は分厚い道のりを歩き通した。", "explanation": "ここは〈長い〉の意味（距離が長いこと）。距離には分厚いを使わない。"}, {"text": "分厚い声で、彼は堂々と話した。", "explanation": "ここは〈太い〉の意味（低く力強い声）。声には分厚いを使わず、太いで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "鍛えて厚くなった胸を表し、毎日の訓練の結果と合う。"}, {"text": "細い", "is_correct": false, "explanation": "細い胸は鍛錬の結果として語るには合わず、文脈と結びつかない。"}, {"text": "白い", "is_correct": false, "explanation": "胸の色は鍛えられた状態と無関係で、文脈に合わない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "鍛えられた胸は硬く締まっているので、柔らかいと矛盾する。"}], "explanations": {"分厚い": "鍛えて厚くなった胸を表し、毎日の訓練の結果と合う。", "細い": "細い胸は鍛錬の結果として語るには合わず、文脈と結びつかない。", "白い": "胸の色は鍛えられた状態と無関係で、文脈に合わない。", "柔らかい": "鍛えられた胸は硬く締まっているので、柔らかいと矛盾する。"}, "sentence_index": 6, "correct_answer": "分厚い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は分厚い責任を一人で背負い込んでいた。", "explanation": "ここは〈重い〉の意味（負担が大きいこと）。責任の重さには分厚いを使わず、重いで表す。"}, {"text": "彼の意見は分厚くて、誰も納得しなかった。", "explanation": "ここは〈重みのある・中身が充実した〉の意味。意見の中身には分厚いを使わず、分厚いは物の厚みに限られる。"}, {"text": "湯のみに分厚いお茶を入れた。", "explanation": "ここは〈濃い〉の意味（味や色が濃いこと）。お茶の濃さには分厚いを使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その封筒は分厚いかったが、中身は少なかった。", "corrected_sentence": "その封筒は分厚かったが、中身は少なかった。", "error_description": "形容詞の過去形は「分厚かった」。語幹に「かった」を付けるので、「分厚いかった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "名詞「靴下」を直接修飾する連体形で、ここに入る形。"}, {"text": "分厚く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「分厚く靴下」とは続かない。"}, {"text": "分厚くて", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「分厚くて靴下」とは続かない。"}, {"text": "分厚ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「分厚ければ靴下」は文法的に成り立たない。"}], "correct_form": "分厚い", "base_form": "分厚い", "form_label": "連体形", "sentence_index": 1, "explanations": {"分厚い": "名詞「靴下」を直接修飾する連体形で、ここに入る形。", "分厚く": "連用形は名詞を直接修飾できず、「分厚く靴下」とは続かない。", "分厚くて": "て形は名詞を直接修飾できず、「分厚くて靴下」とは続かない。", "分厚ければ": "仮定形は名詞を修飾できず、「分厚ければ靴下」は文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この百科事典は分厚いの本で、調べ物に便利だ。", "corrected_sentence": "この百科事典は分厚い本で、調べ物に便利だ。", "error_description": "連体修飾の「分厚い」に「の」を付けた誤り。名詞「本」には「分厚い本」と直接続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "名詞「雑誌」を直接修飾する連体形で、ここに入る形。"}, {"text": "分厚さ", "is_correct": false, "explanation": "名詞形で、「分厚さ雑誌」とは直接続かない。"}, {"text": "分厚かろう", "is_correct": false, "explanation": "推量形は名詞を直接修飾できず、「分厚かろう雑誌」は成り立たない。"}, {"text": "分厚くても", "is_correct": false, "explanation": "逆接の形は名詞を直接修飾できず、「分厚くても雑誌」は成り立たない。"}], "correct_form": "分厚い", "base_form": "分厚い", "form_label": "連体形", "sentence_index": 7, "explanations": {"分厚い": "名詞「雑誌」を直接修飾する連体形で、ここに入る形。", "分厚さ": "名詞形で、「分厚さ雑誌」とは直接続かない。", "分厚かろう": "推量形は名詞を直接修飾できず、「分厚かろう雑誌」は成り立たない。", "分厚くても": "逆接の形は名詞を直接修飾できず、「分厚くても雑誌」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。"}, {"text": "明るい", "is_correct": false, "explanation": "明るいは光の多さを表し、厚みの反対語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "軽いは重さが少ないことを表し、厚みとは別の性質を指す。"}, {"text": "狭い", "is_correct": false, "explanation": "狭いは面積や間隔が小さいことを表し、厚みの反対語ではない。"}], "correct_answer": "薄い", "explanations": {"薄い": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。", "明るい": "明るいは光の多さを表し、厚みの反対語ではない。", "軽い": "軽いは重さが少ないことを表し、厚みとは別の性質を指す。", "狭い": "狭いは面積や間隔が小さいことを表し、厚みの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄い", "is_correct": true, "explanation": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。"}, {"text": "明るい", "is_correct": false, "explanation": "明るいは光の多さを表し、厚みの反対語ではない。"}, {"text": "固い", "is_correct": false, "explanation": "固いは硬さを表し、厚さの反対語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広いは面積や幅が大きいことを表し、厚さとは別の性質を指す。"}], "correct_answer": "薄い", "explanations": {"薄い": "厚みが小さいことを表し、〈分厚い〉の対義語として辞書に載る。", "明るい": "明るいは光の多さを表し、厚みの反対語ではない。", "固い": "固いは硬さを表し、厚さの反対語ではない。", "広い": "広いは面積や幅が大きいことを表し、厚さとは別の性質を指す。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "厚みが大きく、普通より厚いこと。", "primary_collocate": null, "pronunciation": "ぶあつい", "ipa": "bɯ.a.tsɯ.i", "syllable_count": 4, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "図書館で、辞書のように分厚い本を借りたが、重くて持ち歩けない。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "図書館[としょかん]で、辞書[じしょ]のように分厚[ぶあつ]い本[ほん]を借[か]りたが、重[おも]くて持[も]ち歩[ある]けない。", "sentence_source": "generated"}, {"text": "冬は寒いので、分厚いセーターを着て出かける。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]いので、分厚[ぶあつ]いセーターを着[き]て出[で]かける。", "sentence_source": "generated"}, {"text": "彼は分厚い手帳を開き、来週の予定を一つずつ確認した。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "彼[かれ]は分厚[ぶあつ]い手帳[てちょう]を開[ひら]き、来週[らいしゅう]の予定[よてい]を一[ひと]つずつ確認[かくにん]した。", "sentence_source": "generated"}, {"text": "分厚いステーキを焼いたら、中まで火が通るのに時間がかかった。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "分厚[ぶあつ]いステーキを焼[や]いたら、中[なか]まで火[ひ]が通[とお]るのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "雪が降る前に、分厚いカーテンを窓につけて冷気を防いだ。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]る前[まえ]に、分厚[ぶあつ]いカーテンを窓[まど]につけて冷気[れいき]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "この壁は分厚いので、隣の部屋の音がほとんど聞こえない。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "この壁[かべ]は分厚[ぶあつ]いので、隣[となり]の部屋[へや]の音[おと]がほとんど聞[き]こえない。", "sentence_source": "generated"}, {"text": "祖父は分厚い眼鏡をかけているため、目が小さく見える。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "祖父[そふ]は分厚[ぶあつ]い眼鏡[めがね]をかけているため、目[め]が小[ちい]さく見[み]える。", "sentence_source": "generated"}, {"text": "分厚い雲が空を覆い、昼なのに夕方のように暗い。", "target_word": "分厚い", "complexity_tier": "T3", "furigana": "分厚[ぶあつ]い雲[くも]が空[そら]を覆[おお]い、昼[ひる]なのに夕方[ゆうがた]のように暗[くら]い。", "sentence_source": "generated"}, {"text": "その小説は分厚かったが、面白くて一日で読み終えた。", "target_word": "分厚かった", "complexity_tier": "T3", "furigana": "その小説[しょうせつ]は分厚[ぶあつ]かったが、面白[おもしろ]くて一日[いちにち]で読[よ]み終[お]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分厚い", "label": "終止形・連体形"}, {"form": "分厚く", "label": "連用形"}, {"form": "分厚かった", "label": "過去形"}, {"form": "分厚くない", "label": "否定形"}, {"form": "分厚ければ", "label": "仮定形"}], "register": "中立（普通体）", "sense_fingerprint": "本・布・壁などの厚みが普通より大きい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "冷気を防ぐ鎧の文脈に合う、厚みのあるコートを表す。"}, {"text": "薄い", "is_correct": false, "explanation": "薄いコートでは冷気を防げず、「身を守るための鎧」という文脈と矛盾する。"}, {"text": "軽い", "is_correct": false, "explanation": "軽さは防寒の役割と結びつかず、鎧という文脈に合わない。"}, {"text": "涼しい", "is_correct": false, "explanation": "涼しいコートは冷気から守る目的と逆の性質なので、文脈に合わない。"}], "explanations": {"分厚い": "冷気を防ぐ鎧の文脈に合う、厚みのあるコートを表す。", "薄い": "薄いコートでは冷気を防げず、「身を守るための鎧」という文脈と矛盾する。", "軽い": "軽さは防寒の役割と結びつかず、鎧という文脈に合わない。", "涼しい": "涼しいコートは冷気から守る目的と逆の性質なので、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "分厚い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は分厚いコーヒーを飲んで、眠気を覚ました。", "explanation": "ここは〈濃い〉の意味。液体の濃さには分厚いを使わず、コーヒーの濃さは〈濃い〉で表す。"}, {"text": "彼は分厚い勉強を重ねて、試験に合格した。", "explanation": "ここは〈熱心な・集中的な〉の意味。勉強の熱心さには分厚いを使わず、分厚いは物の厚みに限られる。"}, {"text": "彼は分厚い悲しみに沈んでいた。", "explanation": "ここは〈深い〉の意味。感情の深さには分厚いを使わず、分厚いは物の厚みを表す語だ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "厚い壁は音を遮るので、音が聞こえない理由として成り立つ。"}, {"text": "白い", "is_correct": false, "explanation": "壁の色は音の遮断と無関係で、「聞こえない」の理由にならない。"}, {"text": "明るい", "is_correct": false, "explanation": "明るさは音を遮らないので、「聞こえない」の理由として成り立たない。"}, {"text": "赤い", "is_correct": false, "explanation": "壁の色が赤いことは音を遮る理由にならず、文脈に合わない。"}], "explanations": {"分厚い": "厚い壁は音を遮るので、音が聞こえない理由として成り立つ。", "白い": "壁の色は音の遮断と無関係で、「聞こえない」の理由にならない。", "明るい": "明るさは音を遮らないので、「聞こえない」の理由として成り立たない。", "赤い": "壁の色が赤いことは音を遮る理由にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "分厚い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で分厚い間、待っていた。", "explanation": "ここは〈長い〉の意味（時間が長いこと）。時間の長さには分厚いを使わず、分厚いは物の厚みに限られる。"}, {"text": "その館は分厚い雰囲気に包まれていた。", "explanation": "ここは〈重厚〉の意味（落ち着いた重々しさ）。雰囲気には分厚いを使わず、重厚で表す。"}, {"text": "分厚い道を大型トラックが走っていく。", "explanation": "ここは〈太い〉の意味（道幅が広いこと）。道幅には分厚いを使わず、太いで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この辞書は分厚いくて、持ち運ぶのが大変だ。", "corrected_sentence": "この辞書は分厚くて、持ち運ぶのが大変だ。", "error_description": "形容詞の連用形は「分厚く」で、「て」を続けると「分厚くて」になる。「分厚いくて」は語幹に「い」を残した誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "名詞「本」を直接修飾する連体形で、ここに入る形。"}, {"text": "分厚く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「分厚く本」とは続かない。"}, {"text": "分厚くて", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「分厚くて本」とは続かない。"}, {"text": "分厚ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「分厚ければ本を借りた」は文法的に成り立たない。"}], "correct_form": "分厚い", "base_form": "分厚い", "form_label": "連体形", "sentence_index": 1, "explanations": {"分厚い": "名詞「本」を直接修飾する連体形で、ここに入る形。", "分厚く": "連用形は名詞を直接修飾できず、「分厚く本」とは続かない。", "分厚くて": "て形は名詞を直接修飾できず、「分厚くて本」とは続かない。", "分厚ければ": "仮定形は名詞を修飾できず、「分厚ければ本を借りた」は文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は分厚いの眼鏡をかけていて、目が小さく見える。", "corrected_sentence": "祖父は分厚い眼鏡をかけていて、目が小さく見える。", "error_description": "連体修飾の「分厚い」に「の」を付けた誤り。名詞「眼鏡」には「分厚い眼鏡」と直接続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "分厚い", "is_correct": true, "explanation": "名詞「眼鏡」を直接修飾する連体形で、ここに入る形。"}, {"text": "分厚さ", "is_correct": false, "explanation": "名詞形で、「分厚さ眼鏡」とは直接続かない。"}, {"text": "分厚かろう", "is_correct": false, "explanation": "推量形は名詞を直接修飾できず、「分厚かろう眼鏡」は成り立たない。"}, {"text": "分厚くても", "is_correct": false, "explanation": "逆接の形は名詞を直接修飾できず、「分厚くても眼鏡」は成り立たない。"}], "correct_form": "分厚い", "base_form": "分厚い", "form_label": "連体形", "sentence_index": 7, "explanations": {"分厚い": "名詞「眼鏡」を直接修飾する連体形で、ここに入る形。", "分厚さ": "名詞形で、「分厚さ眼鏡」とは直接続かない。", "分厚かろう": "推量形は名詞を直接修飾できず、「分厚かろう眼鏡」は成り立たない。", "分厚くても": "逆接の形は名詞を直接修飾できず、「分厚くても眼鏡」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「袖に」は、ボタンを付ける場所を示し、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「袖が」は主語を示すが、袖がボタンを付けるという動作は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「袖で」は手段を示すので、袖を場所とする文の意味と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「袖へ」は方向を示すが、ボタンを付ける場所としては不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「袖に」は、ボタンを付ける場所を示し、文の意味に合う。", "が": "「袖が」は主語を示すが、袖がボタンを付けるという動作は成り立たない。", "で": "「袖で」は手段を示すので、袖を場所とする文の意味と合わない。", "へ": "「袖へ」は方向を示すが、ボタンを付ける場所としては不自然になる。"}, "error_tags": {"が": "主格", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「袖が」は主語を示し、「袖がほつれていた」という状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「袖を」は目的語を示すが、ほつれるという状態の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「袖と」は共同を示し、ほつれる状態を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「袖に」は場所を示すが、ほつれる状態の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「袖が」は主語を示し、「袖がほつれていた」という状態を表す。", "を": "「袖を」は目的語を示すが、ほつれるという状態の主語にならない。", "と": "「袖と」は共同を示し、ほつれる状態を表せない。", "に": "「袖に」は場所を示すが、ほつれる状態の主語にはならない。"}, "error_tags": {"を": "目的格", "と": "相手・共同", "に": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "服の、腕を入れる部分のことです。", "primary_collocate": null, "pronunciation": "そで", "ipa": "so.de", "syllable_count": 2, "sentences": [{"text": "この上着は袖が長いので、手が隠れてしまう。", "target_word": "袖", "complexity_tier": "T3", "furigana": "この上着[うわぎ]は袖[そで]が長[なが]いので、手[て]が隠[かく]れてしまう。", "sentence_source": "generated"}, {"text": "母は私のシャツの袖にボタンをつけてくれた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]のシャツの袖[そで]にボタンをつけてくれた。", "sentence_source": "generated"}, {"text": "洗い物をする前に、袖をまくった。", "target_word": "袖", "complexity_tier": "T3", "furigana": "洗[あら]い物[もの]をする前[まえ]に、袖[そで]をまくった。", "sentence_source": "generated"}, {"text": "袖のないワンピースは、夏に着ると涼しい。", "target_word": "袖", "complexity_tier": "T3", "furigana": "袖[そで]のないワンピースは、夏[なつ]に着[き]ると涼[すず]しい。", "sentence_source": "generated"}, {"text": "赤いセーターの袖から、白いシャツが少し見えている。", "target_word": "袖", "complexity_tier": "T3", "furigana": "赤[あか]いセーターの袖[そで]から、白[しろ]いシャツが少[すこ]し見[み]えている。", "sentence_source": "generated"}, {"text": "弟は寒い日に袖の中に手を入れて、温めていた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "弟[おとうと]は寒[さむ]い日[ひ]に袖[そで]の中[なか]に手[て]を入[い]れて、温[あたた]めていた。", "sentence_source": "generated"}, {"text": "新しい制服に袖を通したら、少し大きかった。", "target_word": "袖", "complexity_tier": "T3", "furigana": "新[あたら]しい制服[せいふく]に袖[そで]を通[とお]したら、少[すこ]し大[おお]きかった。", "sentence_source": "generated"}, {"text": "袖がほつれていたので、針と糸で縫った。", "target_word": "袖", "complexity_tier": "T3", "furigana": "袖[そで]がほつれていたので、針[はり]と糸[いと]で縫[ぬ]った。", "sentence_source": "generated"}, {"text": "雨にぬれて、上着の袖が重くなった。", "target_word": "袖", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、上着[うわぎ]の袖[そで]が重[おも]くなった。", "sentence_source": "generated"}, {"text": "電車で、知らない人に袖を引かれて、振り向いた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で、知[し]らない人[ひと]に袖[そで]を引[ひ]かれて、振[ふ]り向[む]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "袖", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "服の腕を入れる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "袖", "is_correct": true, "explanation": "腕を入れる部分で、長い袖が手を隠すという文脈に合う。"}, {"text": "襟", "is_correct": false, "explanation": "襟の長さは手が隠れることと関係なく、文脈に合わない。"}, {"text": "ポケット", "is_correct": false, "explanation": "ポケットの長さは手が隠れる理由にならず、文脈に合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "ボタンの長さは手の隠れ方と関係がなく、文脈に合わない。"}], "explanations": {"袖": "腕を入れる部分で、長い袖が手を隠すという文脈に合う。", "襟": "襟の長さは手が隠れることと関係なく、文脈に合わない。", "ポケット": "ポケットの長さは手が隠れる理由にならず、文脈に合わない。", "ボタン": "ボタンの長さは手の隠れ方と関係がなく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "袖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風でズボンの袖が揺れた。", "explanation": "ここは〈裾〉の意味（衣服の下端）。ズボンには袖がなく、揺れたのは裾である。"}, {"text": "傘の袖が折れた。", "explanation": "ここは〈柄〉の意味（持つ部分）。傘には袖がなく、折れたのは柄である。"}, {"text": "ジーンズの袖が擦り切れた。", "explanation": "ここは〈ひざ〉の意味。ジーンズには袖がなく、擦り切れたのはひざの部分である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "袖", "is_correct": true, "explanation": "腕を入れる部分で、制服を着る動作「袖を通す」と合う。"}, {"text": "足", "is_correct": false, "explanation": "足は服を通す部分ではなく、「通す」という動作に合わない。"}, {"text": "指", "is_correct": false, "explanation": "服に指を通す場所はなく、文脈に合わない。"}, {"text": "髪", "is_correct": false, "explanation": "髪は服に通すものではなく、文脈と合わない。"}], "explanations": {"袖": "腕を入れる部分で、制服を着る動作「袖を通す」と合う。", "足": "足は服を通す部分ではなく、「通す」という動作に合わない。", "指": "服に指を通す場所はなく、文脈に合わない。", "髪": "髪は服に通すものではなく、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "袖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアの袖を引いて、中に入った。", "explanation": "ここは〈取っ手〉の意味（ドアを引くための把手）。ドアには袖がなく、引くのは取っ手である。"}, {"text": "運転手は車の袖を握った。", "explanation": "ここは〈ハンドル〉の意味。車には袖がなく、握るのはハンドルである。"}, {"text": "このシャツの袖は首をぴったり囲んでいる。", "explanation": "ここは〈襟〉の意味（首の周りを囲む部分）。首を囲むのは襟で、腕を入れる袖とは別のものだ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コートの袖に少し折り返して、手首を出した。", "corrected_sentence": "コートの袖を少し折り返して、手首を出した。", "error_description": "「折り返す」の対象は「袖を」。「袖に」では折り返す動作の目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52425, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいシャツに袖を通ると、少し大きく感じる。", "corrected_sentence": "新しいシャツに袖を通すと、少し大きく感じる。", "error_description": "「袖を通す」の「通す」は他動詞。「通る」は自動詞なので、袖を目的語に取れない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
