INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衣服の、腕を通す筒状の部分。", "primary_collocate": null, "pronunciation": "そで", "ipa": "so.de", "syllable_count": 2, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "袖", "complexity_tier": "T3", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "寒かったので、長い袖のシャツに着替えた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "寒[さむ]かったので、長[なが]い袖[そで]のシャツに着替[きが]えた。", "sentence_source": "generated"}, {"text": "子どもが袖で口をぬぐうので、母は注意した。", "target_word": "袖", "complexity_tier": "T3", "furigana": "子[こ]どもが袖[そで]で口[くち]をぬぐうので、母[はは]は注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "袖が短すぎて、手首が出てしまう。", "target_word": "袖", "complexity_tier": "T3", "furigana": "袖[そで]が短[みじか]すぎて、手首[てくび]が出[で]てしまう。", "sentence_source": "generated"}, {"text": "彼は袖をまくって、皿洗いを始めた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "彼[かれ]は袖[そで]をまくって、皿洗[さらあら]いを始[はじ]めた。", "sentence_source": "generated"}, {"text": "このブラウスは袖にレースがついていて、かわいい。", "target_word": "袖", "complexity_tier": "T3", "furigana": "このブラウスは袖[そで]にレースがついていて、かわいい。", "sentence_source": "generated"}, {"text": "雨で袖がぬれたため、ハンカチでふいた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "雨[あめ]で袖[そで]がぬれたため、ハンカチでふいた。", "sentence_source": "generated"}, {"text": "腕時計を見るために、彼はコートの袖を少し引いた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "腕時計[うでどけい]を見[み]るために、彼[かれ]はコートの袖[そで]を少[すこ]し引[ひ]いた。", "sentence_source": "generated"}, {"text": "ドアの取っ手に袖がひっかかって、コートが破れた。", "target_word": "袖", "complexity_tier": "T3", "furigana": "ドアの取[と]っ手[て]に袖[そで]がひっかかって、コートが破[やぶ]れた。", "sentence_source": "generated"}, {"text": "袖の長さが合わないので、お店で直してもらった。", "target_word": "袖", "complexity_tier": "T3", "furigana": "袖[そで]の長[なが]さが合[あ]わないので、お店[みせ]で直[なお]してもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "袖", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "上着やシャツなどの、腕を通す筒の形をした部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: ぬぐう (Zipf 1.6)']::text[], 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52426, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "袖", "is_correct": true, "explanation": "腕を通す筒状の部分で、「腕を通し」という動作と一致する。"}, {"text": "襟", "is_correct": false, "explanation": "襟は首を囲む部分で、腕を通す場所ではない。"}, {"text": "裾", "is_correct": false, "explanation": "裾は衣服の下端で、腕を通すことはできない。"}, {"text": "ポケット", "is_correct": false, "explanation": "ポケットは物を入れる袋で、腕を通すものではない。"}], "explanations": {"袖": "腕を通す筒状の部分で、「腕を通し」という動作と一致する。", "襟": "襟は首を囲む部分で、腕を通す場所ではない。", "裾": "裾は衣服の下端で、腕を通すことはできない。", "ポケット": "ポケットは物を入れる袋で、腕を通すものではない。"}, "sentence_index": 0, "correct_answer": "袖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スカートの袖が汚れてしまった。", "explanation": "ここは〈裾〉の意味（衣服の下端）。スカートには袖がなく、汚れたのは裾である。"}, {"text": "首元の袖がほつれてきた。", "explanation": "ここは〈襟〉の意味（首を囲む部分）。首元に袖はなく、ほつれたのは襟である。"}, {"text": "靴の袖を結んだ。", "explanation": "ここは〈紐〉の意味。靴には袖がなく、結ぶのは紐である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52426, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "袖", "is_correct": true, "explanation": "布でできた袖は雨でぬれ、ハンカチでふく対象になる。"}, {"text": "庭", "is_correct": false, "explanation": "庭はハンカチでふく対象にならず、文脈に合わない。"}, {"text": "空", "is_correct": false, "explanation": "空はぬれたりふいたりするものではなく、文脈と合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音はぬれることがなく、ふく対象として成り立たない。"}], "explanations": {"袖": "布でできた袖は雨でぬれ、ハンカチでふく対象になる。", "庭": "庭はハンカチでふく対象にならず、文脈に合わない。", "空": "空はぬれたりふいたりするものではなく、文脈と合わない。", "足音": "足音はぬれることがなく、ふく対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "袖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "帽子の袖が広くて、日差しを防げる。", "explanation": "ここは〈つば〉の意味（帽子の縁）。帽子には袖がなく、日差しを防ぐのはつばである。"}, {"text": "ズボンの袖が破れた。", "explanation": "ここは〈ひざ〉の意味。ズボンには袖がなく、破れたのはひざの部分である。"}, {"text": "靴下の袖に穴が開いた。", "explanation": "ここは〈かかと〉の意味。靴下に袖はなく、穴が開くのはかかとの部分である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、袖が濡らさないように傘をさす。", "corrected_sentence": "雨の日は、袖を濡らさないように傘をさす。", "error_description": "「濡らす」の目的語は「袖を」。「袖が」にすると袖が主語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日は、長い袖セーターを着る。", "corrected_sentence": "寒い日は、長い袖のセーターを着る。", "error_description": "「袖」と「セーター」を結ぶ連体の「の」が抜けている。「長い袖のセーター」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "高く上げるの目的語を示す。上げるは他動詞なので〈を〉が正しい。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列を表し、腕と何かを並べる意味になるため、上げる対象として合わない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞を修飾するだけで、上げる動作の対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すので、上げる対象は示せない。"}], "correct_answer": "を", "explanations": {"を": "高く上げるの目的語を示す。上げるは他動詞なので〈を〉が正しい。", "と": "〈と〉は並列を表し、腕と何かを並べる意味になるため、上げる対象として合わない。", "の": "〈の〉は名詞を修飾するだけで、上げる動作の対象にはならない。", "から": "〈から〉は起点を示すので、上げる対象は示せない。"}, "error_tags": {"と": "並列", "の": "修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "肩から手首までの部分で、物をつかんだり動かしたりするのに使う体の部分。", "primary_collocate": null, "pronunciation": "うで", "ipa": "ɯ.de", "syllable_count": 2, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "腕", "complexity_tier": "T3", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "荷物が重くて、腕がしびれてきた。", "target_word": "腕", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]くて、腕[うで]がしびれてきた。", "sentence_source": "generated"}, {"text": "赤ちゃんを腕に抱いて、ゆっくり歩いた。", "target_word": "腕", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんを腕[うで]に抱[だ]いて、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "彼は腕を組んで、じっと考えていた。", "target_word": "腕", "complexity_tier": "T3", "furigana": "彼[かれ]は腕[うで]を組[く]んで、じっと考[かんが]えていた。", "sentence_source": "generated"}, {"text": "転んだとき、腕を骨折してしまった。", "target_word": "腕", "complexity_tier": "T3", "furigana": "転[ころ]んだとき、腕[うで]を骨折[こっせつ]してしまった。", "sentence_source": "generated"}, {"text": "水泳のあとは、腕と肩が疲れる。", "target_word": "腕", "complexity_tier": "T3", "furigana": "水泳[すいえい]のあとは、腕[うで]と肩[かた]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "母は腕に買い物かごをかけて、店を出た。", "target_word": "腕", "complexity_tier": "T3", "furigana": "母[はは]は腕[うで]に買[か]い物[もの]かごをかけて、店[みせ]を出[で]た。", "sentence_source": "generated"}, {"text": "腕を高く上げて、タクシーを止めた。", "target_word": "腕", "complexity_tier": "T3", "furigana": "腕[うで]を高[たか]く上[あ]げて、タクシーを止[と]めた。", "sentence_source": "generated"}, {"text": "医者は私の腕に注射をして、すぐ終わった。", "target_word": "腕", "complexity_tier": "T3", "furigana": "医者[いしゃ]は私[わたし]の腕[うで]に注射[ちゅうしゃ]をして、すぐ終[お]わった。", "sentence_source": "generated"}, {"text": "腕の力が弱いので、重い箱は持てない。", "target_word": "腕", "complexity_tier": "T3", "furigana": "腕[うで]の力[ちから]が弱[よわ]いので、重[おも]い箱[はこ]は持[も]てない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腕", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "肩から手首までの体の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腕", "is_correct": true, "explanation": "袖に通すのは腕。袖は腕を通す部分なので、ここでは腕が自然に入る。"}, {"text": "足", "is_correct": false, "explanation": "足は脚のこと。袖には通らないので、袖に足を通すとは言わない。"}, {"text": "首", "is_correct": false, "explanation": "首は袖を通る部分ではない。袖に首を通す文は成り立たない。"}, {"text": "肩", "is_correct": false, "explanation": "肩は袖の付け根で、袖に通す体の部分ではない。"}], "explanations": {"腕": "袖に通すのは腕。袖は腕を通す部分なので、ここでは腕が自然に入る。", "足": "足は脚のこと。袖には通らないので、袖に足を通すとは言わない。", "首": "首は袖を通る部分ではない。袖に首を通す文は成り立たない。", "肩": "肩は袖の付け根で、袖に通す体の部分ではない。"}, "sentence_index": 0, "correct_answer": "腕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は箸を腕で持って、ゆっくりご飯を食べた。", "explanation": "ここは〈手〉の意味。箸を持つのは手の役目で、腕で持つとは言わない。手と腕を混同した誤り。"}, {"text": "二社は新製品を作るために、腕を組んで協力することにした。", "explanation": "ここは〈手を組む〉の意味。協力を表すには〈手を組む〉を使い、腕を組むは腕を胸の前で交差させる動作を指す。"}, {"text": "サッカーの試合で、彼はボールを腕で強く蹴った。", "explanation": "ここは〈足〉の意味。蹴るのは足の仕事で、腕で蹴るとは言わない。足と混同した誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腕", "is_correct": true, "explanation": "買い物かごを腕にかけるのは腕。腕に物をかける形として自然。"}, {"text": "膝", "is_correct": false, "explanation": "膝に買い物かごをかけるとは言わない。かけられる部位ではない。"}, {"text": "歯", "is_correct": false, "explanation": "歯に物をかけるという動作は成り立たない。"}, {"text": "眉", "is_correct": false, "explanation": "眉に買い物かごをかける動作は不自然で、文として成り立たない。"}], "explanations": {"腕": "買い物かごを腕にかけるのは腕。腕に物をかける形として自然。", "膝": "膝に買い物かごをかけるとは言わない。かけられる部位ではない。", "歯": "歯に物をかけるという動作は成り立たない。", "眉": "眉に買い物かごをかける動作は不自然で、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "腕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライバルの選手と腕を並べて、優勝を争った。", "explanation": "ここは〈対等に並ぶ〉の意味。〈肩を並べる〉が正しく、腕を並べるとは言わない。"}, {"text": "二人は喫茶店で腕を交えて、将来の話をした。", "explanation": "〈膝を交える〉は向かい合って率直に話すこと。腕を交えるとは言わない。"}, {"text": "試験の前に、彼は腕をひねって答えを考えた。", "explanation": "〈頭をひねる〉は考え込むこと。腕をひねるは別の動作で、思考の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱を腕を抱えて運んだ。", "corrected_sentence": "重い箱を腕で抱えて運んだ。", "error_description": "誤: 腕を（目的語）。正: 腕で（手段）。腕で抱える、の〈で〉が正しく、〈を〉では腕を抱えることになり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52428, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は重い荷物を腕で運んだが、腕が痛めてしまった。", "corrected_sentence": "彼は重い荷物を腕で運んだが、腕を痛めてしまった。", "error_description": "誤: 腕が（主語）。正: 腕を（目的語）。痛めるは他動詞なので、〈を〉が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "着るの目的語を示す。着るは他動詞なので〈を〉が正しい。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は場所や相手を示すので、着るの目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、着る対象は示せない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を示し、着る動作の対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "着るの目的語を示す。着るは他動詞なので〈を〉が正しい。", "に": "〈に〉は場所や相手を示すので、着るの目的語にはならない。", "で": "〈で〉は手段や場所を示すので、着る対象は示せない。", "と": "〈と〉は並列や相手を示し、着る動作の対象として不自然。"}, "error_tags": {"に": "場所・相手", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "防水のコートがあると便利だ。ある（存在）の主語を示すので〈が〉が正しい。"}, {"text": "を", "is_correct": false, "explanation": "あるは目的語を取らない自動詞なので、〈を〉は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、存在の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すので、存在の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "防水のコートがあると便利だ。ある（存在）の主語を示すので〈が〉が正しい。", "を": "あるは目的語を取らない自動詞なので、〈を〉は合わない。", "へ": "〈へ〉は方向を示すので、存在の主語にはならない。", "から": "〈から〉は起点を示すので、存在の主語を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "寒さから体を守るために、上から羽織る長めの衣服。冬の防寒着。", "primary_collocate": null, "pronunciation": "こーと", "ipa": "koːto", "syllable_count": 3, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "コート", "complexity_tier": "T4", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "今朝は寒かったので、厚いコートを着て出かけた。", "target_word": "コート", "complexity_tier": "T2", "furigana": "今朝[けさ]は寒[さむ]かったので、厚[あつ]いコートを着[き]て出[で]かけた。", "sentence_source": "generated"}, {"text": "外は雪だったので、母はコートのボタンを全部とめた。", "target_word": "コート", "complexity_tier": "T3", "furigana": "外[そと]は雪[ゆき]だったので、母[はは]はコートのボタンを全部[ぜんぶ]とめた。", "sentence_source": "generated"}, {"text": "暖房の効いた店に入って、私はすぐにコートを脱いだ。", "target_word": "コート", "complexity_tier": "T3", "furigana": "暖房[だんぼう]の効[き]いた店[みせ]に入[はい]って、私[わたし]はすぐにコートを脱[ぬ]いだ。", "sentence_source": "generated"}, {"text": "このコートは軽いのに、風を通さないのでとても暖かい。", "target_word": "コート", "complexity_tier": "T3", "furigana": "このコートは軽[かる]いのに、風[かぜ]を通[とお]さないのでとても暖[あたた]かい。", "sentence_source": "generated"}, {"text": "弟は背が伸びて、去年のコートが小さくなってしまった。", "target_word": "コート", "complexity_tier": "T3", "furigana": "弟[おとうと]は背[せ]が伸[の]びて、去年[きょねん]のコートが小[ちい]さくなってしまった。", "sentence_source": "generated"}, {"text": "店員さんにコートを預けて、席についた。", "target_word": "コート", "complexity_tier": "T3", "furigana": "店員[てんいん]さんにコートを預[あず]けて、席[せき]についた。", "sentence_source": "generated"}, {"text": "雨の日は、防水のコートがあると便利だ。", "target_word": "コート", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、防水[ぼうすい]のコートがあると便利[べんり]だ。", "sentence_source": "generated"}, {"text": "彼女は黒いコートの下に、赤いセーターを着ていた。", "target_word": "コート", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は黒[くろ]いコートの下[した]に、赤[あか]いセーターを着[き]ていた。", "sentence_source": "generated"}, {"text": "冬になる前に、新しいコートを買うつもりだ。", "target_word": "コート", "complexity_tier": "T2", "furigana": "冬[ふゆ]になる前[まえ]に、新[あたら]しいコートを買[か]うつもりだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コート", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "冬に服の上から羽織る、長めの防寒用の上着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コート", "is_correct": true, "explanation": "分厚いコートには袖がある。上着の袖に腕を通すので、ここで自然に入る。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下には袖がないので、分厚い靴下の袖という文は成り立たない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子にも袖はないので、帽子の袖に腕を通すことはできない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡には袖がなく、袖に腕を通す文の対象にならない。"}], "explanations": {"コート": "分厚いコートには袖がある。上着の袖に腕を通すので、ここで自然に入る。", "靴下": "靴下には袖がないので、分厚い靴下の袖という文は成り立たない。", "帽子": "帽子にも袖はないので、帽子の袖に腕を通すことはできない。", "眼鏡": "眼鏡には袖がなく、袖に腕を通す文の対象にならない。"}, "sentence_index": 0, "correct_answer": "コート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、コートを食べて出かけた。", "explanation": "〈食べる〉は食べ物に使う動詞で、コートは食べられない。上着は〈着る〉が正しい。"}, {"text": "寒いので、コートをはめて出かけた。", "explanation": "〈はめる〉は手袋や指輪に使う。上着にはめるとは言わず、手袋と混同した誤り。"}, {"text": "雨が降ってきたので、コートをさして歩いた。", "explanation": "〈傘をさす〉が正しく、コートをさすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コート", "is_correct": true, "explanation": "店員さんにコートを預けるのは自然。預けられる物として正しい。"}, {"text": "鉛筆", "is_correct": false, "explanation": "店員に鉛筆を預けるのは不自然で、預ける物として合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は預けられるものではなく、店員に預ける文は成り立たない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子を店員に預けるという状況は成り立たない。"}], "explanations": {"コート": "店員さんにコートを預けるのは自然。預けられる物として正しい。", "鉛筆": "店員に鉛筆を預けるのは不自然で、預ける物として合わない。", "雲": "雲は預けられるものではなく、店員に預ける文は成り立たない。", "椅子": "椅子を店員に預けるという状況は成り立たない。"}, "sentence_index": 6, "correct_answer": "コート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒いので、厚いコートを食べて出かけた。", "explanation": "〈食べる〉は食べ物に使う動詞で、コートは食べられない。上着は〈着る〉が正しい。"}, {"text": "寒いので、厚いコートを履いて出かけた。", "explanation": "〈履く〉は靴やズボンに使う。上着を履くとは言わず、靴と混同した誤り。"}, {"text": "彼はコートを鳴らして、店員を呼んだ。", "explanation": "〈指を鳴らす〉が正しく、コートを鳴らすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、厚いコートに着て出かけた。", "corrected_sentence": "寒い日は、厚いコートを着て出かけた。", "error_description": "誤: に。正: を。着るは他動詞なので、目的語のコートには〈を〉が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、防水のコートを便利だ。", "corrected_sentence": "雨の日は、防水のコートが便利だ。", "error_description": "誤: を。正: が。便利だは〈が〉で主語を示す形容動詞なので、〈が〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "正解。「着る（服を体につける）」の対義語で、体から服を外す動作を表す。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、「着る（服を体につける）」の対義語ではない。"}, {"text": "畳む", "is_correct": false, "explanation": "畳むは布を重ねて整える動作で、「着る（服を体につける）」と反対の関係ではない。"}, {"text": "選ぶ", "is_correct": false, "explanation": "選ぶは複数から選び取る動作で、「着る（服を体につける）」と反対の関係ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "正解。「着る（服を体につける）」の対義語で、体から服を外す動作を表す。", "洗う": "洗うは汚れを落とす動作で、「着る（服を体につける）」の対義語ではない。", "畳む": "畳むは布を重ねて整える動作で、「着る（服を体につける）」と反対の関係ではない。", "選ぶ": "選ぶは複数から選び取る動作で、「着る（服を体につける）」と反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "正解。「着る（服を体につける）」の対義語で、体から服を外す動作を表す。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶは紐などをつなぐ動作で、「着る（服を体につける）」と反対の関係ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは表面をこすって光らせる動作で、「着る（服を体につける）」の対義語ではない。"}, {"text": "押す", "is_correct": false, "explanation": "押すは力を加える動作で、「着る（服を体につける）」と反対の関係ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "正解。「着る（服を体につける）」の対義語で、体から服を外す動作を表す。", "結ぶ": "結ぶは紐などをつなぐ動作で、「着る（服を体につける）」と反対の関係ではない。", "磨く": "磨くは表面をこすって光らせる動作で、「着る（服を体につける）」の対義語ではない。", "押す": "押すは力を加える動作で、「着る（服を体につける）」と反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "服を体につける。", "primary_collocate": null, "pronunciation": "きる", "ipa": "kiɾɯ", "syllable_count": 2, "sentences": [{"text": "今日は暑いので、半そでのシャツを着る。", "target_word": "着る", "complexity_tier": "T2", "furigana": "今日[きょう]は暑[あつ]いので、半[はん]そでのシャツを着[き]る。", "sentence_source": "generated"}, {"text": "妹は毎朝、自分で好きな服を選んで着る。", "target_word": "着る", "complexity_tier": "T3", "furigana": "妹[いもうと]は毎朝[まいあさ]、自分[じぶん]で好[す]きな服[ふく]を選[えら]んで着[き]る。", "sentence_source": "generated"}, {"text": "パジャマを着て、ベッドに入った。", "target_word": "着て", "complexity_tier": "T2", "furigana": "パジャマを着[き]て、ベッドに入[はい]った。", "sentence_source": "generated"}, {"text": "冬は、セーターを二枚着ても寒い。", "target_word": "着ても", "complexity_tier": "T3", "furigana": "冬[ふゆ]は、セーターを二枚[にまい]着[き]ても寒[さむ]い。", "sentence_source": "generated"}, {"text": "弟は新しいシャツを着て、うれしそうに笑った。", "target_word": "着て", "complexity_tier": "T3", "furigana": "弟[おとうと]は新[あたら]しいシャツを着[き]て、うれしそうに笑[わら]った。", "sentence_source": "generated"}, {"text": "雨なので、レインコートを着て出かけた。", "target_word": "着て", "complexity_tier": "T2", "furigana": "雨[あめ]なので、レインコートを着[き]て出[で]かけた。", "sentence_source": "generated"}, {"text": "白いシャツを着ている人が、私の先生だ。", "target_word": "着ている", "complexity_tier": "T3", "furigana": "白[しろ]いシャツを着[き]ている人[ひと]が、私[わたし]の先生[せんせい]だ。", "sentence_source": "generated"}, {"text": "服を着たまま、プールに入ってはいけない。", "target_word": "着た", "complexity_tier": "T3", "furigana": "服[ふく]を着[き]たまま、プールに入[はい]ってはいけない。", "sentence_source": "generated"}, {"text": "この服は大きすぎて、子どもが着ると袖が長い。", "target_word": "着ると", "complexity_tier": "T3", "furigana": "この服[ふく]は大[おお]きすぎて、子[こ]どもが着[き]ると袖[そで]が長[なが]い。", "sentence_source": "generated"}, {"text": "彼は何を着ても、よく似合う。", "target_word": "着ても", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]を着[き]ても、よく似合[にあ]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "着る", "label": "終止形・連体形"}, {"form": "着ない", "label": "否定形"}, {"form": "着ます", "label": "丁寧形"}, {"form": "着て", "label": "て形"}, {"form": "着た", "label": "過去形"}, {"form": "着れば", "label": "仮定形"}, {"form": "着よう", "label": "意志形"}, {"form": "着られる", "label": "可能形・受身形"}], "register": "neutral", "sense_fingerprint": "服を体につける動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 半そで (Zipf 1.8)']::text[], 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着る", "is_correct": true, "explanation": "正解。「半そでのシャツを着る。」は服を体につける意味の終止形で、文末に自然に収まる。"}, {"text": "着て", "is_correct": false, "explanation": "て形は文を続ける形なので、文末に置くと文が途中で切れて成り立たない。"}, {"text": "着れば", "is_correct": false, "explanation": "仮定形は「〜ば」と続ける形で、文末に単独で置くと文が途切れる。"}, {"text": "着たら", "is_correct": false, "explanation": "たら形は「〜たら」と続ける形なので、文末に置くと文が途中で切れて成り立たない。"}], "explanations": {"着る": "正解。「半そでのシャツを着る。」は服を体につける意味の終止形で、文末に自然に収まる。", "着て": "て形は文を続ける形なので、文末に置くと文が途中で切れて成り立たない。", "着れば": "仮定形は「〜ば」と続ける形で、文末に単独で置くと文が途切れる。", "着たら": "たら形は「〜たら」と続ける形なので、文末に置くと文が途中で切れて成り立たない。"}, "sentence_index": 0, "correct_answer": "着る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は寒いので、靴を着て出かける。", "explanation": "ここは〈履く〉の意味。靴は足に履くもので、服を体につける〈着る〉とは言わないので合わない。"}, {"text": "雨なので、帽子を着て外へ出た。", "explanation": "ここは〈被る〉の意味。頭にかぶる帽子は〈被る〉を使い、〈着る〉とは言わないので合わない。"}, {"text": "面接のため、ネクタイを着て家を出た。", "explanation": "ここは〈締める〉の意味。ネクタイは首に締めるもので、〈着る〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着ている", "is_correct": true, "explanation": "正解。「白いシャツを着ている人」で、今その服を身につけている状態を名詞に結びつける。"}, {"text": "着ろ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、「白いシャツを着ろ人が」は成り立たない。"}, {"text": "着よう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「白いシャツを着よう人が」は成り立たない。"}, {"text": "着れば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「白いシャツを着れば人が」は文として成り立たない。"}], "explanations": {"着ている": "正解。「白いシャツを着ている人」で、今その服を身につけている状態を名詞に結びつける。", "着ろ": "命令形は名詞を修飾できず、「白いシャツを着ろ人が」は成り立たない。", "着よう": "意志形は名詞を修飾できず、「白いシャツを着よう人が」は成り立たない。", "着れば": "仮定形は名詞を修飾できず、「白いシャツを着れば人が」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "着ている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日の練習で、ピアノの腕前を着た。", "explanation": "ここは〈身につける〉の意味（技術や腕前を得る）。〈着る〉は衣服や装備にだけ使い、腕前には使わないので合わない。"}, {"text": "読書のため、眼鏡を着て机に向かった。", "explanation": "ここは〈かける〉の意味。眼鏡は顔にかけるもので、〈着る〉とは言わないので合わない。"}, {"text": "結婚式で、指輪を着て誓いを立てた。", "explanation": "ここは〈はめる〉の意味。指輪は指にはめるもので、体につける服の〈着る〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、セーターを着ば暖かい。", "corrected_sentence": "寒い日は、セーターを着れば暖かい。", "error_description": "仮定形の活用が誤っている。「着る」の仮定形は「着れば」で、「着ば」は存在しない誤った活用。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "着る", "is_correct": true, "explanation": "正解。「選んで着る。」で文を言い切る終止形。"}, {"text": "着て", "is_correct": false, "explanation": "て形で文を終えると命令の形になり、「妹は」を主語とする平叙文とは合わない。"}, {"text": "着れば", "is_correct": false, "explanation": "仮定形は文末に単独で置くと条件がなく、「選んで着れば。」は成り立たない。"}, {"text": "着たら", "is_correct": false, "explanation": "たら形は文末で完結しないので、「選んで着たら。」は文が途切れて成り立たない。"}], "correct_form": "着る", "base_form": "着る", "form_label": "終止形", "sentence_index": 1, "explanations": {"着る": "正解。「選んで着る。」で文を言い切る終止形。", "着て": "て形で文を終えると命令の形になり、「妹は」を主語とする平叙文とは合わない。", "着れば": "仮定形は文末に単独で置くと条件がなく、「選んで着れば。」は成り立たない。", "着たら": "たら形は文末で完結しないので、「選んで着たら。」は文が途切れて成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52431, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝は、上着を着た外へ出た。", "corrected_sentence": "寒い朝は、上着を着て外へ出た。", "error_description": "後ろの「外へ出た」につなぐには、て形の「着て」が必要。「着た」は過去形で、文を途切れさせている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "着た", "is_correct": true, "explanation": "正解。「着たまま」の形で、過去形「着た」が入る。"}, {"text": "着ず", "is_correct": false, "explanation": "「着ず」は「〜ずに」の形で続くもので、「〜ずまま」とは続かず、この文型には入らない。"}, {"text": "着よう", "is_correct": false, "explanation": "意志形は「〜ようまま」とは続かず、この文型に入らない。"}, {"text": "着られる", "is_correct": false, "explanation": "可能形の「着られる」は「〜まま」の前に置くと不自然で、服を着た状態を表せないので合わない。"}], "correct_form": "着た", "base_form": "着る", "form_label": "過去形（〜たまま）", "sentence_index": 7, "explanations": {"着た": "正解。「着たまま」の形で、過去形「着た」が入る。", "着ず": "「着ず」は「〜ずに」の形で続くもので、「〜ずまま」とは続かず、この文型には入らない。", "着よう": "意志形は「〜ようまま」とは続かず、この文型に入らない。", "着られる": "可能形の「着られる」は「〜まま」の前に置くと不自然で、服を着た状態を表せないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
