INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「スーツを着た」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「スーツに着た」では着る対象を正しく示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、着る対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」では、着る対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「スーツを着た」の目的語を示す「を」。", "に": "「スーツに着た」では着る対象を正しく示せず、文が成り立たない。", "へ": "方向を示す「へ」では、着る対象を表せない。", "より": "比較を示す「より」では、着る対象にならない。"}, "error_tags": {"に": "位置・帰着点（不適）", "へ": "方向（不適）", "より": "比較（不適）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "正解。「着る（身につける）」の対義語で、身につけたものを外す動作を表す。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶは紐などをつなぐ動作で、「着る（身につける）」と反対の関係ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは表面をこすって光らせる動作で、「着る（身につける）」の対義語ではない。"}, {"text": "押す", "is_correct": false, "explanation": "押すは力を加える動作で、「着る（身につける）」と反対の関係ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "正解。「着る（身につける）」の対義語で、身につけたものを外す動作を表す。", "結ぶ": "結ぶは紐などをつなぐ動作で、「着る（身につける）」と反対の関係ではない。", "磨く": "磨くは表面をこすって光らせる動作で、「着る（身につける）」の対義語ではない。", "押す": "押すは力を加える動作で、「着る（身につける）」と反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "衣服や装備などを身につける。", "primary_collocate": null, "pronunciation": "きる", "ipa": "kiɾɯ", "syllable_count": 2, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "着る", "complexity_tier": "T4", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "寒いから、もう一枚着たほうがいい。", "target_word": "着た", "complexity_tier": "T2", "furigana": "寒[さむ]いから、もう一枚[いちまい]着[き]たほうがいい。", "sentence_source": "generated"}, {"text": "消防士は火の中に入る前に、防火服を着る。", "target_word": "着る", "complexity_tier": "T3", "furigana": "消防士[しょうぼうし]は火[ひ]の中[なか]に入[はい]る前[まえ]に、防火服[ぼうかふく]を着[き]る。", "sentence_source": "generated"}, {"text": "毎朝、制服を着て学校へ行く。", "target_word": "着て", "complexity_tier": "T2", "furigana": "毎朝[まいあさ]、制服[せいふく]を着[き]て学校[がっこう]へ行[い]く。", "sentence_source": "generated"}, {"text": "子どもは自分でシャツを着られるようになった。", "target_word": "着られる", "complexity_tier": "T3", "furigana": "子[こ]どもは自分[じぶん]でシャツを着[き]られるようになった。", "sentence_source": "generated"}, {"text": "結婚式では、着物を着る人も多い。", "target_word": "着る", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]では、着物[きもの]を着[き]る人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "熱があるときは、暖かい服を着て寝なさい。", "target_word": "着て", "complexity_tier": "T3", "furigana": "熱[ねつ]があるときは、暖[あたた]かい服[ふく]を着[き]て寝[ね]なさい。", "sentence_source": "generated"}, {"text": "彼は面接のために、初めてスーツを着た。", "target_word": "着た", "complexity_tier": "T3", "furigana": "彼[かれ]は面接[めんせつ]のために、初[はじ]めてスーツを着[き]た。", "sentence_source": "generated"}, {"text": "ここでは作業するとき、必ず作業服を着ること。", "target_word": "着ること", "complexity_tier": "T4", "furigana": "ここでは作業[さぎょう]するとき、必[かなら]ず作業服[さぎょうふく]を着[き]ること。", "sentence_source": "generated"}, {"text": "夏祭りで、娘は浴衣を着ることを楽しみにしている。", "target_word": "着る", "complexity_tier": "T4", "furigana": "夏祭[なつまつ]りで、娘[むすめ]は浴衣[ゆかた]を着[き]ることを楽[たの]しみにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "着る", "label": "終止形・連体形"}, {"form": "着ない", "label": "否定形"}, {"form": "着ます", "label": "丁寧形"}, {"form": "着て", "label": "て形"}, {"form": "着た", "label": "過去形"}, {"form": "着れば", "label": "仮定形"}, {"form": "着よう", "label": "意志形"}, {"form": "着られる", "label": "可能形・受身形"}], "register": "neutral", "sense_fingerprint": "衣服や防具・装備などを身につける動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着る", "is_correct": true, "explanation": "正解。「鎧を着る。」は装備を身につけるという意味の終止形で、文末に自然に収まる。"}, {"text": "着て", "is_correct": false, "explanation": "て形は文を続ける形なので、文末に置くと文が途中で切れて成り立たない。"}, {"text": "着れば", "is_correct": false, "explanation": "仮定形は「〜ば」と続ける形で、文末に単独で置くと条件のないまま文が途切れる。"}, {"text": "着たら", "is_correct": false, "explanation": "たら形は「〜たら」と続ける形で、文末に置くと文が途切れて成り立たない。"}], "explanations": {"着る": "正解。「鎧を着る。」は装備を身につけるという意味の終止形で、文末に自然に収まる。", "着て": "て形は文を続ける形なので、文末に置くと文が途中で切れて成り立たない。", "着れば": "仮定形は「〜ば」と続ける形で、文末に単独で置くと条件のないまま文が途切れる。", "着たら": "たら形は「〜たら」と続ける形で、文末に置くと文が途切れて成り立たない。"}, "sentence_index": 0, "correct_answer": "着る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業のため、安全靴を着て現場へ入る。", "explanation": "ここは〈履く〉の意味。靴は足に履くもので、装備を身につける〈着る〉とは言わないので合わない。"}, {"text": "作業中は、ヘルメットを着て頭を守る。", "explanation": "ここは〈被る〉の意味。頭にかぶるヘルメットは〈被る〉を使い、〈着る〉とは言わないので合わない。"}, {"text": "寒い現場では、手袋を着て手を温める。", "explanation": "ここは〈はめる〉の意味。手袋は手にはめるもので、〈着る〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着て", "is_correct": true, "explanation": "正解。「着て寝る」で、身につけたまま寝るという意味になり、後ろの「寝なさい」につながる。"}, {"text": "着る", "is_correct": false, "explanation": "終止形のままでは「服を着る寝なさい」となり、後ろの動詞とつながらない。"}, {"text": "着た", "is_correct": false, "explanation": "過去形では後ろの動詞と続かず、「服を着た寝なさい」は不自然になる。"}, {"text": "着よう", "is_correct": false, "explanation": "意志形は後ろの動詞と続かず、「服を着よう寝なさい」は成り立たない。"}], "explanations": {"着て": "正解。「着て寝る」で、身につけたまま寝るという意味になり、後ろの「寝なさい」につながる。", "着る": "終止形のままでは「服を着る寝なさい」となり、後ろの動詞とつながらない。", "着た": "過去形では後ろの動詞と続かず、「服を着た寝なさい」は不自然になる。", "着よう": "意志形は後ろの動詞と続かず、「服を着よう寝なさい」は成り立たない。"}, "sentence_index": 6, "correct_answer": "着て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長年の努力で、確かな英語力を着た。", "explanation": "ここは〈身につける〉の意味（知識や力を得る）。〈着る〉は衣服や装備にだけ使い、英語力には使わないので合わない。"}, {"text": "黒板が見えないので、眼鏡を着た。", "explanation": "ここは〈かける〉の意味。眼鏡は顔にかけるもので、〈着る〉とは言わないので合わない。"}, {"text": "面接の前に、ネクタイを着て身だしなみを整えた。", "explanation": "ここは〈締める〉の意味。ネクタイは首に締めるもので、〈着る〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "騎士は重い鎧を着と、城の門をくぐった。", "corrected_sentence": "騎士は重い鎧を着て、城の門をくぐった。", "error_description": "「着る」に続ける接続の形が誤っている。「着と」は活用形として存在しない。後ろの動詞につなぐ正しい形は「着て」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "着た", "is_correct": true, "explanation": "正解。「〜たほうがいい」の形で、「着る」の過去形「着た」が入る。"}, {"text": "着て", "is_correct": false, "explanation": "て形は「〜てほうがいい」とは続けられず、文として成り立たない。"}, {"text": "着れば", "is_correct": false, "explanation": "仮定形は「〜ればいい」と続くので、「〜ほうがいい」の前に置くと不自然になる。"}, {"text": "着ます", "is_correct": false, "explanation": "丁寧形は「〜ますほうがいい」とは続かず、この文型に入らない。"}], "correct_form": "着た", "base_form": "着る", "form_label": "過去形（〜たほうがいい）", "sentence_index": 1, "explanations": {"着た": "正解。「〜たほうがいい」の形で、「着る」の過去形「着た」が入る。", "着て": "て形は「〜てほうがいい」とは続けられず、文として成り立たない。", "着れば": "仮定形は「〜ればいい」と続くので、「〜ほうがいい」の前に置くと不自然になる。", "着ます": "丁寧形は「〜ますほうがいい」とは続かず、この文型に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏祭りの日、娘は浴衣を着たことを楽しみにしている。", "corrected_sentence": "夏祭りの日、娘は浴衣を着ることを楽しみにしている。", "error_description": "「楽しみにする」は未来のことに使うので、過去形「着た」ではなく非過去の「着る」が正しい。誤っているのは活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "着た", "is_correct": true, "explanation": "正解。「初めてスーツを着た」の過去形で、過去の出来事を表す。"}, {"text": "着ない", "is_correct": false, "explanation": "否定形の「着ない」は身につけなかったことを表すので、スーツを着たという文の内容と逆になる。"}, {"text": "着られる", "is_correct": false, "explanation": "可能形の「着られる」は身につけられるという意味で、実際に着た出来事を表す文には合わない。"}, {"text": "着よう", "is_correct": false, "explanation": "意志形は意図を表すので、過去の出来事を述べる文には入らない。"}], "correct_form": "着た", "base_form": "着る", "form_label": "過去形", "sentence_index": 7, "explanations": {"着た": "正解。「初めてスーツを着た」の過去形で、過去の出来事を表す。", "着ない": "否定形の「着ない」は身につけなかったことを表すので、スーツを着たという文の内容と逆になる。", "着られる": "可能形の「着られる」は身につけられるという意味で、実際に着た出来事を表す文には合わない。", "着よう": "意志形は意図を表すので、過去の出来事を述べる文には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「銀色の鎧を着ていた」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「鎧が着ていた」では、着る主体との関係が成り立たず、文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「鎧に着ていた」では、着る対象を正しく示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」では、「鎧で着ていた」は着る対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「銀色の鎧を着ていた」の目的語を示す「を」。", "が": "「鎧が着ていた」では、着る主体との関係が成り立たず、文として不自然。", "に": "「鎧に着ていた」では、着る対象を正しく示せない。", "で": "手段を示す「で」では、「鎧で着ていた」は着る対象にならない。"}, "error_tags": {"が": "主語の格（不適）", "に": "位置・相手（不適）", "で": "手段・場所（不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「鎧を脱ぐと」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「鎧が脱ぐと」では、脱ぐ主体との関係が成り立たず、文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「鎧に脱ぐと」では、脱ぐ対象を正しく示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、脱ぐ対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「鎧を脱ぐと」の目的語を示す「を」。", "が": "「鎧が脱ぐと」では、脱ぐ主体との関係が成り立たず、文として不自然。", "に": "「鎧に脱ぐと」では、脱ぐ対象を正しく示せない。", "へ": "方向を示す「へ」では、脱ぐ対象にならない。"}, "error_tags": {"が": "主語の格（不適）", "に": "位置・相手（不適）", "へ": "方向（不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体を守るための、かたい服。", "primary_collocate": null, "pronunciation": "よろい", "ipa": "joɾoi", "syllable_count": 3, "sentences": [{"text": "昔の兵士は、かたい鎧を着て戦った。", "target_word": "鎧", "complexity_tier": "T2", "furigana": "昔[むかし]の兵士[へいし]は、かたい鎧[よろい]を着[き]て戦[たたか]った。", "sentence_source": "generated"}, {"text": "映画の中で、騎士が銀色の鎧を着ていた。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "映画[えいが]の中[なか]で、騎士[きし]が銀色[ぎんいろ]の鎧[よろい]を着[き]ていた。", "sentence_source": "generated"}, {"text": "この鎧はとても重くて、持ち上げるのもたいへんだ。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "この鎧[よろい]はとても重[おも]くて、持[も]ち上[あ]げるのもたいへんだ。", "sentence_source": "generated"}, {"text": "博物館で、本物の鎧を見た。", "target_word": "鎧", "complexity_tier": "T2", "furigana": "博物館[はくぶつかん]で、本物[ほんもの]の鎧[よろい]を見[み]た。", "sentence_source": "generated"}, {"text": "鎧は体を守るが、重いので速く走れない。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "鎧[よろい]は体[からだ]を守[まも]るが、重[おも]いので速[はや]く走[はし]れない。", "sentence_source": "generated"}, {"text": "兄は段ボールで鎧を作って、仮装大会に出た。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "兄[あに]は段[だん]ボールで鎧[よろい]を作[つく]って、仮装[かそう]大会[たいかい]に出[で]た。", "sentence_source": "generated"}, {"text": "敵の剣が鎧に当たって、大きな音がした。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "敵[てき]の剣[けん]が鎧[よろい]に当[あ]たって、大[おお]きな音[おと]がした。", "sentence_source": "generated"}, {"text": "鎧を脱ぐと、兵士は汗でびっしょりだった。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "鎧[よろい]を脱[ぬ]ぐと、兵士[へいし]は汗[あせ]でびっしょりだった。", "sentence_source": "generated"}, {"text": "城の入り口に、古い鎧が一つ立っている。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "城[しろ]の入[い]り口[ぐち]に、古[ふる]い鎧[よろい]が一[ひと]つ立[た]っている。", "sentence_source": "generated"}, {"text": "この鎧には、胸や肩を守る部分がある。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "この鎧[よろい]には、胸[むね]や肩[かた]を守[まも]る部分[ぶぶん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鎧", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "戦うときに体を守るために着る、かたい防具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鎧", "is_correct": true, "explanation": "正解。「かたい鎧を着て戦った」で、戦うときに体を守る防具を指す。"}, {"text": "盾", "is_correct": false, "explanation": "盾は手に持つ防具で、「着て戦った」の対象としては合わない。"}, {"text": "兜", "is_correct": false, "explanation": "兜は頭にかぶる防具で、体に着て戦う防具としては合わない。"}, {"text": "脛当て", "is_correct": false, "explanation": "脛当てはすねを守る部分の防具で、体全体に着て戦う防具ではないので合わない。"}], "explanations": {"鎧": "正解。「かたい鎧を着て戦った」で、戦うときに体を守る防具を指す。", "盾": "盾は手に持つ防具で、「着て戦った」の対象としては合わない。", "兜": "兜は頭にかぶる防具で、体に着て戦う防具としては合わない。", "脛当て": "脛当てはすねを守る部分の防具で、体全体に着て戦う防具ではないので合わない。"}, "sentence_index": 0, "correct_answer": "鎧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敵の刃を防ぐため、鎧を手に構えた。", "explanation": "ここは〈盾〉の意味。手に構えて使うのは盾で、体に着る鎧は〈構える〉とは使わないので合わない。"}, {"text": "戦場で、鎧を頭にかぶった。", "explanation": "ここは〈兜〉の意味。頭にかぶるのは兜で、体に着る鎧は〈かぶる〉とは言わないので合わない。"}, {"text": "すねを守るため、鎧をすねにつけた。", "explanation": "ここは〈脛当て〉の意味。すねを守る防具は脛当てで、体に着る鎧をすねにつけるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鎧", "is_correct": true, "explanation": "正解。「敵の剣が鎧に当たって、大きな音がした」で、剣が当たる体の防具を指す。"}, {"text": "紙", "is_correct": false, "explanation": "紙は柔らかく、剣が当たっても大きな音は出ないので、この文の対象に合わない。"}, {"text": "綿", "is_correct": false, "explanation": "綿は柔らかく、剣が当たっても金属の大きな音は出ないので、この文の対象に合わない。"}, {"text": "花", "is_correct": false, "explanation": "花は柔らかく、剣が当たっても大きな音は出ないので、この文の対象に合わない。"}], "explanations": {"鎧": "正解。「敵の剣が鎧に当たって、大きな音がした」で、剣が当たる体の防具を指す。", "紙": "紙は柔らかく、剣が当たっても大きな音は出ないので、この文の対象に合わない。", "綿": "綿は柔らかく、剣が当たっても金属の大きな音は出ないので、この文の対象に合わない。", "花": "花は柔らかく、剣が当たっても大きな音は出ないので、この文の対象に合わない。"}, "sentence_index": 6, "correct_answer": "鎧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の前に、家の窓の鎧を下ろした。", "explanation": "ここは〈鎧戸〉（窓の外側にある開閉する板戸）の意味。窓の戸を指すなら〈鎧戸〉と言い、武具の〈鎧〉とは言わないので合わない。"}, {"text": "寒い朝、手に鎧をはめて出かけた。", "explanation": "ここは〈手袋〉の意味。手にはめるのは手袋で、体に着る鎧は〈はめる〉とは言わないので合わない。"}, {"text": "雨の日は、鎧を履いて出かける。", "explanation": "ここは〈靴〉の意味。足に履くのは靴で、体に着る鎧は〈履く〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦いの前に、兵士は鎧に着て整列した。", "corrected_sentence": "戦いの前に、兵士は鎧を着て整列した。", "error_description": "「着る」の対象は「を」で示す。「鎧に」は誤りで、正しくは「鎧を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52433, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "戦が終わり、兵士は鎧が外して休んだ。", "corrected_sentence": "戦が終わり、兵士は鎧を外して休んだ。", "error_description": "「外す」の対象は「を」で示す。「鎧が」は誤りで、正しくは「鎧を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
