INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「金色の鎧を身につけた」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「鎧が身につけた」では、身につける主体との関係が成り立たず、文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「鎧に身につけた」では、身につける対象を正しく示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、身につける対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「金色の鎧を身につけた」の目的語を示す「を」。", "が": "「鎧が身につけた」では、身につける主体との関係が成り立たず、文として不自然。", "に": "「鎧に身につけた」では、身につける対象を正しく示せない。", "へ": "方向を示す「へ」では、身につける対象にならない。"}, "error_tags": {"が": "主語の格（不適）", "に": "位置・相手（不適）", "へ": "方向（不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "戦いや危険から身を守るために着る、金属や革で作られた防具。", "primary_collocate": null, "pronunciation": "よろい", "ipa": "joɾoi", "syllable_count": 3, "sentences": [{"text": "彼は不器用ながらも、敵の刃から身を守るための鎧を着る。", "target_word": "鎧", "complexity_tier": "T4", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、敵[てき]の刃[やいば]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "generated"}, {"text": "博物館には、武士が戦で身につけた古い鎧が飾られている。", "target_word": "鎧", "complexity_tier": "T4", "furigana": "博物館[はくぶつかん]には、武士[ぶし]が戦[いくさ]で身[み]につけた古[ふる]い鎧[よろい]が飾[かざ]られている。", "sentence_source": "generated"}, {"text": "騎士は重い鎧を着ていたので、動くのに時間がかかった。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "騎士[きし]は重[おも]い鎧[よろい]を着[き]ていたので、動[うご]くのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "鉄でできた鎧は、矢を防ぐことができた。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "鉄[てつ]でできた鎧[よろい]は、矢[や]を防[ふせ]ぐことができた。", "sentence_source": "generated"}, {"text": "戦いのあと、鎧にはたくさんの傷が残っていた。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "戦[たたか]いのあと、鎧[よろい]にはたくさんの傷[きず]が残[のこ]っていた。", "sentence_source": "generated"}, {"text": "祭りでは、鎧をつけた武者の行列が町を歩く。", "target_word": "鎧", "complexity_tier": "T4", "furigana": "祭[まつ]りでは、鎧[よろい]をつけた武者[むしゃ]の行列[ぎょうれつ]が町[まち]を歩[ある]く。", "sentence_source": "generated"}, {"text": "全身を覆う革の鎧は軽いが、金属ほど強くない。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "全身[ぜんしん]を覆[おお]う革[かわ]の鎧[よろい]は軽[かる]いが、金属[きんぞく]ほど強[つよ]くない。", "sentence_source": "generated"}, {"text": "王は戦場に出る前に、金色の鎧を身につけた。", "target_word": "鎧", "complexity_tier": "T3", "furigana": "王[おう]は戦場[せんじょう]に出[で]る前[まえ]に、金色[きんいろ]の鎧[よろい]を身[み]につけた。", "sentence_source": "generated"}, {"text": "鎧の下には、動きやすい服を着るのが普通だった。", "target_word": "鎧", "complexity_tier": "T4", "furigana": "鎧[よろい]の下[した]には、動[うご]きやすい服[ふく]を着[き]るのが普通[ふつう]だった。", "sentence_source": "generated"}, {"text": "五月には、兜と鎧を家に飾る習慣がある。", "target_word": "鎧", "complexity_tier": "T4", "furigana": "五月[ごがつ]には、兜[かぶと]と鎧[よろい]を家[いえ]に飾[かざ]る習慣[しゅうかん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鎧", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "戦いで身を守るために着る、金属や革製の防具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37f9da9-f48e-4714-b052-f7b23acd773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鎧", "is_correct": true, "explanation": "正解。「身を守るための鎧を着る」で、体に着る防具を指す。"}, {"text": "盾", "is_correct": false, "explanation": "盾は手に持って構える防具で、体に着る防具ではないので、この文の「着る」の対象に合わない。"}, {"text": "兜", "is_correct": false, "explanation": "兜は頭にかぶる防具で、体に着る防具ではないので、この文の「着る」の対象に合わない。"}, {"text": "籠手", "is_correct": false, "explanation": "籠手は腕にはめる防具で、体全体に着るものではないので、この文の「着る」の対象に合わない。"}], "explanations": {"鎧": "正解。「身を守るための鎧を着る」で、体に着る防具を指す。", "盾": "盾は手に持って構える防具で、体に着る防具ではないので、この文の「着る」の対象に合わない。", "兜": "兜は頭にかぶる防具で、体に着る防具ではないので、この文の「着る」の対象に合わない。", "籠手": "籠手は腕にはめる防具で、体全体に着るものではないので、この文の「着る」の対象に合わない。"}, "sentence_index": 0, "correct_answer": "鎧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "頭を守るため、鎧をかぶって戦った。", "explanation": "ここは〈兜〉の意味。頭にかぶるのは兜で、体に着る鎧は〈かぶる〉とは言わないので合わない。"}, {"text": "敵の矢を受けるため、鎧を前に構えた。", "explanation": "ここは〈盾〉の意味。手に持って構えるのは盾で、体に着る鎧は〈構える〉とは言わないので合わない。"}, {"text": "腕を守るため、鎧を腕にはめた。", "explanation": "ここは〈籠手〉の意味。腕にはめるのは籠手で、体に着る鎧は〈はめる〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鎧", "is_correct": true, "explanation": "正解。「革の鎧は軽いが、金属ほど強くない」で、体を守る防具の材質を比べる文になる。"}, {"text": "面", "is_correct": false, "explanation": "面は頭だけにつける防具で、全身を覆う鎧の対象にはならないので合わない。"}, {"text": "胴", "is_correct": false, "explanation": "胴は体の前後だけを守る部分で、全身を覆う鎧ではないので、この文の対象に合わない。"}, {"text": "脛当て", "is_correct": false, "explanation": "脛当てはすねだけを守る防具で、全身を覆う鎧ではないので、この文の対象に合わない。"}], "explanations": {"鎧": "正解。「革の鎧は軽いが、金属ほど強くない」で、体を守る防具の材質を比べる文になる。", "面": "面は頭だけにつける防具で、全身を覆う鎧の対象にはならないので合わない。", "胴": "胴は体の前後だけを守る部分で、全身を覆う鎧ではないので、この文の対象に合わない。", "脛当て": "脛当てはすねだけを守る防具で、全身を覆う鎧ではないので、この文の対象に合わない。"}, "sentence_index": 6, "correct_answer": "鎧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になると、窓の鎧を閉めて寝る。", "explanation": "ここは〈鎧戸〉（窓の外側にある開閉する板戸）の意味。窓の戸を指すなら〈鎧戸〉と言い、武具の〈鎧〉とは言わないので合わない。"}, {"text": "剣道の練習で、鎧をつけた。", "explanation": "ここは〈面〉の意味。剣道で頭につけるのは面で、戦いの体の防具の〈鎧〉は練習には使わないので合わない。"}, {"text": "的を狙って、鎧を強く引いた。", "explanation": "ここは〈弓〉の意味。矢を放つ前に引くのは弓で、鎧は身につけるものなので〈引く〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王は金色の鎧に身につけて、戦場へ向かった。", "corrected_sentence": "王は金色の鎧を身につけて、戦場へ向かった。", "error_description": "「身につける」の対象は「を」で示す。「鎧に」は誤りで、正しくは「鎧を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52434, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兵士は鎧が脱いで、汗をふいた。", "corrected_sentence": "兵士は鎧を脱いで、汗をふいた。", "error_description": "「脱ぐ」の対象は「を」で示す。「鎧が」は誤りで、正しくは「鎧を脱いで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128bbf40-8380-487c-aa8f-e4f7f5c1f17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「冷気は下にたまりやすい」と話題を示す主題として、文頭の冷気に続く。ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「たまる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「冷気に下にたまりやすい」と続き、「に」が二重になるため不自然。"}, {"text": "と", "is_correct": false, "explanation": "「冷気と下にたまりやすい」では並列の意味になり、文の主題が立たない。"}], "correct_answer": "は", "explanations": {"は": "「冷気は下にたまりやすい」と話題を示す主題として、文頭の冷気に続く。ここに入る。", "を": "「たまる」は自動詞なので、目的語の「を」は取れない。", "に": "「冷気に下にたまりやすい」と続き、「に」が二重になるため不自然。", "と": "「冷気と下にたまりやすい」では並列の意味になり、文の主題が立たない。"}, "error_tags": {"は": "主題", "を": "目的語", "に": "場所・位置", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「冷気のせいで」と続き、冷気が原因の名詞に係る。ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "「冷気へせいで」では向かう先になり、原因を表す「せい」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「冷気でせいで」と「で」が重なり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「冷気からせいで」では起点の意味になり、「せい」の続きとして不自然。"}], "correct_answer": "の", "explanations": {"の": "「冷気のせいで」と続き、冷気が原因の名詞に係る。ここに入る。", "へ": "「冷気へせいで」では向かう先になり、原因を表す「せい」と合わない。", "で": "「冷気でせいで」と「で」が重なり、文が成り立たない。", "から": "「冷気からせいで」では起点の意味になり、「せい」の続きとして不自然。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "で": "原因・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "冷気は、冷たい空気のことです。", "primary_collocate": null, "pronunciation": "れいき", "ipa": "reːki", "syllable_count": 3, "sentences": [{"text": "ドアを開けた瞬間、外の冷気が顔にあたった。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "ドアを開[あ]けた瞬間[しゅんかん]、外[そと]の冷気[れいき]が顔[かお]にあたった。", "sentence_source": "generated"}, {"text": "冷気は下にたまりやすいので、床の近くがいちばん寒い。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷気[れいき]は下[した]にたまりやすいので、床[ゆか]の近[ちか]くがいちばん寒[さむ]い。", "sentence_source": "generated"}, {"text": "冷たい水辺から冷気が上がってきて、夕方は上着が必要だ。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷[つめ]たい水辺[みずべ]から冷気[れいき]が上[あ]がってきて、夕方[ゆうがた]は上着[うわぎ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "氷の入った箱から白い冷気がゆっくり出ていた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "氷[こおり]の入[はい]った箱[はこ]から白[しろ]い冷気[れいき]がゆっくり出[で]ていた。", "sentence_source": "generated"}, {"text": "冬の夜は、ふとんの外の冷気が肌にしみる。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]は、ふとんの外[そと]の冷気[れいき]が肌[はだ]にしみる。", "sentence_source": "generated"}, {"text": "部屋の冷気が逃げないよう、カーテンを閉めた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "部屋[へや]の冷気[れいき]が逃[に]げないよう、カーテンを閉[し]めた。", "sentence_source": "generated"}, {"text": "店の入り口から冷気が出ていて、通ると涼しい。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "店[みせ]の入[い]り口[ぐち]から冷気[れいき]が出[で]ていて、通[とお]ると涼[すず]しい。", "sentence_source": "generated"}, {"text": "冷気のせいで、窓ガラスが白く曇った。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷気[れいき]のせいで、窓[まど]ガラスが白[しろ]く曇[くも]った。", "sentence_source": "generated"}, {"text": "北からの冷気が流れ込み、明日は朝から冷え込むそうだ。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "北[きた]からの冷気[れいき]が流[なが]れ込[こ]み、明日[あした]は朝[あさ]から冷[ひ]え込[こ]むそうだ。", "sentence_source": "generated"}, {"text": "冷気を感じて空を見ると、雪が降り始めていた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷気[れいき]を感[かん]じて空[そら]を見[み]ると、雪[ゆき]が降[ふ]り始[はじ]めていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷気", "label": "基本形"}], "register": "標準（書き言葉・話し言葉どちらでも使う）", "sense_fingerprint": "冷たい空気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷気", "is_correct": true, "explanation": "「外の冷気が顔にあたった」で、外から来る冷たい空気として文脈に合う。"}, {"text": "体重計", "is_correct": false, "explanation": "体重計は顔にあたるものとして成り立たず、文が不自然になる。"}, {"text": "大根", "is_correct": false, "explanation": "大根が顔にあたるという状況は文脈に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖が顔にあたる状況は想定できず、意味が通らない。"}], "explanations": {"冷気": "「外の冷気が顔にあたった」で、外から来る冷たい空気として文脈に合う。", "体重計": "体重計は顔にあたるものとして成り立たず、文が不自然になる。", "大根": "大根が顔にあたるという状況は文脈に合わない。", "砂糖": "砂糖が顔にあたる状況は想定できず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "冷気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱が上がり、冷気がひどいので毛布を重ねた。", "explanation": "ここは〈寒気〉（ぞくぞくする寒さの感覚）の意味。冷気は周囲の空気なので、体の感覚には使わない。"}, {"text": "彼女は冷気に仕事を片付けた。", "explanation": "ここは〈冷静〉（落ち着いて物事を処理する）の意味。冷気は空気なので、人の落ち着いた態度には使えない。"}, {"text": "彼女の冷気の返事に、皆が黙り込んだ。", "explanation": "ここは〈冷淡〉（冷たく素っ気ない様子）の意味。冷気は空気なので、人の返事の性質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷気", "is_correct": true, "explanation": "「店の入り口から冷気が出ていて」で、店の入り口から出てくる冷たい空気が合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "店の入り口から鉛筆が出ているという状況は想定できず、文が成り立たない。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡が入り口から出ているという内容は文脈に合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸が入り口から出ているという状況は不自然で、意味が通らない。"}], "explanations": {"冷気": "「店の入り口から冷気が出ていて」で、店の入り口から出てくる冷たい空気が合う。", "鉛筆": "店の入り口から鉛筆が出ているという状況は想定できず、文が成り立たない。", "鏡": "鏡が入り口から出ているという内容は文脈に合わない。", "石鹸": "石鹸が入り口から出ているという状況は不自然で、意味が通らない。"}, "sentence_index": 6, "correct_answer": "冷気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人が冷気を言って、みんなが笑った。", "explanation": "ここは〈冷やかし〉（からかう言葉）の意味。冷気は空気なので、言う内容にはならない。"}, {"text": "冷気の笑みを浮かべた。", "explanation": "ここは〈冷ややか〉（冷たく見下す様子）の意味。冷気は空気なので、人の表情には使えない。"}, {"text": "寒いので冷気を切った。", "explanation": "ここは〈冷房〉（冷やす機器）の意味。切る対象は機器で、冷気は空気なので切るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの前には冷気に漂っていた。", "corrected_sentence": "ドアの前には冷気が漂っていた。", "error_description": "「漂う」の主語は「冷気が」。「冷気に」は場所や相手を示す「に」で、「冷気に漂う」は主語にならず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52435, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドアが開くたびに、冷気が店内へ流れ込ませる。", "corrected_sentence": "ドアが開くたびに、冷気が店内へ流れ込む。", "error_description": "「流れ込む」は自動詞。「流れ込ませる」は使役形で、動かす対象（目的語）を必要とするため、冷気を主語にするこの文では不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「冷気が足もとに流れてきた」で、冷気が流れる主語になる。ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「流れてくる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "の", "is_correct": false, "explanation": "「冷気の足もと」と続くと冷気の所在の話になり、流れる主体にならない。"}, {"text": "に", "is_correct": false, "explanation": "直後に「足もとに」と「に」が続くため、「に」を重ねることになり不自然。"}], "correct_answer": "が", "explanations": {"が": "「冷気が足もとに流れてきた」で、冷気が流れる主語になる。ここに入る。", "を": "「流れてくる」は自動詞なので、目的語の「を」は取れない。", "の": "「冷気の足もと」と続くと冷気の所在の話になり、流れる主体にならない。", "に": "直後に「足もとに」と「に」が続くため、「に」を重ねることになり不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「冷気が直接顔に当たって」で、冷気が当たる主語になる。ここに入る。"}, {"text": "で", "is_correct": false, "explanation": "「冷気で直接顔に当たって」では冷気が当たる主体にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「冷気と直接顔に当たって」では動作の主体が立たず、並列の意味も合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すが、「冷気へ顔に当たる」では冷気が到達点になり文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "「冷気が直接顔に当たって」で、冷気が当たる主語になる。ここに入る。", "で": "「冷気で直接顔に当たって」では冷気が当たる主体にならず、文が成り立たない。", "と": "「冷気と直接顔に当たって」では動作の主体が立たず、並列の意味も合わない。", "へ": "「へ」は向かう先を示すが、「冷気へ顔に当たる」では冷気が到達点になり文脈に合わない。"}, "error_tags": {"が": "主語", "で": "原因・手段", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "冷気は、周りの温度より低く、冷たさを感じさせる空気のことです。", "primary_collocate": null, "pronunciation": "れいき", "ipa": "reːki", "syllable_count": 3, "sentences": [{"text": "彼は不器用ながらも、分厚いコートの袖に腕を通し、冷気から身を守るための鎧を着る。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "彼[かれ]は不器用[ぶきよう]ながらも、分厚[ぶあつ]いコートの袖[そで]に腕[うで]を通[とお]し、冷気[れいき]から身[み]を守[まも]るための鎧[よろい]を着[き]る。", "sentence_source": "mined"}, {"text": "冷蔵庫の扉を開けると、冷気が足もとに流れてきた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の扉[とびら]を開[あ]けると、冷気[れいき]が足[あし]もとに流[なが]れてきた。", "sentence_source": "generated"}, {"text": "窓の隙間から冷気が入り込み、部屋がなかなか暖まらない。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "窓[まど]の隙間[すきま]から冷気[れいき]が入[はい]り込[こ]み、部屋[へや]がなかなか暖[あたた]まらない。", "sentence_source": "generated"}, {"text": "山の洞窟に入ると、奥から冷気が吹き出してきて身震いした。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "山[やま]の洞窟[どうくつ]に入[はい]ると、奥[おく]から冷気[れいき]が吹[ふ]き出[だ]してきて身震[みぶる]いした。", "sentence_source": "generated"}, {"text": "夏でも地下室は冷気が漂っていて、少し寒いくらいだ。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "夏[なつ]でも地下室[ちかしつ]は冷気[れいき]が漂[ただよ]っていて、少[すこ]し寒[さむ]いくらいだ。", "sentence_source": "generated"}, {"text": "冷気を逃がさないように、店の入り口は急いで閉めてください。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷気[れいき]を逃[に]がさないように、店[みせ]の入[い]り口[ぐち]は急[いそ]いで閉[し]めてください。", "sentence_source": "generated"}, {"text": "朝の冷気で目が覚め、毛布を肩まで引き上げた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "朝[あさ]の冷気[れいき]で目[め]が覚[さ]め、毛布[もうふ]を肩[かた]まで引[ひ]き上[あ]げた。", "sentence_source": "generated"}, {"text": "エアコンの冷気が直接顔に当たって、のどが痛くなった。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "エアコンの冷気[れいき]が直接[ちょくせつ]顔[かお]に当[あ]たって、のどが痛[いた]くなった。", "sentence_source": "generated"}, {"text": "雪原を渡る風は鋭い冷気をまとっていた。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "雪原[せつげん]を渡[わた]る風[かぜ]は鋭[するど]い冷気[れいき]をまとっていた。", "sentence_source": "generated"}, {"text": "冷凍庫から出る冷気のせいで、手がかじかんだ。", "target_word": "冷気", "complexity_tier": "T3", "furigana": "冷凍庫[れいとうこ]から出[で]る冷気[れいき]のせいで、手[て]がかじかんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷気", "label": "基本形"}], "register": "標準（書き言葉・話し言葉どちらでも使う）", "sense_fingerprint": "周囲より低温で冷たさを感じさせる空気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷気", "is_correct": true, "explanation": "「冷気から身を守る」の対象として、寒さをもたらす空気が文脈に合う。"}, {"text": "歌声", "is_correct": false, "explanation": "歌声は身を守る対象にならず、鎧を着る理由が成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖から鎧で身を守るという内容は文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は身を守る対象にならず、文の意味が通らない。"}], "explanations": {"冷気": "「冷気から身を守る」の対象として、寒さをもたらす空気が文脈に合う。", "歌声": "歌声は身を守る対象にならず、鎧を着る理由が成り立たない。", "砂糖": "砂糖から鎧で身を守るという内容は文脈に合わない。", "教科書": "教科書は身を守る対象にならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "冷気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪で熱が出て、冷気が止まらない。", "explanation": "ここは〈寒気〉（ぞくぞくする寒さの症状）の意味。冷気は周囲の空気なので、体の症状には使えない。"}, {"text": "この店は冷気の客ばかりで、買う人がほとんどいない。", "explanation": "ここは〈冷やかし〉（買わずに見て回る客）の意味。冷気は空気なので、人を指す語にはならない。"}, {"text": "あの人は冷気で、誰にも親身にならない。", "explanation": "ここは〈冷淡〉（人に対して冷たく親身でない）の意味。冷気は空気なので、人の性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷気", "is_correct": true, "explanation": "「朝の冷気で目が覚める」が成り立つ。寒さが目覚めの原因になる。"}, {"text": "定規", "is_correct": false, "explanation": "定規は目覚めの原因にならず、「朝の定規で目が覚め」は意味が通らない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸で目が覚めるという因果関係は文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は目覚めの原因にならず、文が成り立たない。"}], "explanations": {"冷気": "「朝の冷気で目が覚める」が成り立つ。寒さが目覚めの原因になる。", "定規": "定規は目覚めの原因にならず、「朝の定規で目が覚め」は意味が通らない。", "石鹸": "石鹸で目が覚めるという因果関係は文脈に合わない。", "鉛筆": "鉛筆は目覚めの原因にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "冷気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は冷気に状況を見極め、すぐに指示を出した。", "explanation": "ここは〈冷静〉（落ち着いて判断する）の意味。冷気は空気を指すので、人の落ち着いた態度には使えない。"}, {"text": "彼女の冷気の視線に、場が静まり返った。", "explanation": "ここは〈冷ややか〉（冷たく突き放す様子）の意味。冷気は空気なので、人の視線や態度には使わない。"}, {"text": "暑いので、部屋の冷気をつけた。", "explanation": "ここは〈冷房〉（冷やす機器）の意味。つける対象は機器で、冷気は空気なのでつけるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、冷気を部屋に入ってきた。", "corrected_sentence": "窓を開けると、冷気が部屋に入ってきた。", "error_description": "「冷気」の後には主語を表す「が」が正しい。「を」は目的語用で、自動詞の「入ってくる」とは組み合わさらないため不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52436, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このドアは隙間が多く、冷気が部屋に入り込んでくれる。", "corrected_sentence": "このドアは隙間が多く、冷気が部屋に入り込んでくる。", "error_description": "「入り込んでくる」が正しい。「くれる」は他者が恩恵として行う動作を表す補助動詞で、冷気が主語の自然現象には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「制服のボタンを数える」で、ボタンが数える対象の目的語になる。ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「ボタンが数えていた」では主語が立たず、数えるのは弟なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ボタンに数える」は場所や相手の意味になり、数える対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「ボタンと数える」では並列の意味になり、数える対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「制服のボタンを数える」で、ボタンが数える対象の目的語になる。ここに入る。", "が": "「ボタンが数えていた」では主語が立たず、数えるのは弟なので合わない。", "に": "「ボタンに数える」は場所や相手の意味になり、数える対象を示せない。", "と": "「ボタンと数える」では並列の意味になり、数える対象として成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "場所・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かわいい動物の形のボタンを子ども服に付けた」で、ボタンが付ける対象の目的語になる。ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "「ボタンへ子ども服に付けた」では向かう先になり、付ける対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「ボタンから子ども服に付けた」では起点の意味になり、付ける対象として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「ボタンより子ども服に付けた」では比較の意味になり、付ける対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「かわいい動物の形のボタンを子ども服に付けた」で、ボタンが付ける対象の目的語になる。ここに入る。", "へ": "「ボタンへ子ども服に付けた」では向かう先になり、付ける対象を示せない。", "から": "「ボタンから子ども服に付けた」では起点の意味になり、付ける対象として成り立たない。", "より": "「ボタンより子ども服に付けた」では比較の意味になり、付ける対象を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "服の前をとめるための、小さくてまるいもの。", "primary_collocate": null, "pronunciation": "ぼたん", "ipa": "botaɴ", "syllable_count": 3, "sentences": [{"text": "白いシャツの丸いボタンが一つ、床に落ちていた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "白[しろ]いシャツの丸[まる]いボタンが一[ひと]つ、床[ゆか]に落[お]ちていた。", "sentence_source": "generated"}, {"text": "弟は新しい制服のボタンを、うれしそうに数えていた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "弟[おとうと]は新[あたら]しい制服[せいふく]のボタンを、うれしそうに数[かぞ]えていた。", "sentence_source": "generated"}, {"text": "赤いコートには、大きなボタンが三つ付いている。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "赤[あか]いコートには、大[おお]きなボタンが三[みっ]つ付[つ]いている。", "sentence_source": "generated"}, {"text": "ボタンが外れそうなので、針と糸を用意した。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "ボタンが外[はず]れそうなので、針[はり]と糸[いと]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "洗濯したら、ボタンが一つなくなっていた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "洗濯[せんたく]したら、ボタンが一[ひと]つなくなっていた。", "sentence_source": "generated"}, {"text": "妹は服のボタンを自分で留められるようになった。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "妹[いもうと]は服[ふく]のボタンを自分[じぶん]で留[と]められるようになった。", "sentence_source": "generated"}, {"text": "黒い上着には、金色のボタンがよく似合う。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "黒[くろ]い上着[うわぎ]には、金色[きんいろ]のボタンがよく似合[にあ]う。", "sentence_source": "generated"}, {"text": "かわいい動物の形のボタンを、子ども服に付けた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "かわいい動物[どうぶつ]の形[かたち]のボタンを、子[こ]ども服[ふく]に付[つ]けた。", "sentence_source": "generated"}, {"text": "ボタンを留めないまま家を出て、友だちに笑われた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "ボタンを留[と]めないまま家[いえ]を出[で]て、友[とも]だちに笑[わら]われた。", "sentence_source": "generated"}, {"text": "古い洋服から、きれいなボタンだけを取っておいた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "古[ふる]い洋服[ようふく]から、きれいなボタンだけを取[と]っておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボタン", "label": "基本形"}], "register": "標準（日常語）", "sense_fingerprint": "服の前をとめる小さくて丸いもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボタン", "is_correct": true, "explanation": "「白いシャツの丸いボタン」は服の前をとめる小さくて丸い部品として成り立つ。"}, {"text": "日記", "is_correct": false, "explanation": "シャツの丸い日記という組み合わせは成り立たず、文が不自然になる。"}, {"text": "座布団", "is_correct": false, "explanation": "シャツに付いた座布団という状況は文脈に合わない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯ブラシは丸くなく、「丸い歯ブラシ」は文脈に合わない。"}], "explanations": {"ボタン": "「白いシャツの丸いボタン」は服の前をとめる小さくて丸い部品として成り立つ。", "日記": "シャツの丸い日記という組み合わせは成り立たず、文が不自然になる。", "座布団": "シャツに付いた座布団という状況は文脈に合わない。", "歯ブラシ": "歯ブラシは丸くなく、「丸い歯ブラシ」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ボタン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、コートのボタンを固く結んだ。", "explanation": "ここは〈紐〉を結ぶ意味。ボタンは穴に通して留める部品で、結ぶものではない。"}, {"text": "傷口に、小さなボタンを貼って血を止めた。", "explanation": "ここは〈絆創膏〉を貼る意味。ボタンは傷を覆うものではなく、服の合わせ目をとめる部品として使う。"}, {"text": "着物のボタンを締めて、背筋を伸ばした。", "explanation": "ここは〈帯〉を締める意味。ボタンは留めるもので、締める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボタン", "is_correct": true, "explanation": "「金色のボタンがよく似合う」で、上着に付く飾りとして自然に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "金色の教科書が上着に似合うという内容は成り立たない。"}, {"text": "消火器", "is_correct": false, "explanation": "金色の消火器が上着に似合うという文脈は不自然で、意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫が上着に似合うという状況は想定できず、文が成り立たない。"}], "explanations": {"ボタン": "「金色のボタンがよく似合う」で、上着に付く飾りとして自然に合う。", "教科書": "金色の教科書が上着に似合うという内容は成り立たない。", "消火器": "金色の消火器が上着に似合うという文脈は不自然で、意味が通らない。", "冷蔵庫": "冷蔵庫が上着に似合うという状況は想定できず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ボタン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "書類の束を、ボタンで挟んでまとめた。", "explanation": "ここは〈クリップ〉（紙を挟んでとめる文具）の意味。ボタンは服の合わせ目をとめる部品で、紙は挟まない。"}, {"text": "ビンのボタンを抜いて、ワインを開けた。", "explanation": "ここは〈栓〉を抜く意味。ボタンは抜く対象ではなく、栓の働きをしない。"}, {"text": "スカーフのボタンを首に巻いて、寒さをしのいだ。", "explanation": "ここは〈マフラー〉を巻く意味。ボタンは穴に通して留める部品で、首に巻くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒いので、ジャケットのボタンをしっかり縛った。", "corrected_sentence": "寒いので、ジャケットのボタンをしっかり留めた。", "error_description": "ボタンと組む動詞は「留める」が正しい。「縛る」は紐や荷物を巻いて固定する動作に使うので、ボタンには合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52437, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カバンの中に、小さなボタンを一つ転がっていた。", "corrected_sentence": "カバンの中に、小さなボタンが一つ転がっていた。", "error_description": "「転がる」の主語には「が」が正しい。「を」は目的語用で、自動詞の「転がる」とは組み合わさらないため不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ボタンが取れた」で、ボタンが取れる主語になる。ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「取れた」は自動詞なので、「ボタンを取れた」とは目的語を取れない。"}, {"text": "に", "is_correct": false, "explanation": "「ボタンに取れた」では場所や相手になり、取れる主体にならない。"}, {"text": "で", "is_correct": false, "explanation": "「ボタンで取れた」では手段の意味になり、取れた主体として不自然。"}], "correct_answer": "が", "explanations": {"が": "「ボタンが取れた」で、ボタンが取れる主語になる。ここに入る。", "を": "「取れた」は自動詞なので、「ボタンを取れた」とは目的語を取れない。", "に": "「ボタンに取れた」では場所や相手になり、取れる主体にならない。", "で": "「ボタンで取れた」では手段の意味になり、取れた主体として不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所・相手", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ボタンがたくさん入っていた」で、ボタンが入っている主語になる。ここに入る。"}, {"text": "と", "is_correct": false, "explanation": "「ボタンとたくさん入っていた」では並列の意味になり、主語が立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ボタンへたくさん入っていた」では向かう先になり、入るものとして不自然。"}, {"text": "から", "is_correct": false, "explanation": "「ボタンからたくさん入っていた」では起点の意味になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ボタンがたくさん入っていた」で、ボタンが入っている主語になる。ここに入る。", "と": "「ボタンとたくさん入っていた」では並列の意味になり、主語が立たない。", "へ": "「ボタンへたくさん入っていた」では向かう先になり、入るものとして不自然。", "から": "「ボタンからたくさん入っていた」では起点の意味になり、文が成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衣服などの合わせ目をとめるための、小さな部品。布やプラスチックなどでできていて、通すための穴（ボタンホール）に通したり、押し込んだりして使う。", "primary_collocate": null, "pronunciation": "ぼたん", "ipa": "botaɴ", "syllable_count": 3, "sentences": [{"text": "寒い朝、ボタンを一つずつ留めてから外へ出た。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]、ボタンを一[ひと]つずつ留[と]めてから外[そと]へ出[で]た。", "sentence_source": "generated"}, {"text": "コートのボタンが取れたので、母に付け直してもらった。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "コートのボタンが取[と]れたので、母[はは]に付[つ]け直[なお]してもらった。", "sentence_source": "generated"}, {"text": "急いでいたので、シャツのボタンを一つ掛け違えてしまった。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "急[いそ]いでいたので、シャツのボタンを一[ひと]つ掛[か]け違[ちが]えてしまった。", "sentence_source": "generated"}, {"text": "このジャケットは大きな金属のボタンが特徴だ。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "このジャケットは大[おお]きな金属[きんぞく]のボタンが特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "小さな子どもにはボタンより、ファスナーのほうが着せやすい。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]どもにはボタンより、ファスナーのほうが着[き]せやすい。", "sentence_source": "generated"}, {"text": "袖のボタンが緩んでいたので、糸で縫い直した。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "袖[そで]のボタンが緩[ゆる]んでいたので、糸[いと]で縫[ぬ]い直[なお]した。", "sentence_source": "generated"}, {"text": "首元のボタンまで留めると、少し息苦しい。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "首元[くびもと]のボタンまで留[と]めると、少[すこ]し息苦[いきぐる]しい。", "sentence_source": "generated"}, {"text": "祖母の箱には、古い貝のボタンがたくさん入っていた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "祖母[そぼ]の箱[はこ]には、古[ふる]い貝[かい]のボタンがたくさん入[はい]っていた。", "sentence_source": "generated"}, {"text": "このシャツは穴が小さすぎて、ボタンがなかなか通らない。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "このシャツは穴[あな]が小[ちい]さすぎて、ボタンがなかなか通[とお]らない。", "sentence_source": "generated"}, {"text": "寒くなったので、コートのボタンを上まで全部留めた。", "target_word": "ボタン", "complexity_tier": "T3", "furigana": "寒[さむ]くなったので、コートのボタンを上[うえ]まで全部[ぜんぶ]留[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボタン", "label": "基本形"}], "register": "標準（日常語）", "sense_fingerprint": "衣服の合わせ目を穴に通してとめる小さな部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボタン", "is_correct": true, "explanation": "「ボタンを一つずつ留めてから」が成り立つ。留める対象として自然。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶を一つひとつ留めるという動作は成り立たず、文が不自然になる。"}, {"text": "硬貨", "is_correct": false, "explanation": "硬貨を留める動作は想定できず、文脈に合わない。"}, {"text": "大根", "is_correct": false, "explanation": "大根を留める仕草という内容は意味が通らない。"}], "explanations": {"ボタン": "「ボタンを一つずつ留めてから」が成り立つ。留める対象として自然。", "紅茶": "紅茶を一つひとつ留めるという動作は成り立たず、文が不自然になる。", "硬貨": "硬貨を留める動作は想定できず、文脈に合わない。", "大根": "大根を留める仕草という内容は意味が通らない。"}, "sentence_index": 0, "correct_answer": "ボタン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、ボタンを一番上まで上げた。", "explanation": "ここは〈ファスナー〉を上げる意味。ボタンは留めるもので、上げるとは言わない。"}, {"text": "真冬の屋外で、ボタンを首にぐるぐる巻いた。", "explanation": "ここは〈マフラー〉を巻く意味。ボタンは穴に通して留める小さな部品で、首に巻くものではない。"}, {"text": "ネックレスのボタンを外して、宝石箱にしまった。", "explanation": "ここは〈留め金〉（留め具）の意味。ネックレスの留め具を指し、服の合わせ目の部品ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボタン", "is_correct": true, "explanation": "「首元のボタンまで留めると」が成り立つ。首元で留める部品として自然。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋を首元で留めるという行為は成り立たず、文脈に合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵を首元で留めるという内容は不自然で、文が成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手を首元で留めるという状況は想定できず、意味が通らない。"}], "explanations": {"ボタン": "「首元のボタンまで留めると」が成り立つ。首元で留める部品として自然。", "手袋": "手袋を首元で留めるという行為は成り立たず、文脈に合わない。", "鍵": "鍵を首元で留めるという内容は不自然で、文が成り立たない。", "切手": "切手を首元で留めるという状況は想定できず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "ボタン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ベルトのボタンを締めて、ズボンを固定した。", "explanation": "ここは〈バックル〉（締めて留める金具）の意味。ボタンは留めるもので、締める対象にはならない。"}, {"text": "靴のボタンをほどいて、足を楽にした。", "explanation": "ここは〈靴紐〉をほどく意味。ボタンは留めるもので、ほどくとは言わない。"}, {"text": "エレベーターのボタンを押して、一階に行った。", "explanation": "ここは〈押しボタン〉（押して機器を動かす部品）の意味。服の合わせ目をとめる部品としてのボタンとは別の意味で使っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い朝、コートのボタンをしっかり結んで出かけた。", "corrected_sentence": "寒い朝、コートのボタンをしっかり留めて出かけた。", "error_description": "ボタンと組む動詞は「留める」が正しい。「結ぶ」は紐や糸を結び合わせる動作に使うので、ボタンには合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "眠る前に、パジャマのボタンに一つずつ外した。", "corrected_sentence": "眠る前に、パジャマのボタンを一つずつ外した。", "error_description": "「外す」の目的語には「を」が正しい。「ボタンに」は場所や相手を示す「に」で、目的語として働かず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
