INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52441, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをするときの、手や体の小さな動きのことです。", "primary_collocate": null, "pronunciation": "しぐさ", "ipa": "ɕiɡɯsa", "syllable_count": 3, "sentences": [{"text": "妹が髪を耳にかける仕草は、母によく似ている。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "妹[いもうと]が髪[かみ]を耳[みみ]にかける仕草[しぐさ]は、母[はは]によく似[に]ている。", "sentence_source": "generated"}, {"text": "母は、うれしいと手をたたく仕草をする。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "母[はは]は、うれしいと手[て]をたたく仕草[しぐさ]をする。", "sentence_source": "generated"}, {"text": "彼は考えるとき、あごに手を当てる仕草をする。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "彼[かれ]は考[かんが]えるとき、あごに手[て]を当[あ]てる仕草[しぐさ]をする。", "sentence_source": "generated"}, {"text": "子どもが「ありがとう」と頭を下げる仕草を覚えた。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "子[こ]どもが「ありがとう」と頭[あたま]を下[さ]げる仕草[しぐさ]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "手を振る仕草だけで、遠くの友だちに気づいてもらえた。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "手[て]を振[ふ]る仕草[しぐさ]だけで、遠[とお]くの友[とも]だちに気[き]づいてもらえた。", "sentence_source": "generated"}, {"text": "店員さんはお茶を置く仕草がていねいだった。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "店員[てんいん]さんはお茶[ちゃ]を置[お]く仕草[しぐさ]がていねいだった。", "sentence_source": "generated"}, {"text": "彼女は眠い目をこする仕草をして、あくびをした。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は眠[ねむ]い目[め]をこする仕草[しぐさ]をして、あくびをした。", "sentence_source": "generated"}, {"text": "首をかしげる仕草で、「わからない」と伝えた。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "首[くび]をかしげる仕草[しぐさ]で、「わからない」と伝[つた]えた。", "sentence_source": "generated"}, {"text": "祖父が眼鏡を探す仕草をしたので、私は机の上を指さした。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "祖父[そふ]が眼鏡[めがね]を探[さが]す仕草[しぐさ]をしたので、私[わたし]は机[つくえ]の上[うえ]を指[ゆび]さした。", "sentence_source": "generated"}, {"text": "兄の走る仕草をまねして、弟は庭を駆け回った。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "兄[あに]の走[はし]る仕草[しぐさ]をまねして、弟[おとうと]は庭[にわ]を駆[か]け回[まわ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕草", "label": "基本形"}], "register": "標準（書き言葉・話し言葉どちらでも使う）", "sense_fingerprint": "何かをするときの手や体の小さな動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52441, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕草", "is_correct": true, "explanation": "髪を耳にかける手の小さな動きを指し、母に似ているという比べ方に合う。"}, {"text": "声", "is_correct": false, "explanation": "耳で聞くものなので、髪を耳にかける動きの対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を指すので、人の手の動きには当てはまらない。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描かれた図なので、髪を耳にかける動きの説明にはならない。"}], "explanations": {"仕草": "髪を耳にかける手の小さな動きを指し、母に似ているという比べ方に合う。", "声": "耳で聞くものなので、髪を耳にかける動きの対象にはならない。", "天気": "空の状態を指すので、人の手の動きには当てはまらない。", "地図": "紙に描かれた図なので、髪を耳にかける動きの説明にはならない。"}, "sentence_index": 0, "correct_answer": "仕草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、ロボットアームの仕草を毎日点検している。", "explanation": "ここは〈動作〉の意味。仕草は人の手や体の小さな動きなので、機械の動作点検には合わない。"}, {"text": "この時計は仕草が細かく、修理できる人が少ない。", "explanation": "ここは〈仕組み〉の意味。仕草は人の体の動きを指すので、時計の内部の構造には使わない。"}, {"text": "彼は舞台の上で仕草を大きく響かせ、客席の後ろまで届けた。", "explanation": "ここは〈声〉の意味。仕草は見える動きなので、響いて届くのは音や声に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52441, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕草", "is_correct": true, "explanation": "眠い目をこするという体の動きを指し、「をして」と続いて自然。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送る文章なので、目をこする動きの対象にはならない。"}, {"text": "階段", "is_correct": false, "explanation": "段差のある通路なので、目をこするという行為とは結びつかない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる入れ物なので、目をこするという動きには合わない。"}], "explanations": {"仕草": "眠い目をこするという体の動きを指し、「をして」と続いて自然。", "手紙": "書いて送る文章なので、目をこする動きの対象にはならない。", "階段": "段差のある通路なので、目をこするという行為とは結びつかない。", "財布": "お金を入れる入れ物なので、目をこするという動きには合わない。"}, "sentence_index": 6, "correct_answer": "仕草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は寝坊する仕草が直らず、毎朝遅刻している。", "explanation": "ここは〈癖〉の意味。寝坊は体の動きではなく習慣なので、仕草とは言わない。"}, {"text": "そのアプリは仕草の登録に三日かかる。", "explanation": "ここは〈手続き〉の意味。仕草は体の動きを指すので、アプリの登録手続きには使わない。"}, {"text": "彼は話し合いで、誠実な仕草を最後まで貫いた。", "explanation": "ここは〈態度〉の意味。仕草は一瞬の体の動きなので、最後まで貫くような持続的な構えには言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52441, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、答えが分からないと、首を横に振る仕草へする。", "corrected_sentence": "先生は、答えが分からないと、首を横に振る仕草をする。", "error_description": "「する」は「仕草を」と目的語に「を」を取る。「仕草へ」は方向の「へ」で誤り。正しくは「仕草を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52441, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は指で鼻をかく仕草へして、笑った。", "corrected_sentence": "兄は指で鼻をかく仕草をして、笑った。", "error_description": "「仕草へ」は方向の「へ」で誤り。対象を表す「を」が正しく、正しくは「仕草をして」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "仕草が主語になり、「変わらない」の主語として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「変わらない」は目的語を取らない語なので、「を」は続かない。"}, {"text": "に", "is_correct": false, "explanation": "「変わらない」は相手や場所を「に」で受けないので、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「変わらない」は行き先を取らないので、「へ」では文の流れに合わない。"}], "correct_answer": "が", "explanations": {"が": "仕草が主語になり、「変わらない」の主語として自然に続く。", "を": "「変わらない」は目的語を取らない語なので、「を」は続かない。", "に": "「変わらない」は相手や場所を「に」で受けないので、文が成り立たない。", "へ": "「変わらない」は行き先を取らないので、「へ」では文の流れに合わない。"}, "error_tags": {"を": "対象の格（目的語）", "に": "相手・場所の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「見とれる」は「～に見とれる」と対象を「に」で示すので自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「見とれる」は「に」を取る語なので、「を」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「見とれる」に方向の「へ」は続かず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」では並べる相手が示せず、「見とれた」と続く文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「見とれる」は「～に見とれる」と対象を「に」で示すので自然に続く。", "を": "「見とれる」は「に」を取る語なので、「を」は続かない。", "へ": "「見とれる」に方向の「へ」は続かず、文が成り立たない。", "と": "「と」では並べる相手が示せず、「見とれた」と続く文が成立しない。"}, "error_tags": {"を": "対象の格（目的語）", "へ": "方向の格", "と": "並列の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人の動作や行動の様子。特に、細かい動きや表情を含めた、そのときの振る舞いを表す言葉。", "primary_collocate": null, "pronunciation": "しぐさ", "ipa": "ɕiɡɯsa", "syllable_count": 3, "sentences": [{"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "仕草", "complexity_tier": "T5", "furigana": "凍[い]てつく空気[くうき]の中[なか]、ボタンを一[ひと]つひとつ留[と]める仕草[しぐさ]には、未知[みち]の領域[りょういき]へ挑[いど]む戦士[せんし]のような厳粛[げんしゅく]ささえ漂[ただよ]っていた。", "sentence_source": "mined"}, {"text": "彼女は困ったときに髪をさわる仕草が、子どものころから変わらない。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は困[こま]ったときに髪[かみ]をさわる仕草[しぐさ]が、子[こ]どものころから変[か]わらない。", "sentence_source": "generated"}, {"text": "犬を抱き上げる仕草がやさしくて、見ていた客も笑顔になった。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "犬[いぬ]を抱[だ]き上[あ]げる仕草[しぐさ]がやさしくて、見[み]ていた客[きゃく]も笑顔[えがお]になった。", "sentence_source": "generated"}, {"text": "役者は細かい仕草で、老人の疲れを見事に表していた。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "役者[やくしゃ]は細[こま]かい仕草[しぐさ]で、老人[ろうじん]の疲[つか]れを見事[みごと]に表[あらわ]していた。", "sentence_source": "generated"}, {"text": "彼の照れたときの仕草は、兄とそっくりだ。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "彼[かれ]の照[て]れたときの仕草[しぐさ]は、兄[あに]とそっくりだ。", "sentence_source": "generated"}, {"text": "話を聞いているふりをしていたが、時計を見る仕草で退屈だとわかった。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "話[はなし]を聞[き]いているふりをしていたが、時計[とけい]を見[み]る仕草[しぐさ]で退屈[たいくつ]だとわかった。", "sentence_source": "generated"}, {"text": "赤ちゃんの小さな仕草を見るだけで、毎日が楽しい。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの小[ちい]さな仕草[しぐさ]を見[み]るだけで、毎日[まいにち]が楽[たの]しい。", "sentence_source": "generated"}, {"text": "彼女の上品な仕草に、会場の誰もが見とれた。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の上品[じょうひん]な仕草[しぐさ]に、会場[かいじょう]の誰[だれ]もが見[み]とれた。", "sentence_source": "generated"}, {"text": "言葉が通じなくても、仕草を見れば気持ちは伝わる。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じなくても、仕草[しぐさ]を見[み]れば気持[きも]ちは伝[つた]わる。", "sentence_source": "generated"}, {"text": "先生は、驚いたときに眉を上げる仕草をよくする。", "target_word": "仕草", "complexity_tier": "T3", "furigana": "先生[せんせい]は、驚[おどろ]いたときに眉[まゆ]を上[あ]げる仕草[しぐさ]をよくする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕草", "label": "基本形"}], "register": "標準（書き言葉・話し言葉どちらでも使う）", "sense_fingerprint": "細かい動きや表情を含む、その人の振る舞いの様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕草", "is_correct": true, "explanation": "ボタンを留める細かい手の動きや様子を表し、「厳粛さが漂っていた」と自然につながる。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送る文章を指すので、ボタンを留める動きの様子にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指すので、ボタンを留める行為には結びつかない。"}, {"text": "階段", "is_correct": false, "explanation": "段差のある通路を指すので、ボタンを留める動きを表せない。"}], "explanations": {"仕草": "ボタンを留める細かい手の動きや様子を表し、「厳粛さが漂っていた」と自然につながる。", "手紙": "書いて送る文章を指すので、ボタンを留める動きの様子にはならない。", "天気": "空模様を指すので、ボタンを留める行為には結びつかない。", "階段": "段差のある通路を指すので、ボタンを留める動きを表せない。"}, "sentence_index": 0, "correct_answer": "仕草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は仕草が複雑で、説明書を読んでも分からない。", "explanation": "ここは〈仕組み〉の意味。仕草は人や動物の体の動きを指すので、機械の構造には使わない。"}, {"text": "この倉庫では、フォークリフトの仕草を毎朝確認している。", "explanation": "ここは〈動作〉の意味。仕草は人の細かい体の動きを指すので、機械の動作確認には合わない。"}, {"text": "彼は会社の方針を大きく変えるため、新しい仕草を発表した。", "explanation": "ここは〈施策〉の意味。仕草は体の動きを指すので、会社の方針や施策を打ち出す場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕草", "is_correct": true, "explanation": "赤ちゃんの小さな体の動きを指し、「を見る」の対象として自然。"}, {"text": "声", "is_correct": false, "explanation": "声は聞くものなので、「見る」の対象としては合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は聞こえるものなので、「見る」の対象にはならない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは嗅ぐものなので、「見る」の対象としては不自然。"}], "explanations": {"仕草": "赤ちゃんの小さな体の動きを指し、「を見る」の対象として自然。", "声": "声は聞くものなので、「見る」の対象としては合わない。", "足音": "足音は聞こえるものなので、「見る」の対象にはならない。", "匂い": "匂いは嗅ぐものなので、「見る」の対象としては不自然。"}, "sentence_index": 6, "correct_answer": "仕草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、毎朝遅刻する仕草がなかなか直らない。", "explanation": "ここは〈癖〉の意味。遅刻は体の動きではなく習慣なので、仕草とは言わない。"}, {"text": "役所では、仕草の届け出に一週間ほどかかる。", "explanation": "ここは〈手続き〉の意味。仕草は体の動きを指すので、役所の届け出や手続きには使わない。"}, {"text": "彼女は舞台で、仕草を大きく響かせて客席の後ろまで届けた。", "explanation": "ここは〈声〉の意味。仕草は見える動きなので、響かせて届けるのは音や声に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は緊張すると、指で机をたたく仕草に繰り返した。", "corrected_sentence": "彼は緊張すると、指で机をたたく仕草を繰り返した。", "error_description": "「繰り返す」は目的語に「を」を取る。「仕草に」は誤りで、正しくは「仕草を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は話し終えると、髪を耳にかける仕草へした。", "corrected_sentence": "彼女は話し終えると、髪を耳にかける仕草をした。", "error_description": "「仕草へ」は方向の「へ」で誤り。対象を表す「を」が正しく、正しくは「仕草をした」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
