INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たたかう人のこと。", "primary_collocate": null, "pronunciation": "せんし", "ipa": "seɴɕi", "syllable_count": 3, "sentences": [{"text": "昔、この国には何百人もの戦士がいた。", "target_word": "戦士", "complexity_tier": "T2", "furigana": "昔[むかし]、この国[くに]には何百人[なんびゃくにん]もの戦士[せんし]がいた。", "sentence_source": "generated"}, {"text": "戦士は朝早くから剣の練習を始めた。", "target_word": "戦士", "complexity_tier": "T2", "furigana": "戦士[せんし]は朝早[あさはや]くから剣[けん]の練習[れんしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "あの戦士は体が大きくて、とても力が強い。", "target_word": "戦士", "complexity_tier": "T2", "furigana": "あの戦士[せんし]は体[からだ]が大[おお]きくて、とても力[ちから]が強[つよ]い。", "sentence_source": "generated"}, {"text": "博物館で、古代の戦士が着ていた鎧を見た。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、古代[こだい]の戦士[せんし]が着[き]ていた鎧[よろい]を見[み]た。", "sentence_source": "generated"}, {"text": "戦士は村を守るために、山の道で見張りをしていた。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "戦士[せんし]は村[むら]を守[まも]るために、山[やま]の道[みち]で見張[みは]りをしていた。", "sentence_source": "generated"}, {"text": "若い戦士は、先輩の戦士から戦い方を教わった。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "若[わか]い戦士[せんし]は、先輩[せんぱい]の戦士[せんし]から戦[たたか]い方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "映画の最後で、戦士は敵のリーダーと一対一で戦った。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "映画[えいが]の最後[さいご]で、戦士[せんし]は敵[てき]のリーダーと一対一[いちたいいち]で戦[たたか]った。", "sentence_source": "generated"}, {"text": "戦いが始まると、戦士たちは一斉に走り出した。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "戦[たたか]いが始[はじ]まると、戦士[せんし]たちは一斉[いっせい]に走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "この祭りでは、戦士の姿をした子どもたちが町を歩く。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "この祭[まつ]りでは、戦士[せんし]の姿[すがた]をした子[こ]どもたちが町[まち]を歩[ある]く。", "sentence_source": "generated"}, {"text": "私の弟はゲームで戦士を選ぶことが多い。", "target_word": "戦士", "complexity_tier": "T2", "furigana": "私[わたし]の弟[おとうと]はゲームで戦士[せんし]を選[えら]ぶことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦士", "label": "基本形"}, {"form": "戦士たち", "label": "複数的表現"}], "register": "中立", "sense_fingerprint": "戦いに加わる人、兵や剣士など", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦士", "is_correct": true, "explanation": "何百人もの戦う人を指し、「何百人もの戦士がいた」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を指すので、人の数を表す語としては合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送る文章なので、「何百人もの」で数えられる対象ではない。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描かれた図なので、人の数を表す文には入らない。"}], "explanations": {"戦士": "何百人もの戦う人を指し、「何百人もの戦士がいた」と自然に続く。", "天気": "空の状態を指すので、人の数を表す語としては合わない。", "手紙": "書いて送る文章なので、「何百人もの」で数えられる対象ではない。", "地図": "紙に描かれた図なので、人の数を表す文には入らない。"}, "sentence_index": 0, "correct_answer": "戦士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の広場に、戦士の形勢が逆転したと書かれた掲示が貼られた。", "explanation": "ここは〈戦局〉の意味。戦士は人を指すので、戦いの形勢や局面を表す場面では使わない。"}, {"text": "父は若いころ、戦士で勇敢に働いたと聞いている。", "explanation": "ここは〈戦場〉の意味。戦士は人を指すので、戦いが行われる場所を表す使い方はしない。"}, {"text": "部隊は戦士を三頭連れて、山道を越えた。", "explanation": "ここは〈軍用馬〉の意味。戦士は人を指すので、頭で数える軍用の動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦士", "is_correct": true, "explanation": "一対一で戦う人を指し、「は敵のリーダーと戦った」と主語として自然に続く。"}, {"text": "階段", "is_correct": false, "explanation": "段差のある通路なので、戦いの主語にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる入れ物なので、戦う主体にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部なので、戦う主体にはならない。"}], "explanations": {"戦士": "一対一で戦う人を指し、「は敵のリーダーと戦った」と主語として自然に続く。", "階段": "段差のある通路なので、戦いの主語にはならない。", "財布": "お金を入れる入れ物なので、戦う主体にはならない。", "窓": "建物の開口部なので、戦う主体にはならない。"}, "sentence_index": 6, "correct_answer": "戦士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けまでに、職人は戦士を十本研ぎ上げた。", "explanation": "ここは〈刀剣〉の意味。戦士は人を指すので、本で数えて研ぐ武器には使わない。"}, {"text": "夜明けに戦士が始まり、町中が騒がしくなった。", "explanation": "ここは〈戦争〉の意味。戦士は戦う人を指すので、始まる出来事としての戦いには使わない。"}, {"text": "彼は重い戦士を肩に着けて、雨の中を歩いた。", "explanation": "ここは〈鎧〉の意味。戦士は人を指すので、身につけて着る防具には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は、戦士で剣の使い方を教わった。", "corrected_sentence": "父は、戦士に剣の使い方を教わった。", "error_description": "「教わる」は教える相手を「に」で示す。「戦士で」は手段の「で」となり誤り。正しくは「戦士に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52445, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王は若い戦士を育つことに力を注いだ。", "corrected_sentence": "王は若い戦士を育てることに力を注いだ。", "error_description": "「育てる」は「戦士を」と目的語を取る他動詞。「育つ」は自動詞なので「戦士を」は続かず、誤り。正しくは「育てる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
