INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "戦いをする人のこと。特に、勇ましく戦う人を指す。", "primary_collocate": null, "pronunciation": "せんし", "ipa": "seɴɕi", "syllable_count": 3, "sentences": [{"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "戦士", "complexity_tier": "T5", "furigana": "凍[い]てつく空気[くうき]の中[なか]、ボタンを一[ひと]つひとつ留[と]める仕草[しぐさ]には、未知[みち]の領域[りょういき]へ挑[いど]む戦士[せんし]のような厳粛[げんしゅく]ささえ漂[ただよ]っていた。", "sentence_source": "mined"}, {"text": "この物語の主人公は、国を守るために立ち上がった若い戦士だ。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "この物語[ものがたり]の主人公[しゅじんこう]は、国[くに]を守[まも]るために立[た]ち上[あ]がった若[わか]い戦士[せんし]だ。", "sentence_source": "generated"}, {"text": "古い城の壁には、剣と盾を持つ戦士の絵が描かれている。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]の壁[かべ]には、剣[けん]と盾[たて]を持[も]つ戦士[せんし]の絵[え]が描[えが]かれている。", "sentence_source": "generated"}, {"text": "戦士は仲間を逃がすため、最後まで一人で敵の前に立ち続けた。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "戦士[せんし]は仲間[なかま]を逃[に]がすため、最後[さいご]まで一人[ひとり]で敵[てき]の前[まえ]に立[た]ち続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は恐れを見せない勇敢な戦士として、村人に尊敬されていた。", "target_word": "戦士", "complexity_tier": "T4", "furigana": "彼[かれ]は恐[おそ]れを見[み]せない勇敢[ゆうかん]な戦士[せんし]として、村人[むらびと]に尊敬[そんけい]されていた。", "sentence_source": "generated"}, {"text": "ゲームでは、戦士は体力が高いので、前に出て敵を引きつける役だ。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "ゲームでは、戦士[せんし]は体力[たいりょく]が高[たか]いので、前[まえ]に出[で]て敵[てき]を引[ひ]きつける役[やく]だ。", "sentence_source": "generated"}, {"text": "長い戦いを終えた戦士たちは、故郷へ帰る日を静かに待っていた。", "target_word": "戦士", "complexity_tier": "T4", "furigana": "長[なが]い戦[たたか]いを終[お]えた戦士[せんし]たちは、故郷[こきょう]へ帰[かえ]る日[ひ]を静[しず]かに待[ま]っていた。", "sentence_source": "generated"}, {"text": "傷だらけの戦士は、それでも剣を握りしめて立ち上がった。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "傷[きず]だらけの戦士[せんし]は、それでも剣[けん]を握[にぎ]りしめて立[た]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "王は戦士たちを広間に集め、明日の出発について話した。", "target_word": "戦士", "complexity_tier": "T3", "furigana": "王[おう]は戦士[せんし]たちを広間[ひろま]に集[あつ]め、明日[あした]の出発[しゅっぱつ]について話[はな]した。", "sentence_source": "generated"}, {"text": "彼女は幼いころから、強い戦士になることを夢見て訓練を重ねてきた。", "target_word": "戦士", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は幼[おさな]いころから、強[つよ]い戦士[せんし]になることを夢見[ゆめみ]て訓練[くんれん]を重[かさ]ねてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦士", "label": "基本形"}, {"form": "戦士たち", "label": "複数的表現"}], "register": "中立", "sense_fingerprint": "勇ましく戦う人、勇者としての戦士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 凍てつく (Zipf 2.35)']::text[], 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦士", "is_correct": true, "explanation": "未知の領域に挑む、勇ましく戦う人を指し、「挑む戦士のような」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空の様子を指すので、挑む対象としては合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送る文章なので、挑むという行為の対象にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる入れ物なので、「挑む」の相手として合わない。"}], "explanations": {"戦士": "未知の領域に挑む、勇ましく戦う人を指し、「挑む戦士のような」と自然に続く。", "天気": "空の様子を指すので、挑む対象としては合わない。", "手紙": "書いて送る文章なので、挑むという行為の対象にはならない。", "財布": "お金を入れる入れ物なので、「挑む」の相手として合わない。"}, "sentence_index": 0, "correct_answer": "戦士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "戦士の形勢が逆転し、味方が優勢になった。", "explanation": "ここは〈戦局〉の意味。戦士は人を指すので、戦いの形勢や局面を表す場面では使わない。"}, {"text": "夜明けに戦士が始まり、町中が騒がしくなった。", "explanation": "ここは〈戦争〉の意味。戦士は戦う人を指すので、始まる出来事としての戦いには使わない。"}, {"text": "夜明け、戦士の砲撃で港が揺れ、住民は山へ逃げた。", "explanation": "ここは〈戦艦〉の意味。戦士は人を指すので、砲撃する軍艦には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦士", "is_correct": true, "explanation": "長い戦いを終えた、戦う人たちを指し、「たちは」と自然に続く。"}, {"text": "階段", "is_correct": false, "explanation": "段差のある通路なので、戦いを終えた人には当てはまらない。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描いた図なので、戦いを終えた人を指さない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部なので、戦いを終えた人を表さない。"}], "explanations": {"戦士": "長い戦いを終えた、戦う人たちを指し、「たちは」と自然に続く。", "階段": "段差のある通路なので、戦いを終えた人には当てはまらない。", "地図": "紙に描いた図なので、戦いを終えた人を指さない。", "窓": "建物の開口部なので、戦いを終えた人を表さない。"}, "sentence_index": 6, "correct_answer": "戦士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明け前、戦士が三両並び、砂ぼこりを上げて進んだ。", "explanation": "ここは〈戦車〉の意味。戦士は人を指すので、両で数える乗り物には使わない。"}, {"text": "夜明けに、彼女は戦士を一本ずつ研いで刃の具合を確かめた。", "explanation": "ここは〈刀剣〉の意味。戦士は人を指すので、本で数えて研ぐ武器には使わない。"}, {"text": "彼女は舞台の前、胸に戦士がわいて手が震えた。", "explanation": "ここは〈勇気〉の意味。戦士は戦う人を指すので、心に起こる勇ましい気持ちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村には、剣を持つ戦士を三人いる。", "corrected_sentence": "この村には、剣を持つ戦士が三人いる。", "error_description": "「いる」は存在を表し、「が」で主語を立てる。「戦士を」は誤りで、正しくは「戦士が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若い少年は、強い戦士を憧れて剣を習っている。", "corrected_sentence": "若い少年は、強い戦士に憧れて剣を習っている。", "error_description": "「憧れる」は対象に「に」を取る。「戦士を」は誤りで、正しくは「戦士に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「入る」の到達点を示す「に」。「領域に入る」で、他人の範囲へ踏み込むことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は移動先を「に」で示すので「を」は合わない。「領域を勝手に入る」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、移動の到達点には使わない。「領域で勝手に入る」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表す。「領域と入る」は文として意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。「入る」の到達点を示す「に」。「領域に入る」で、他人の範囲へ踏み込むことを表す。", "を": "「入る」は移動先を「に」で示すので「を」は合わない。「領域を勝手に入る」は不自然。", "で": "「で」は場所や手段を表すが、移動の到達点には使わない。「領域で勝手に入る」は成り立たない。", "と": "「と」は並列や相手を表す。「領域と入る」は文として意味が通らない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や範囲のこと。", "primary_collocate": null, "pronunciation": "りょういき", "ipa": "ɾʲoːiki", "syllable_count": 4, "sentences": [{"text": "この研究は、医学と工学の両方にまたがる領域だ。", "target_word": "領域", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]は、医学[いがく]と工学[こうがく]の両方[りょうほう]にまたがる領域[りょういき]だ。", "sentence_source": "generated"}, {"text": "他人の領域に勝手に入るのは失礼だ。", "target_word": "領域", "complexity_tier": "T3", "furigana": "他人[たにん]の領域[りょういき]に勝手[かって]に入[はい]るのは失礼[しつれい]だ。", "sentence_source": "generated"}, {"text": "専門の領域を超えた質問には答えられない。", "target_word": "領域", "complexity_tier": "T3", "furigana": "専門[せんもん]の領域[りょういき]を超[こ]えた質問[しつもん]には答[こた]えられない。", "sentence_source": "generated"}, {"text": "この地図では、立ち入り禁止の領域が赤で示されている。", "target_word": "領域", "complexity_tier": "T3", "furigana": "この地図[ちず]では、立[た]ち入[い]り禁止[きんし]の領域[りょういき]が赤[あか]で示[しめ]されている。", "sentence_source": "generated"}, {"text": "海の領域をめぐって、二つの国が争っている。", "target_word": "領域", "complexity_tier": "T3", "furigana": "海[うみ]の領域[りょういき]をめぐって、二[ふた]つの国[くに]が争[あらそ]っている。", "sentence_source": "generated"}, {"text": "彼女は料理だけでなく、デザインの領域でも活躍している。", "target_word": "領域", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は料理[りょうり]だけでなく、デザインの領域[りょういき]でも活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "人工知能は、すでに医療の領域で使われ始めた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "人工知能[じんこうちのう]は、すでに医療[いりょう]の領域[りょういき]で使[つか]われ始[はじ]めた。", "sentence_source": "generated"}, {"text": "この机の左半分は弟の領域で、私は物を置かない。", "target_word": "領域", "complexity_tier": "T3", "furigana": "この机[つくえ]の左半分[ひだりはんぶん]は弟[おとうと]の領域[りょういき]で、私[わたし]は物[もの]を置[お]かない。", "sentence_source": "generated"}, {"text": "その問題は、私の領域ではないので、専門家に聞いてほしい。", "target_word": "領域", "complexity_tier": "T3", "furigana": "その問題[もんだい]は、私[わたし]の領域[りょういき]ではないので、専門家[せんもんか]に聞[き]いてほしい。", "sentence_source": "generated"}, {"text": "科学が進んで、人間が行ける宇宙の領域も広がった。", "target_word": "領域", "complexity_tier": "T3", "furigana": "科学[かがく]が進[すす]んで、人間[にんげん]が行[い]ける宇宙[うちゅう]の領域[りょういき]も広[ひろ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "領域", "label": "基本形"}, {"form": "領域の", "label": "連体形"}, {"form": "領域に", "label": "格助詞つき"}], "register": "中立（普通体）", "sense_fingerprint": "場所・分野・勢力などの範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "領域", "is_correct": true, "explanation": "正解。医学と工学にまたがる学問の範囲を表す「領域」が入る。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生物や物が存在する期間を指す。「両方にまたがる寿命」は文として成り立たない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度を表す語で、学問の範囲を述べる文には入らない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人の年数を表す語で、学問の範囲には合わない。"}], "explanations": {"領域": "正解。医学と工学にまたがる学問の範囲を表す「領域」が入る。", "寿命": "寿命は生物や物が存在する期間を指す。「両方にまたがる寿命」は文として成り立たない。", "気温": "気温は空気の温度を表す語で、学問の範囲を述べる文には入らない。", "年齢": "年齢は人の年数を表す語で、学問の範囲には合わない。"}, "sentence_index": 0, "correct_answer": "領域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みの領域は三週間だ。", "explanation": "ここは〈期間〉の意味。領域は場所や分野の範囲を指し、時間の長さには使わない。"}, {"text": "けがの領域は軽かった。", "explanation": "ここは〈程度〉の意味。領域は範囲を表し、傷の重さという度合いには使わない。"}, {"text": "彼は英語の領域がとても高い。", "explanation": "ここは〈能力〉の意味。「英語の能力が高い」は自然だが、領域は能力の高さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "領域", "is_correct": true, "explanation": "正解。医療という分野の範囲を表すので、「医療の領域で」と続く。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の背の高さを表す語で、分野を示す文には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、医療の分野を表す文には合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や物の重さで、分野を示す語として成り立たない。"}], "explanations": {"領域": "正解。医療という分野の範囲を表すので、「医療の領域で」と続く。", "身長": "身長は人の背の高さを表す語で、分野を示す文には入らない。", "天気": "天気は空模様のことで、医療の分野を表す文には合わない。", "体重": "体重は人や物の重さで、分野を示す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "領域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社は領域が大きく、社員は二百人を超える。", "explanation": "ここは〈規模〉の意味。会社の大きさは規模で表すので、領域とは言わない。"}, {"text": "彼女は鋭い領域で危険を察した。", "explanation": "ここは〈感覚〉の意味。危険を察するのは鋭い感覚で、範囲を表す領域は使わない。"}, {"text": "その石は領域が硬く、ハンマーでも割れなかった。", "explanation": "ここは〈硬さ〉の意味。硬さは硬度で表し、範囲を表す領域とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "専門家の領域に超えた判断は避けるべきだ。", "corrected_sentence": "専門家の領域を超えた判断は避けるべきだ。", "error_description": "誤りは助詞。「超える」は対象を「を」で示す。「に」を使うと「領域に超える」となり成り立たない。正しくは「領域を超える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、新しい領域で進出した。", "corrected_sentence": "その会社は、新しい領域に進出した。", "error_description": "「進出する」は行き先を「に」で示す。「で」は場所を示すので、進出先には使わない。正しくは「領域に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「白い霧が漂っていた」で、漂っていたの主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「霧を漂っていた」は成立せず、漂うは目的語を取らない自動詞。"}, {"text": "へ", "is_correct": false, "explanation": "「霧へ漂っていた」は移動の方向になり、漂う様子とは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「霧の漂っていた」は名詞修飾になり、文の述語が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「白い霧が漂っていた」で、漂っていたの主語を示す。", "を": "「霧を漂っていた」は成立せず、漂うは目的語を取らない自動詞。", "へ": "「霧へ漂っていた」は移動の方向になり、漂う様子とは合わない。", "の": "「霧の漂っていた」は名詞修飾になり、文の述語が成立しない。"}, "error_tags": {"を": "目的語の格（自動詞に目的語は立たない）", "へ": "方向（移動の向きを示す）", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「夜の街に、焼き鳥のけむりが漂っていた」で、漂っていたの主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「けむりと漂っていた」は並列になり、漂っていたの主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「けむりより漂っていた」は比較の意味になり、主語を示さない。"}, {"text": "から", "is_correct": false, "explanation": "「けむりから漂っていた」は起点の意味になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「夜の街に、焼き鳥のけむりが漂っていた」で、漂っていたの主語を示す。", "と": "「けむりと漂っていた」は並列になり、漂っていたの主語を示せない。", "より": "「けむりより漂っていた」は比較の意味になり、主語を示さない。", "から": "「けむりから漂っていた」は起点の意味になり、主語を示せない。"}, "error_tags": {"と": "並列（主語を示せない）", "より": "比較（比べる相手になる）", "から": "起点（出どころを示す）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが空気の中にただよっているように見えること。", "primary_collocate": null, "pronunciation": "ただよう", "ipa": "tadajoɯ", "syllable_count": 4, "sentences": [{"text": "台所からカレーのいい匂いが漂っている。", "target_word": "漂っている", "complexity_tier": "T3", "furigana": "台所[だいどころ]からカレーのいい匂[にお]いが漂[ただよ]っている。", "sentence_source": "generated"}, {"text": "朝の湖に、白い霧が漂っていた。", "target_word": "漂っていた", "complexity_tier": "T3", "furigana": "朝[あさ]の湖[みずうみ]に、白[しろ]い霧[きり]が漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "たばこの煙が部屋の中に漂って、目が痛くなった。", "target_word": "漂って", "complexity_tier": "T3", "furigana": "たばこの煙[けむり]が部屋[へや]の中[なか]に漂[ただよ]って、目[め]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "春の公園には、花の甘い香りが漂う。", "target_word": "漂う", "complexity_tier": "T3", "furigana": "春[はる]の公園[こうえん]には、花[はな]の甘[あま]い香[かお]りが漂[ただよ]う。", "sentence_source": "generated"}, {"text": "山のふもとに、うすい雲が漂っていた。", "target_word": "漂っていた", "complexity_tier": "T3", "furigana": "山[やま]のふもとに、うすい雲[くも]が漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "コーヒーの香りが漂って、みんな目をさました。", "target_word": "漂って", "complexity_tier": "T3", "furigana": "コーヒーの香[かお]りが漂[ただよ]って、みんな目[め]をさました。", "sentence_source": "generated"}, {"text": "工場の近くには、油のにおいが漂っている。", "target_word": "漂っている", "complexity_tier": "T3", "furigana": "工場[こうじょう]の近[ちか]くには、油[あぶら]のにおいが漂[ただよ]っている。", "sentence_source": "generated"}, {"text": "夜の街に、焼き鳥のけむりが漂っていた。", "target_word": "漂っていた", "complexity_tier": "T3", "furigana": "夜[よる]の街[まち]に、焼[や]き鳥[とり]のけむりが漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "線香の煙が静かに漂い、部屋は落ち着いた空気だった。", "target_word": "漂い", "complexity_tier": "T4", "furigana": "線香[せんこう]の煙[けむり]が静[しず]かに漂[ただよ]い、部屋[へや]は落[お]ち着[つ]いた空気[くうき]だった。", "sentence_source": "generated"}, {"text": "風がないので、霧が谷にずっと漂っていた。", "target_word": "漂っていた", "complexity_tier": "T3", "furigana": "風[かぜ]がないので、霧[きり]が谷[たに]にずっと漂[ただよ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "漂わない", "label": "未然形+ない"}, {"form": "漂います", "label": "連用形+ます"}, {"form": "漂った", "label": "過去形"}, {"form": "漂って", "label": "て形"}, {"form": "漂っている", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "霧・煙・香りなどが空気の中をゆったり浮かぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂っている", "is_correct": true, "explanation": "正解。匂いが空気中にただよっている様子を表す。"}, {"text": "光っている", "is_correct": false, "explanation": "光るは明るく輝くことで、匂いの主語には合わない。"}, {"text": "凍っている", "is_correct": false, "explanation": "凍るは液体が固まることで、匂いには当てはまらない。"}, {"text": "割れている", "is_correct": false, "explanation": "割れるは物が壊れることで、匂いの文には合わない。"}], "explanations": {"漂っている": "正解。匂いが空気中にただよっている様子を表す。", "光っている": "光るは明るく輝くことで、匂いの主語には合わない。", "凍っている": "凍るは液体が固まることで、匂いには当てはまらない。", "割れている": "割れるは物が壊れることで、匂いの文には合わない。"}, "sentence_index": 0, "correct_answer": "漂っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い石が、床の上にゆっくり漂っていた。", "explanation": "ここは〈置かれている〉の場面。漂うは空気や水の中で浮いて見える様子で、床の上の重い石には使わない。"}, {"text": "重い鉄のかたまりが、海の底へ漂っていった。", "explanation": "ここは〈沈む〉の意味。重いものが海底へ下がる動きは沈むで表し、漂うは水や空気の中でゆるやかに流れる様子を指すので合わない。"}, {"text": "お皿が、棚の上でずっと漂っている。", "explanation": "ここは〈置かれている〉の場面。空中に浮いて動くのではないので、漂うは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂っている", "is_correct": true, "explanation": "正解。油のにおいが空気中にただよっている様子を表す。"}, {"text": "固まっている", "is_correct": false, "explanation": "固まるは液体が固体になることで、においには当てはまらない。"}, {"text": "沸いている", "is_correct": false, "explanation": "沸くは液体が熱で泡立つことで、においの文には合わない。"}, {"text": "砕けている", "is_correct": false, "explanation": "砕けるは固い物が細かくなることで、においには使えない。"}], "explanations": {"漂っている": "正解。油のにおいが空気中にただよっている様子を表す。", "固まっている": "固まるは液体が固体になることで、においには当てはまらない。", "沸いている": "沸くは液体が熱で泡立つことで、においの文には合わない。", "砕けている": "砕けるは固い物が細かくなることで、においには使えない。"}, "sentence_index": 6, "correct_answer": "漂っている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな岩が、畑の真ん中にずっと漂っていた。", "explanation": "ここは〈置かれている〉の場面。空中や水中に浮いて見える様子ではないので、漂うは使えない。"}, {"text": "コップの底に泥が漂った。", "explanation": "ここは〈沈殿〉の意味。泥が底に溜まる様子は沈殿で、漂うは浮いて揺れる様子なので合わない。"}, {"text": "屋根の上に雪がどっしり載って、そのまま漂っていた。", "explanation": "ここは〈積もる〉の意味。漂うは空気中で浮いて見える様子を表すので、屋根に雪が積もる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に花の香りが漂うた。", "corrected_sentence": "庭に花の香りが漂った。", "error_description": "過去の形は「漂った」で、「漂うた」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "漂っていた", "is_correct": true, "explanation": "正解。霧が漂い続けていた様子を表す継続形の過去。"}, {"text": "漂わせていた", "is_correct": false, "explanation": "使役形で、霧が主語のままでは目的語が欠けて文が成り立たない。"}, {"text": "漂いていた", "is_correct": false, "explanation": "連用形に「ていた」はつかず、この形は作れない。"}, {"text": "漂うていた", "is_correct": false, "explanation": "「う」を残した形は現代語の活用として誤り。"}], "correct_form": "漂っていた", "base_form": "漂う", "form_label": "継続形（過去）", "sentence_index": 1, "explanations": {"漂っていた": "正解。霧が漂い続けていた様子を表す継続形の過去。", "漂わせていた": "使役形で、霧が主語のままでは目的語が欠けて文が成り立たない。", "漂いていた": "連用形に「ていた」はつかず、この形は作れない。", "漂うていた": "「う」を残した形は現代語の活用として誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52449, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谷の上に、霧を漂っていた。", "corrected_sentence": "谷の上に、霧が漂っていた。", "error_description": "「漂う」は自動詞なので目的語の「を」は取らず、主語の「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "漂っていた", "is_correct": true, "explanation": "正解。けむりが漂い続けていた様子を表す継続形の過去。"}, {"text": "漂って", "is_correct": false, "explanation": "て形で、文を過去として締める形になっていない。"}, {"text": "漂いた", "is_correct": false, "explanation": "連用形に直接「た」をつけた形で、この動詞の過去形としては成立しない。"}, {"text": "漂いてい", "is_correct": false, "explanation": "連用形＋「て」＋「い」の不完全な形で、活用として成立しない。"}], "correct_form": "漂っていた", "base_form": "漂う", "form_label": "継続形（過去）", "sentence_index": 7, "explanations": {"漂っていた": "正解。けむりが漂い続けていた様子を表す継続形の過去。", "漂って": "て形で、文を過去として締める形になっていない。", "漂いた": "連用形に直接「た」をつけた形で、この動詞の過去形としては成立しない。", "漂いてい": "連用形＋「て」＋「い」の不完全な形で、活用として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
