INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「勢いが」と続けて、よかった状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「勢いをよかった」は成り立たず、形容詞の主語には「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「勢いによかった」は成り立たず、状態を述べる文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「勢いとよかった」は並列や引用の働きで、ここでは文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「勢いが」と続けて、よかった状態の主語を示す。", "を": "「勢いをよかった」は成り立たず、形容詞の主語には「を」は使えない。", "に": "「勢いによかった」は成り立たず、状態を述べる文に合わない。", "と": "「勢いとよかった」は並列や引用の働きで、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "と": "相手・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、元気や力の強さのこと。", "primary_collocate": null, "pronunciation": "いきおい", "ipa": "ikioi", "syllable_count": 4, "sentences": [{"text": "新入社員たちは勢いがあって、会議でも遠慮なく意見を言う。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]たちは勢[いきお]いがあって、会議[かいぎ]でも遠慮[えんりょ]なく意見[いけん]を言[い]う。", "sentence_source": "generated"}, {"text": "子どもたちは勢いよく手を挙げて、先生の質問に答えた。", "target_word": "勢い", "complexity_tier": "T2", "furigana": "子[こ]どもたちは勢[いきお]いよく手[て]を挙[あ]げて、先生[せんせい]の質問[しつもん]に答[こた]えた。", "sentence_source": "generated"}, {"text": "彼は勢いのある声で、教室のみんなにあいさつした。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "彼[かれ]は勢[いきお]いのある声[こえ]で、教室[きょうしつ]のみんなにあいさつした。", "sentence_source": "generated"}, {"text": "祖父は年をとっても、若いころの勢いを失っていない。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "祖父[そふ]は年[とし]をとっても、若[わか]いころの勢[いきお]いを失[うしな]っていない。", "sentence_source": "generated"}, {"text": "選手たちは勢いよくグラウンドへ走り出した。", "target_word": "勢い", "complexity_tier": "T2", "furigana": "選手[せんしゅ]たちは勢[いきお]いよくグラウンドへ走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "彼女は勢いよくドアを開けて、元気に「ただいま」と言った。", "target_word": "勢い", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は勢[いきお]いよくドアを開[あ]けて、元気[げんき]に「ただいま」と言[い]った。", "sentence_source": "generated"}, {"text": "勝ったチームは、その勢いのまま次の試合にも勝った。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "勝[か]ったチームは、その勢[いきお]いのまま次[つぎ]の試合[しあい]にも勝[か]った。", "sentence_source": "generated"}, {"text": "最初は勢いがよかったが、疲れて歩く速さが落ちた。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "最初[さいしょ]は勢[いきお]いがよかったが、疲[つか]れて歩[ある]く速[はや]さが落[お]ちた。", "sentence_source": "generated"}, {"text": "彼の話し方には勢いがあって、聞いている人を引きつける。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]には勢[いきお]いがあって、聞[き]いている人[ひと]を引[ひ]きつける。", "sentence_source": "generated"}, {"text": "弟は勢いよくご飯を食べ、すぐにおかわりを頼んだ。", "target_word": "勢い", "complexity_tier": "T2", "furigana": "弟[おとうと]は勢[いきお]いよくご飯[はん]を食[た]べ、すぐにおかわりを頼[たの]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勢い", "label": "基本形"}, {"form": "勢いよく", "label": "副詞的用法"}], "register": "中立", "sense_fingerprint": "人の動作や話し方に表れる元気や力強さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勢い", "is_correct": true, "explanation": "人の元気や力強さを表し、「勢いがあって」と続くので自然。"}, {"text": "効率", "is_correct": false, "explanation": "「効率がある」とは言わず、人の元気や態度を表せない。"}, {"text": "速度", "is_correct": false, "explanation": "「速度がある」は不自然で、人の意見の言い方には合わない。"}, {"text": "賃金", "is_correct": false, "explanation": "「賃金がある」は文脈に合わず、会議での発言態度を表せない。"}], "explanations": {"勢い": "人の元気や力強さを表し、「勢いがあって」と続くので自然。", "効率": "「効率がある」とは言わず、人の元気や態度を表せない。", "速度": "「速度がある」は不自然で、人の意見の言い方には合わない。", "賃金": "「賃金がある」は文脈に合わず、会議での発言態度を表せない。"}, "sentence_index": 0, "correct_answer": "勢い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の勢いは毎朝九時と決まっている。", "explanation": "ここは〈時刻〉の意味。開始の時刻は時刻で言い、人の元気や力の強さを表す勢いでは言わない。"}, {"text": "この電池は勢いが長く、一週間は持つ。", "explanation": "ここは〈寿命〉の意味。電池の持続期間は寿命で言い、人の元気や力強さを表す勢いでは言わない。"}, {"text": "この部屋は勢いが広くて、家具を置いても余裕がある。", "explanation": "ここは〈面積〉の意味。空間の広さは面積で言い、元気や力の強さを表す勢いでは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勢い", "is_correct": true, "explanation": "「勢いのまま」は、勢いが続いた状態を表し、文脈に合う。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子のまま」は不自然で、勝ち続けた状態を表せない。"}, {"text": "重心", "is_correct": false, "explanation": "「重心のまま」は不自然で、チームの試合の流れを表せない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温のまま」は不自然で、試合の勢いの続きを表せない。"}], "explanations": {"勢い": "「勢いのまま」は、勢いが続いた状態を表し、文脈に合う。", "帽子": "「帽子のまま」は不自然で、勝ち続けた状態を表せない。", "重心": "「重心のまま」は不自然で、チームの試合の流れを表せない。", "体温": "「体温のまま」は不自然で、試合の勢いの続きを表せない。"}, "sentence_index": 6, "correct_answer": "勢い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道の勢いは駅まで二キロある。", "explanation": "ここは〈距離〉の意味。道のりの長さは距離で言い、元気や力の強さを表す勢いでは言わない。"}, {"text": "この本は勢いが硬く、ページをめくるのに力がいる。", "explanation": "ここは〈硬さ〉の意味。物の硬さは硬さで言い、人の元気や力強さを表す勢いでは言わない。"}, {"text": "この箱は勢いが重く、一人では持ち上げられない。", "explanation": "ここは〈重さ〉の意味。物の重さは重さで言い、人の元気や力強さを表す勢いでは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは勢いに教室を飛び出していった。", "corrected_sentence": "子どもたちは勢いよく教室を飛び出していった。", "error_description": "勢いの後ろは副詞形の「よく」が必要で、「勢いに」は誤り。正しくは「勢いよく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手は勢いに失わず、最後まで走り続けた。", "corrected_sentence": "選手は勢いを失わず、最後まで走り続けた。", "error_description": "「失う」は目的語に「を」を取るので、「勢いを失う」が正しい。「勢いに失う」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「増す」の目的語を示し、「勢いを増し」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「勢いに増し」は「増す」の格に合わず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「勢いと増し」は並列や引用の働きで、ここでは文脈に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「勢いへ増し」は方向を示す助詞で、「増す」の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「増す」の目的語を示し、「勢いを増し」が自然。", "に": "「勢いに増し」は「増す」の格に合わず、文が成り立たない。", "と": "「勢いと増し」は並列や引用の働きで、ここでは文脈に合わない。", "へ": "「勢いへ増し」は方向を示す助詞で、「増す」の対象を表せない。"}, "error_tags": {"に": "方向・結果", "と": "相手・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「勢い」を話題として示し、海の上で強くなる対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「強くなる」は自動詞で目的語の「を」を取らず、「勢いを強くなる」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「勢いに強くなる」は到達点の関係が成り立たず、文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「勢いと強くなる」は並列や引用の働きで、ここでは文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「勢い」を話題として示し、海の上で強くなる対象を表す。", "を": "「強くなる」は自動詞で目的語の「を」を取らず、「勢いを強くなる」は成り立たない。", "に": "「勢いに強くなる」は到達点の関係が成り立たず、文脈に合わない。", "と": "「勢いと強くなる」は並列や引用の働きで、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "と": "相手・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの、活発な力や勢い。また、その度合い。", "primary_collocate": null, "pronunciation": "いきおい", "ipa": "ikioi", "syllable_count": 4, "sentences": [{"text": "やがて準備が整い、彼は勢いよく扉を押し開ける。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "やがて準備[じゅんび]が整[ととの]い、彼[かれ]は勢[いきお]いよく扉[とびら]を押[お]し開[あ]ける。", "sentence_source": "mined"}, {"text": "川の水は雨のあとで勢いを増し、橋の下を激しく流れていった。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は雨[あめ]のあとで勢[いきお]いを増[ま]し、橋[はし]の下[した]を激[はげ]しく流[なが]れていった。", "sentence_source": "generated"}, {"text": "火は風に押されて、あっという間に勢いを強めた。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "火[ひ]は風[かぜ]に押[お]されて、あっという間[ま]に勢[いきお]いを強[つよ]めた。", "sentence_source": "generated"}, {"text": "売り上げの勢いは、発売から一か月たっても衰えなかった。", "target_word": "勢い", "complexity_tier": "T4", "furigana": "売[う]り上[あ]げの勢[いきお]いは、発売[はつばい]から一[いっ]か月[げつ]たっても衰[おとろ]えなかった。", "sentence_source": "generated"}, {"text": "試合の終盤、相手チームの勢いに押されて、私たちは点を取られた。", "target_word": "勢い", "complexity_tier": "T4", "furigana": "試合[しあい]の終盤[しゅうばん]、相手[あいて]チームの勢[いきお]いに押[お]されて、私[わたし]たちは点[てん]を取[と]られた。", "sentence_source": "generated"}, {"text": "雨の勢いが弱まったので、傘をたたんで外に出た。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "雨[あめ]の勢[いきお]いが弱[よわ]まったので、傘[かさ]をたたんで外[そと]に出[で]た。", "sentence_source": "generated"}, {"text": "蛇口をひねると、水が勢いよく飛び出して服がぬれた。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "蛇口[じゃぐち]をひねると、水[みず]が勢[いきお]いよく飛[と]び出[だ]して服[ふく]がぬれた。", "sentence_source": "generated"}, {"text": "台風の勢いは海の上で一段と強くなっている。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "台風[たいふう]の勢[いきお]いは海[うみ]の上[うえ]で一段[いちだん]と強[つよ]くなっている。", "sentence_source": "generated"}, {"text": "ボールは勢いよく転がり、壁に当たって跳ね返った。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "ボールは勢[いきお]いよく転[ころ]がり、壁[かべ]に当[あ]たって跳[は]ね返[かえ]った。", "sentence_source": "generated"}, {"text": "山火事は強い風に乗って勢いを増し、消防隊も近づけなかった。", "target_word": "勢い", "complexity_tier": "T3", "furigana": "山火事[やまかじ]は強[つよ]い風[かぜ]に乗[の]って勢[いきお]いを増[ま]し、消防隊[しょうぼうたい]も近[ちか]づけなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勢い", "label": "基本形"}, {"form": "勢いよく", "label": "副詞的用法"}], "register": "中立", "sense_fingerprint": "水・火・天候・試合などの動きの力とその強さの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勢い", "is_correct": true, "explanation": "「勢いよく」の形で、力強く扉を押す様子に合う。"}, {"text": "速さ", "is_correct": false, "explanation": "「速さよく」とは言えず、副詞句として成り立たない。"}, {"text": "勇気", "is_correct": false, "explanation": "「勇気よく」は不自然で、扉を押す動作の力強さを表せない。"}, {"text": "強さ", "is_correct": false, "explanation": "「強さよく」とは言わず、副詞にするなら「強く」になるので合わない。"}], "explanations": {"勢い": "「勢いよく」の形で、力強く扉を押す様子に合う。", "速さ": "「速さよく」とは言えず、副詞句として成り立たない。", "勇気": "「勇気よく」は不自然で、扉を押す動作の力強さを表せない。", "強さ": "「強さよく」とは言わず、副詞にするなら「強く」になるので合わない。"}, "sentence_index": 0, "correct_answer": "勢い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工事は勢いが三年続く予定だ。", "explanation": "ここは〈期間〉の意味。工事の長さは期間で言い、活発な力の度合いを表す勢いでは言わない。"}, {"text": "この測定器は勢いが高く、誤差がほとんどない。", "explanation": "ここは〈精度〉の意味。測定の正確さは精度で言い、勢いは物事の活発な力を指すので合わない。"}, {"text": "今朝の勢いは氷点下まで下がり、水たまりが凍っていた。", "explanation": "ここは〈気温〉の意味。温度の高さや低さは気温で言い、勢いは活発な力を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勢い", "is_correct": true, "explanation": "「勢いよく」の形で、水が強く飛び出す様子に合う。"}, {"text": "速度", "is_correct": false, "explanation": "「速度よく」とは言わず、副詞句として成り立たない。"}, {"text": "圧力", "is_correct": false, "explanation": "「圧力よく」は不自然で、水の出方を表せない。"}, {"text": "量", "is_correct": false, "explanation": "「量よく」とは言えず、飛び出す様子を表す語として合わない。"}], "explanations": {"勢い": "「勢いよく」の形で、水が強く飛び出す様子に合う。", "速度": "「速度よく」とは言わず、副詞句として成り立たない。", "圧力": "「圧力よく」は不自然で、水の出方を表せない。", "量": "「量よく」とは言えず、飛び出す様子を表す語として合わない。"}, "sentence_index": 6, "correct_answer": "勢い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このシャツは勢いが明るい黄色で、遠くからでも目立つ。", "explanation": "ここは〈色〉の意味。色合いは色で言い、活発な力を表す勢いでは言わない。"}, {"text": "このスープは勢いが薄く、味がぼやけていた。", "explanation": "ここは〈味の濃さ〉の意味。料理の味の濃淡は濃さで言い、活発な力の度合いを表す勢いでは言わない。"}, {"text": "この部署は勢いが五人しかいない。", "explanation": "ここは〈人数〉の意味。人の数は人数で言い、活発な力を表す勢いでは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山道を下るとき、自転車は勢いに増して、坂の途中で止められなくなった。", "corrected_sentence": "山道を下るとき、自転車は勢いを増して、坂の途中で止められなくなった。", "error_description": "「増す」は目的語に「を」を取るので、「勢いを増す」が正しい。「勢いに増す」は助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
