INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52455, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "冷たい風。", "primary_collocate": null, "pronunciation": "かんぷう", "ipa": "kampɯː", "syllable_count": 4, "sentences": [{"text": "今日は寒風が強くて、外を歩くのがつらい。", "target_word": "寒風", "complexity_tier": "T2", "furigana": "今日[きょう]は寒風[かんぷう]が強[つよ]くて、外[そと]を歩[ある]くのがつらい。", "sentence_source": "generated"}, {"text": "寒風のせいで、顔が真っ赤になった。", "target_word": "寒風", "complexity_tier": "T2", "furigana": "寒風[かんぷう]のせいで、顔[かお]が真[ま]っ赤[か]になった。", "sentence_source": "generated"}, {"text": "冬の海岸には、寒風が吹いている。", "target_word": "寒風", "complexity_tier": "T2", "furigana": "冬[ふゆ]の海岸[かいがん]には、寒風[かんぷう]が吹[ふ]いている。", "sentence_source": "generated"}, {"text": "寒風が吹くと、木の葉が一斉に揺れた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]が吹[ふ]くと、木[き]の葉[は]が一斉[いっせい]に揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "彼は寒風を避けるため、建物の陰に入った。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "彼[かれ]は寒風[かんぷう]を避[さ]けるため、建物[たてもの]の陰[かげ]に入[はい]った。", "sentence_source": "generated"}, {"text": "寒風の中、犬は元気に散歩をしていた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]の中[なか]、犬[いぬ]は元気[げんき]に散歩[さんぽ]をしていた。", "sentence_source": "generated"}, {"text": "手袋をしていても、寒風で指が冷たくなる。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "手袋[てぶくろ]をしていても、寒風[かんぷう]で指[ゆび]が冷[つめ]たくなる。", "sentence_source": "generated"}, {"text": "朝の寒風に、思わず首をすくめた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "朝[あさ]の寒風[かんぷう]に、思[おも]わず首[くび]をすくめた。", "sentence_source": "generated"}, {"text": "寒風が止んだので、公園に子どもたちが戻ってきた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]が止[や]んだので、公園[こうえん]に子[こ]どもたちが戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "テントが寒風で大きく揺れ、夜はよく眠れなかった。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "テントが寒風[かんぷう]で大[おお]きく揺[ゆ]れ、夜[よる]はよく眠[ねむ]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒風", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "寒い季節の冷たい風", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52455, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒風", "is_correct": true, "explanation": "冷たい風を表し、「寒風が強くて」と続けると外を歩くつらさの理由になる。"}, {"text": "寝床", "is_correct": false, "explanation": "寝るための場所で、「強くて」と続けても外の天気の説明にならない。"}, {"text": "石畳", "is_correct": false, "explanation": "敷き詰めた石の道で、強さを表す主語として文が成り立たない。"}, {"text": "水たまり", "is_correct": false, "explanation": "地面にたまる水で、外を歩くつらさの原因として文脈に合わない。"}], "explanations": {"寒風": "冷たい風を表し、「寒風が強くて」と続けると外を歩くつらさの理由になる。", "寝床": "寝るための場所で、「強くて」と続けても外の天気の説明にならない。", "石畳": "敷き詰めた石の道で、強さを表す主語として文が成り立たない。", "水たまり": "地面にたまる水で、外を歩くつらさの原因として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "寒風"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒風で手を洗うと、指がかじかむほど冷たかった。", "explanation": "ここは〈冷水〉の意味。手を洗う水は冷水で言い、吹く風の寒風では言わない。"}, {"text": "氷が溶けて、寒風になって流れた。", "explanation": "ここは〈水〉の意味。溶けて流れるのは水で、吹く風の寒風では言わない。"}, {"text": "夜の間に寒風が降り積もり、道が白くなった。", "explanation": "ここは〈雪〉の意味。降り積もって地面を白くするのは雪で、吹く風の寒風では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52455, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒風", "is_correct": true, "explanation": "冷たい風で指が冷たくなる理由になり、「寒風で」と続けて自然。"}, {"text": "辞書", "is_correct": false, "explanation": "「辞書で指が冷たくなる」は不自然で、指を冷やす原因として成り立たない。"}, {"text": "石畳", "is_correct": false, "explanation": "敷き詰めた石の道で、指を冷たくする原因として成り立たない。"}, {"text": "紙やすり", "is_correct": false, "explanation": "磨くための道具で、指が冷たくなる原因として文が成り立たない。"}], "explanations": {"寒風": "冷たい風で指が冷たくなる理由になり、「寒風で」と続けて自然。", "辞書": "「辞書で指が冷たくなる」は不自然で、指を冷やす原因として成り立たない。", "石畳": "敷き詰めた石の道で、指を冷たくする原因として成り立たない。", "紙やすり": "磨くための道具で、指が冷たくなる原因として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "寒風"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂漠の寒風で、喉がからからになった。", "explanation": "ここは〈熱風〉の意味。砂漠の高温の風は熱風で言い、冷たい寒風とは逆になる。"}, {"text": "夏の夕方に寒風が吹いて、昼寝をした。", "explanation": "ここは〈そよ風〉の意味。夏の夕方に穏やかに吹く風はそよ風で言い、冷たく強い寒風とは合わない。"}, {"text": "ドライヤーの寒風で髪を乾かした。", "explanation": "ここは〈温風〉の意味。ドライヤーから出る温かい風は温風で言い、冷たい寒風とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52455, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬の海岸では、寒風に強く吹いていた。", "corrected_sentence": "冬の海岸では、寒風が強く吹いていた。", "error_description": "「吹く」は風が主語になるので「寒風が」が正しい。「寒風に」は「吹かれる」の形でなければ誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52455, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは寒風で中、元気に走り回っていた。", "corrected_sentence": "子どもたちは寒風の中、元気に走り回っていた。", "error_description": "「の中」で場所を表すため、「寒風の中」が正しい。「寒風で中」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「寒風が吹く」と続けて、吹く動作の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「寒風に吹く」は「吹かれる」の形でなければ成り立たず、ここでは誤り。"}, {"text": "と", "is_correct": false, "explanation": "「寒風と吹く」は並列や引用の働きで、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「寒風へ吹く」は方向を示すが、吹く動作の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「寒風が吹く」と続けて、吹く動作の主語を示す。", "に": "「寒風に吹く」は「吹かれる」の形でなければ成り立たず、ここでは誤り。", "と": "「寒風と吹く」は並列や引用の働きで、主語を示せない。", "へ": "「寒風へ吹く」は方向を示すが、吹く動作の主語にはならない。"}, "error_tags": {"に": "方向・場所", "と": "相手・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「寒風が入って」と続け、隙間から入る動作の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「寒風を入って」は成り立たず、入るという動きの主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「寒風と入って」は並列や引用の働きで、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「寒風へ入って」は方向を示すが、入る主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「寒風が入って」と続け、隙間から入る動作の主語を示す。", "を": "「寒風を入って」は成り立たず、入るという動きの主語にならない。", "と": "「寒風と入って」は並列や引用の働きで、主語を示せない。", "へ": "「寒風へ入って」は方向を示すが、入る主体を表せない。"}, "error_tags": {"を": "目的語", "と": "相手・引用", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "冬などに吹く、冷たくて強い風。", "primary_collocate": null, "pronunciation": "かんぷう", "ipa": "kampɯː", "syllable_count": 4, "sentences": [{"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "寒風", "complexity_tier": "T5", "furigana": "苛烈[かれつ]な寒風[かんぷう]が頬[ほお]を打[う]つ外[そと]の世界[せかい]へと、無垢[むく]な好奇心[こうきしん]を携[たずさ]えて駆[か]け出[だ]していくその背中[せなか]には、人間[にんげん]が本来[ほんらい]備[そな]えている、過酷[かこく]な環境[かんきょう]をも楽[たの]しみへと変貌[へんぼう]させる逞[たくま]しさが凝縮[ぎょうしゅく]されていたのである。", "sentence_source": "mined"}, {"text": "寒風が吹く朝、父はマフラーを巻いて駅まで歩いていった。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]が吹[ふ]く朝[あさ]、父[ちち]はマフラーを巻[ま]いて駅[えき]まで歩[ある]いていった。", "sentence_source": "generated"}, {"text": "海沿いの町では、冬になると強い寒風が毎日のように吹きつける。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "海沿[うみぞ]いの町[まち]では、冬[ふゆ]になると強[つよ]い寒風[かんぷう]が毎日[まいにち]のように吹[ふ]きつける。", "sentence_source": "generated"}, {"text": "寒風にさらされて、洗濯物がかちかちに凍ってしまった。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]にさらされて、洗濯物[せんたくもの]がかちかちに凍[こお]ってしまった。", "sentence_source": "generated"}, {"text": "コートの襟を立てても、寒風が首筋から入り込んでくる。", "target_word": "寒風", "complexity_tier": "T4", "furigana": "コートの襟[えり]を立[た]てても、寒風[かんぷう]が首筋[くびすじ]から入[はい]り込[こ]んでくる。", "sentence_source": "generated"}, {"text": "山の頂上は寒風が吹き荒れ、長くはとどまれなかった。", "target_word": "寒風", "complexity_tier": "T4", "furigana": "山[やま]の頂上[ちょうじょう]は寒風[かんぷう]が吹[ふ]き荒[あ]れ、長[なが]くはとどまれなかった。", "sentence_source": "generated"}, {"text": "農家の人々は、寒風の中でも畑の手入れを休まない。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "農家[のうか]の人々[ひとびと]は、寒風[かんぷう]の中[なか]でも畑[はたけ]の手入[てい]れを休[やす]まない。", "sentence_source": "generated"}, {"text": "窓を閉めていても、寒風が隙間から入って部屋が冷えた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "窓[まど]を閉[し]めていても、寒風[かんぷう]が隙間[すきま]から入[はい]って部屋[へや]が冷[ひ]えた。", "sentence_source": "generated"}, {"text": "寒風の吹く校庭で、生徒たちは体を動かして温まろうとした。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]の吹[ふ]く校庭[こうてい]で、生徒[せいと]たちは体[からだ]を動[うご]かして温[あたた]まろうとした。", "sentence_source": "generated"}, {"text": "寒風に吹かれながら待っていたので、電車に乗ると体が震えた。", "target_word": "寒風", "complexity_tier": "T3", "furigana": "寒風[かんぷう]に吹[ふ]かれながら待[ま]っていたので、電車[でんしゃ]に乗[の]ると体[からだ]が震[ふる]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒風", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "冬に吹きつける冷たく強い風", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c464064b-ef38-4009-9022-84bab44de4cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒風", "is_correct": true, "explanation": "頬を打つ冷たく強い風を表し、外の厳しい環境を描く文に合う。"}, {"text": "石垣", "is_correct": false, "explanation": "積まれた石の壁で、頬を打つものではないので合わない。"}, {"text": "水たまり", "is_correct": false, "explanation": "地面にたまる水で、頬を打つ対象にはならない。"}, {"text": "紅葉", "is_correct": false, "explanation": "色づいた葉のことで、頬を打つという動きに合わない。"}], "explanations": {"寒風": "頬を打つ冷たく強い風を表し、外の厳しい環境を描く文に合う。", "石垣": "積まれた石の壁で、頬を打つものではないので合わない。", "水たまり": "地面にたまる水で、頬を打つ対象にはならない。", "紅葉": "色づいた葉のことで、頬を打つという動きに合わない。"}, "sentence_index": 0, "correct_answer": "寒風"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地下室は寒風がこもって、ひんやりしている。", "explanation": "ここは〈冷気〉の意味。閉じた空間にこもる冷たい空気は冷気で言い、外で吹き動く寒風とは違う。"}, {"text": "氷が溶けて、寒風になって流れた。", "explanation": "ここは〈水〉の意味。溶けて流れるのは水で、吹きつける風の寒風では言わない。"}, {"text": "朝の草には寒風が降りて、一面が白くなった。", "explanation": "ここは〈霜〉の意味。地面に降りて白くする霜は霜で言い、吹きつける寒風では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒風", "is_correct": true, "explanation": "冷たく強い風で、寒い中でも畑仕事を続ける文脈に合う。"}, {"text": "寝床", "is_correct": false, "explanation": "寝るための場所で、畑の手入れという文脈に合わない。"}, {"text": "石畳", "is_correct": false, "explanation": "敷き詰めた石の道で、畑の手入れの場所にならない。"}, {"text": "樹液", "is_correct": false, "explanation": "木から出る液で、畑の手入れの条件として文脈に合わない。"}], "explanations": {"寒風": "冷たく強い風で、寒い中でも畑仕事を続ける文脈に合う。", "寝床": "寝るための場所で、畑の手入れという文脈に合わない。", "石畳": "敷き詰めた石の道で、畑の手入れの場所にならない。", "樹液": "木から出る液で、畑の手入れの条件として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "寒風"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は寒風が厚く、コートを二枚重ねても寒かった。", "explanation": "ここは〈厚さ〉の意味。布や層の厚みは厚さで言い、吹きつける寒風では言わない。"}, {"text": "ストーブの寒風で、部屋がすぐに暖かくなった。", "explanation": "ここは〈温風〉の意味。暖房から出る温かい風は温風で言い、冷たい風の寒風とは逆になる。"}, {"text": "エアコンの寒風が心地よく、昼寝をした。", "explanation": "ここは〈冷風〉の意味。冷房から出る風は冷風で言い、冬に吹く寒風とは場面が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒風に吹く夕方、子どもたちは急いで家へ帰った。", "corrected_sentence": "寒風の吹く夕方、子どもたちは急いで家へ帰った。", "error_description": "「吹く」は風を主語にして使うので、「寒風の吹く」が正しい。「寒風に吹く」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52456, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒風で吹かれて、帰り道の足取りが重かった。", "corrected_sentence": "寒風に吹かれて、帰り道の足取りが重かった。", "error_description": "「吹かれる」は受身で、風を示すには「に」を使う。「寒風で吹かれて」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662435a9-21ac-42e4-ac96-76ff99a2b0ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
