INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52457, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもきびしくて、はげしいこと。", "primary_collocate": null, "pronunciation": "かれつ", "ipa": "kaɾetsɯ", "syllable_count": 3, "sentences": [{"text": "両軍の戦いは、日がたつにつれて苛烈になった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "両軍[りょうぐん]の戦[たたか]いは、日[ひ]がたつにつれて苛烈[かれつ]になった。", "sentence_source": "generated"}, {"text": "苛烈な訓練に耐えた選手だけが、代表に選ばれた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "苛烈[かれつ]な訓練[くんれん]に耐[た]えた選手[せんしゅ]だけが、代表[だいひょう]に選[えら]ばれた。", "sentence_source": "generated"}, {"text": "王は反対する者に苛烈な罰を与えた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "王[おう]は反対[はんたい]する者[もの]に苛烈[かれつ]な罰[ばつ]を与[あた]えた。", "sentence_source": "generated"}, {"text": "夏の砂漠は日差しが苛烈で、昼間は外を歩けない。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "夏[なつ]の砂漠[さばく]は日差[ひざ]しが苛烈[かれつ]で、昼間[ひるま]は外[そと]を歩[ある]けない。", "sentence_source": "generated"}, {"text": "企業どうしの競争は、年々苛烈になっている。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "企業[きぎょう]どうしの競争[きょうそう]は、年々[ねんねん]苛烈[かれつ]になっている。", "sentence_source": "generated"}, {"text": "彼女は自分にも他人にも苛烈な人だった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]にも他人[たにん]にも苛烈[かれつ]な人[ひと]だった。", "sentence_source": "generated"}, {"text": "新人への批判は苛烈を極め、彼はついに会社をやめた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "新人[しんじん]への批判[ひはん]は苛烈[かれつ]を極[きわ]め、彼[かれ]はついに会社[かいしゃ]をやめた。", "sentence_source": "generated"}, {"text": "苛烈な暑さの中で、工事は何日も続けられた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "苛烈[かれつ]な暑[あつ]さの中[なか]で、工事[こうじ]は何日[なんにち]も続[つづ]けられた。", "sentence_source": "generated"}, {"text": "戦争の苛烈な現実を、その写真は静かに伝えている。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "戦争[せんそう]の苛烈[かれつ]な現実[げんじつ]を、その写真[しゃしん]は静[しず]かに伝[つた]えている。", "sentence_source": "generated"}, {"text": "苛烈な言葉で責められても、彼は反論しなかった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "苛烈[かれつ]な言葉[ことば]で責[せ]められても、彼[かれ]は反論[はんろん]しなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苛烈", "label": "語幹"}, {"form": "苛烈な", "label": "連体形"}, {"form": "苛烈に", "label": "連用形"}, {"form": "苛烈で", "label": "中止形"}], "register": "やや硬い書き言葉（普通体）", "sense_fingerprint": "非常にきびしく激しいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "正解。戦いが非常にきびしく激しくなる様子を表す。"}, {"text": "無邪気", "is_correct": false, "explanation": "無邪気は子どもっぽく屈託のないさま。戦いの激しさには合わない。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚は清らかで上品なさま。戦いが激しくなる文脈には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るくにぎやかなさま。戦いの激化を表す文には合わない。"}], "explanations": {"苛烈": "正解。戦いが非常にきびしく激しくなる様子を表す。", "無邪気": "無邪気は子どもっぽく屈託のないさま。戦いの激しさには合わない。", "清楚": "清楚は清らかで上品なさま。戦いが激しくなる文脈には合わない。", "陽気": "陽気は明るくにぎやかなさま。戦いの激化を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "苛烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "苛烈な子守唄を聞いて、赤ちゃんはすぐに眠った。", "explanation": "ここは〈穏やかな〉の意味。やさしい子守唄は穏やかな響きで、激しさや厳しさを表す苛烈は合わない。"}, {"text": "苛烈な気配りに感動した。", "explanation": "ここは〈細やかな〉の意味。細かく行き届いた気配りには細やかを使い、苛烈とは言わない。"}, {"text": "苛烈な子犬が走り回った。", "explanation": "ここは〈勢いの強い〉の意味。走り回る勢いの激しさには猛烈を使い、苛烈は厳しさや容赦のなさを表すので子犬の動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "正解。「苛烈を極める」で、非常にきびしい状態になることを表す。"}, {"text": "上品", "is_correct": false, "explanation": "上品は品があるさま。批判の激しさを表す「〜を極める」には続かない。"}, {"text": "健気", "is_correct": false, "explanation": "健気は懸命でけなげなさま。「〜を極める」とは続かない。"}, {"text": "朗らか", "is_correct": false, "explanation": "朗らかは明るいさま。批判の程度を表す文には合わない。"}], "explanations": {"苛烈": "正解。「苛烈を極める」で、非常にきびしい状態になることを表す。", "上品": "上品は品があるさま。批判の激しさを表す「〜を極める」には続かない。", "健気": "健気は懸命でけなげなさま。「〜を極める」とは続かない。", "朗らか": "朗らかは明るいさま。批判の程度を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "苛烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苛烈な布団で眠ったので、疲れが取れた。", "explanation": "ここは〈柔らかい〉の意味。やわらかい布団には柔らかいを使い、苛烈は使わない。"}, {"text": "苛烈なお菓子を食べて満足した。", "explanation": "ここは〈甘い〉の意味。甘いお菓子に苛烈は合わず、甘いを使う。"}, {"text": "苛烈な花が庭に咲いた。", "explanation": "ここは〈鮮やかな〉の意味。鮮やかで印象的な花には鮮烈を使い、苛烈は厳しさや激しさを表すので花には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真夏の太陽が苛烈な照りつける。", "corrected_sentence": "真夏の太陽が苛烈に照りつける。", "error_description": "誤りは活用形。動詞「照りつける」を修飾するには連用形「苛烈に」が必要。「苛烈な」は連体形で、動詞を直接修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "正解。語幹で、後ろに「な」を続けて「訓練」を修飾する。"}, {"text": "苛烈に", "is_correct": false, "explanation": "連用形。「〜な訓練」の位置には入らず、名詞を修飾できない。"}, {"text": "苛烈で", "is_correct": false, "explanation": "中止形。名詞を修飾する「な訓練」の形にならない。"}, {"text": "苛烈さ", "is_correct": false, "explanation": "名詞形。「苛烈さな訓練」とは続かず、「な訓練」の位置に入らない。"}], "correct_form": "苛烈", "base_form": "苛烈", "form_label": "語幹", "sentence_index": 1, "explanations": {"苛烈": "正解。語幹で、後ろに「な」を続けて「訓練」を修飾する。", "苛烈に": "連用形。「〜な訓練」の位置には入らず、名詞を修飾できない。", "苛烈で": "中止形。名詞を修飾する「な訓練」の形にならない。", "苛烈さ": "名詞形。「苛烈さな訓練」とは続かず、「な訓練」の位置に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その試合は、終盤になるほど苛烈を務めた。", "corrected_sentence": "その試合は、終盤になるほど苛烈を極めた。", "error_description": "誤りは「苛烈を」に続く動詞。「苛烈を極める」が正しい。「務める」は役目を果たす意味で、「苛烈を務める」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "苛烈", "is_correct": true, "explanation": "正解。語幹で、後ろに「な暑さ」と続けて名詞を修飾する。"}, {"text": "苛烈だ", "is_correct": false, "explanation": "断定の終止形。「だ」で文を言い切るため、「〜な暑さ」の位置には続かない。"}, {"text": "苛烈です", "is_correct": false, "explanation": "丁寧な終止形。名詞「暑さ」の前には入らず、文が成り立たない。"}, {"text": "苛烈なら", "is_correct": false, "explanation": "仮定形。「なら」で文が続くため、名詞「暑さ」を修飾できない。"}], "correct_form": "苛烈", "base_form": "苛烈", "form_label": "語幹", "sentence_index": 7, "explanations": {"苛烈": "正解。語幹で、後ろに「な暑さ」と続けて名詞を修飾する。", "苛烈だ": "断定の終止形。「だ」で文を言い切るため、「〜な暑さ」の位置には続かない。", "苛烈です": "丁寧な終止形。名詞「暑さ」の前には入らず、文が成り立たない。", "苛烈なら": "仮定形。「なら」で文が続くため、名詞「暑さ」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「カメラとノートを携える」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。カメラとノートが携えるでは目的語が欠け、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置を示す。カメラとノートに携えるという関係は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示す。ノートから携えるでは対象を取る文にならない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「カメラとノートを携える」の目的語を示す格助詞。", "が": "〈が〉は主語を示す。カメラとノートが携えるでは目的語が欠け、文が成り立たない。", "に": "〈に〉は位置を示す。カメラとノートに携えるという関係は成り立たない。", "から": "〈から〉は起点を示す。ノートから携えるでは対象を取る文にならない。"}, "error_tags": {"が": "主語", "に": "位置", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「弁当を携える」の目的語を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。弁当へ携えるという形では目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段を示す。弁当で携えるという手段の関係は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞同士をつなぐ。弁当の携えるでは文が続かない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「弁当を携える」の目的語を示す格助詞。", "へ": "〈へ〉は方向を示す。弁当へ携えるという形では目的語を示せない。", "で": "〈で〉は手段を示す。弁当で携えるという手段の関係は成り立たない。", "の": "〈の〉は名詞同士をつなぐ。弁当の携えるでは文が続かない。"}, "error_tags": {"へ": "方向", "で": "手段", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手に持って、どこかへ行くこと。", "primary_collocate": null, "pronunciation": "たずさえる", "ipa": "tazɯsaeɾɯ", "syllable_count": 5, "sentences": [{"text": "傘を携えて家を出たので、急な雨にも困らなかった。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "傘[かさ]を携[たずさ]えて家[いえ]を出[で]たので、急[きゅう]な雨[あめ]にも困[こま]らなかった。", "sentence_source": "generated"}, {"text": "記者はカメラとノートを携えて、現場へ急いだ。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "記者[きしゃ]はカメラとノートを携[たずさ]えて、現場[げんば]へ急[いそ]いだ。", "sentence_source": "generated"}, {"text": "彼は花束を携えて、入院中の友人を見舞った。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼[かれ]は花束[はなたば]を携[たずさ]えて、入院中[にゅういんちゅう]の友人[ゆうじん]を見舞[みま]った。", "sentence_source": "generated"}, {"text": "登山者は十分な食料を携えて、山小屋を出発した。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は十分[じゅうぶん]な食料[しょくりょう]を携[たずさ]えて、山小屋[やまごや]を出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "先生は資料を携えて、隣の教室へ向かった。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "先生[せんせい]は資料[しりょう]を携[たずさ]えて、隣[となり]の教室[きょうしつ]へ向[む]かった。", "sentence_source": "generated"}, {"text": "彼女は大きな旅行かばんを携えて、駅のホームに現れた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大[おお]きな旅行[りょこう]かばんを携[たずさ]えて、駅[えき]のホームに現[あらわ]れた。", "sentence_source": "generated"}, {"text": "使者は王の手紙を携えて、隣国へ旅立った。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "使者[ししゃ]は王[おう]の手紙[てがみ]を携[たずさ]えて、隣国[りんごく]へ旅立[たびだ]った。", "sentence_source": "generated"}, {"text": "弁当を携えて公園に行き、桜の下で昼食を食べた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "弁当[べんとう]を携[たずさ]えて公園[こうえん]に行[い]き、桜[さくら]の下[した]で昼食[ちゅうしょく]を食[た]べた。", "sentence_source": "generated"}, {"text": "釣り竿を携えて川へ行ったが、一匹も釣れなかった。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "釣[つ]り竿[ざお]を携[たずさ]えて川[かわ]へ行[い]ったが、一匹[いっぴき]も釣[つ]れなかった。", "sentence_source": "generated"}, {"text": "彼は土産を携えて、恩師の家を訪ねた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼[かれ]は土産[みやげ]を携[たずさ]えて、恩師[おんし]の家[いえ]を訪[たず]ねた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "携えない", "label": "否定形"}, {"form": "携え", "label": "連用形"}, {"form": "携えて", "label": "て形"}, {"form": "携えた", "label": "た形"}, {"form": "携えれば", "label": "仮定形"}, {"form": "携えよう", "label": "意志形"}], "register": "neutral-literary", "sense_fingerprint": "物を手に持って目的地へ向かう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携えて", "is_correct": true, "explanation": "傘を手に持って家を出る、という意味で文脈に合う。"}, {"text": "蹴って", "is_correct": false, "explanation": "〈蹴る〉は足で打つ動作で、傘を蹴って家を出る文は不自然。"}, {"text": "切って", "is_correct": false, "explanation": "〈切る〉は刃物で断つ動作で、傘を切って家を出る文は意味が通らない。"}, {"text": "投げて", "is_correct": false, "explanation": "〈投げる〉は放る動作で、傘を持って行く意味にはならない。"}], "explanations": {"携えて": "傘を手に持って家を出る、という意味で文脈に合う。", "蹴って": "〈蹴る〉は足で打つ動作で、傘を蹴って家を出る文は不自然。", "切って": "〈切る〉は刃物で断つ動作で、傘を切って家を出る文は意味が通らない。", "投げて": "〈投げる〉は放る動作で、傘を持って行く意味にはならない。"}, "sentence_index": 0, "correct_answer": "携えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は長年、研究室の指揮を携えた。", "explanation": "ここは〈執る〉（指揮を取る）の意味。携えるは持って行く意味なので、指揮を取る文には使えない。"}, {"text": "彼は長年、学校の教頭を携えた。", "explanation": "ここは〈務める〉（役目を果たす）の意味。携えるは持って行く意味で、役職を担う文には合わない。"}, {"text": "彼は新事業の立ち上げを携えた。", "explanation": "ここは〈始める〉（着手する）の意味。携えるは持って行く意味なので、事業を立ち上げる文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携えて", "is_correct": true, "explanation": "王の手紙を手に持って旅立つ、という意味で文脈に合う。"}, {"text": "脱いで", "is_correct": false, "explanation": "〈脱ぐ〉は身につけたものを外す動作で、手紙を脱ぐ文は成り立たない。"}, {"text": "噛んで", "is_correct": false, "explanation": "〈噛む〉は口で物をかむ動作で、手紙を噛んで旅立つ文にはならない。"}, {"text": "叩いて", "is_correct": false, "explanation": "〈叩く〉は打つ動作で、手紙を持って行く意味にはならない。"}], "explanations": {"携えて": "王の手紙を手に持って旅立つ、という意味で文脈に合う。", "脱いで": "〈脱ぐ〉は身につけたものを外す動作で、手紙を脱ぐ文は成り立たない。", "噛んで": "〈噛む〉は口で物をかむ動作で、手紙を噛んで旅立つ文にはならない。", "叩いて": "〈叩く〉は打つ動作で、手紙を持って行く意味にはならない。"}, "sentence_index": 6, "correct_answer": "携えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大規模な調査を携えた。", "explanation": "ここは〈行う〉（実施する）の意味。携えるは持ち運ぶ意味で、調査を実施する文では使えない。"}, {"text": "彼は地元の銀行の業務を携えた。", "explanation": "ここは〈勤める〉（その機関で働く）の意味。携えるは持って行く意味なので、業務に就く文には合わない。"}, {"text": "手紙の末尾に署名を携えた。", "explanation": "ここは〈添える〉（付け加える）の意味。携えるは持って行く意味で、末尾に署名を書き加える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は弁当に携えて、山の頂上へ向かった。", "corrected_sentence": "父は弁当を携えて、山の頂上へ向かった。", "error_description": "助詞の誤り。携えるは〈を〉で目的語を取るので、「弁当を」とする。〈に〉では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "携えて", "is_correct": true, "explanation": "て形。「〜て、〜た」と文を続ける形で、ここに入る。"}, {"text": "携えれば", "is_correct": false, "explanation": "仮定形「携えれば」は条件の形になり、過去の動作を述べる文に合わない。"}, {"text": "携えない", "is_correct": false, "explanation": "否定形。持たない意味になり、現場へ急ぐ文の流れに合わない。"}, {"text": "携えよう", "is_correct": false, "explanation": "意志形。「携えよう、〜」と誘う形になり、過去の行動を述べる文に合わない。"}], "correct_form": "携えて", "base_form": "携える", "form_label": "て形", "sentence_index": 1, "explanations": {"携えて": "て形。「〜て、〜た」と文を続ける形で、ここに入る。", "携えれば": "仮定形「携えれば」は条件の形になり、過去の動作を述べる文に合わない。", "携えない": "否定形。持たない意味になり、現場へ急ぐ文の流れに合わない。", "携えよう": "意志形。「携えよう、〜」と誘う形になり、過去の行動を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52461, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生は辞書を携えるて、図書館へ入った。", "corrected_sentence": "学生は辞書を携えて、図書館へ入った。", "error_description": "「携えるて」は動詞の活用として成り立たない。正しくは「携えて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "携えて", "is_correct": true, "explanation": "て形。「〜て、〜た」と文を続ける形で、ここに入る。"}, {"text": "携える", "is_correct": false, "explanation": "終止形。文を切ってしまい、後ろの「行き」「食べた」と続かない。"}, {"text": "携えた", "is_correct": false, "explanation": "た形。文を終えてしまい、「公園に行き」と続かない。"}, {"text": "携えられ", "is_correct": false, "explanation": "受身の連用形。「弁当を」の〈を〉と合わず、主語も変わってしまう。"}], "correct_form": "携えて", "base_form": "携える", "form_label": "て形", "sentence_index": 7, "explanations": {"携えて": "て形。「〜て、〜た」と文を続ける形で、ここに入る。", "携える": "終止形。文を切ってしまい、後ろの「行き」「食べた」と続かない。", "携えた": "た形。文を終えてしまい、「公園に行き」と続かない。", "携えられ": "受身の連用形。「弁当を」の〈を〉と合わず、主語も変わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「夢と自信を携える」の目的語を示し、携えるの直前に入る格助詞。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。自信が携えるという形では目的語が欠け、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置や相手を示す。自信に携えるという関係は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。ここは携える対象を示す場面なので合わない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「夢と自信を携える」の目的語を示し、携えるの直前に入る格助詞。", "が": "〈が〉は主語を示す。自信が携えるという形では目的語が欠け、文が成り立たない。", "に": "〈に〉は位置や相手を示す。自信に携えるという関係は成り立たない。", "へ": "〈へ〉は方向を示す。ここは携える対象を示す場面なので合わない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「決意を携える」の目的語を示し、携えるの直前に入る格助詞。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示す。決意から携えるという形は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示す。決意より携えるという文は通らない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞同士をつなぐ。決意の携えるでは文が続かない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「決意を携える」の目的語を示し、携えるの直前に入る格助詞。", "から": "〈から〉は起点を示す。決意から携えるという形は成り立たない。", "より": "〈より〉は比較を示す。決意より携えるという文は通らない。", "の": "〈の〉は名詞同士をつなぐ。決意の携えるでは文が続かない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手に持ったり、身につけたりして、一緒に持っていくこと。また、ある物や気持ちなどを、自分の一部として持つこと。", "primary_collocate": null, "pronunciation": "たずさえる", "ipa": "tazɯsaeɾɯ", "syllable_count": 5, "sentences": [{"text": "彼女は優しい思い出を携えて、故郷を後にした。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は優[やさ]しい思[おも]い出[で]を携[たずさ]えて、故郷[こきょう]を後[あと]にした。", "sentence_source": "generated"}, {"text": "彼は夢と自信を携えて、新しい街へ旅立った。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼[かれ]は夢[ゆめ]と自信[じしん]を携[たずさ]えて、新[あたら]しい街[まち]へ旅立[たびだ]った。", "sentence_source": "generated"}, {"text": "彼女は優しい笑顔を携えて、会場に入ってきた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は優[やさ]しい笑顔[えがお]を携[たずさ]えて、会場[かいじょう]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "新入社員は強い意欲を携えて、初出勤の日を迎えた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]は強[つよ]い意欲[いよく]を携[たずさ]えて、初出勤[はつしゅっきん]の日[ひ]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "兵士は剣を腰に携え、城門の前に立っていた。", "target_word": "携え", "complexity_tier": "T3", "furigana": "兵士[へいし]は剣[けん]を腰[こし]に携[たずさ]え、城門[じょうもん]の前[まえ]に立[た]っていた。", "sentence_source": "generated"}, {"text": "旅人は地図と水筒を携えて山道を歩いた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "旅人[たびびと]は地図[ちず]と水筒[すいとう]を携[たずさ]えて山道[やまみち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "彼は豊かな経験を携えて故郷に戻り、後輩の指導を始めた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼[かれ]は豊[ゆた]かな経験[けいけん]を携[たずさ]えて故郷[こきょう]に戻[もど]り、後輩[こうはい]の指導[しどう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "選手たちは勝利への決意を携えて、決勝の舞台に向かった。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは勝利[しょうり]への決意[けつい]を携[たずさ]えて、決勝[けっしょう]の舞台[ぶたい]に向[む]かった。", "sentence_source": "generated"}, {"text": "祖母は古い写真を携えて、孫の結婚式に出席した。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "祖母[そぼ]は古[ふる]い写真[しゃしん]を携[たずさ]えて、孫[まご]の結婚式[けっこんしき]に出席[しゅっせき]した。", "sentence_source": "generated"}, {"text": "彼は謝罪の気持ちを携えて、取引先を訪れた。", "target_word": "携えて", "complexity_tier": "T3", "furigana": "彼[かれ]は謝罪[しゃざい]の気持[きも]ちを携[たずさ]えて、取引先[とりひきさき]を訪[おとず]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "携えない", "label": "否定形"}, {"form": "携え", "label": "連用形"}, {"form": "携えて", "label": "て形"}, {"form": "携えた", "label": "た形"}, {"form": "携えれば", "label": "仮定形"}, {"form": "携えよう", "label": "意志形"}], "register": "neutral-literary", "sense_fingerprint": "物・気持ち・経験などを身につけ、自分の一部として持って行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携えて", "is_correct": true, "explanation": "思い出を身につけて持ったまま故郷を後にする、という意味で文脈に合う。"}, {"text": "割って", "is_correct": false, "explanation": "〈割る〉は物を砕く動作で、思い出を割るとは言えないため文が成り立たない。"}, {"text": "踏んで", "is_correct": false, "explanation": "〈踏む〉は足で押さえる動作で、思い出を持って行く意味にはならない。"}, {"text": "投げて", "is_correct": false, "explanation": "〈投げる〉は放り出す動作で、思い出を持って故郷を後にする意味とは合わない。"}], "explanations": {"携えて": "思い出を身につけて持ったまま故郷を後にする、という意味で文脈に合う。", "割って": "〈割る〉は物を砕く動作で、思い出を割るとは言えないため文が成り立たない。", "踏んで": "〈踏む〉は足で押さえる動作で、思い出を持って行く意味にはならない。", "投げて": "〈投げる〉は放り出す動作で、思い出を持って故郷を後にする意味とは合わない。"}, "sentence_index": 0, "correct_answer": "携えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は十年間、教育の現場を携えてきた。", "explanation": "ここは〈携わる〉（関わる）の意味。携えるは持って行く・身につける意味なので、現場に関わる文では使わない。"}, {"text": "契約書に署名を携えた。", "explanation": "ここは〈添える〉（付け加える）の意味。携えるは持って行く意味なので、書類に署名を付け加える文には合わない。"}, {"text": "彼らは新製品の開発を携えた。", "explanation": "ここは〈取りかかる〉（取り組む）の意味。携えるは持って行く意味なので、開発に取り組む文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携えて", "is_correct": true, "explanation": "経験を身につけて持ち帰る、という意味で文脈に合う。"}, {"text": "壊して", "is_correct": false, "explanation": "〈壊す〉は物を壊す動作で、経験を壊して持つという文にはならない。"}, {"text": "脱いで", "is_correct": false, "explanation": "〈脱ぐ〉は身につけたものを外す動作で、経験には使えない。"}, {"text": "噛んで", "is_correct": false, "explanation": "〈噛む〉は口で物をかむ動作で、経験を噛むという文は成り立たない。"}], "explanations": {"携えて": "経験を身につけて持ち帰る、という意味で文脈に合う。", "壊して": "〈壊す〉は物を壊す動作で、経験を壊して持つという文にはならない。", "脱いで": "〈脱ぐ〉は身につけたものを外す動作で、経験には使えない。", "噛んで": "〈噛む〉は口で物をかむ動作で、経験を噛むという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "携えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長年、会長を携えた。", "explanation": "ここは〈務める〉（役目を果たす）の意味。携えるは物や気持ちを持って行く意味で、役職を担う文には使わない。"}, {"text": "彼は新しい実験を携えた。", "explanation": "ここは〈行う〉（実施する）の意味。携えるは持ち運ぶ意味で、実験を実施する文では使えない。"}, {"text": "彼は大手企業の経営を携えた。", "explanation": "ここは〈担う〉（引き受けて務める）の意味。携えるは持って行く・身につける意味なので、経営を引き受ける文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は不安に携えて、初めての面接に臨んだ。", "corrected_sentence": "彼女は不安を携えて、初めての面接に臨んだ。", "error_description": "目的語の助詞が誤り。携えるは「〜を携える」で目的語を取るため、「不安を」と〈を〉を使う。〈に〉では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "携えて", "is_correct": true, "explanation": "て形。「〜て、〜た」と文を続ける形で、ここに入る。"}, {"text": "携えれば", "is_correct": false, "explanation": "仮定形「携えれば」は条件の形になり、過去の出来事を述べる文に合わない。"}, {"text": "携えない", "is_correct": false, "explanation": "否定形。夢と自信を持たない意味になり、旅立つ文の流れに合わない。"}, {"text": "携えよう", "is_correct": false, "explanation": "意志形。「携えよう、〜」と誘う形になり、過去の出来事を述べる文に合わない。"}], "correct_form": "携えて", "base_form": "携える", "form_label": "て形", "sentence_index": 1, "explanations": {"携えて": "て形。「〜て、〜た」と文を続ける形で、ここに入る。", "携えれば": "仮定形「携えれば」は条件の形になり、過去の出来事を述べる文に合わない。", "携えない": "否定形。夢と自信を持たない意味になり、旅立つ文の流れに合わない。", "携えよう": "意志形。「携えよう、〜」と誘う形になり、過去の出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52462, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は小さな夢を携える、故郷の町を後にした。", "corrected_sentence": "彼は小さな夢を携えて、故郷の町を後にした。", "error_description": "て形にすべきところを終止形で切っている。後ろの「後にした」と続けるには〈携えて〉が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "携えて", "is_correct": true, "explanation": "て形。「〜て、〜た」と文を続ける形で、ここに入る。"}, {"text": "携える", "is_correct": false, "explanation": "終止形。文を切ってしまい、後ろの「向かった」と続かない。"}, {"text": "携えた", "is_correct": false, "explanation": "た形。文を終えてしまい、「決勝の舞台に向かった」と続かない。"}, {"text": "携えられ", "is_correct": false, "explanation": "受身の連用形。「決意を」の〈を〉と合わず、主語も変わってしまう。"}], "correct_form": "携えて", "base_form": "携える", "form_label": "て形", "sentence_index": 7, "explanations": {"携えて": "て形。「〜て、〜た」と文を続ける形で、ここに入る。", "携える": "終止形。文を切ってしまい、後ろの「向かった」と続かない。", "携えた": "た形。文を終えてしまい、「決勝の舞台に向かった」と続かない。", "携えられ": "受身の連用形。「決意を」の〈を〉と合わず、主語も変わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「樽のふたを押し開ける」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。樽のふたが押し開けるでは、目的語を取る動詞の形と合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段を示す。樽のふたで押し開けるでは、ふたを道具として使う意味になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞同士をつなぐ。樽のふたの押し開けるでは文が続かない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「樽のふたを押し開ける」の目的語を示す格助詞。", "が": "〈が〉は主語を示す。樽のふたが押し開けるでは、目的語を取る動詞の形と合わない。", "で": "〈で〉は手段を示す。樽のふたで押し開けるでは、ふたを道具として使う意味になり不自然。", "の": "〈の〉は名詞同士をつなぐ。樽のふたの押し開けるでは文が続かない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「木戸を」の目的語を示す格助詞。押し開ける対象を示し、「無理に押し開けたら」と続く。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。木戸が無理に押し開けたらでは、木戸自身が動作主になり、押し開ける対象として合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段・場所を示す。木戸で無理に押し開けたらでは、木戸を道具として使う意味になり、目的語の関係が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列・相手を示す。木戸と無理に押し開けたらでは、誰かと一緒に開けるような意味になり、目的語の関係が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「木戸を」の目的語を示す格助詞。押し開ける対象を示し、「無理に押し開けたら」と続く。", "が": "〈が〉は主語を示す。木戸が無理に押し開けたらでは、木戸自身が動作主になり、押し開ける対象として合わない。", "で": "〈で〉は手段・場所を示す。木戸で無理に押し開けたらでは、木戸を道具として使う意味になり、目的語の関係が崩れる。", "と": "〈と〉は並列・相手を示す。木戸と無理に押し開けたらでは、誰かと一緒に開けるような意味になり、目的語の関係が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "力を入れて、戸やふたを開けること。", "primary_collocate": null, "pronunciation": "おしあける", "ipa": "oɕiakeɾɯ", "syllable_count": 5, "sentences": [{"text": "雪で凍った戸を、全身の力で押し開けた。", "target_word": "押し開けた", "complexity_tier": "T3", "furigana": "雪[ゆき]で凍[こお]った戸[と]を、全身[ぜんしん]の力[ちから]で押[お]し開[あ]けた。", "sentence_source": "generated"}, {"text": "樽のふたを押し開けると、酒の香りが広がった。", "target_word": "押し開ける", "complexity_tier": "T3", "furigana": "樽[たる]のふたを押[お]し開[あ]けると、酒[さけ]の香[かお]りが広[ひろ]がった。", "sentence_source": "generated"}, {"text": "風が強く、玄関の扉を押し開けるのに苦労した。", "target_word": "押し開ける", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]く、玄関[げんかん]の扉[とびら]を押[お]し開[あ]けるのに苦労[くろう]した。", "sentence_source": "generated"}, {"text": "倉庫の重い扉を押し開けて、荷物を運び込んだ。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の重[おも]い扉[とびら]を押[お]し開[あ]けて、荷物[にもつ]を運[はこ]び込[こ]んだ。", "sentence_source": "generated"}, {"text": "彼女は肩で部屋のドアを押し開けて、お盆を運んだ。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は肩[かた]で部屋[へや]のドアを押[お]し開[あ]けて、お盆[ぼん]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "犯人は裏口を押し開けて、暗い路地へ逃げた。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "犯人[はんにん]は裏口[うらぐち]を押[お]し開[あ]けて、暗[くら]い路地[ろじ]へ逃[に]げた。", "sentence_source": "generated"}, {"text": "子どもたちは校門を押し開けて、元気に走り出した。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "子[こ]どもたちは校門[こうもん]を押[お]し開[あ]けて、元気[げんき]に走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "壊れかけた木戸を無理に押し開けたら、蝶番が外れた。", "target_word": "押し開けた", "complexity_tier": "T3", "furigana": "壊[こわ]れかけた木戸[きど]を無理[むり]に押[お]し開[あ]けたら、蝶番[ちょうつがい]が外[はず]れた。", "sentence_source": "generated"}, {"text": "彼は暖炉の鉄のふたを押し開け、薪をくべた。", "target_word": "押し開け", "complexity_tier": "T3", "furigana": "彼[かれ]は暖炉[だんろ]の鉄[てつ]のふたを押[お]し開[あ]け、薪[まき]をくべた。", "sentence_source": "generated"}, {"text": "吹雪の中、やっとのことで山小屋の戸を押し開けた。", "target_word": "押し開けた", "complexity_tier": "T3", "furigana": "吹雪[ふぶき]の中[なか]、やっとのことで山小屋[やまごや]の戸[と]を押[お]し開[あ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押し開けない", "label": "否定形"}, {"form": "押し開け", "label": "連用形"}, {"form": "押し開けて", "label": "て形"}, {"form": "押し開けた", "label": "た形"}, {"form": "押し開ければ", "label": "仮定形"}, {"form": "押し開けよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "固い戸やふたに力を入れて押し開ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押し開けた", "is_correct": true, "explanation": "凍った戸を全身の力で押して開けた、という意味で文脈に合う。"}, {"text": "注いだ", "is_correct": false, "explanation": "〈注ぐ〉は液体を流し入れる動作で、戸に使うと意味が通らない。"}, {"text": "編んだ", "is_correct": false, "explanation": "〈編む〉は糸で編み上げる動作で、戸を編むという文は成り立たない。"}, {"text": "数えた", "is_correct": false, "explanation": "〈数える〉は数を数える動作で、戸を数えても開ける意味にはならない。"}], "explanations": {"押し開けた": "凍った戸を全身の力で押して開けた、という意味で文脈に合う。", "注いだ": "〈注ぐ〉は液体を流し入れる動作で、戸に使うと意味が通らない。", "編んだ": "〈編む〉は糸で編み上げる動作で、戸を編むという文は成り立たない。", "数えた": "〈数える〉は数を数える動作で、戸を数えても開ける意味にはならない。"}, "sentence_index": 0, "correct_answer": "押し開けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "観客が広場を押し開けた。", "explanation": "ここは〈押し寄せる〉（大勢が集まって押し寄せる）の意味。押し開けるは戸やふたに使う動作で、広場を開ける文には合わない。"}, {"text": "強盗が窓から家を押し開けた。", "explanation": "ここは〈押し入る〉（無理に入り込む）の意味。押し開けるは戸やふたを開ける動作で、家に入る文には使えない。"}, {"text": "彼は強い反対を押し開けて進んだ。", "explanation": "ここは〈押し切る〉（反対を退けて進める）の意味。押し開けるは戸やふたを開ける動作で、反対を退ける文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押し開けて", "is_correct": true, "explanation": "校門を押して開け、元気に走り出した、という意味で文脈に合う。"}, {"text": "混ぜて", "is_correct": false, "explanation": "〈混ぜる〉は材料を混ぜ合わせる動作で、校門を混ぜるという文は成り立たない。"}, {"text": "溶かして", "is_correct": false, "explanation": "〈溶かす〉は熱で溶かす動作で、校門を溶かして走り出す文は意味が通らない。"}, {"text": "煮込んで", "is_correct": false, "explanation": "〈煮込む〉は食材を煮る動作で、校門を煮込む文は成り立たない。"}], "explanations": {"押し開けて": "校門を押して開け、元気に走り出した、という意味で文脈に合う。", "混ぜて": "〈混ぜる〉は材料を混ぜ合わせる動作で、校門を混ぜるという文は成り立たない。", "溶かして": "〈溶かす〉は熱で溶かす動作で、校門を溶かして走り出す文は意味が通らない。", "煮込んで": "〈煮込む〉は食材を煮る動作で、校門を煮込む文は成り立たない。"}, "sentence_index": 6, "correct_answer": "押し開けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は研究を押し開けて、論文を書いた。", "explanation": "ここは〈押し進める〉（推し進める）の意味。押し開けるは戸やふたを開ける動作で、研究を進める文では使えない。"}, {"text": "相手を押し開けて、ボールを奪った。", "explanation": "ここは〈押し倒す〉（押して倒す）の意味。押し開けるは戸やふたを開ける動作で、人を倒す文には合わない。"}, {"text": "かばんに本を押し開けた。", "explanation": "ここは〈押し込む〉（押して中に入れる）の意味。押し開けるは開く動作で、本を入れる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は重い木箱のふたが押し開けて、古い地図を取り出した。", "corrected_sentence": "祖父は重い木箱のふたを押し開けて、古い地図を取り出した。", "error_description": "助詞の誤り。押し開けるは〈を〉で目的語（ふた）を取るので、〈が〉ではなく〈を〉にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押し開ける", "is_correct": true, "explanation": "辞書形。「〜と」の前に置かれ、ふたを開ける動作を述べる形。"}, {"text": "押し開けない", "is_correct": false, "explanation": "否定形。開けないという意味になり、香りが広がった結果と合わない。"}, {"text": "押し開け", "is_correct": false, "explanation": "連用形。「〜と」の前には置けず、文が成り立たない。"}, {"text": "押し開けなかった", "is_correct": false, "explanation": "否定の過去形。開けなかった意味になり、香りが広がった文の流れに合わない。"}], "correct_form": "押し開ける", "base_form": "押し開ける", "form_label": "辞書形", "sentence_index": 1, "explanations": {"押し開ける": "辞書形。「〜と」の前に置かれ、ふたを開ける動作を述べる形。", "押し開けない": "否定形。開けないという意味になり、香りが広がった結果と合わない。", "押し開け": "連用形。「〜と」の前には置けず、文が成り立たない。", "押し開けなかった": "否定の過去形。開けなかった意味になり、香りが広がった文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52463, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の日、彼は凍った門を押し開ける、外へ出た。", "corrected_sentence": "雪の日、彼は凍った門を押し開けて、外へ出た。", "error_description": "て形にすべきところを辞書形で切っている。後ろの「外へ出た」と続けるには〈押し開けて〉が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押し開けた", "is_correct": true, "explanation": "た形。「〜たら」と続けて、扉を押し開けた後の結果を述べる形。"}, {"text": "押し開ける", "is_correct": false, "explanation": "辞書形。「〜ら」と続かず、条件の文として成り立たない。"}, {"text": "押し開け", "is_correct": false, "explanation": "連用形。「〜たら」の前に置けず、条件を表す文にならない。"}, {"text": "押し開けろ", "is_correct": false, "explanation": "命令形。命令の文になり、蝶番が外れた結果を述べる文に合わない。"}], "correct_form": "押し開けた", "base_form": "押し開ける", "form_label": "た形", "sentence_index": 7, "explanations": {"押し開けた": "た形。「〜たら」と続けて、扉を押し開けた後の結果を述べる形。", "押し開ける": "辞書形。「〜ら」と続かず、条件の文として成り立たない。", "押し開け": "連用形。「〜たら」の前に置けず、条件を表す文にならない。", "押し開けろ": "命令形。命令の文になり、蝶番が外れた結果を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "〈で〉は手段を示す。「肩で押し開ける」と動作の手段を表す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。肩を押し開けるでは意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置を示す。肩に押し開けるでは動作の手段にならない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞同士をつなぐ。肩の押し開けるでは文が続かない。"}], "correct_answer": "で", "explanations": {"で": "〈で〉は手段を示す。「肩で押し開ける」と動作の手段を表す格助詞。", "を": "〈を〉は目的語を示す。肩を押し開けるでは意味が通らない。", "に": "〈に〉は位置を示す。肩に押し開けるでは動作の手段にならない。", "の": "〈の〉は名詞同士をつなぐ。肩の押し開けるでは文が続かない。"}, "error_tags": {"を": "目的語", "に": "位置", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は「ガラス戸を押し開ける」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。店のガラス戸が押し開けるでは、戸が自分で開く意味になり文が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。ガラス戸へ押し開けるでは目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段を示す。ガラス戸で押し開けるでは、戸を道具として使う意味になり不自然。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は「ガラス戸を押し開ける」の目的語を示す格助詞。", "が": "〈が〉は主語を示す。店のガラス戸が押し開けるでは、戸が自分で開く意味になり文が合わない。", "へ": "〈へ〉は方向を示す。ガラス戸へ押し開けるでは目的語を示せない。", "で": "〈で〉は手段を示す。ガラス戸で押し開けるでは、戸を道具として使う意味になり不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "押して、閉まっているものを開ける。ドアやふたなどを、手や体で押しながら開ける。", "primary_collocate": null, "pronunciation": "おしあける", "ipa": "oɕiakeɾɯ", "syllable_count": 5, "sentences": [{"text": "やがて準備が整い、彼は勢いよく扉を押し開ける。", "target_word": "押し開ける", "complexity_tier": "T3", "furigana": "やがて準備[じゅんび]が整[ととの]い、彼[かれ]は勢[いきお]いよく扉[とびら]を押[お]し開[あ]ける。", "sentence_source": "mined"}, {"text": "重い鉄の扉を肩で押し開けると、冷たい風が吹き込んだ。", "target_word": "押し開ける", "complexity_tier": "T3", "furigana": "重[おも]い鉄[てつ]の扉[とびら]を肩[かた]で押[お]し開[あ]けると、冷[つめ]たい風[かぜ]が吹[ふ]き込[こ]んだ。", "sentence_source": "generated"}, {"text": "両手がふさがっていたので、背中で戸を押し開けた。", "target_word": "押し開けた", "complexity_tier": "T3", "furigana": "両手[りょうて]がふさがっていたので、背中[せなか]で戸[と]を押[お]し開[あ]けた。", "sentence_source": "generated"}, {"text": "彼は雨戸を押し開けて、朝の光を部屋に入れた。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "彼[かれ]は雨戸[あまど]を押[お]し開[あ]けて、朝[あさ]の光[ひかり]を部屋[へや]に入[い]れた。", "sentence_source": "generated"}, {"text": "錆びついた門を力いっぱい押し開け、庭に入った。", "target_word": "押し開け", "complexity_tier": "T3", "furigana": "錆[さ]びついた門[もん]を力[ちから]いっぱい押[お]し開[あ]け、庭[にわ]に入[はい]った。", "sentence_source": "generated"}, {"text": "少女はそっと襖を押し開け、中の様子をうかがった。", "target_word": "押し開け", "complexity_tier": "T3", "furigana": "少女[しょうじょ]はそっと襖[ふすま]を押[お]し開[あ]け、中[なか]の様子[ようす]をうかがった。", "sentence_source": "generated"}, {"text": "消防士は歪んだドアを押し開けて、中に取り残された人を探した。", "target_word": "押し開けて", "complexity_tier": "T3", "furigana": "消防士[しょうぼうし]は歪[ゆが]んだドアを押[お]し開[あ]けて、中[なか]に取[と]り残[のこ]された人[ひと]を探[さが]した。", "sentence_source": "generated"}, {"text": "彼女は店のガラス戸を押し開け、「こんにちは」と声をかけた。", "target_word": "押し開け", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は店[みせ]のガラス戸[ど]を押[お]し開[あ]け、「こんにちは」と声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "窓が固くて、何度も体重をかけて押し開けた。", "target_word": "押し開けた", "complexity_tier": "T3", "furigana": "窓[まど]が固[かた]くて、何度[なんど]も体重[たいじゅう]をかけて押[お]し開[あ]けた。", "sentence_source": "generated"}, {"text": "箱のふたを押し開けると、中から古い手紙が出てきた。", "target_word": "押し開ける", "complexity_tier": "T3", "furigana": "箱[はこ]のふたを押[お]し開[あ]けると、中[なか]から古[ふる]い手紙[てがみ]が出[で]てきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押し開けない", "label": "否定形"}, {"form": "押し開け", "label": "連用形"}, {"form": "押し開けて", "label": "て形"}, {"form": "押し開けた", "label": "た形"}, {"form": "押し開ければ", "label": "仮定形"}, {"form": "押し開けよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "閉まっている扉やふたを手や体で押して開ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押し開ける", "is_correct": true, "explanation": "閉まった扉を勢いよく押して開ける、という意味で文脈に合う。"}, {"text": "脱ぎ捨てる", "is_correct": false, "explanation": "〈脱ぎ捨てる〉は衣服を脱いで投げ出す意味で、扉には使えない。"}, {"text": "縫う", "is_correct": false, "explanation": "〈縫う〉は布を糸で綴る動作で、扉を縫うことはできない。"}, {"text": "結びつける", "is_correct": false, "explanation": "〈結びつける〉は物をくくって付ける動作で、扉を勢いよく開ける文に合わない。"}], "explanations": {"押し開ける": "閉まった扉を勢いよく押して開ける、という意味で文脈に合う。", "脱ぎ捨てる": "〈脱ぎ捨てる〉は衣服を脱いで投げ出す意味で、扉には使えない。", "縫う": "〈縫う〉は布を糸で綴る動作で、扉を縫うことはできない。", "結びつける": "〈結びつける〉は物をくくって付ける動作で、扉を勢いよく開ける文に合わない。"}, "sentence_index": 0, "correct_answer": "押し開ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強盗が勝手口から家に押し開けた。", "explanation": "ここは〈押し入る〉（無理に入り込む）の意味。押し開けるは閉まった戸やふたを開ける動作で、家に入る文には使えない。"}, {"text": "彼は反対を押し開けて、計画を進めた。", "explanation": "ここは〈押し切る〉（反対を退けて進める）の意味。押し開けるは戸やふたを開ける動作で、反対を退ける文には合わない。"}, {"text": "彼は相手を押し開けて、床に倒した。", "explanation": "ここは〈押し倒す〉（押して倒す）の意味。押し開けるは戸やふたを開ける動作で、人を倒す文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押し開けて", "is_correct": true, "explanation": "歪んだドアを押して開け、中へ入る、という意味で文脈に合う。"}, {"text": "結んで", "is_correct": false, "explanation": "〈結ぶ〉は紐などを結ぶ動作で、ドアを結んで開けるという文は成り立たない。"}, {"text": "数えて", "is_correct": false, "explanation": "〈数える〉は数を数える動作で、ドアに使うと文が意味をなさない。"}, {"text": "塗って", "is_correct": false, "explanation": "〈塗る〉は色を付ける動作で、ドアを塗って人を探す文にはならない。"}], "explanations": {"押し開けて": "歪んだドアを押して開け、中へ入る、という意味で文脈に合う。", "結んで": "〈結ぶ〉は紐などを結ぶ動作で、ドアを結んで開けるという文は成り立たない。", "数えて": "〈数える〉は数を数える動作で、ドアに使うと文が意味をなさない。", "塗って": "〈塗る〉は色を付ける動作で、ドアを塗って人を探す文にはならない。"}, "sentence_index": 6, "correct_answer": "押し開けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大群が町を押し開けた。", "explanation": "ここは〈押し寄せる〉（大勢が押し寄せる）の意味。押し開けるは戸やふたに使う動作で、町を開ける文には合わない。"}, {"text": "彼は研究を押し開けた。", "explanation": "ここは〈押し進める〉（推し進める）の意味。押し開けるは戸やふたを開ける動作で、研究を進める文では使えない。"}, {"text": "箱に紙を押し開けた。", "explanation": "ここは〈押し込む〉（押して中へ入れる）の意味。押し開けるは開く動作で、紙を入れる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少年は玄関の戸に押し開けて、外へ出た。", "corrected_sentence": "少年は玄関の戸を押し開けて、外へ出た。", "error_description": "助詞の誤り。押し開けるは〈を〉で目的語（戸）を取るので、〈に〉ではなく〈を〉にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押し開ける", "is_correct": true, "explanation": "辞書形。「〜と」の前に置かれ、扉を押し開ける動作を述べる形。"}, {"text": "押し開けた", "is_correct": false, "explanation": "た形。「〜と」の前では過去の動作になり、続く「吹き込んだ」の流れと合わない。"}, {"text": "押し開けない", "is_correct": false, "explanation": "否定形。開けない意味になり、風が吹き込んだ文の流れに合わない。"}, {"text": "押し開け", "is_correct": false, "explanation": "連用形。「〜と」の前には置けず、文が成り立たない。"}], "correct_form": "押し開ける", "base_form": "押し開ける", "form_label": "辞書形", "sentence_index": 1, "explanations": {"押し開ける": "辞書形。「〜と」の前に置かれ、扉を押し開ける動作を述べる形。", "押し開けた": "た形。「〜と」の前では過去の動作になり、続く「吹き込んだ」の流れと合わない。", "押し開けない": "否定形。開けない意味になり、風が吹き込んだ文の流れに合わない。", "押し開け": "連用形。「〜と」の前には置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は裏口の戸が押し開けて、静かに外へ出た。", "corrected_sentence": "彼女は裏口の戸を押し開けて、静かに外へ出た。", "error_description": "助詞の誤り。押し開けるは〈を〉で目的語（戸）を取るので、〈が〉ではなく〈を〉にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押し開け", "is_correct": true, "explanation": "連用形。「押し開け、〜」と後ろに続ける形で、ここに入る。"}, {"text": "押し開ける", "is_correct": false, "explanation": "辞書形。文を切ってしまい、「声をかけた」と続かない。"}, {"text": "押し開けない", "is_correct": false, "explanation": "否定形。「〜ない、」と切ると文が続かず、接続が成り立たない。"}, {"text": "押し開けろ", "is_correct": false, "explanation": "命令形。命令の文になり、彼女が声をかけた過去の出来事と合わない。"}], "correct_form": "押し開け", "base_form": "押し開ける", "form_label": "連用形", "sentence_index": 7, "explanations": {"押し開け": "連用形。「押し開け、〜」と後ろに続ける形で、ここに入る。", "押し開ける": "辞書形。文を切ってしまい、「声をかけた」と続かない。", "押し開けない": "否定形。「〜ない、」と切ると文が続かず、接続が成り立たない。", "押し開けろ": "命令形。命令の文になり、彼女が声をかけた過去の出来事と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『面接に備え』の『に』。備える対象を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『面接を備え』は目的語の形になり、『備える』の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、『面接へ備える』とは言わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、『面接から備える』では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "『面接に備え』の『に』。備える対象を示す格助詞。", "を": "『面接を備え』は目的語の形になり、『備える』の対象を示せない。", "へ": "方向を示すが、『面接へ備える』とは言わない。", "から": "起点を示すので、『面接から備える』では意味が通らない。"}, "error_tags": {"を": "目的語（誤り）", "へ": "方向（誤り）", "から": "起点（誤り）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『病気に備え』の『に』。備える対象を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。『病気で備え』では備える対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』で、『病気と備え』は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。『病気が備え』となり、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "『病気に備え』の『に』。備える対象を示す格助詞。", "で": "手段や場所を示す。『病気で備え』では備える対象を表せない。", "と": "並列の『と』で、『病気と備え』は文が成り立たない。", "が": "主語の格。『病気が備え』となり、意味が通らない。"}, "error_tags": {"で": "手段・場所（誤り）", "と": "並列（誤り）", "が": "主語（誤り）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをするために、前もって用意をすること。", "primary_collocate": null, "pronunciation": "そなえる", "ipa": "sonaeɾɯ", "syllable_count": 4, "sentences": [{"text": "大雨に備えて、川の近くの住民が避難所へ移った。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "大雨[おおあめ]に備[そな]えて、川[かわ]の近[ちか]くの住民[じゅうみん]が避難所[ひなんじょ]へ移[うつ]った。", "sentence_source": "generated"}, {"text": "面接に備え、想定される質問への答えを練習した。", "target_word": "備え", "complexity_tier": "T3", "furigana": "面接[めんせつ]に備[そな]え、想定[そうてい]される質問[しつもん]への答[こた]えを練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "冬に備えて、庭の木に雪よけの囲いを作った。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "冬[ふゆ]に備[そな]えて、庭[にわ]の木[き]に雪[ゆき]よけの囲[かこ]いを作[つく]った。", "sentence_source": "generated"}, {"text": "監督は次の試合に備えて、選手に早めの休養を命じた。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "監督[かんとく]は次[つぎ]の試合[しあい]に備[そな]えて、選手[せんしゅ]に早[はや]めの休養[きゅうよう]を命[めい]じた。", "sentence_source": "generated"}, {"text": "停電に備え、懐中電灯と電池を玄関に置いている。", "target_word": "備え", "complexity_tier": "T3", "furigana": "停電[ていでん]に備[そな]え、懐中電灯[かいちゅうでんとう]と電池[でんち]を玄関[げんかん]に置[お]いている。", "sentence_source": "generated"}, {"text": "彼らは敵の攻撃に備えて、国境に兵を集めた。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "彼[かれ]らは敵[てき]の攻撃[こうげき]に備[そな]えて、国境[こっきょう]に兵[へい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "万一の火事に備えて、各部屋に消火器を置いた。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "万一[まんいち]の火事[かじ]に備[そな]えて、各部屋[かくへや]に消火器[しょうかき]を置[お]いた。", "sentence_source": "generated"}, {"text": "旅行先での病気に備え、常備薬を持っていった。", "target_word": "備え", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]での病気[びょうき]に備[そな]え、常備薬[じょうびやく]を持[も]っていった。", "sentence_source": "generated"}, {"text": "将来に備えて、毎月少しずつ貯金している。", "target_word": "備えて", "complexity_tier": "T3", "furigana": "将来[しょうらい]に備[そな]えて、毎月[まいつき]少[すこ]しずつ貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "明日の発表に備え、今夜は早く寝ることにした。", "target_word": "備え", "complexity_tier": "T3", "furigana": "明日[あした]の発表[はっぴょう]に備[そな]え、今夜[こんや]は早[はや]く寝[ね]ることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "備えない", "label": "否定形"}, {"form": "備え", "label": "連用形"}, {"form": "備えて", "label": "て形"}, {"form": "備えた", "label": "た形"}, {"form": "備えれば", "label": "仮定形"}, {"form": "備えよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "起こりうる事態や行事のために前もって準備する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 常備薬 (Zipf 1.95)']::text[], '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "備えて", "is_correct": true, "explanation": "て形。『大雨に備えて』と目的を表し、後ろの文に続く。"}, {"text": "備えない", "is_correct": false, "explanation": "否定形。「備えない、」と切ると文が続かず、意味も逆になる。"}, {"text": "備えよう", "is_correct": false, "explanation": "意志形。『〜しよう』となり、『住民が避難所へ移った』と続かない。"}, {"text": "備えさせ", "is_correct": false, "explanation": "使役の連用形。人に準備させる意味になり、文意に合わない。"}], "explanations": {"備えて": "て形。『大雨に備えて』と目的を表し、後ろの文に続く。", "備えない": "否定形。「備えない、」と切ると文が続かず、意味も逆になる。", "備えよう": "意志形。『〜しよう』となり、『住民が避難所へ移った』と続かない。", "備えさせ": "使役の連用形。人に準備させる意味になり、文意に合わない。"}, "sentence_index": 0, "correct_answer": "備えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手はボールを備えて、ゴールをじっと見据えた。", "explanation": "ここは〈構える〉の意味。備えるは前もって必要なものを整える意味で、ボールを身構える場面では使わない。"}, {"text": "全員の意見を備えて、結論をまとめた。", "explanation": "ここは〈揃える〉の意味。備えるは物事に前もって用意しておく意味で、意見をそろえることには使わない。"}, {"text": "寝る前に、子どもたちは歯を備えた。", "explanation": "ここは〈磨く〉の意味。備えるは用意しておく意味で、歯を手入れする動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "備えて", "is_correct": true, "explanation": "て形。『万一の火事に備えて』と目的を表し、後ろの文に続く。"}, {"text": "備えた", "is_correct": false, "explanation": "た形。文を終えてしまい、後ろの「置いた」と続かない。"}, {"text": "備える", "is_correct": false, "explanation": "終止形。文を切ってしまい、「各部屋に消火器を置いた」と続かない。"}, {"text": "備えたい", "is_correct": false, "explanation": "希望の形。『備えたい、』では文が途切れて後ろの文と結べない。"}], "explanations": {"備えて": "て形。『万一の火事に備えて』と目的を表し、後ろの文に続く。", "備えた": "た形。文を終えてしまい、後ろの「置いた」と続かない。", "備える": "終止形。文を切ってしまい、「各部屋に消火器を置いた」と続かない。", "備えたい": "希望の形。『備えたい、』では文が途切れて後ろの文と結べない。"}, "sentence_index": 6, "correct_answer": "備えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は長年の夢を備え、ついに海外へ旅立った。", "explanation": "ここは〈叶える〉の意味。備えるは前もって用意する意味で、夢を実現する意味では使わない。"}, {"text": "二人は固い約束を備えて、別れた。", "explanation": "ここは〈結ぶ〉の意味。備えるは用意しておく意味で、約束を交わす意味では使わない。"}, {"text": "彼は新しい生活へ向けて、大きな借金を備えた。", "explanation": "ここは〈抱える〉の意味。備えるは用意しておく意味や自然に持つ状態を指すので、借金を背負う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年の大会を備えて、選手たちは毎日走り込んでいる。", "corrected_sentence": "来年の大会に備えて、選手たちは毎日走り込んでいる。", "error_description": "『備えて』は『〜に備える』の形で、対象は『に』で示す。『を』は誤りで、正しくは『大会に備えて』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "備え", "is_correct": true, "explanation": "連用形。『面接に備え、』と後ろへ続く形。"}, {"text": "備えさせ", "is_correct": false, "explanation": "使役の連用形。人に準備させる意味になり、自分が準備した文意に合わない。"}, {"text": "備えない", "is_correct": false, "explanation": "否定形。『面接に備えない』となり、文の内容と逆になる。"}, {"text": "備えよう", "is_correct": false, "explanation": "意志形。『〜しよう』の意味になり、事実の報告として続かない。"}], "correct_form": "備え", "base_form": "備える", "form_label": "連用形", "sentence_index": 1, "explanations": {"備え": "連用形。『面接に備え、』と後ろへ続く形。", "備えさせ": "使役の連用形。人に準備させる意味になり、自分が準備した文意に合わない。", "備えない": "否定形。『面接に備えない』となり、文の内容と逆になる。", "備えよう": "意志形。『〜しよう』の意味になり、事実の報告として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52465, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の遠足を備えて、子どもたちは毎日体力をつけている。", "corrected_sentence": "来週の遠足に備えて、子どもたちは毎日体力をつけている。", "error_description": "助詞の誤り。「備えて」の対象は〈に〉で示すので、〈を〉は誤り。正しくは「遠足に備えて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "備え", "is_correct": true, "explanation": "連用形。『病気に備え、』と後ろへ続く形。"}, {"text": "備えた", "is_correct": false, "explanation": "た形。文を終えてしまい、「持っていった」と続かない。"}, {"text": "備えられ", "is_correct": false, "explanation": "受身の連用形。『病気に備えられ』では主語と動作が合わない。"}, {"text": "備える", "is_correct": false, "explanation": "終止形。文を切ってしまい、「常備薬を持っていった」と続かない。"}], "correct_form": "備え", "base_form": "備える", "form_label": "連用形", "sentence_index": 7, "explanations": {"備え": "連用形。『病気に備え、』と後ろへ続く形。", "備えた": "た形。文を終えてしまい、「持っていった」と続かない。", "備えられ": "受身の連用形。『病気に備えられ』では主語と動作が合わない。", "備える": "終止形。文を切ってしまい、「常備薬を持っていった」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "『庭へ駆け出した』の『へ』。走っていく向きを示す。"}, {"text": "の", "is_correct": false, "explanation": "連体の『の』で、『庭の駆け出した』は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』で、『庭と駆け出した』は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。『子どもたちは庭が駆け出した』では意味が通らない。"}], "correct_answer": "へ", "explanations": {"へ": "『庭へ駆け出した』の『へ』。走っていく向きを示す。", "の": "連体の『の』で、『庭の駆け出した』は文が成り立たない。", "と": "並列の『と』で、『庭と駆け出した』は文が成り立たない。", "が": "主語の格。『子どもたちは庭が駆け出した』では意味が通らない。"}, "error_tags": {"の": "連体（誤り）", "と": "並列（誤り）", "が": "主語（誤り）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "『外へ駆け出した』の『へ』。走っていく向きを示す。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示す形式的な格で、『外より駆け出した』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の『の』で、『外の駆け出した』は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。『外が駆け出した』は主語にならず不自然。"}], "correct_answer": "へ", "explanations": {"へ": "『外へ駆け出した』の『へ』。走っていく向きを示す。", "より": "比較や起点を示す形式的な格で、『外より駆け出した』は不自然。", "の": "連体の『の』で、『外の駆け出した』は文が成り立たない。", "が": "主語の格。『外が駆け出した』は主語にならず不自然。"}, "error_tags": {"より": "比較・起点（誤り）", "の": "連体（誤り）", "が": "主語（誤り）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "急いで外へ走り出すこと。", "primary_collocate": null, "pronunciation": "かけだす", "ipa": "kakedasɯ", "syllable_count": 4, "sentences": [{"text": "地震が起きて、みんなが急いで外へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "じしんがおきて、みんながいそいでそとへかけだした。", "sentence_source": "generated"}, {"text": "雪が降り始めると、子どもたちは庭へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "ゆきがふりはじめると、こどもたちはにわへかけだした。", "sentence_source": "generated"}, {"text": "玄関のベルが鳴ったので、妹は外へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "げんかんのべるがなったので、いもうとはそとへかけだした。", "sentence_source": "generated"}, {"text": "火事の知らせを聞いて、住民たちは通りへ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "かじのしらせをきいて、じゅうみんたちはとおりへかけだした。", "sentence_source": "generated"}, {"text": "授業が終わると、生徒たちは教室から校庭へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "じゅぎょうがおわると、せいとたちはきょうしつからこうていへかけだした。", "sentence_source": "generated"}, {"text": "彼は傘も持たずに、雨の中へ駆け出していった。", "target_word": "駆け出して", "complexity_tier": "T3", "furigana": "かれはかさももたずに、あめのなかへかけだしていった。", "sentence_source": "generated"}, {"text": "花火の音が聞こえ、家族みんなが外へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "はなびのおとがきこえ、かぞくみんながそとへかけだした。", "sentence_source": "generated"}, {"text": "猫が逃げたので、兄はサンダルのまま外へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "ねこがにげたので、あにはさんだるのままそとへかけだした。", "sentence_source": "generated"}, {"text": "雪景色に気づいた娘は、パジャマのまま外に駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "ゆきげしきにきづいたむすめは、ぱじゃまのままそとにかけだした。", "sentence_source": "generated"}, {"text": "忘れ物を届けようと、父は外へ駆け出して行った。", "target_word": "駆け出して", "complexity_tier": "T3", "furigana": "わすれものをとどけようと、ちちはそとへかけだしていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆け出す", "label": "終止形"}, {"form": "駆け出し", "label": "連用形"}, {"form": "駆け出した", "label": "過去形"}, {"form": "駆け出して", "label": "て形"}, {"form": "駆け出さない", "label": "否定形"}, {"form": "駆け出そう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "屋内から急いで外へ走って出ていく動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。『急いで外へ駆け出した』で文を終え、事実を述べる。"}, {"text": "駆け出して", "is_correct": false, "explanation": "て形。文末で止まり、『〜した。』の文として成り立たない。"}, {"text": "駆け出そう", "is_correct": false, "explanation": "意志形。『〜しよう』の意味になり、事実の報告にならない。"}, {"text": "駆け出せ", "is_correct": false, "explanation": "命令形。命令の意味になり、『〜した。』の文と結べない。"}], "explanations": {"駆け出した": "過去形。『急いで外へ駆け出した』で文を終え、事実を述べる。", "駆け出して": "て形。文末で止まり、『〜した。』の文として成り立たない。", "駆け出そう": "意志形。『〜しよう』の意味になり、事実の報告にならない。", "駆け出せ": "命令形。命令の意味になり、『〜した。』の文と結べない。"}, "sentence_index": 0, "correct_answer": "駆け出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泥棒は窓から、物音も立てずに家の中へ駆け出した。", "explanation": "ここは〈忍び込む〉の意味。駆け出すは勢いよく走る動きなので、物音を立てず静かに入る意味では使わない。"}, {"text": "家族は夕方、ゆっくりと通りへ駆け出した。", "explanation": "ここは〈散歩する〉の意味。駆け出すは急いで走り出す動きで、ゆっくり歩く意味では使わない。"}, {"text": "住民たちは火事の知らせを聞いて、そっと通りへ駆け出した。", "explanation": "ここは〈そっと抜け出す〉の意味。駆け出すは勢いよく走る動きで、人目を忍ぶ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。『家族みんなが外へ駆け出した』で文を終え、事実を述べる。"}, {"text": "駆け出しても", "is_correct": false, "explanation": "〜ても形。主節がないため、文が成り立たない。"}, {"text": "駆け出せば", "is_correct": false, "explanation": "仮定形。主節がないため、『〜た。』の文と結べない。"}, {"text": "駆け出しつつ", "is_correct": false, "explanation": "〜つつ形。『〜しつつ』で文が途切れ、『〜た。』と結べない。"}], "explanations": {"駆け出した": "過去形。『家族みんなが外へ駆け出した』で文を終え、事実を述べる。", "駆け出しても": "〜ても形。主節がないため、文が成り立たない。", "駆け出せば": "仮定形。主節がないため、『〜た。』の文と結べない。", "駆け出しつつ": "〜つつ形。『〜しつつ』で文が途切れ、『〜た。』と結べない。"}, "sentence_index": 6, "correct_answer": "駆け出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は忘れ物を届けようと、三時間ずっと外へ駆け出して行った。", "explanation": "ここは〈走り続ける〉の意味。駆け出すは急に走り始める動きで、長く走り続ける意味では使わない。"}, {"text": "父は忘れ物を届けようと、外へ駆け出すように遺言を残した。", "explanation": "ここは〈遺言を残す〉の意味。駆け出すは走り出す動作で、言葉を後に残す意味では使わない。"}, {"text": "忘れ物は父の手元へ駆け出して行った。", "explanation": "ここは〈届く〉の意味。駆け出すは人や動物の動作を表し、物が主語になって走る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花火が上がると、子どもたちは庭の駆け出した。", "corrected_sentence": "花火が上がると、子どもたちは庭へ駆け出した。", "error_description": "『駆け出した』は向きを示す『へ』をとる。『の』では連体の働きになり、文が成り立たない。正しくは『庭へ駆け出した』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。『子どもたちは庭へ駆け出した』と、出来事を過去として述べる形。"}, {"text": "駆け出して", "is_correct": false, "explanation": "て形。『庭へ駆け出して』では文が終わらず、述語として成り立たない。"}, {"text": "駆け出さない", "is_correct": false, "explanation": "否定形。走らなかったという逆の意味になる。"}, {"text": "駆け出そう", "is_correct": false, "explanation": "意志形。『〜しよう』の意味になり、事実の報告にならない。"}], "correct_form": "駆け出した", "base_form": "駆け出す", "form_label": "過去形", "sentence_index": 1, "explanations": {"駆け出した": "過去形。『子どもたちは庭へ駆け出した』と、出来事を過去として述べる形。", "駆け出して": "て形。『庭へ駆け出して』では文が終わらず、述語として成り立たない。", "駆け出さない": "否定形。走らなかったという逆の意味になる。", "駆け出そう": "意志形。『〜しよう』の意味になり、事実の報告にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花火の音が聞こえると、家族みんなが外へ駆け出して。", "corrected_sentence": "花火の音が聞こえると、家族みんなが外へ駆け出した。", "error_description": "文末を『駆け出して』で終えるのは誤り。文を終えるには過去形『駆け出した』が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。『兄はサンダルのまま外へ駆け出した』と、出来事を過去として述べる形。"}, {"text": "駆け出さず", "is_correct": false, "explanation": "ず形。文末にならず、『〜した。』の文と結べない。"}, {"text": "駆け出し", "is_correct": false, "explanation": "連用形。『駆け出し、』と続く形で、文末の述語にならない。"}, {"text": "駆け出せ", "is_correct": false, "explanation": "命令形。命令の意味になり、事実の報告にならない。"}], "correct_form": "駆け出した", "base_form": "駆け出す", "form_label": "過去形", "sentence_index": 7, "explanations": {"駆け出した": "過去形。『兄はサンダルのまま外へ駆け出した』と、出来事を過去として述べる形。", "駆け出さず": "ず形。文末にならず、『〜した。』の文と結べない。", "駆け出し": "連用形。『駆け出し、』と続く形で、文末の述語にならない。", "駆け出せ": "命令形。命令の意味になり、事実の報告にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "『公園へ駆け出した』の『へ』。走っていく向きを示す。"}, {"text": "の", "is_correct": false, "explanation": "連体の『の』で、『公園の駆け出した』は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』で、『公園と駆け出した』は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。『公園が駆け出した』では意味が通らない。"}], "correct_answer": "へ", "explanations": {"へ": "『公園へ駆け出した』の『へ』。走っていく向きを示す。", "の": "連体の『の』で、『公園の駆け出した』は文が成り立たない。", "と": "並列の『と』で、『公園と駆け出した』は文が成り立たない。", "が": "主語の格。『公園が駆け出した』では意味が通らない。"}, "error_tags": {"の": "連体（誤り）", "と": "並列（誤り）", "が": "主語（誤り）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをしようとして、急に走り始めること。", "primary_collocate": null, "pronunciation": "かけだす", "ipa": "kakedasɯ", "syllable_count": 4, "sentences": [{"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "駆け出して", "complexity_tier": "T3", "furigana": "かれつなかんぷうがほおをうつそとのせかいへと、むくなこうきしんをたずさえてかけだしていくそのせなかには、にんげんがほんらいそなえている、かこくなかんきょうをもたのしみへとへんぼうさせるたくましさがぎょうしゅくされていたのである。", "sentence_source": "mined"}, {"text": "雨がやんだので、子どもたちは公園へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "あめがやんだので、こどもたちはこうえんへかけだした。", "sentence_source": "generated"}, {"text": "友達の姿を見つけて、彼女は改札の方へ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "ともだちのすがたをみつけて、かのじょはかいさつのほうへかけだした。", "sentence_source": "generated"}, {"text": "犬は飼い主の声を聞くと、うれしそうに駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "いぬはかいぬしのこえをきくと、うれしそうにかけだした。", "sentence_source": "generated"}, {"text": "ゴールが見えたとたん、選手は最後の力で駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "ごーるがみえたとたん、せんしゅはさいごのちからでかけだした。", "sentence_source": "generated"}, {"text": "電車が来る音がして、私はホームへ駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "でんしゃがくるおとがして、わたしはほーむへかけだした。", "sentence_source": "generated"}, {"text": "スタートの合図と同時に、全員が一斉に駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "すたーとのあいずとどうじに、ぜんいんがいっせいにかけだした。", "sentence_source": "generated"}, {"text": "母に手を振って、少年は元気よく駆け出して行った。", "target_word": "駆け出して", "complexity_tier": "T3", "furigana": "ははにてをふって、しょうねんはげんきよくかけだしていった。", "sentence_source": "generated"}, {"text": "駆け出そうとした瞬間、後ろから名前を呼ばれた。", "target_word": "駆け出そう", "complexity_tier": "T3", "furigana": "かけだそうとしたしゅんかん、うしろからなまえをよばれた。", "sentence_source": "generated"}, {"text": "財布を忘れたことに気づき、彼は家へ向かって駆け出した。", "target_word": "駆け出した", "complexity_tier": "T3", "furigana": "さいふをわすれたことにきづき、かれはいえへむかってかけだした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆け出す", "label": "終止形"}, {"form": "駆け出し", "label": "連用形"}, {"form": "駆け出した", "label": "過去形"}, {"form": "駆け出して", "label": "て形"}, {"form": "駆け出さない", "label": "否定形"}, {"form": "駆け出そう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "何かの目的のために急に走り始める動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆け出して", "is_correct": true, "explanation": "て形。『駆け出していく』の『て』で、後ろの『いく』へ続く。"}, {"text": "駆け出せ", "is_correct": false, "explanation": "命令形。『携えて駆け出せいく』となり、文が成り立たない。"}, {"text": "駆け出そう", "is_correct": false, "explanation": "意志形。『駆け出そういく』となり、関係節が成り立たない。"}, {"text": "駆け出さない", "is_correct": false, "explanation": "否定形。『駆け出さないいく』となり、文が成り立たない。"}], "explanations": {"駆け出して": "て形。『駆け出していく』の『て』で、後ろの『いく』へ続く。", "駆け出せ": "命令形。『携えて駆け出せいく』となり、文が成り立たない。", "駆け出そう": "意志形。『駆け出そういく』となり、関係節が成り立たない。", "駆け出さない": "否定形。『駆け出さないいく』となり、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "駆け出して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人は杖をつき、ゆっくりと公園へ駆け出した。", "explanation": "ここは〈歩き出す〉の意味。駆け出すは急いで走り出す動きなので、杖をついてゆっくり進む動きには合わない。"}, {"text": "彼は夢の実現に向けて、ついに長いあくびとともに駆け出した。", "explanation": "ここは〈気だるく歩き出す〉の意味。駆け出すは急に走り始める動きで、だらだらと動き出す様子には合わない。"}, {"text": "彼は駅の階段を、一段ずつ駆け出した。", "explanation": "ここは〈上る〉の意味。駆け出すは急に走り始める動きで、一段ずつ進む様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。『一斉に駆け出した』で文を終え、事実を述べる。"}, {"text": "駆け出して", "is_correct": false, "explanation": "て形。文末で止まり、『〜した。』の文として成り立たない。"}, {"text": "駆け出しても", "is_correct": false, "explanation": "〜ても形。主節がないため、文が成り立たない。"}, {"text": "駆け出せば", "is_correct": false, "explanation": "仮定形。主節がないため、『〜た。』の文と結べない。"}], "explanations": {"駆け出した": "過去形。『一斉に駆け出した』で文を終え、事実を述べる。", "駆け出して": "て形。文末で止まり、『〜した。』の文として成り立たない。", "駆け出しても": "〜ても形。主節がないため、文が成り立たない。", "駆け出せば": "仮定形。主節がないため、『〜た。』の文と結べない。"}, "sentence_index": 6, "correct_answer": "駆け出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は朝から三時間、駆け出した。", "explanation": "ここは〈走り続ける〉の意味。駆け出すは急に走り始める動きなので、長く走り続ける意味では使わない。"}, {"text": "彼は宿題の途中で、眠りへ駆け出した。", "explanation": "ここは〈寝入る〉の意味。駆け出すは急に走り始める動きで、眠りに落ちる意味では使わない。"}, {"text": "彼は急いで、しゃがみ込んだまま駆け出した。", "explanation": "ここは〈しゃがむ〉の意味。駆け出すは立って走り出す動作で、しゃがんだ姿勢のまま動く意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨がやむと、子どもたちは庭へ駆け出して。", "corrected_sentence": "雨がやむと、子どもたちは庭へ駆け出した。", "error_description": "文末を『駆け出して』で終えるのは誤り。文を終えるには過去形の『駆け出した』が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "駆け出した", "is_correct": true, "explanation": "過去形。雨がやんだ後の出来事を報告する形。"}, {"text": "駆け出さず", "is_correct": false, "explanation": "ず形。文末にならず、『〜した。』の文と結べない。"}, {"text": "駆け出さない", "is_correct": false, "explanation": "否定形。走らなかったという逆の意味になる。"}, {"text": "駆け出そう", "is_correct": false, "explanation": "意志形。『〜しよう』の意味になり、事実の報告にならない。"}], "correct_form": "駆け出した", "base_form": "駆け出す", "form_label": "過去形", "sentence_index": 1, "explanations": {"駆け出した": "過去形。雨がやんだ後の出来事を報告する形。", "駆け出さず": "ず形。文末にならず、『〜した。』の文と結べない。", "駆け出さない": "否定形。走らなかったという逆の意味になる。", "駆け出そう": "意志形。『〜しよう』の意味になり、事実の報告にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52468, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コンサートの合図で、観客は一斉にステージへ駆け出し。", "corrected_sentence": "コンサートの合図で、観客は一斉にステージへ駆け出した。", "error_description": "連用形『駆け出し』で文を終えるのは誤り。文を終えるには過去形『駆け出した』が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "駆け出して", "is_correct": true, "explanation": "て形。『元気よく駆け出して行った』の『て』で、後ろの『行った』へ続く。"}, {"text": "駆け出した", "is_correct": false, "explanation": "過去形。『駆け出した行った』となり、文が成り立たない。"}, {"text": "駆け出せ", "is_correct": false, "explanation": "命令形。命令の意味になり、『行った』と続かない。"}, {"text": "駆け出しても", "is_correct": false, "explanation": "〜ても形。『〜ても行った』と主節が成り立たず、文意が合わない。"}], "correct_form": "駆け出して", "base_form": "駆け出す", "form_label": "て形", "sentence_index": 7, "explanations": {"駆け出して": "て形。『元気よく駆け出して行った』の『て』で、後ろの『行った』へ続く。", "駆け出した": "過去形。『駆け出した行った』となり、文が成り立たない。", "駆け出せ": "命令形。命令の意味になり、『行った』と続かない。", "駆け出しても": "〜ても形。『〜ても行った』と主節が成り立たず、文意が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「再開発で」は変貌の原因や手段を表す「で」で、この文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「変貌」は目的語を取らない語なので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列を表すが、ここでは並べる働きがないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「再開発へ大きく変貌」では原因や手段が示せず合わない。"}], "correct_answer": "で", "explanations": {"で": "「再開発で」は変貌の原因や手段を表す「で」で、この文に合う。", "を": "「変貌」は目的語を取らない語なので、「を」は合わない。", "と": "「と」は引用や並列を表すが、ここでは並べる働きがないので合わない。", "へ": "「へ」は方向を表すので、「再開発へ大きく変貌」では原因や手段が示せず合わない。"}, "error_tags": {"を": "目的語（変貌は他動詞ではないので「を」は合わない）", "と": "引用・並列（ここでは並べる働きがない）", "へ": "方向（「再開発へ大きく変貌」は手段を示せず意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "形や様子がすっかり変わってしまうこと。", "primary_collocate": null, "pronunciation": "へんぼう", "ipa": "hembo̞ː", "syllable_count": 4, "sentences": [{"text": "十年ぶりに訪れた町は、すっかり変貌していた。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "十年[じゅうねん]ぶりに訪[おとず]れた町[まち]は、すっかり変貌[へんぼう]していた。", "sentence_source": "generated"}, {"text": "駅前の商店街は再開発で大きく変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の商店街[しょうてんがい]は再開発[さいかいはつ]で大[おお]きく変貌[へんぼう]した。", "sentence_source": "generated"}, {"text": "静かだった漁村が観光地へと変貌を遂げた。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "静[しず]かだった漁村[ぎょそん]が観光地[かんこうち]へと変貌[へんぼう]を遂[と]げた。", "sentence_source": "generated"}, {"text": "久しぶりに会った友人の変貌に驚いた。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに会[あ]った友人[ゆうじん]の変貌[へんぼう]に驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "工場の跡地は、緑豊かな公園に変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "工場[こうじょう]の跡地[あとち]は、緑豊[みどりゆた]かな公園[こうえん]に変貌[へんぼう]した。", "sentence_source": "generated"}, {"text": "戦争によって、国の姿は大きく変貌してしまった。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "戦争[せんそう]によって、国[くに]の姿[すがた]は大[おお]きく変貌[へんぼう]してしまった。", "sentence_source": "generated"}, {"text": "森だった場所が、数年で住宅地に変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "森[もり]だった場所[ばしょ]が、数年[すうねん]で住宅地[じゅうたくち]に変貌[へんぼう]した。", "sentence_source": "generated"}, {"text": "彼は優しい父親から厳しい指導者へと変貌した。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "彼[かれ]は優[やさ]しい父親[ちちおや]から厳[きび]しい指導者[しどうしゃ]へと変貌[へんぼう]した。", "sentence_source": "generated"}, {"text": "災害のあと、村の風景は変貌し、昔の面影はなかった。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "災害[さいがい]のあと、村[むら]の風景[ふうけい]は変貌[へんぼう]し、昔[むかし]の面影[おもかげ]はなかった。", "sentence_source": "generated"}, {"text": "写真を見比べると、この都市の変貌がよくわかる。", "target_word": "変貌", "complexity_tier": "T3", "furigana": "写真[しゃしん]を見比[みくら]べると、この都市[とし]の変貌[へんぼう]がよくわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変貌", "label": "基本形"}, {"form": "変貌する", "label": "する動詞形"}, {"form": "変貌した", "label": "過去形"}, {"form": "変貌して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "形や様子が以前とはすっかり違うものになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変貌", "is_correct": true, "explanation": "「変貌」は形や様子がすっかり変わることで、町の変化を述べる文に合う。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解」は相手や事柄を取り違えることで、町の様子が変わる文には合わない。"}, {"text": "暗記", "is_correct": false, "explanation": "「暗記」は内容を覚えることで、町の様子を主語にしても意味が通らない。"}, {"text": "辞退", "is_correct": false, "explanation": "「辞退」は申し出を断ることで、町を主語にする文には使えない。"}], "explanations": {"変貌": "「変貌」は形や様子がすっかり変わることで、町の変化を述べる文に合う。", "誤解": "「誤解」は相手や事柄を取り違えることで、町の様子が変わる文には合わない。", "暗記": "「暗記」は内容を覚えることで、町の様子を主語にしても意味が通らない。", "辞退": "「辞退」は申し出を断ることで、町を主語にする文には使えない。"}, "sentence_index": 0, "correct_answer": "変貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は約束の時間を変貌させて、友達を待たせた。", "explanation": "ここは〈変更〉の意味。時刻を変えることは変更で言い、変貌は形や様子が変わることに使うので合わない。"}, {"text": "熱を加えると、卵のたんぱく質が変貌して固まった。", "explanation": "ここは〈変性〉の意味。たんぱく質などの性質が変わることは変性で言い、変貌は外から見た形や様子の変化に使うので合わない。"}, {"text": "坂道では、ギアを変貌させて楽に登れるようにする。", "explanation": "ここは〈変速〉の意味。ギアを切り替えることは変速で言い、変貌は様子の変化に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変貌", "is_correct": true, "explanation": "「変貌」は森だった場所が住宅地へ大きく変わったという文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は答案などに点数をつけることで、場所の変化には使えない。"}, {"text": "辞任", "is_correct": false, "explanation": "「辞任」は職を辞めることで、場所を主語にする文には合わない。"}, {"text": "監督", "is_correct": false, "explanation": "「監督」は人が指示や管理をすることで、場所が主語の文には合わない。"}], "explanations": {"変貌": "「変貌」は森だった場所が住宅地へ大きく変わったという文に合う。", "採点": "「採点」は答案などに点数をつけることで、場所の変化には使えない。", "辞任": "「辞任」は職を辞めることで、場所を主語にする文には合わない。", "監督": "「監督」は人が指示や管理をすることで、場所が主語の文には合わない。"}, "sentence_index": 6, "correct_answer": "変貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "株価の変貌が激しく、午後には大きく値を戻した。", "explanation": "ここは〈変動〉の意味。相場の上下は変動で言い、変貌は形や様子の大きな変化に使うので合わない。"}, {"text": "このファイルは、形式を変貌させて保存し直した。", "explanation": "ここは〈変換〉の意味。データの形式を別のものに直すことは変換で言い、変貌は合わない。"}, {"text": "夏の暑さで、このジャムは変貌して味が落ちた。", "explanation": "ここは〈変質〉の意味。食品などが質的に悪くなることは変質で言い、変貌は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い商店街が、すっかり変貌ていた。", "corrected_sentence": "古い商店街が、すっかり変貌していた。", "error_description": "「変貌」は「する」を伴う名詞で、過去の状態を表すには「変貌して」の形が必要。「変貌ていた」は「して」が抜けた誤りで、正しくは「変貌していた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52471, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村は、数年で観光地を変貌した。", "corrected_sentence": "この村は、数年で観光地に変貌した。", "error_description": "「変貌」は「〜に変貌する」で結果を表すので、目標を示す助詞は「に」。「を」は他動詞用法の目的語に使うもので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楽しみを、子どもの頃に知った」で、知る対象としての目的語になり文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「楽しみが知った」では楽しみが主語になり、知る主体として意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「楽しみに知った」は時間・方向に続かず、知るという動作と合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾の『の』で、『楽しみの、子どもの頃に知った』は文が続かない。"}], "correct_answer": "を", "explanations": {"を": "「楽しみを、子どもの頃に知った」で、知る対象としての目的語になり文が成り立つ。", "が": "「楽しみが知った」では楽しみが主語になり、知る主体として意味が通らない。", "に": "「楽しみに知った」は時間・方向に続かず、知るという動作と合わない。", "の": "名詞修飾の『の』で、『楽しみの、子どもの頃に知った』は文が続かない。"}, "error_tags": {"が": "主語", "に": "時間", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「楽しみは、頂上の景色だけではない」で、楽しみについて主題を示し文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』で、『楽しみを、景色だけではない』と文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「楽しみへ、景色だけではない」は方向を表すが、文の主題として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「楽しみの、景色だけではない」は名詞修飾の形で、文として続かない。"}], "correct_answer": "は", "explanations": {"は": "「楽しみは、頂上の景色だけではない」で、楽しみについて主題を示し文が成り立つ。", "を": "目的語の『を』で、『楽しみを、景色だけではない』と文が成り立たない。", "へ": "「楽しみへ、景色だけではない」は方向を表すが、文の主題として成り立たない。", "の": "「楽しみの、景色だけではない」は名詞修飾の形で、文として続かない。"}, "error_tags": {"を": "目的語（誤り）", "へ": "方向", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしていて、うれしい気持ちになること。", "primary_collocate": null, "pronunciation": "たのしみ", "ipa": "tanoɕimi", "syllable_count": 4, "sentences": [{"text": "毎朝の散歩が、祖父の何よりの楽しみだ。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "まいあさのさんぽが、そふのなによりのたのしみだ。", "sentence_source": "generated"}, {"text": "絵を描く楽しみを、子どもの頃に知った。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "えをかくたのしみを、こどものころにしった。", "sentence_source": "generated"}, {"text": "釣りの楽しみは、魚を待つ時間にあると父は言う。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "つりのたのしみは、さかなをまつじかんにあるとちちはいう。", "sentence_source": "generated"}, {"text": "友達と話す楽しみがあるから、学校は嫌いではない。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "ともだちとはなすたのしみがあるから、がっこうはきらいではない。", "sentence_source": "generated"}, {"text": "本を読む楽しみは、時間を忘れさせてくれることだ。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "ほんをよむたのしみは、じかんをわすれさせてくれることだ。", "sentence_source": "generated"}, {"text": "料理を作る楽しみを、母は私に教えてくれた。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "りょうりをつくるたのしみを、はははわたしにおしえてくれた。", "sentence_source": "generated"}, {"text": "年を取ってからは、孫と遊ぶことが唯一の楽しみになった。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "としをとってからは、まごとあそぶことがゆいいつのたのしみになった。", "sentence_source": "generated"}, {"text": "山に登る楽しみは、頂上の景色だけではない。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "やまにのぼるたのしみは、ちょうじょうのけしきだけではない。", "sentence_source": "generated"}, {"text": "彼は仕事の合間に、短い詩を書く楽しみを見つけた。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "かれはしごとのあいまに、みじかいしをかくたのしみをみつけた。", "sentence_source": "generated"}, {"text": "旅をする楽しみは、知らない町を歩くことにある。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "たびをするたのしみは、しらないまちをあるくことにある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しみ", "label": "基本形"}, {"form": "楽しみは", "label": "は格"}, {"form": "楽しみが", "label": "が格"}, {"form": "楽しみに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "何かをする中で味わうよろこびや満足感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しみ", "is_correct": true, "explanation": "「何よりの楽しみだ」で、散歩が祖父にとって大きなよろこびだという意味に合う。"}, {"text": "鎧", "is_correct": false, "explanation": "「祖父の何よりの鎧だ」は意味をなさず、散歩の位置づけとして成立しない。"}, {"text": "石", "is_correct": false, "explanation": "「祖父の何よりの石だ」は意味が通らず、散歩の話題に合わない。"}, {"text": "粘土", "is_correct": false, "explanation": "「祖父の何よりの粘土だ」は不自然で、散歩を表す文脈に入らない。"}], "explanations": {"楽しみ": "「何よりの楽しみだ」で、散歩が祖父にとって大きなよろこびだという意味に合う。", "鎧": "「祖父の何よりの鎧だ」は意味をなさず、散歩の位置づけとして成立しない。", "石": "「祖父の何よりの石だ」は意味が通らず、散歩の話題に合わない。", "粘土": "「祖父の何よりの粘土だ」は不自然で、散歩を表す文脈に入らない。"}, "sentence_index": 0, "correct_answer": "楽しみ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父の入院を知らせる電話に、楽しみを感じた。", "explanation": "ここは〈心配〉の意味。入院の知らせは楽しみの対象にならず、この言葉は使わない。"}, {"text": "仕事への楽しみを上司にぶつけた。", "explanation": "ここは〈不満〉の意味。楽しみは不満をぶつける対象として使えず、この言葉は使わない。"}, {"text": "監督は新人の彼に、大きな楽しみをかけた。", "explanation": "ここは〈期待〉の意味。人に期待をかけるとは言うが、「楽しみ」はかけるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しみ", "is_correct": true, "explanation": "「唯一の楽しみになった」で、孫と遊ぶことがよろこびの源になったという意味に合う。"}, {"text": "枕", "is_correct": false, "explanation": "「唯一の枕になった」は意味が通らず、孫と遊ぶことの説明にならない。"}, {"text": "扇子", "is_correct": false, "explanation": "「唯一の扇子になった」は不自然で、遊ぶことの位置づけとして合わない。"}, {"text": "傘", "is_correct": false, "explanation": "「唯一の傘になった」は文脈に合わず、遊ぶことの説明として成り立たない。"}], "explanations": {"楽しみ": "「唯一の楽しみになった」で、孫と遊ぶことがよろこびの源になったという意味に合う。", "枕": "「唯一の枕になった」は意味が通らず、孫と遊ぶことの説明にならない。", "扇子": "「唯一の扇子になった」は不自然で、遊ぶことの位置づけとして合わない。", "傘": "「唯一の傘になった」は文脈に合わず、遊ぶことの説明として成り立たない。"}, "sentence_index": 6, "correct_answer": "楽しみ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理不尽な扱いに楽しみを募らせた。", "explanation": "ここは〈怒り〉の意味。楽しみは不快な扱いに募るものではなく、この言葉は使わない。"}, {"text": "祖父の入院が楽しみで、眠れなかった。", "explanation": "ここは〈心配〉の意味。楽しみは入院のような悪い出来事には使えない。"}, {"text": "試合の負けが楽しみで、涙が出た。", "explanation": "ここは〈悔しさ〉の意味。負けに楽しみを感じるのは文の内容と矛盾し、言葉として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末に仲間と釣りへ行くことが、何よりの楽しみに。", "corrected_sentence": "週末に仲間と釣りへ行くことが、何よりの楽しみだ。", "error_description": "文末の「だ」を「に」にすると文が終わらない。「楽しみだ」の断定の形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52475, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海辺で貝殻を集めることが、家族を楽しみになった。", "corrected_sentence": "海辺で貝殻を集めることが、家族の楽しみになった。", "error_description": "「家族の楽しみ」の「の」を「を」にすると、家族が目的語になり「楽しみになった」と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈が〉は「旅行が楽しみ」の対象を示す格助詞。「楽しみで、夜も眠れない」と続けて理由を述べる。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。「旅行を楽しみで」では名詞に目的語の助詞が付く形になり、対象として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は帰着・対象を示す。「旅行に楽しみで」では楽しみの対象の関係が崩れ、文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。「旅行へ楽しみで」では方向の意味になり、楽しみの対象として合わない。"}], "correct_answer": "が", "explanations": {"が": "〈が〉は「旅行が楽しみ」の対象を示す格助詞。「楽しみで、夜も眠れない」と続けて理由を述べる。", "を": "〈を〉は目的語を示す。「旅行を楽しみで」では名詞に目的語の助詞が付く形になり、対象として成り立たない。", "に": "〈に〉は帰着・対象を示す。「旅行に楽しみで」では楽しみの対象の関係が崩れ、文が続かない。", "へ": "〈へ〉は方向を示す。「旅行へ楽しみで」では方向の意味になり、楽しみの対象として合わない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「楽しみに待っている」で、心待ちにする様子を表し、文の流れに合う。"}, {"text": "と", "is_correct": false, "explanation": "「楽しみと待っている」は並列の形になり、待つ様子の表現として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「楽しみで待っている」は手段・理由の形になり、動詞「待つ」と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「楽しみの待っている」は名詞修飾の形で、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「楽しみに待っている」で、心待ちにする様子を表し、文の流れに合う。", "と": "「楽しみと待っている」は並列の形になり、待つ様子の表現として不自然。", "で": "「楽しみで待っている」は手段・理由の形になり、動詞「待つ」と合わない。", "の": "「楽しみの待っている」は名詞修飾の形で、文として成り立たない。"}, "error_tags": {"と": "並列", "で": "手段", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "楽しみに感じること。心がわくわくする状態や、そう感じさせる事柄。", "primary_collocate": null, "pronunciation": "たのしみ", "ipa": "tanoɕimi", "syllable_count": 4, "sentences": [{"text": "週末に友達と会う日が、今から楽しみだ。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "しゅうまつにともだちとあうひが、いまからたのしみだ。", "sentence_source": "generated"}, {"text": "来週の旅行が楽しみで、夜もなかなか眠れない。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "らいしゅうのりょこうがたのしみで、よるもなかなかねむれない。", "sentence_source": "generated"}, {"text": "祖母に会えるのが、今から楽しみです。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "そぼにあえるのが、いまからたのしみです。", "sentence_source": "generated"}, {"text": "合格発表の日が来るのが、楽しみでたまらない。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "合格[ごうかく]発表[はっぴょう]の日[ひ]が来[く]るのが、楽しみ[たのしみ]でたまらない。", "sentence_source": "generated"}, {"text": "遠足の日が近づき、子どもたちの楽しみは大きくなるばかりだ。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "えんそくのひがちかづき、こどもたちのたのしみはおおきくなるばかりだ。", "sentence_source": "generated"}, {"text": "新しいゲームの発売が楽しみで、毎日カレンダーを見ている。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "あたらしいげーむのはつばいがたのしみで、まいにちかれんだーをみている。", "sentence_source": "generated"}, {"text": "週末の映画を楽しみにして、今週も仕事をがんばった。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "しゅうまつのえいがをたのしみにして、こんしゅうもしごとをがんばった。", "sentence_source": "generated"}, {"text": "誕生日のプレゼントは何だろうと、楽しみに待っている。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "たんじょうびのぷれぜんとはなんだろうと、たのしみにまっている。", "sentence_source": "generated"}, {"text": "新しい職場での生活が、今から楽しみだ。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "新[あたら]しい職場[しょくば]での生活[せいかつ]が、今[いま]から楽しみ[たのしみ]だ。", "sentence_source": "generated"}, {"text": "結果は明日わかるので、楽しみでもあり不安でもある。", "target_word": "楽しみ", "complexity_tier": "T3", "furigana": "けっかはあしたわかるので、たのしみでもありふあんでもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しみ", "label": "基本形"}, {"form": "楽しみに", "label": "に格"}, {"form": "楽しみで", "label": "で形"}, {"form": "楽しみだ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "これから起きることへの期待や、わくわくさせる事柄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6d986c-91f7-4c1f-b925-43719c1007b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しみ", "is_correct": true, "explanation": "「過酷な環境を楽しみへと変貌させる」で、環境を心が弾む対象に変える意味に合う。"}, {"text": "鎧", "is_correct": false, "explanation": "鎧は具体的な防具で、環境を鎧へ変貌させるという抽象的な流れに合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は物質で、人の心の状態へ変わるという文脈に入らない。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は素材で、この文の「変貌」の対象としては意味が通らない。"}], "explanations": {"楽しみ": "「過酷な環境を楽しみへと変貌させる」で、環境を心が弾む対象に変える意味に合う。", "鎧": "鎧は具体的な防具で、環境を鎧へ変貌させるという抽象的な流れに合わない。", "石": "石は物質で、人の心の状態へ変わるという文脈に入らない。", "粘土": "粘土は素材で、この文の「変貌」の対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "楽しみ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父にとって、庭の手入れは今も変わらぬ楽しみだ。", "explanation": "ここは〈趣味・娯楽〉の意味。今の習慣を指し、これから起きることへの期待ではない。"}, {"text": "夕食後の読書が、彼女のささやかな楽しみだ。", "explanation": "ここは〈趣味・娯楽〉の意味。今ある楽しみを指し、未来への期待ではない。"}, {"text": "彼の裏切りを知り、楽しみを抱いて涙を流した。", "explanation": "ここは〈失望〉の意味。裏切られて涙を流す場面では、期待の気持ちを表す「楽しみ」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しみ", "is_correct": true, "explanation": "「楽しみにして」で、映画を心待ちにする意味になり、文の流れに合う。"}, {"text": "鍋", "is_correct": false, "explanation": "「映画を鍋にして」は意味をなさず、映画の対象として成立しない。"}, {"text": "座布団", "is_correct": false, "explanation": "「映画を座布団にして」は意味が通らず、文の流れに合わない。"}, {"text": "箒", "is_correct": false, "explanation": "「映画を箒にして」は意味が通らず、週末の出来事として不自然。"}], "explanations": {"楽しみ": "「楽しみにして」で、映画を心待ちにする意味になり、文の流れに合う。", "鍋": "「映画を鍋にして」は意味をなさず、映画の対象として成立しない。", "座布団": "「映画を座布団にして」は意味が通らず、文の流れに合わない。", "箒": "「映画を箒にして」は意味が通らず、週末の出来事として不自然。"}, "sentence_index": 6, "correct_answer": "楽しみ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの病気が楽しみで、夜も眠れなかった。", "explanation": "ここは〈心配〉の意味。楽しみは病気のような悪い出来事には使えず、「心配で」が正しい。"}, {"text": "失礼な店員に楽しみをぶつけた。", "explanation": "ここは〈怒り〉の意味。楽しみは「ぶつける」とは組み合わず、この言葉は使わない。"}, {"text": "不審者への楽しみを怠らないように言われた。", "explanation": "ここは〈警戒〉の意味。「楽しみ」は警戒心を表す語ではなく、警戒の場面では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "次の試合が今から楽しみを、練習にも力が入る。", "corrected_sentence": "次の試合が今から楽しみで、練習にも力が入る。", "error_description": "「楽しみ」の後ろは「で」で続けるのが正しい。「楽しみを」と目的語の助詞にすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52476, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月の旅行が楽しみの、荷造りを早めに始めた。", "corrected_sentence": "来月の旅行が楽しみで、荷造りを早めに始めた。", "error_description": "「楽しみで」の「で」を「の」にすると名詞修飾の形になり、文が続かない。正しくは「楽しみで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e149b514-d127-46c4-9da1-73ec84b42cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
