INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52477, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校の建物のこと。", "primary_collocate": null, "pronunciation": "こうしゃ", "ipa": "koːɕa", "syllable_count": 3, "sentences": [{"text": "校舎の入り口で、先生が生徒たちにあいさつしている。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "校舎[こうしゃ]の入[い]り口[ぐち]で、先生[せんせい]が生徒[せいと]たちにあいさつしている。", "sentence_source": "generated"}, {"text": "夏休みの間、校舎の窓を全部開けて掃除した。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの間[あいだ]、校舎[こうしゃ]の窓[まど]を全部[ぜんぶ]開[あ]けて掃除[そうじ]した。", "sentence_source": "generated"}, {"text": "駅から校舎までは、歩いて十分ほどかかる。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "駅[えき]から校舎[こうしゃ]までは、歩[ある]いて十分[じゅっぷん]ほどかかる。", "sentence_source": "generated"}, {"text": "新しい校舎には、広い図書室と理科室がある。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "新[あたら]しい校舎[こうしゃ]には、広[ひろ]い図書室[としょしつ]と理科室[りかしつ]がある。", "sentence_source": "generated"}, {"text": "台風が来る前に、校舎の窓を閉めて回った。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に、校舎[こうしゃ]の窓[まど]を閉[し]めて回[まわ]った。", "sentence_source": "generated"}, {"text": "校舎の裏には、小さな花壇がある。", "target_word": "校舎", "complexity_tier": "T2", "furigana": "校舎[こうしゃ]の裏[うら]には、小[ちい]さな花壇[かだん]がある。", "sentence_source": "generated"}, {"text": "夜の校舎は暗くて、少し怖い感じがした。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "夜[よる]の校舎[こうしゃ]は暗[くら]くて、少[すこ]し怖[こわ]い感[かん]じがした。", "sentence_source": "generated"}, {"text": "古い木の校舎は、冬になるととても寒い。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の校舎[こうしゃ]は、冬[ふゆ]になるととても寒[さむ]い。", "sentence_source": "generated"}, {"text": "工事のため、東側の校舎はしばらく使えません。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、東側[ひがしがわ]の校舎[こうしゃ]はしばらく使[つか]えません。", "sentence_source": "generated"}, {"text": "私たちの校舎は、山の上にあって景色がいい。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "私[わたし]たちの校舎[こうしゃ]は、山[やま]の上[うえ]にあって景色[けしき]がいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "校舎", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "学校の建物(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52477, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校舎", "is_correct": true, "explanation": "「校舎の入り口」の「校舎」で、学校の建物を指す。正しい。"}, {"text": "洗濯機", "is_correct": false, "explanation": "「洗濯機の入り口で先生があいさつする」は成り立たず、場所として不自然。"}, {"text": "切符", "is_correct": false, "explanation": "切符に入り口はなく、先生が生徒にあいさつする場所として合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶の入り口は存在せず、文の場所として不自然。"}], "explanations": {"校舎": "「校舎の入り口」の「校舎」で、学校の建物を指す。正しい。", "洗濯機": "「洗濯機の入り口で先生があいさつする」は成り立たず、場所として不自然。", "切符": "切符に入り口はなく、先生が生徒にあいさつする場所として合わない。", "花瓶": "花瓶の入り口は存在せず、文の場所として不自然。"}, "sentence_index": 0, "correct_answer": "校舎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休み、妹は校舎で髪を切った。", "explanation": "ここは〈美容院〉の意味。髪を切るのは美容院で、学校の建物の校舎には合わない。"}, {"text": "昼休み、生徒たちは校舎で鬼ごっこをした。", "explanation": "ここは〈校庭〉の意味。鬼ごっこをする場所は校庭で、建物の校舎には合わない。"}, {"text": "彼女は来春、この校舎に入学する。", "explanation": "ここは〈学校〉の意味。入学するのは学校で、建物の校舎には入学できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52477, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校舎", "is_correct": true, "explanation": "「夜の校舎は暗くて」の「校舎」で、学校の建物を指す。正しい。"}, {"text": "鍋", "is_correct": false, "explanation": "「夜の鍋は暗くて、少し怖い感じがした」は成り立たず、主語として不自然。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は暗くて怖いと感じる対象として文脈に合わない。"}, {"text": "座椅子", "is_correct": false, "explanation": "「夜の座椅子」は場所を表さず、暗くて怖い感じの主語として合わない。"}], "explanations": {"校舎": "「夜の校舎は暗くて」の「校舎」で、学校の建物を指す。正しい。", "鍋": "「夜の鍋は暗くて、少し怖い感じがした」は成り立たず、主語として不自然。", "手袋": "手袋は暗くて怖いと感じる対象として文脈に合わない。", "座椅子": "「夜の座椅子」は場所を表さず、暗くて怖い感じの主語として合わない。"}, "sentence_index": 6, "correct_answer": "校舎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は、校舎の窓口で住民票を取った。", "explanation": "ここは〈役所〉の意味。住民票を取るのは役所で、学校の建物の校舎には合わない。"}, {"text": "夏の午後、生徒たちは校舎で泳ぎを練習した。", "explanation": "ここは〈プール〉の意味。泳ぎの練習をする場所はプールで、建物の校舎には合わない。"}, {"text": "雨の日は、校舎で卓球の大会を開いた。", "explanation": "ここは〈体育館〉の意味。卓球の大会を開く場所は体育館で、校舎は建物全体を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52477, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晴れた日は、校舎を窓から運動場がよく見える。", "corrected_sentence": "晴れた日は、校舎の窓から運動場がよく見える。", "error_description": "「校舎の窓」は所有を示す「の」が必要。「校舎を窓」と「を」を使うと誤り。正しくは「校舎の窓から」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52477, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校舎は台風のあとに塗り直しられた。", "corrected_sentence": "校舎は台風のあとに塗り直された。", "error_description": "「塗り直す」の受身は「塗り直される」で、過去は「塗り直された」。「塗り直しられた」は誤った受身形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
