INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52478, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校の建物。校舎は、授業や活動が行われる建物です。", "primary_collocate": null, "pronunciation": "こうしゃ", "ipa": "koːɕa", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "校舎", "complexity_tier": "T4", "furigana": "未知[みち]の空間[くうかん]たる新校舎[しんこうしゃ]の扉[とびら]をくぐる娘[むすめ]の背中[せなか]には、微[かす]かな緊張[きんちょう]と、それをはるかに上回[うわまわ]る好奇心[こうきしん]が漲[みなぎ]っていた。", "sentence_source": "mined"}, {"text": "古い校舎は来年取り壊されて、新しい建物になる。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "古[ふる]い校舎[こうしゃ]は来年[らいねん]取[と]り壊[こわ]されて、新[あたら]しい建物[たてもの]になる。", "sentence_source": "generated"}, {"text": "雨の日は、校舎の中で昼休みを過ごした。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、校舎[こうしゃ]の中[なか]で昼休[ひるやす]みを過[す]ごした。", "sentence_source": "generated"}, {"text": "校舎の屋上から、町の景色がよく見える。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "校舎[こうしゃ]の屋上[おくじょう]から、町[まち]の景色[けしき]がよく見[み]える。", "sentence_source": "generated"}, {"text": "卒業式の日、私は長い間お世話になった校舎を見上げた。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]の日[ひ]、私[わたし]は長[なが]い間[あいだ]お世話[せわ]になった校舎[こうしゃ]を見上[みあ]げた。", "sentence_source": "generated"}, {"text": "地震に備えて、校舎の壁を強くする工事が行われた。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "地震[じしん]に備[そな]えて、校舎[こうしゃ]の壁[かべ]を強[つよ]くする工事[こうじ]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "放課後の校舎は静かで、ピアノの音だけが聞こえた。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "放課後[ほうかご]の校舎[こうしゃ]は静[しず]かで、ピアノの音[おと]だけが聞[き]こえた。", "sentence_source": "generated"}, {"text": "文化祭の日は、校舎のあちこちに生徒たちの作品が飾られる。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]の日[ひ]は、校舎[こうしゃ]のあちこちに生徒[せいと]たちの作品[さくひん]が飾[かざ]られる。", "sentence_source": "generated"}, {"text": "この学校には校舎が三つあり、一年生は一番新しい校舎で学ぶ。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "この学校[がっこう]には校舎[こうしゃ]が三[みっ]つあり、一年生[いちねんせい]は一番[いちばん]新[あたら]しい校舎[こうしゃ]で学[まな]ぶ。", "sentence_source": "generated"}, {"text": "兄が通った校舎を、今は私が毎朝歩いている。", "target_word": "校舎", "complexity_tier": "T3", "furigana": "兄[あに]が通[かよ]った校舎[こうしゃ]を、今[いま]は私[わたし]が毎朝[まいあさ]歩[ある]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "校舎", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "授業や活動が行われる学校の建物(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 漲っ (Zipf 1.92)']::text[], '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校舎", "is_correct": true, "explanation": "「新校舎」の「校舎」で、授業が行われる学校の建物を指す。扉をくぐる文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「新冷蔵庫の扉をくぐる」は成り立たない。冷蔵庫は人がくぐる建物ではない。"}, {"text": "切符", "is_correct": false, "explanation": "切符には扉がなく、「新切符の扉」は意味をなさない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶に扉はなく、人がくぐる対象として合わない。"}], "explanations": {"校舎": "「新校舎」の「校舎」で、授業が行われる学校の建物を指す。扉をくぐる文脈に合う。", "冷蔵庫": "「新冷蔵庫の扉をくぐる」は成り立たない。冷蔵庫は人がくぐる建物ではない。", "切符": "切符には扉がなく、「新切符の扉」は意味をなさない。", "花瓶": "花瓶に扉はなく、人がくぐる対象として合わない。"}, "sentence_index": 0, "correct_answer": "校舎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼休み、友達と校舎でラーメンを注文した。", "explanation": "ここは〈食堂〉の意味。注文して食べるのは食堂で、授業の建物である校舎には合わない。"}, {"text": "昼休み、子どもたちは校舎でサッカーをした。", "explanation": "ここは〈校庭〉の意味。サッカーをする場所は校庭で、建物の校舎には合わない。"}, {"text": "彼は来年、この校舎を卒業する。", "explanation": "ここは〈学校〉の意味。卒業するのは学校の課程で、建物の校舎は卒業の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校舎", "is_correct": true, "explanation": "「放課後の校舎は静かで」の「校舎」で、学校の建物を指す。正しい。"}, {"text": "味噌汁", "is_correct": false, "explanation": "「放課後の味噌汁は静かで」は成り立たず、主語として不自然。"}, {"text": "財布", "is_correct": false, "explanation": "財布は静かだとも音が聞こえる場所だとも言えず、文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "「放課後の座布団」は場所を表さず、ピアノの音が聞こえる文脈に合わない。"}], "explanations": {"校舎": "「放課後の校舎は静かで」の「校舎」で、学校の建物を指す。正しい。", "味噌汁": "「放課後の味噌汁は静かで」は成り立たず、主語として不自然。", "財布": "財布は静かだとも音が聞こえる場所だとも言えず、文脈に合わない。", "座布団": "「放課後の座布団」は場所を表さず、ピアノの音が聞こえる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "校舎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は、校舎の改札で定期券を見せた。", "explanation": "ここは〈駅〉の意味。改札で定期券を見せるのは駅で、学校の建物の校舎には合わない。"}, {"text": "席替えのあと、私は校舎の一番後ろに座った。", "explanation": "ここは〈教室〉の意味。一番後ろの席は部屋の中の位置で、建物全体の校舎には合わない。"}, {"text": "雨の日は、校舎でバスケットボールをした。", "explanation": "ここは〈体育館〉の意味。バスケットボールをする場所は体育館で、校舎は建物全体を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放課後、生徒たちは校舎を裏で話していた。", "corrected_sentence": "放課後、生徒たちは校舎の裏で話していた。", "error_description": "「校舎の裏」は場所を示す「の」が必要。「校舎を裏」と「を」を使うと誤り。正しくは「校舎の裏で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校舎は三年前に建て替えさられた。", "corrected_sentence": "校舎は三年前に建て替えられた。", "error_description": "受身は「建て替えられた」。「さ」を入れた「建て替えさられた」は使役と受身の混同による誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
