INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52479, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの中や下を通って、向こう側に行くこと。", "primary_collocate": null, "pronunciation": "もぐる", "ipa": "mogɯɾɯ", "syllable_count": 3, "sentences": [{"text": "プールで、兄はレーンのロープの下を潜って隣のコースへ出た。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "ぷーるで、あにはれーんのろーぷのしたをもぐってとなりのこーすへでた。", "sentence_source": "generated"}, {"text": "私は息を止めて、ボートの下を潜り、反対側で顔を出した。", "target_word": "潜り", "complexity_tier": "T3", "furigana": "わたしはいきをとめて、ぼーとのしたをもぐり、はんたいがわでかおをだした。", "sentence_source": "generated"}, {"text": "ダイバーは沈んだ船の入り口から潜って、反対側の穴から外へ出た。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "だいばーはしずんだふねのいりぐちからもぐって、はんたいがわのあなからそとへでた。", "sentence_source": "generated"}, {"text": "水が流れ込む洞窟の入り口を潜ると、奥に広い空間がある。", "target_word": "潜ると", "complexity_tier": "T3", "furigana": "みずがながれこむどうくつのいりぐちをもぐると、おくにひろいくうかんがある。", "sentence_source": "generated"}, {"text": "彼女は泳ぎが得意で、浮かぶ丸太の下を潜って向こう岸へ渡った。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "かのじょはおよぎがとくいで、うかぶまるたのしたをもぐってむこうぎしへわたった。", "sentence_source": "generated"}, {"text": "湾の入り口に張られた網の下を潜れば、外の海へ出られる。", "target_word": "潜れば", "complexity_tier": "T3", "furigana": "わんのいりぐちにはられたあみのしたをもぐれば、そとのうみへでられる。", "sentence_source": "generated"}, {"text": "犬は垣根の下を潜って、隣の庭へ入ってしまった。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "いぬはかきねのしたをもぐって、となりのにわへはいってしまった。", "sentence_source": "generated"}, {"text": "岩の下を潜って向こう側に出た瞬間、青い魚の群れが見えた。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "いわのしたをもぐってむこうがわにでたしゅんかん、あおいさかなのむれがみえた。", "sentence_source": "generated"}, {"text": "監視員は、深い所を潜って向こう岸へ行かないよう注意した。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "かんしいんは、ふかいところをもぐってむこうぎしへいかないようちゅういした。", "sentence_source": "generated"}, {"text": "浅い池なので、子どもでも水の中を潜って反対の岸まで行ける。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "あさいいけなので、こどもでもみずのなかをもぐってはんたいのきしまでいける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜る", "label": "辞書形"}, {"form": "潜り", "label": "連用形"}, {"form": "潜って", "label": "て形"}, {"form": "潜った", "label": "過去形"}, {"form": "潜れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物の下や中を通過して反対側へ抜ける動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜って", "is_correct": true, "explanation": "物の下を通って反対側へ抜ける動きを表し、レーンの下を通って隣のコースへ出た文と合う。"}, {"text": "眠って", "is_correct": false, "explanation": "眠っては自動詞で「下を眠って」とは続かず、下を通り抜ける動きに合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "笑っては感情の表出で、「下を笑って」は成り立たず文に合わない。"}, {"text": "座って", "is_correct": false, "explanation": "座ってはその場に腰を下ろす動きで、「下を座って」は文として成り立たない。"}], "explanations": {"潜って": "物の下を通って反対側へ抜ける動きを表し、レーンの下を通って隣のコースへ出た文と合う。", "眠って": "眠っては自動詞で「下を眠って」とは続かず、下を通り抜ける動きに合わない。", "笑って": "笑っては感情の表出で、「下を笑って」は成り立たず文に合わない。", "座って": "座ってはその場に腰を下ろす動きで、「下を座って」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "潜って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "険しい山道を潜ると、頂上に小さな神社がある。", "explanation": "ここは〈登る〉の意味。潜るは物の下や中を通る動きで、山道を上がる意味では使わない。"}, {"text": "鳥は崖の上を潜って、川を越えた。", "explanation": "ここは〈飛ぶ〉の意味。上空を越える動きで、物の下を通り抜ける潜るとは合わない。"}, {"text": "雨粒が道路で潜って、服が濡れた。", "explanation": "ここは〈跳ねる〉の意味。はね返る動きで、潜るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜って", "is_correct": true, "explanation": "垣根の下を通り抜けて隣の庭へ入る動きを表し、文の内容と合う。"}, {"text": "怒って", "is_correct": false, "explanation": "怒っては感情を表し、「垣根の下を怒って」は文として成り立たない。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫んではさけぶ動作で、「垣根の下を叫んで」は文として成り立たない。"}, {"text": "泣いて", "is_correct": false, "explanation": "泣いては感情の表出で、「垣根の下を泣いて」は意味が合わない。"}], "explanations": {"潜って": "垣根の下を通り抜けて隣の庭へ入る動きを表し、文の内容と合う。", "怒って": "怒っては感情を表し、「垣根の下を怒って」は文として成り立たない。", "叫んで": "叫んではさけぶ動作で、「垣根の下を叫んで」は文として成り立たない。", "泣いて": "泣いては感情の表出で、「垣根の下を泣いて」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "潜って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の土を潜って、球根を植えた。", "explanation": "ここは〈掘る〉の意味。土を掘って穴を作る作業で、潜るは使わない。"}, {"text": "重い石が川の底に潜った。", "explanation": "ここは〈沈む〉の意味。水底へ落ちる動きで、石が自分から入るように言う潜るとは合わない。"}, {"text": "夕方、川沿いの道を潜って帰った。", "explanation": "ここは〈歩く〉の意味。道を進む動きで、潜るは道を進む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子犬は塀の下を潜ろう、裏の道へ出て行った。", "corrected_sentence": "子犬は塀の下を潜って、裏の道へ出て行った。", "error_description": "「潜って」が正しい。「潜ろう」は意志を表す形で、過去の出来事を語る文では続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潜り", "is_correct": true, "explanation": "連用形で、文を続けて「反対側で顔を出した」へつなぐことができる。"}, {"text": "潜った", "is_correct": false, "explanation": "過去形で文を言い切ってしまい、後ろの「反対側で顔を出した」と自然につながらない。"}, {"text": "潜ろう", "is_correct": false, "explanation": "意志形で、これから潜る意思を表し、顔を出した過去の行動と合わない。"}, {"text": "潜れ", "is_correct": false, "explanation": "命令形で、文脈に合わない命令になってしまう。"}], "correct_form": "潜り", "base_form": "潜る", "form_label": "連用形", "sentence_index": 1, "explanations": {"潜り": "連用形で、文を続けて「反対側で顔を出した」へつなぐことができる。", "潜った": "過去形で文を言い切ってしまい、後ろの「反対側で顔を出した」と自然につながらない。", "潜ろう": "意志形で、これから潜る意思を表し、顔を出した過去の行動と合わない。", "潜れ": "命令形で、文脈に合わない命令になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは橋の下を潜る、向こう岸へ渡った。", "corrected_sentence": "子どもは橋の下を潜って、向こう岸へ渡った。", "error_description": "「潜って」が正しい。「潜る」は辞書形で、読点の後に過去の動作を続ける文にはつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潜って", "is_correct": true, "explanation": "て形で、「向こう側に出た瞬間」へ続けて動作の流れを表せる。"}, {"text": "潜る", "is_correct": false, "explanation": "辞書形で、後ろの「向こう側に出た瞬間」と続かず文の流れが切れてしまう。"}, {"text": "潜ろう", "is_correct": false, "explanation": "意志形で話し手の決意を表すため、「岩の下を潜ろう向こう側に出た」と続かず、出た瞬間の描写とも合わない。"}, {"text": "潜らない", "is_correct": false, "explanation": "否定形で潜らずに向こう側へ出たことになり、文の内容と矛盾する。"}], "correct_form": "潜って", "base_form": "潜る", "form_label": "て形", "sentence_index": 7, "explanations": {"潜って": "て形で、「向こう側に出た瞬間」へ続けて動作の流れを表せる。", "潜る": "辞書形で、後ろの「向こう側に出た瞬間」と続かず文の流れが切れてしまう。", "潜ろう": "意志形で話し手の決意を表すため、「岩の下を潜ろう向こう側に出た」と続かず、出た瞬間の描写とも合わない。", "潜らない": "否定形で潜らずに向こう側へ出たことになり、文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
