INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52480, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "狭い場所や物の下を通り抜ける。また、水中に入る。", "primary_collocate": null, "pronunciation": "もぐる", "ipa": "mogɯɾɯ", "syllable_count": 3, "sentences": [{"text": "降り積もった雪の気配を避けるように、野良猫は朽ちた納屋の床下へ体ごと潜って、夜明けまで息を殺していた。", "target_word": "潜って", "complexity_tier": "T5", "furigana": "降(ふ)り積(つ)もった雪(ゆき)の気配(けはい)を避(さ)けるように、野良猫(のらねこ)は朽(く)ちた納屋(なや)の床下(ゆかした)へ体(からだ)ごと潜(もぐ)って、夜明(よあ)けまで息(いき)を殺(ころ)していた。", "sentence_source": "generated"}, {"text": "猫が寒い夜に布団の中へ潜って、朝まで出てこなかった。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "ねこがさむいよるにふとんのなかへもぐって、あさまででてこなかった。", "sentence_source": "generated"}, {"text": "海女は息を止めて、海の深くまで潜る。", "target_word": "潜る", "complexity_tier": "T3", "furigana": "あまはいきをとめて、うみのふかくまでもぐる。", "sentence_source": "generated"}, {"text": "子どもたちは夏になると、川で水の中に潜って遊ぶ。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "こどもたちはなつになると、かわでみずのなかにもぐってあそぶ。", "sentence_source": "generated"}, {"text": "雷が鳴ったので、犬は机の下に潜って震えていた。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "かみなりがなったので、いぬはつくえのしたにもぐってふるえていた。", "sentence_source": "generated"}, {"text": "ダイバーは酸素ボンベを背負って、静かな海へ潜った。", "target_word": "潜った", "complexity_tier": "T3", "furigana": "だいばーはさんそぼんべをせおって、しずかなうみへもぐった。", "sentence_source": "generated"}, {"text": "恥ずかしくなった弟は、頭から毛布に潜ってしまった。", "target_word": "潜って", "complexity_tier": "T3", "furigana": "はずかしくなったおとうとは、あたまからもうふにもぐってしまった。", "sentence_source": "generated"}, {"text": "カワウは魚を捕るために、何度も水に潜る。", "target_word": "潜る", "complexity_tier": "T3", "furigana": "かわうはさかなをとるために、なんどもみずにもぐる。", "sentence_source": "generated"}, {"text": "波が高い日は、海に潜るのは危険なので船を出さなかった。", "target_word": "潜る", "complexity_tier": "T3", "furigana": "なみがたかいひは、うみにもぐるのはきけんなのでふねをださなかった。", "sentence_source": "generated"}, {"text": "水が冷たくても、あの子は平気でプールの底まで潜る。", "target_word": "潜る", "complexity_tier": "T3", "furigana": "みずがつめたくても、あのこはへいきでぷーるのそこまでもぐる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜る", "label": "辞書形"}, {"form": "潜って", "label": "て形"}, {"form": "潜った", "label": "過去形"}, {"form": "潜らない", "label": "否定形"}, {"form": "潜れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "水中や物の下・狭い所へ体ごと入り込む動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜って", "is_correct": true, "explanation": "物の下の狭い所へ体ごと入り込む動きを表し、床下へ入る文と合う。"}, {"text": "笑って", "is_correct": false, "explanation": "笑っては感情の表出で、「床下へ体ごと笑って」は動きとして成り立たない。"}, {"text": "歌って", "is_correct": false, "explanation": "歌っては声を出す動作で、床下へ入る動きには合わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫んでは声を上げる動作で、「床下へ体ごと叫んで」は文として成り立たない。"}], "explanations": {"潜って": "物の下の狭い所へ体ごと入り込む動きを表し、床下へ入る文と合う。", "笑って": "笑っては感情の表出で、「床下へ体ごと笑って」は動きとして成り立たない。", "歌って": "歌っては声を出す動作で、床下へ入る動きには合わない。", "叫んで": "叫んでは声を上げる動作で、「床下へ体ごと叫んで」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "潜って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥の群れが、夏になると空高く潜る。", "explanation": "ここは〈飛ぶ〉の意味。潜るは物の下や中へ入る動きで、空を飛ぶ動きには使わない。"}, {"text": "ボールが床で潜って、棚の上まで上がった。", "explanation": "ここは〈弾む〉の意味。床ではね返る動きは弾むで、潜るは使わない。"}, {"text": "子どもたちは夏になると、山の頂上まで潜る。", "explanation": "ここは〈登る〉の意味。潜るは下や中へ入る動きで、山を登る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜って", "is_correct": true, "explanation": "頭から毛布の中に入り込む動きを表し、「毛布に潜ってしまった」と文に合う。"}, {"text": "怒って", "is_correct": false, "explanation": "怒っては感情を表し、「毛布に怒ってしまった」は成り立たない。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫んではさけぶ動作で、「毛布に叫んでしまった」とは続かず文に合わない。"}, {"text": "泣いて", "is_correct": false, "explanation": "泣いては感情の表出で、「毛布に泣いてしまった」は文として成り立たない。"}], "explanations": {"潜って": "頭から毛布の中に入り込む動きを表し、「毛布に潜ってしまった」と文に合う。", "怒って": "怒っては感情を表し、「毛布に怒ってしまった」は成り立たない。", "叫んで": "叫んではさけぶ動作で、「毛布に叫んでしまった」とは続かず文に合わない。", "泣いて": "泣いては感情の表出で、「毛布に泣いてしまった」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "潜って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に井戸を潜って、水をくみ上げた。", "explanation": "ここは〈掘る〉の意味。井戸は掘って作るもので、潜ると言うのは意味が合わない。"}, {"text": "毛糸を玉に潜って、手袋を編んだ。", "explanation": "ここは〈巻く〉の意味。毛糸を丸くまとめる動きで、潜るは使わない。"}, {"text": "洗濯物が夕方には潜った。", "explanation": "ここは〈乾く〉の意味。水分がなくなる変化で、潜るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は池の底まで潜りて、石を拾った。", "corrected_sentence": "兄は池の底まで潜って、石を拾った。", "error_description": "「潜る」のて形は「潜って」。「潜りて」は誤った活用で、正しくは「潜って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潜って", "is_correct": true, "explanation": "て形で、「朝まで出てこなかった」へ続けることができる。"}, {"text": "潜った", "is_correct": false, "explanation": "過去形で文を言い切ってしまい、後ろの「朝まで出てこなかった」と続かない。"}, {"text": "潜らない", "is_correct": false, "explanation": "否定形で布団に潜ったという事実と矛盾し、後ろの節とも続かない。"}, {"text": "潜ろう", "is_correct": false, "explanation": "意志形で猫の意思を表すため、「布団の中へ潜ろう、朝まで出てこなかった」と結果の文が続かない。"}], "correct_form": "潜って", "base_form": "潜る", "form_label": "て形", "sentence_index": 1, "explanations": {"潜って": "て形で、「朝まで出てこなかった」へ続けることができる。", "潜った": "過去形で文を言い切ってしまい、後ろの「朝まで出てこなかった」と続かない。", "潜らない": "否定形で布団に潜ったという事実と矛盾し、後ろの節とも続かない。", "潜ろう": "意志形で猫の意思を表すため、「布団の中へ潜ろう、朝まで出てこなかった」と結果の文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダイバーは深い海に潜るを、魚を観察した。", "corrected_sentence": "ダイバーは深い海に潜って、魚を観察した。", "error_description": "「潜るを」が誤り。動詞の後に「を」は続かず、て形の「潜って」で「魚を観察した」へ続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潜る", "is_correct": true, "explanation": "辞書形で、カワウの習性を述べる文末に合う。"}, {"text": "潜れ", "is_correct": false, "explanation": "命令形で、カワウに命じる文になり、習性を述べる文脈に合わない。"}, {"text": "潜ろう", "is_correct": false, "explanation": "意志形で、話し手の決意を表し、習性の説明とは合わない。"}, {"text": "潜り", "is_correct": false, "explanation": "連用形で文末として言い切れず、文が途中で終わってしまう。"}], "correct_form": "潜る", "base_form": "潜る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"潜る": "辞書形で、カワウの習性を述べる文末に合う。", "潜れ": "命令形で、カワウに命じる文になり、習性を述べる文脈に合わない。", "潜ろう": "意志形で、話し手の決意を表し、習性の説明とは合わない。", "潜り": "連用形で文末として言い切れず、文が途中で終わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
