INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量・程度がわずかであるさま。また、かすかではっきりしないさま。", "primary_collocate": null, "pronunciation": "かすか", "ipa": "kasɯka", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "微か", "complexity_tier": "T4", "furigana": "みちのくうかんたるしんこうしゃのとびらをくぐるむすめのせなかには、かすかなきんちょうと、それをはるかにうわまわるこうきしんがみなぎっていた。", "sentence_source": "mined"}, {"text": "遠くから、犬の鳴き声が微かに聞こえた。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "とおくから、いぬのなきごえがかすかにきこえた。", "sentence_source": "generated"}, {"text": "部屋に入ると、花の微かな香りがした。", "target_word": "微かな", "complexity_tier": "T3", "furigana": "へやにはいると、はなのかすかなかおりがした。", "sentence_source": "generated"}, {"text": "朝になって、熱が下がる微かな兆しが見えた。", "target_word": "微かな", "complexity_tier": "T3", "furigana": "あさになって、ねつがさがるかすかなきざしがみえた。", "sentence_source": "generated"}, {"text": "彼女の声は微かに震えていて、緊張しているのが分かった。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "かのじょのこえはかすかにふるえていて、きんちょうしているのがわかった。", "sentence_source": "generated"}, {"text": "助かる微かな望みを信じて、救助隊は夜通し捜索を続けた。", "target_word": "微かな", "complexity_tier": "T3", "furigana": "たすかるかすかなのぞみをしんじて、きゅうじょたいはよどおしそうさくをつづけた。", "sentence_source": "generated"}, {"text": "窓の外で、雨の音が微かに続いていた。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "まどのそとで、あめのおとがかすかにつづいていた。", "sentence_source": "generated"}, {"text": "彼の顔には微かな笑みが浮かんでいたが、目は笑っていなかった。", "target_word": "微かな", "complexity_tier": "T3", "furigana": "かれのかおにはかすかなえみがうかんでいたが、めはわらっていなかった。", "sentence_source": "generated"}, {"text": "古い写真には、祖父の姿が微かに写っているだけだった。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "ふるいしゃしんには、そふのすがたがかすかにうつっているだけだった。", "sentence_source": "generated"}, {"text": "霧が濃くて、向こうの山の形がやっと微かに見える程度だった。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "きりがこくて、むこうのやまのかたちがやっとかすかにみえるていどだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微かだ", "label": "終止形"}, {"form": "微かな", "label": "連体形"}, {"form": "微かに", "label": "連用形"}, {"form": "微かだった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "音・光・気配などが弱くてはっきりしないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微か", "is_correct": true, "explanation": "「微かな緊張」の形で、わずかな緊張を表す。文中の位置に合う。"}, {"text": "賑やか", "is_correct": false, "explanation": "にぎやかな様子を表す語で、緊張の程度を言うのには合わない。"}, {"text": "几帳面", "is_correct": false, "explanation": "きちんとした性格を表すので、緊張の描写には当てはまらない。"}, {"text": "健やか", "is_correct": false, "explanation": "心身が健康な様子を表すので、緊張の描写には当てはまらない。"}], "explanations": {"微か": "「微かな緊張」の形で、わずかな緊張を表す。文中の位置に合う。", "賑やか": "にぎやかな様子を表す語で、緊張の程度を言うのには合わない。", "几帳面": "きちんとした性格を表すので、緊張の描写には当てはまらない。", "健やか": "心身が健康な様子を表すので、緊張の描写には当てはまらない。"}, "sentence_index": 0, "correct_answer": "微か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は微かで、大人でも持ち上がらない。", "explanation": "ここは〈重い〉の意味。持ち上がらないのは重さの話。微かは程度がわずかという意味で、重さには使えず合わない。"}, {"text": "この靴は微かで、長く歩くと足が痛くなる。", "explanation": "ここは〈きつい〉の意味。足が痛くなるのは靴の締めつけの話。微かは程度がわずかという意味で、窮屈さには使えず合わない。"}, {"text": "庭に微かな雪が降り積もって、足首まで埋まった。", "explanation": "ここは〈大量〉の意味。足首まで埋まるほどの量は多いことなので、量がわずかという微かとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微かに", "is_correct": true, "explanation": "連用形。「続いていた」を修飾し、雨の音がわずかに続く様子を表す。"}, {"text": "まさに", "is_correct": false, "explanation": "「ちょうど」の意味で、音が続く様子の描写には合わない。"}, {"text": "ついに", "is_correct": false, "explanation": "「最後に」の意味で、ずっと続いていた状態とは合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "深く眠る様子を表すので、雨の音が続く描写には合わない。"}], "explanations": {"微かに": "連用形。「続いていた」を修飾し、雨の音がわずかに続く様子を表す。", "まさに": "「ちょうど」の意味で、音が続く様子の描写には合わない。", "ついに": "「最後に」の意味で、ずっと続いていた状態とは合わない。", "ぐっすり": "深く眠る様子を表すので、雨の音が続く描写には合わない。"}, "sentence_index": 6, "correct_answer": "微かに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この布は微かで、向こうが透けて見えるほどだ。", "explanation": "ここは〈薄い〉の意味。布の薄さは〈薄い〉で言う。微かは音や光などの弱さに使い、布の薄さには言わない。"}, {"text": "この会場は微かで、千人が入る。", "explanation": "ここは〈広い〉の意味。会場の広さは〈広い〉で言う。微かは数量や音・光の弱さに使い、広さには言わない。"}, {"text": "この部屋は微かで、床がぴかぴかに磨かれている。", "explanation": "ここは〈清潔〉の意味。磨かれた清潔さは〈きれい〉で言う。微かは弱さを表す語で、清潔さには言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの隙間から、微かだ光が差し込んでいた。", "corrected_sentence": "ドアの隙間から、微かな光が差し込んでいた。", "error_description": "名詞「光」を修飾する連体形は「微かな」。「微かだ」は終止形で、名詞の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微かに", "is_correct": true, "explanation": "連用形。「聞こえた」を修飾し、音がわずかに届く様子を表す。"}, {"text": "微かな", "is_correct": false, "explanation": "連体形で名詞を修飾する。動詞「聞こえた」の前には置けない。"}, {"text": "微かだ", "is_correct": false, "explanation": "終止形。動詞を修飾する位置には入らない。"}, {"text": "微かだった", "is_correct": false, "explanation": "過去の述語形。「聞こえた」を修飾する位置には入らない。"}], "correct_form": "微かに", "base_form": "微かだ", "form_label": "連用形", "sentence_index": 1, "explanations": {"微かに": "連用形。「聞こえた」を修飾し、音がわずかに届く様子を表す。", "微かな": "連体形で名詞を修飾する。動詞「聞こえた」の前には置けない。", "微かだ": "終止形。動詞を修飾する位置には入らない。", "微かだった": "過去の述語形。「聞こえた」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠くのビルの明かりが微かな見える。", "corrected_sentence": "遠くのビルの明かりが微かに見える。", "error_description": "動詞「見える」を修飾するので連用形「微かに」が必要。「微かな」は連体形で、動詞の前には置けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微かな", "is_correct": true, "explanation": "連体形。名詞「笑み」を修飾する形で、わずかな笑みを表す。"}, {"text": "微かで", "is_correct": false, "explanation": "て形。名詞「笑み」の前には置けず、「笑み」を修飾できない。"}, {"text": "微かであった", "is_correct": false, "explanation": "過去の述語形。名詞の前には置けず、「笑み」を修飾できない。"}, {"text": "微かなら", "is_correct": false, "explanation": "仮定形。名詞の前には置けず、「笑み」を修飾できない。"}], "correct_form": "微かな", "base_form": "微かだ", "form_label": "連体形", "sentence_index": 7, "explanations": {"微かな": "連体形。名詞「笑み」を修飾する形で、わずかな笑みを表す。", "微かで": "て形。名詞「笑み」の前には置けず、「笑み」を修飾できない。", "微かであった": "過去の述語形。名詞の前には置けず、「笑み」を修飾できない。", "微かなら": "仮定形。名詞の前には置けず、「笑み」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語の「が」。存在するものとして娘を示す形になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「いる」は目的語をとらない動詞なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」。娘を存在の主体として示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「いる」の対象を示す形にはならない。"}], "correct_answer": "が", "explanations": {"が": "主語の「が」。存在するものとして娘を示す形になる。", "を": "目的語の「を」。「いる」は目的語をとらない動詞なので合わない。", "で": "場所や手段の「で」。娘を存在の主体として示せない。", "へ": "方向の「へ」。「いる」の対象を示す形にはならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "相手の「に」。絵本を読んであげる相手として娘を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。ここでは「絵本を」が既に目的語で、娘には使えない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」。娘を場所や手段として示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。娘と何かを比べる文脈ではない。"}], "correct_answer": "に", "explanations": {"に": "相手の「に」。絵本を読んであげる相手として娘を示す。", "を": "目的語の「を」。ここでは「絵本を」が既に目的語で、娘には使えない。", "で": "場所や手段の「で」。娘を場所や手段として示せない。", "より": "比較の「より」。娘と何かを比べる文脈ではない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お母さんとお父さんの子どもの女の子のこと。", "primary_collocate": null, "pronunciation": "むすめ", "ipa": "mɯsɯme", "syllable_count": 3, "sentences": [{"text": "娘は毎朝、七時に起きて顔を洗う。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめはまいあさ、しちじにおきてかおをあらう。", "sentence_source": "generated"}, {"text": "私には五歳の娘がいる。", "target_word": "娘", "complexity_tier": "T3", "furigana": "わたしにはごさいのむすめがいる。", "sentence_source": "generated"}, {"text": "娘の誕生日に、大きなケーキを買った。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめのたんじょうびに、おおきなけーきをかった。", "sentence_source": "generated"}, {"text": "娘が泣いていたので、母は急いで部屋に行った。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめがないていたので、はははいそいでへやにいった。", "sentence_source": "generated"}, {"text": "父は娘と手をつないで公園を散歩した。", "target_word": "娘", "complexity_tier": "T3", "furigana": "ちちはむすめとてをつないでこうえんをさんぽした。", "sentence_source": "generated"}, {"text": "うちの娘は絵を描くのが大好きで、毎日クレヨンを使う。", "target_word": "娘", "complexity_tier": "T3", "furigana": "うちのむすめはえをかくのがだいすきで、まいにちくれよんをつかう。", "sentence_source": "generated"}, {"text": "娘が熱を出したため、今日は会社を休むことにした。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめがねつをだしたため、きょうはかいしゃをやすむことにした。", "sentence_source": "generated"}, {"text": "娘に絵本を読んであげると、すぐに眠ってしまった。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめにえほんをよんであげると、すぐにねむってしまった。", "sentence_source": "generated"}, {"text": "昨日、娘は初めて自転車に乗れるようになった。", "target_word": "娘", "complexity_tier": "T3", "furigana": "きのう、むすめははじめてじてんしゃにのれるようになった。", "sentence_source": "generated"}, {"text": "娘の友だちが遊びに来るので、お菓子を用意した。", "target_word": "娘", "complexity_tier": "T3", "furigana": "むすめのともだちがあそびにくるので、おかしをよういした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "娘", "label": "基本形"}, {"form": "娘さん", "label": "敬称形"}, {"form": "娘たち", "label": "複数形"}], "register": "neutral", "sense_fingerprint": "親から見た自分の女の子の子ども", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娘", "is_correct": true, "explanation": "親の子である女の子を指す「娘」。毎朝起きて顔を洗う人物として正しい。"}, {"text": "窓", "is_correct": false, "explanation": "物で、起きて顔を洗うことはない。"}, {"text": "時計", "is_correct": false, "explanation": "物で、顔を洗う主語にはならない。"}, {"text": "机", "is_correct": false, "explanation": "物で、起きて顔を洗う動作の主語にはならない。"}], "explanations": {"娘": "親の子である女の子を指す「娘」。毎朝起きて顔を洗う人物として正しい。", "窓": "物で、起きて顔を洗うことはない。", "時計": "物で、顔を洗う主語にはならない。", "机": "物で、起きて顔を洗う動作の主語にはならない。"}, "sentence_index": 0, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の娘は、家を継ぐ長男だ。", "explanation": "ここは〈息子〉の意味。娘は女の子を指すので、長男には使えない。"}, {"text": "私の娘は、七十歳の祖母だ。", "explanation": "ここは〈お婆さん〉の意味。娘は親から見た子どもを指すので、親の親には使わない。"}, {"text": "私の娘は、一つ上の姉だ。", "explanation": "ここは〈お姉さん〉の意味。娘は親から見て子どもを指すので、年上の姉には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娘", "is_correct": true, "explanation": "親の子である女の子を指す「娘」。熱を出して会社を休む理由になる人物として正しい。"}, {"text": "車", "is_correct": false, "explanation": "乗り物で、熱を出すことはない。"}, {"text": "椅子", "is_correct": false, "explanation": "家具で、熱を出すことはない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文房具で、熱を出して会社を休む主語にはならない。"}], "explanations": {"娘": "親の子である女の子を指す「娘」。熱を出して会社を休む理由になる人物として正しい。", "車": "乗り物で、熱を出すことはない。", "椅子": "家具で、熱を出すことはない。", "鉛筆": "文房具で、熱を出して会社を休む主語にはならない。"}, "sentence_index": 6, "correct_answer": "娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの娘は、四月に生まれたばかりの、私の息子の子だ。", "explanation": "ここは〈孫〉の意味。娘は親から見た子どもを指すので、息子の子には使わない。"}, {"text": "私の娘は、父より年上の兄だ。", "explanation": "ここは〈お兄さん〉の意味。娘は女の子を指すので、年上の男のきょうだいには使えない。"}, {"text": "私の娘は、家で一番大きな犬だ。", "explanation": "ここは〈ペット〉の意味。娘は人間の女の子を指す語で、家で飼う犬には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "娘に毎朝、牛乳を飲む。", "corrected_sentence": "娘が毎朝、牛乳を飲む。", "error_description": "飲む動作の主語には「が」を使う。「に」は相手や方向を表すので、主語の「娘」には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の娘を、朝早く学校へ行った。", "corrected_sentence": "私の娘が、朝早く学校へ行った。", "error_description": "行く動作の主語には「が」を使う。「を」は目的語を表すので、行く動作の主体には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人生の長さ」と名詞を修飾する連体修飾の「の」で、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "「人生が長さ」と名詞が直接つながり、文として不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。人生が長さを修飾する関係にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。長さを修飾する関係に合わない。"}], "correct_answer": "の", "explanations": {"の": "「人生の長さ」と名詞を修飾する連体修飾の「の」で、文意に合う。", "が": "「人生が長さ」と名詞が直接つながり、文として不自然になる。", "を": "目的語を示す助詞。人生が長さを修飾する関係にならない。", "へ": "方向を示す助詞。長さを修飾する関係に合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
