INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が生まれてから死ぬまでの時間のことです。", "primary_collocate": null, "pronunciation": "じんせい", "ipa": "dʑiɴseː", "syllable_count": 2, "sentences": [{"text": "人生は一度きりだから、後悔しないように生きたい。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]は一度[いちど]きりだから、後悔[こうかい]しないように生[い]きたい。", "sentence_source": "generated"}, {"text": "人生の長さは、人によって大きく違う。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]の長[なが]さは、人[ひと]によって大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "人生の三分の一は眠っている時間だと言われる。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]の三分[さんぶん]の一[いち]は眠[ねむ]っている時間[じかん]だと言[い]われる。", "sentence_source": "generated"}, {"text": "彼は人生の最後まで、毎日日記を書き続けた。", "target_word": "人生", "complexity_tier": "T3", "furigana": "彼[かれ]は人生[じんせい]の最後[さいご]まで、毎日[まいにち]日記[にっき]を書[か]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "人生は短いので、好きなことに時間を使うべきだ。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]は短[みじか]いので、好[す]きなことに時間[じかん]を使[つか]うべきだ。", "sentence_source": "generated"}, {"text": "祖父は九十年の人生を、静かに終えた。", "target_word": "人生", "complexity_tier": "T3", "furigana": "祖父[そふ]は九十年[きゅうじゅうねん]の人生[じんせい]を、静[しず]かに終[お]えた。", "sentence_source": "generated"}, {"text": "人生の半分を過ぎてから、私は絵を習い始めた。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]の半分[はんぶん]を過[す]ぎてから、私[わたし]は絵[え]を習[なら]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "限りある人生を、無駄にしたくない。", "target_word": "人生", "complexity_tier": "T3", "furigana": "限[かぎ]りある人生[じんせい]を、無駄[むだ]にしたくない。", "sentence_source": "generated"}, {"text": "母は人生の長さより、中身が大事だと話した。", "target_word": "人生", "complexity_tier": "T3", "furigana": "母[はは]は人生[じんせい]の長[なが]さより、中身[なかみ]が大事[だいじ]だと話[はな]した。", "sentence_source": "generated"}, {"text": "人生のうち、仕事をする時間は意外と長い。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]のうち、仕事[しごと]をする時間[じかん]は意外[いがい]と長[なが]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人生", "label": "基本形"}, {"form": "人生観", "label": "派生語"}], "register": "標準（中立）", "sense_fingerprint": "生まれてから死ぬまでの期間・時間の長さとしての人生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "「人生は一度きり」で、生まれてから死ぬまでの期間を表し、文意に合う。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格を表す。「値段は一度きり」とは言わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の水分量を表す。一度きりという言い方とは結びつかない。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表す。後悔しないように生きるという文脈に合わない。"}], "explanations": {"人生": "「人生は一度きり」で、生まれてから死ぬまでの期間を表し、文意に合う。", "値段": "値段は価格を表す。「値段は一度きり」とは言わない。", "湿度": "湿度は空気の水分量を表す。一度きりという言い方とは結びつかない。", "面積": "面積は広さを表す。後悔しないように生きるという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建物は人生が五十年を超えている。", "explanation": "ここは〈築年数〉の意味。建物が建ってからの年数は築年数で表し、人生とは言わない。"}, {"text": "この契約の人生は二年だ。", "explanation": "ここは〈契約期間〉の意味。契約が有効な期間は契約期間と言い、人生とは言わない。"}, {"text": "この牛乳は人生が短いので、早めに飲み切ろう。", "explanation": "ここは〈賞味期限〉の意味。食品をおいしく食べられる期限は賞味期限と言い、人生とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "「人生の半分」で、生まれてから死ぬまでの期間の半ばを表し、文意に合う。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す。「音量の半分を過ぎてから」は意味をなさない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色合いを表す。期間の半分という文脈には入らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さを表す。「体重の半分を過ぎてから」は意味をなさない。"}], "explanations": {"人生": "「人生の半分」で、生まれてから死ぬまでの期間の半ばを表し、文意に合う。", "音量": "音量は音の大きさを表す。「音量の半分を過ぎてから」は意味をなさない。", "色彩": "色彩は色合いを表す。期間の半分という文脈には入らない。", "体重": "体重は体の重さを表す。「体重の半分を過ぎてから」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この橋の人生は三年かかった。", "explanation": "ここは〈工期〉の意味。建設にかかる期間は工期と言い、人生とは言わない。"}, {"text": "この展示会の人生は三日間だった。", "explanation": "ここは〈会期〉の意味。展示が行われる期間は会期と言い、人生とは言わない。"}, {"text": "この定期券の人生は三か月だった。", "explanation": "ここは〈有効期間〉の意味。定期券が使える期間は有効期間と言い、人生とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人生に長さは、誰にとっても同じではない。", "corrected_sentence": "人生の長さは、誰にとっても同じではない。", "error_description": "「人生の長さ」と名詞をつなぐには「の」が必要。「人生に長さ」は誤りで、「に」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は人生で芸術の研究に捧げた。", "corrected_sentence": "彼は人生を芸術の研究に捧げた。", "error_description": "「捧げる」は「〜を捧げる」と目的語に「を」を取る。「人生で」は誤りで、正しくは「人生を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「語る」の目的語を示す格助詞で、「人生を」は文の中心として正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。ここでは語る対象なので目的語の「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。語る内容には使わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。文の述語が続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「語る」の目的語を示す格助詞で、「人生を」は文の中心として正しい。", "が": "主語を示す助詞。ここでは語る対象なので目的語の「を」が必要。", "へ": "方向を示す助詞。語る内容には使わない。", "の": "連体修飾の助詞。文の述語が続かず、文が成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「人生で一番うれしかった日」の範囲、つまり人生の中での出来事を示し、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「人生が一番うれしかった日」では文の主語が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "存在や時点を示す助詞。「人生に一番うれしかった日」は不自然で、範囲の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。人生の範囲を表すには使えない。"}], "correct_answer": "で", "explanations": {"で": "「人生で一番うれしかった日」の範囲、つまり人生の中での出来事を示し、文意に合う。", "が": "主語を示す助詞。「人生が一番うれしかった日」では文の主語が崩れる。", "に": "存在や時点を示す助詞。「人生に一番うれしかった日」は不自然で、範囲の意味にならない。", "へ": "方向を示す助詞。人生の範囲を表すには使えない。"}, "error_tags": {"が": "主語", "に": "存在・時点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がこの世に生きている間の、出来事や経験の全体。", "primary_collocate": null, "pronunciation": "じんせい", "ipa": "dʑiɴseː", "syllable_count": 4, "sentences": [{"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "人生", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の人生[じんせい]におけるこの学校[がっこう]の初日[しょにち]は、単[たん]なる物理的[ぶつりてき]な場所[ばしょ]の移動[いどう]を意味[いみ]するものではない。", "sentence_source": "mined"}, {"text": "祖母は波乱に満ちた人生を、笑いながら語ってくれた。", "target_word": "人生", "complexity_tier": "T3", "furigana": "祖母[そぼ]は波乱[はらん]に満[み]ちた人生[じんせい]を、笑[わら]いながら語[かた]ってくれた。", "sentence_source": "generated"}, {"text": "大きな病気をしたことで、私の人生に対する考え方が変わった。", "target_word": "人生", "complexity_tier": "T3", "furigana": "大[おお]きな病気[びょうき]をしたことで、私[わたし]の人生[じんせい]に対[たい]する考[かんが]え方[かた]が変[か]わった。", "sentence_source": "generated"}, {"text": "あの旅は、私の人生を大きく変える出来事になった。", "target_word": "人生", "complexity_tier": "T3", "furigana": "あの旅[たび]は、私[わたし]の人生[じんせい]を大[おお]きく変[か]える出来事[できごと]になった。", "sentence_source": "generated"}, {"text": "失敗も人生の大切な経験だと、先生は言った。", "target_word": "人生", "complexity_tier": "T3", "furigana": "失敗[しっぱい]も人生[じんせい]の大切[たいせつ]な経験[けいけん]だと、先生[せんせい]は言[い]った。", "sentence_source": "generated"}, {"text": "この小説は、一人の女性の人生を丁寧に描いている。", "target_word": "人生", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、一人[ひとり]の女性[じょせい]の人生[じんせい]を丁寧[ていねい]に描[えが]いている。", "sentence_source": "generated"}, {"text": "留学したことは、私の人生にとって大きな転機になった。", "target_word": "人生", "complexity_tier": "T3", "furigana": "留学[りゅうがく]したことは、私[わたし]の人生[じんせい]にとって大[おお]きな転機[てんき]になった。", "sentence_source": "generated"}, {"text": "人生で一番うれしかった日を、今も忘れられない。", "target_word": "人生", "complexity_tier": "T3", "furigana": "人生[じんせい]で一番[いちばん]うれしかった日[ひ]を、今[いま]も忘[わす]れられない。", "sentence_source": "generated"}, {"text": "父は長い人生で学んだことを、手紙に書き残した。", "target_word": "人生", "complexity_tier": "T3", "furigana": "父[ちち]は長[なが]い人生[じんせい]で学[まな]んだことを、手紙[てがみ]に書[か]き残[のこ]した。", "sentence_source": "generated"}, {"text": "彼らは人生の苦楽を共にしてきた夫婦だ。", "target_word": "人生", "complexity_tier": "T3", "furigana": "彼[かれ]らは人生[じんせい]の苦楽[くらく]を共[とも]にしてきた夫婦[ふうふ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人生", "label": "基本形"}, {"form": "人生観", "label": "派生語"}], "register": "標準（中立）", "sense_fingerprint": "生きている間に起こる出来事や経験の全体としての人生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 苦楽 (Zipf 2.41)']::text[], '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "「彼女の人生におけるこの学校の初日」で、経験全体としての人生を指し、文意に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の水分の割合を表す。「彼女の湿度におけるこの学校の初日」では文が成り立たない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す。人の経験の全体を示す場所には入らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色合いを表す。「彼女の色彩における初日」は意味をなさない。"}], "explanations": {"人生": "「彼女の人生におけるこの学校の初日」で、経験全体としての人生を指し、文意に合う。", "湿度": "湿度は空気の水分の割合を表す。「彼女の湿度におけるこの学校の初日」では文が成り立たない。", "音量": "音量は音の大きさを表す。人の経験の全体を示す場所には入らない。", "色彩": "色彩は色合いを表す。「彼女の色彩における初日」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家賃が上がり、人生を切り詰めることにした。", "explanation": "ここは〈生活〉の意味。切り詰めるのは暮らしの費用や支出で、経験の全体としての人生とは言わない。"}, {"text": "彼女は人生が優しくて、子どもたちによく好かれる。", "explanation": "ここは〈人柄〉の意味。優しさは人柄で表し、人生が優しいとは言わない。"}, {"text": "この機械は人生が短いので、早めに買い替えた。", "explanation": "ここは〈寿命〉の意味。機械や物が使える期間は寿命で、人生とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "「私の人生にとって大きな転機」で、生き方全体への影響を表し、文意に合う。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格を表す。「私の値段にとって大きな転機」は意味をなさない。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表す。人生の転機という文脈と結びつかない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さを表す。留学が体重にとって転機という文にはならない。"}], "explanations": {"人生": "「私の人生にとって大きな転機」で、生き方全体への影響を表し、文意に合う。", "値段": "値段は価格を表す。「私の値段にとって大きな転機」は意味をなさない。", "面積": "面積は広さを表す。人生の転機という文脈と結びつかない。", "体重": "体重は体の重さを表す。留学が体重にとって転機という文にはならない。"}, "sentence_index": 6, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は画家として、人生を立てている。", "explanation": "ここは〈生計〉の意味。収入を得て暮らすことは「生計を立てる」と言い、人生を立てるとは言わない。"}, {"text": "彼は人生が整っていて、俳優のような美男子だ。", "explanation": "ここは〈容姿〉の話。顔立ちが整っていると言い、人生が整っているとは言わない。"}, {"text": "この本は人生が分かりやすく、読みやすい。", "explanation": "ここは〈文章〉の意味。読みやすさは文章の性質で、本の人生が分かりやすいとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、波乱に満ちた自分の人生に笑いながら語ってくれた。", "corrected_sentence": "祖母は、波乱に満ちた自分の人生を笑いながら語ってくれた。", "error_description": "「語る」は「〜を語る」と目的語に「を」を取る。「人生に」は誤りで、正しくは「人生を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夫婦として長く暮らし、互いの人生を支え合いてきた。", "corrected_sentence": "夫婦として長く暮らし、互いの人生を支え合ってきた。", "error_description": "「支え合う」は連用形「合い」に「てきた」が続かず、正しくは「支え合ってきた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
