INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52487, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものの数や大きさが、別のものより大きいこと。", "primary_collocate": null, "pronunciation": "うわまわる", "ipa": "ɯwamawaɾɯ", "syllable_count": 5, "sentences": [{"text": "この学校では、男子の数が女子の数を上回っている。", "target_word": "上回", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、男子[だんし]の数[かず]が女子[じょし]の数[かず]を上回[うわまわ]っている。", "sentence_source": "generated"}, {"text": "この町の人口は、隣の町の人口を上回っている。", "target_word": "上回っている", "complexity_tier": "T3", "furigana": "この町[まち]の人口[じんこう]は、隣[となり]の町[まち]の人口[じんこう]を上回[うわまわ]っている。", "sentence_source": "generated"}, {"text": "今年の来場者は、去年の二倍を上回った。", "target_word": "上回", "complexity_tier": "T3", "furigana": "今年[ことし]の来場者[らいじょうしゃ]は、去年[きょねん]の二倍[にばい]を上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "収入が支出を上回れば、貯金ができる。", "target_word": "上回", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]が支出[ししゅつ]を上回[うわまわ]れば、貯金[ちょきん]ができる。", "sentence_source": "generated"}, {"text": "川の水位が基準の高さを上回り、避難が始まった。", "target_word": "上回", "complexity_tier": "T3", "furigana": "川[かわ]の水位[すいい]が基準[きじゅん]の高[たか]さを上回[うわまわ]り、避難[ひなん]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "この箱の重さは、十キロを上回るだろう。", "target_word": "上回る", "complexity_tier": "T3", "furigana": "この箱[はこ]の重[おも]さは、十[じゅう]キロを上回[うわまわ]るだろう。", "sentence_source": "generated"}, {"text": "今月は雨の日の数が、晴れの日の数を上回った。", "target_word": "上回", "complexity_tier": "T3", "furigana": "今月[こんげつ]は雨[あめ]の日[ひ]の数[かず]が、晴[は]れの日[ひ]の数[かず]を上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "欠席者が出席者を上回り、会議は延期された。", "target_word": "上回", "complexity_tier": "T3", "furigana": "欠席者[けっせきしゃ]が出席者[しゅっせきしゃ]を上回[うわまわ]り、会議[かいぎ]は延期[えんき]された。", "sentence_source": "generated"}, {"text": "この木の高さは、隣の家の二階の高さを上回っている。", "target_word": "上回っている", "complexity_tier": "T3", "furigana": "この木[き]の高[たか]さは、隣[となり]の家[いえ]の二階[にかい]の高[たか]さを上回[うわまわ]っている。", "sentence_source": "generated"}, {"text": "今月の注文は、先月の数を上回った。", "target_word": "上回", "complexity_tier": "T3", "furigana": "今月[こんげつ]の注文[ちゅうもん]は、先月[せんげつ]の数[かず]を上回[うわまわ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上回る", "label": "終止形"}, {"form": "上回った", "label": "過去形"}, {"form": "上回って", "label": "て形"}, {"form": "上回らない", "label": "ない形"}, {"form": "上回ります", "label": "ます形"}, {"form": "上回れば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "二つのものの数量・大きさを比べて、一方が他方より大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形の語幹。「上回っている」の形を作り、文意に合う。"}, {"text": "上回る", "is_correct": false, "explanation": "終止形を「っている」の前に置くと成り立たない。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は「っている」に続かず、文が成り立たない。"}, {"text": "上回ら", "is_correct": false, "explanation": "未然形は「っている」の前に置けず、文が崩れる。"}], "explanations": {"上回": "連用形の語幹。「上回っている」の形を作り、文意に合う。", "上回る": "終止形を「っている」の前に置くと成り立たない。", "上回れ": "命令形は「っている」に続かず、文が成り立たない。", "上回ら": "未然形は「っている」の前に置けず、文が崩れる。"}, "sentence_index": 0, "correct_answer": "上回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を上回って、一人で運んだ。", "explanation": "ここは〈運ぶ〉の意味。荷物を運ぶ動作は上回ると言わず、数量の大小を表さない。"}, {"text": "急な山道を上回った。", "explanation": "ここは〈登る〉の意味。山道を登る動作は上回るとは言わず、数量の比較にはならない。"}, {"text": "景色を上回った。", "explanation": "ここは〈眺める〉の意味。景色を見る動作は眺めると言い、上回るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形の語幹。「上回った」の形を作り、過去の事実を述べる文に合う。"}, {"text": "上回り", "is_correct": false, "explanation": "連用形だが「た」に続けると形が崩れ、文が成り立たない。"}, {"text": "上回らず", "is_correct": false, "explanation": "打ち消しの連用形で、「た」に続けられず文が成り立たない。"}, {"text": "上回ろう", "is_correct": false, "explanation": "意志形で、事実を述べる文の中に入れられない。"}], "explanations": {"上回": "連用形の語幹。「上回った」の形を作り、過去の事実を述べる文に合う。", "上回り": "連用形だが「た」に続けると形が崩れ、文が成り立たない。", "上回らず": "打ち消しの連用形で、「た」に続けられず文が成り立たない。", "上回ろう": "意志形で、事実を述べる文の中に入れられない。"}, "sentence_index": 6, "correct_answer": "上回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床を上回った。", "explanation": "ここは〈洗う〉の意味。床を洗う動作は上回るとは言わず、数量の大小を表さない。"}, {"text": "扉を上回った。", "explanation": "ここは〈叩く〉の意味。扉を叩く動作は上回るとは言わず、比較の意味にはならない。"}, {"text": "写真を上回った。", "explanation": "ここは〈撮る〉の意味。写真を撮る動作は上回るとは言わず、数や程度の基準超えを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクラスでは、女子の数が男子の数に上回っている。", "corrected_sentence": "このクラスでは、女子の数が男子の数を上回っている。", "error_description": "「上回る」は「〜を上回る」と目的語に「を」を取る。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上回っている", "is_correct": true, "explanation": "て形に「いる」が続いた形で、今の状態を表し、文意に合う。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は文末で述語として成り立たず、この文では不自然。"}, {"text": "上回って", "is_correct": false, "explanation": "て形で文が終わり、述語が完成しない。"}, {"text": "上回らない", "is_correct": false, "explanation": "否定形で、人口が上回るという事実と反対の内容になる。"}], "correct_form": "上回っている", "base_form": "上回る", "form_label": "て形＋いる（状態）", "sentence_index": 1, "explanations": {"上回っている": "て形に「いる」が続いた形で、今の状態を表し、文意に合う。", "上回れ": "命令形は文末で述語として成り立たず、この文では不自然。", "上回って": "て形で文が終わり、述語が完成しない。", "上回らない": "否定形で、人口が上回るという事実と反対の内容になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年の応募者は、昨年の人数を上回り見込みだ。", "corrected_sentence": "今年の応募者は、昨年の人数を上回る見込みだ。", "error_description": "「見込み」を修飾するには連体形「上回る」が必要。「上回り」は連用形で名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形（中止形）。「上回り、」の語幹で、後ろの文へ続く形として正しい。"}, {"text": "上回る", "is_correct": false, "explanation": "終止形のまま「、」で続けると文として成り立たない。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は文の途中で続かず、文が成り立たない。"}, {"text": "上回ろう", "is_correct": false, "explanation": "意志形で、事実を報告する文の流れに合わない。"}], "correct_form": "上回", "base_form": "上回る", "form_label": "連用形（中止形）", "sentence_index": 7, "explanations": {"上回": "連用形（中止形）。「上回り、」の語幹で、後ろの文へ続く形として正しい。", "上回る": "終止形のまま「、」で続けると文として成り立たない。", "上回れ": "命令形は文の途中で続かず、文が成り立たない。", "上回ろう": "意志形で、事実を報告する文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下回る", "is_correct": true, "explanation": "対義語。基準より数や程度が低いことを表し、上回るの対義語にあたる。"}, {"text": "超える", "is_correct": false, "explanation": "類義語で、対義語ではない。"}, {"text": "達する", "is_correct": false, "explanation": "ある水準に届くことを表すが、対義語とは言えない。"}, {"text": "届く", "is_correct": false, "explanation": "手や物が届く意味で、数や程度の対義語にはならない。"}], "correct_answer": "下回る", "explanations": {"下回る": "対義語。基準より数や程度が低いことを表し、上回るの対義語にあたる。", "超える": "類義語で、対義語ではない。", "達する": "ある水準に届くことを表すが、対義語とは言えない。", "届く": "手や物が届く意味で、数や程度の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下回る", "is_correct": true, "explanation": "対義語。基準より数や程度が低いことを表し、上回るの対義語にあたる。"}, {"text": "満たす", "is_correct": false, "explanation": "基準や条件に達することを表すが、上回るの対義語ではない。"}, {"text": "及ぶ", "is_correct": false, "explanation": "ある水準まで届く意味で、対義語とは言えない。"}, {"text": "迫る", "is_correct": false, "explanation": "近づく意味で、数や程度の対義語にはならない。"}], "correct_answer": "下回る", "explanations": {"下回る": "対義語。基準より数や程度が低いことを表し、上回るの対義語にあたる。", "満たす": "基準や条件に達することを表すが、上回るの対義語ではない。", "及ぶ": "ある水準まで届く意味で、対義語とは言えない。", "迫る": "近づく意味で、数や程度の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "基準となるものよりも、数や程度が高いこと。", "primary_collocate": null, "pronunciation": "うわまわる", "ipa": "ɯwamawaɾɯ", "syllable_count": 5, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "上回る", "complexity_tier": "T4", "furigana": "未知[みち]の空間[くうかん]たる新校舎[しんこうしゃ]の扉[とびら]をくぐる娘[むすめ]の背中[せなか]には、微[かす]かな緊張[きんちょう]と、それをはるかに上回[うわまわ]る好奇心[こうきしん]が漲[みなぎ]っていた。", "sentence_source": "mined"}, {"text": "今年の売り上げは、目標を大きく上回った。", "target_word": "上回", "complexity_tier": "T3", "furigana": "今年[ことし]の売[う]り上[あ]げは、目標[もくひょう]を大[おお]きく上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "参加者の数は、予想を上回る多さだった。", "target_word": "上回る", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の数[かず]は、予想[よそう]を上回[うわまわ]る多[おお]さだった。", "sentence_source": "generated"}, {"text": "試験の結果は、期待を上回るものではなかった。", "target_word": "上回る", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]は、期待[きたい]を上回[うわまわ]るものではなかった。", "sentence_source": "generated"}, {"text": "今月は、例年を上回る暑さが続いている。", "target_word": "上回る", "complexity_tier": "T3", "furigana": "今月[こんげつ]は、例年[れいねん]を上回[うわまわ]る暑[あつ]さが続[つづ]いている。", "sentence_source": "generated"}, {"text": "申し込みが定員を上回ったので、抽選になった。", "target_word": "上回", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みが定員[ていいん]を上回[うわまわ]ったので、抽選[ちゅうせん]になった。", "sentence_source": "generated"}, {"text": "実際の費用が予算を上回り、計画を見直した。", "target_word": "上回", "complexity_tier": "T3", "furigana": "実際[じっさい]の費用[ひよう]が予算[よさん]を上回[うわまわ]り、計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "新製品の性能は、前のモデルを上回っている。", "target_word": "上回", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の性能[せいのう]は、前[まえ]のモデルを上回[うわまわ]っている。", "sentence_source": "generated"}, {"text": "今回の成績は、去年の自分を上回れなかった。", "target_word": "上回", "complexity_tier": "T3", "furigana": "今回[こんかい]の成績[せいせき]は、去年[きょねん]の自分[じぶん]を上回[うわまわ]れなかった。", "sentence_source": "generated"}, {"text": "品質への評価は、事前の想像をはるかに上回った。", "target_word": "上回", "complexity_tier": "T3", "furigana": "品質[ひんしつ]への評価[ひょうか]は、事前[じぜん]の想像[そうぞう]をはるかに上回[うわまわ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上回る", "label": "終止形"}, {"form": "上回った", "label": "過去形"}, {"form": "上回って", "label": "て形"}, {"form": "上回らない", "label": "ない形"}, {"form": "上回ります", "label": "ます形"}, {"form": "上回れば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "予想・目標・基準など比べる対象より、数や程度が高くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 漲っ (Zipf 1.92)']::text[], '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上回る", "is_correct": true, "explanation": "連体形。「それをはるかに上回る好奇心」と名詞を修飾し、文が成り立つ。"}, {"text": "上回って", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、ここに入ると文が崩れる。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、文が成り立たない。"}, {"text": "上回ろう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、好奇心を修飾する位置に入らない。"}], "explanations": {"上回る": "連体形。「それをはるかに上回る好奇心」と名詞を修飾し、文が成り立つ。", "上回って": "て形は名詞を直接修飾できず、ここに入ると文が崩れる。", "上回れ": "命令形は名詞を修飾できず、文が成り立たない。", "上回ろう": "意志形は名詞を修飾できず、好奇心を修飾する位置に入らない。"}, "sentence_index": 0, "correct_answer": "上回る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急な坂道を上回った。", "explanation": "ここは〈上る〉（のぼる）の意味。坂を登る動作は上回ると言わず、数や程度の基準超えを表さない。"}, {"text": "前の車を上回って、一気に追い抜いた。", "explanation": "ここは〈追い越す〉の意味。車を抜く動作は追い越すで、数や程度が基準より高いことには使わない。"}, {"text": "景色を上回った。", "explanation": "ここは〈眺める〉の意味。景色を見る動作は眺めるで、上回るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形（中止形）。「予算を上回り、」の語幹で、後ろの文へ続く形として正しい。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は文の途中で続かず、「、」の前に置けない。"}, {"text": "上回られ", "is_correct": false, "explanation": "受身の形で、主語と動作の関係が文に合わない。"}, {"text": "上回り方", "is_correct": false, "explanation": "名詞形で、動詞の位置には入らない。"}], "explanations": {"上回": "連用形（中止形）。「予算を上回り、」の語幹で、後ろの文へ続く形として正しい。", "上回れ": "命令形は文の途中で続かず、「、」の前に置けない。", "上回られ": "受身の形で、主語と動作の関係が文に合わない。", "上回り方": "名詞形で、動詞の位置には入らない。"}, "sentence_index": 6, "correct_answer": "上回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い荷物を上回った。", "explanation": "ここは〈持ち上げる〉の意味。物を持ち上げる動作は上回ると言わず、数や程度の基準超えを表さない。"}, {"text": "川を上回った。", "explanation": "ここは〈渡る〉の意味。川を越えて向こうへ行く動作は上回るとは言わない。"}, {"text": "扉を上回った。", "explanation": "ここは〈叩く〉の意味。扉を叩く動作は上回るとは言わず、数量の大小には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年の利益は、前年の数字を上回らる見込みだ。", "corrected_sentence": "今年の利益は、前年の数字を上回る見込みだ。", "error_description": "「見込み」を修飾する連体形は「上回る」。「上回らる」は存在しない誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形。「上回った」の語幹で、「った」の前に来る形として文に合う。"}, {"text": "上回る", "is_correct": false, "explanation": "辞書形は「った」に続けられず、この文では不適切。"}, {"text": "上回って", "is_correct": false, "explanation": "て形は「った」の前に置くと文が崩れる。"}, {"text": "上回れ", "is_correct": false, "explanation": "命令形は「った」に続かず、文の形として合わない。"}], "correct_form": "上回", "base_form": "上回る", "form_label": "連用形（た形の前）", "sentence_index": 1, "explanations": {"上回": "連用形。「上回った」の語幹で、「った」の前に来る形として文に合う。", "上回る": "辞書形は「った」に続けられず、この文では不適切。", "上回って": "て形は「った」の前に置くと文が崩れる。", "上回れ": "命令形は「った」に続かず、文の形として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今月の売り上げは、前月の実績に上回る見通しだ。", "corrected_sentence": "今月の売り上げは、前月の実績を上回る見通しだ。", "error_description": "「上回る」は目的語に「を」を取る。「実績に」は誤りで、正しくは「実績を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上回", "is_correct": true, "explanation": "連用形で、「上回っている」の語幹にあたる。「って」に続く形として正しい。"}, {"text": "上回らない", "is_correct": false, "explanation": "否定形で、「前のモデルを上回っている」という肯定の状態と合わない。"}, {"text": "上回ろう", "is_correct": false, "explanation": "意志形で、現在の状態を述べる文に合わない。"}, {"text": "上回った", "is_correct": false, "explanation": "た形は過去を表し、「っている」の現在の状態と合わない。"}], "correct_form": "上回", "base_form": "上回る", "form_label": "連用形（て形の語幹）", "sentence_index": 7, "explanations": {"上回": "連用形で、「上回っている」の語幹にあたる。「って」に続く形として正しい。", "上回らない": "否定形で、「前のモデルを上回っている」という肯定の状態と合わない。", "上回ろう": "意志形で、現在の状態を述べる文に合わない。", "上回った": "た形は過去を表し、「っている」の現在の状態と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「故郷に安住する」の「に」。落ち着く場所を示し、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「故郷を安住する」は目的語を取らない用法なので不自然。"}, {"text": "が", "is_correct": false, "explanation": "「故郷が安住する」は主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「故郷と安住する」は相手を示すが、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「故郷に安住する」の「に」。落ち着く場所を示し、正しい。", "を": "「故郷を安住する」は目的語を取らない用法なので不自然。", "が": "「故郷が安住する」は主語として不自然。", "と": "「故郷と安住する」は相手を示すが、意味が通らない。"}, "error_tags": {"に": "場所", "を": "目的語", "が": "主語", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「家に安住している」の「に」。落ち着く場所を示し、正しい。"}, {"text": "から", "is_correct": false, "explanation": "「家から安住している」は起点を示すが、落ち着く場所とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「家へ安住している」は方向を示すが、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「家の安住している」は名詞を続けられず、文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「家に安住している」の「に」。落ち着く場所を示し、正しい。", "から": "「家から安住している」は起点を示すが、落ち着く場所とは合わない。", "へ": "「家へ安住している」は方向を示すが、不自然。", "の": "「家の安住している」は名詞を続けられず、文が成立しない。"}, "error_tags": {"に": "場所", "から": "起点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "安心して住むこと。", "primary_collocate": null, "pronunciation": "あんじゅう", "ipa": "aɲdʑɯː", "syllable_count": 4, "sentences": [{"text": "洪水の心配がない高台は、家族が安住するのにふさわしい。", "target_word": "安住", "complexity_tier": "T3", "furigana": "洪水[こうずい]の心配[しんぱい]がない高台[たかだい]は、家族[かぞく]が安住[あんじゅう]するのにふさわしい。", "sentence_source": "generated"}, {"text": "兄は海外生活をやめて、故郷に安住することにした。", "target_word": "安住", "complexity_tier": "T3", "furigana": "兄[あに]は海外[かいがい]生活[せいかつ]をやめて、故郷[こきょう]に安住[あんじゅう]することにした。", "sentence_source": "generated"}, {"text": "難民たちは新しい国で安住を許され、ほっとした。", "target_word": "安住", "complexity_tier": "T3", "furigana": "難民[なんみん]たちは新[あたら]しい国[くに]で安住[あんじゅう]を許[ゆる]され、ほっとした。", "sentence_source": "generated"}, {"text": "夜も一人で歩けるほど安全な町なので、安住に向いている。", "target_word": "安住", "complexity_tier": "T3", "furigana": "夜[よる]も一人[ひとり]で歩[ある]けるほど安全[あんぜん]な町[まち]なので、安住[あんじゅう]に向[む]いている。", "sentence_source": "generated"}, {"text": "地震の多い国では、揺れに強い家でなければ安住できない。", "target_word": "安住", "complexity_tier": "T3", "furigana": "地震[じしん]の多[おお]い国[くに]では、揺[ゆ]れに強[つよ]い家[いえ]でなければ安住[あんじゅう]できない。", "sentence_source": "generated"}, {"text": "祖母は、庭のある小さな家で安住の日々を送っている。", "target_word": "安住", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、庭[にわ]のある小[ちい]さな家[いえ]で安住[あんじゅう]の日々[ひび]を送[おく]っている。", "sentence_source": "generated"}, {"text": "大家さんが親切なので、このアパートに長く安住したい。", "target_word": "安住", "complexity_tier": "T3", "furigana": "大家[おおや]さんが親切[しんせつ]なので、このアパートに長[なが]く安住[あんじゅう]したい。", "sentence_source": "generated"}, {"text": "保護された子猫は、やっと見つけた家に安住している。", "target_word": "安住", "complexity_tier": "T3", "furigana": "保護[ほご]された子猫[こねこ]は、やっと見[み]つけた家[いえ]に安住[あんじゅう]している。", "sentence_source": "generated"}, {"text": "安住できる住まいを探して、私たちは毎週不動産屋を回った。", "target_word": "安住", "complexity_tier": "T3", "furigana": "安住[あんじゅう]できる住[す]まいを探[さが]して、私[わたし]たちは毎週[まいしゅう]不動産屋[ふどうさんや]を回[まわ]った。", "sentence_source": "generated"}, {"text": "戦いのない世の中でなければ、人は安住することができない。", "target_word": "安住", "complexity_tier": "T3", "furigana": "戦[たたか]いのない世[よ]の中[なか]でなければ、人[ひと]は安住[あんじゅう]することができない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安住する", "label": "サ変動詞・辞書形"}, {"form": "安住した", "label": "過去形"}, {"form": "安住して", "label": "て形"}, {"form": "安住できない", "label": "可能の否定形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "危険や不安を感じずに安心して住むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安住", "is_correct": true, "explanation": "家族が落ち着いて住み続けるという意味で、「ふさわしい」と自然につながる。"}, {"text": "浪費", "is_correct": false, "explanation": "お金や物を無駄に使う意味で、住む場所の文脈には合わない。"}, {"text": "清算", "is_correct": false, "explanation": "お金の決済を終える意味で、「家族が〜するのにふさわしい」とは続かない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を置き換える作業で、家族の行為として文が成立しない。"}], "explanations": {"安住": "家族が落ち着いて住み続けるという意味で、「ふさわしい」と自然につながる。", "浪費": "お金や物を無駄に使う意味で、住む場所の文脈には合わない。", "清算": "お金の決済を終える意味で、「家族が〜するのにふさわしい」とは続かない。", "翻訳": "言葉を置き換える作業で、家族の行為として文が成立しない。"}, "sentence_index": 0, "correct_answer": "安住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古い橋は安住だから、大型トラックも渡れる。", "explanation": "ここは〈安全〉（危険がないこと）の意味。安住は落ち着いて暮らすことなので、橋には使わない。"}, {"text": "赤ちゃんは、ぐっすり安住している。", "explanation": "ここは〈安眠〉（安らかに眠ること）の意味。安住は住む場所に関する語なので、眠りには使わない。"}, {"text": "昼休みに、しばらく安住した。", "explanation": "ここは〈休憩〉の意味。安住は長く住み続けることなので、短い休みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安住", "is_correct": true, "explanation": "このアパートに長く住みたいという意味で、自然に続く。"}, {"text": "謝罪", "is_correct": false, "explanation": "相手に詫びる行為で、住む意味とは関係がない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真を撮る行為で、「アパートに長く」という文脈には合わない。"}, {"text": "購読", "is_correct": false, "explanation": "雑誌などを定期的に受け取ることで、住むことを表さない。"}], "explanations": {"安住": "このアパートに長く住みたいという意味で、自然に続く。", "謝罪": "相手に詫びる行為で、住む意味とは関係がない。", "撮影": "写真を撮る行為で、「アパートに長く」という文脈には合わない。", "購読": "雑誌などを定期的に受け取ることで、住むことを表さない。"}, "sentence_index": 6, "correct_answer": "安住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験に合格して、彼は安住のため息をついた。", "explanation": "ここは〈安堵〉（ほっとすること）の意味。安住は落ち着いて住み続けることなので、ため息には使わない。"}, {"text": "ホテルに一週間、安住した。", "explanation": "ここは〈滞在〉（一時的に泊まること）の意味。安住は長く住み続けることなので、短期の滞在には使わない。"}, {"text": "船は港に安住した。", "explanation": "ここは〈停泊〉（船が港に留まること）の意味。安住は人が住む場所に落ち着くことなので、船には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は田舎で安住された日々を送っている。", "corrected_sentence": "祖父は田舎で安住の日々を送っている。", "error_description": "「安住」に受け身の「された」を付けるのは誤り。「安住の日々」と名詞として使うのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52489, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい家を安住したい。", "corrected_sentence": "新しい家に安住したい。", "error_description": "「安住する」の落ち着く場所は「に」で示す。「を」は目的語の形で誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この町に安住する」の「に」。落ち着く場所を示し、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「町を安住する」は目的語を取らない用法なので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「町と安住する」は相手を示すが、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「町が安住する」は主語として不自然。"}], "correct_answer": "に", "explanations": {"に": "「この町に安住する」の「に」。落ち着く場所を示し、正しい。", "を": "「町を安住する」は目的語を取らない用法なので不自然。", "と": "「町と安住する」は相手を示すが、意味が通らない。", "が": "「町が安住する」は主語として不自然。"}, "error_tags": {"に": "場所", "を": "目的語", "と": "相手", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "心配なく、落ち着いて生活できる場所に住むこと。", "primary_collocate": null, "pronunciation": "あんじゅう", "ipa": "aɲdʑɯː", "syllable_count": 4, "sentences": [{"text": "それは、確立された安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "安住", "complexity_tier": "T4", "furigana": "それは、確立[かくりつ]された安住[あんじゅう]の地[ち]からの離脱[りだつ]であり、新[あら]たな社会的[しゃかいてき]文脈[ぶんみゃく]における自己[じこ]の再構築[さいこうちく]を迫[せま]られる、極[きわ]めて重要[じゅうよう]な通過儀礼[つうかぎれい]なのである。", "sentence_source": "mined"}, {"text": "長い旅の末、彼はようやく安住できる町にたどり着いた。", "target_word": "安住", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]の末[すえ]、彼[かれ]はようやく安住[あんじゅう]できる町[まち]にたどり着[つ]いた。", "sentence_source": "generated"}, {"text": "戦争で家を失った人々は、安住の地を求めて国境を越えた。", "target_word": "安住", "complexity_tier": "T3", "furigana": "戦争[せんそう]で家[いえ]を失[うしな]った人々[ひとびと]は、安住[あんじゅう]の地[ち]を求[もと]めて国境[こっきょう]を越[こ]えた。", "sentence_source": "generated"}, {"text": "老後は海の近くで安住したいと、夫婦は田舎に家を買った。", "target_word": "安住", "complexity_tier": "T3", "furigana": "老後[ろうご]は海[うみ]の近[ちか]くで安住[あんじゅう]したいと、夫婦[ふうふ]は田舎[いなか]に家[いえ]を買[か]った。", "sentence_source": "generated"}, {"text": "治安のよい地域でなければ、子どもを連れて安住することは難しい。", "target_word": "安住", "complexity_tier": "T3", "furigana": "治安[ちあん]のよい地域[ちいき]でなければ、子[こ]どもを連[つ]れて安住[あんじゅう]することは難[むずか]しい。", "sentence_source": "generated"}, {"text": "転勤が多かった父は、定年後にやっと安住の場所を手に入れた。", "target_word": "安住", "complexity_tier": "T3", "furigana": "転勤[てんきん]が多[おお]かった父[ちち]は、定年後[ていねんご]にやっと安住[あんじゅう]の場所[ばしょ]を手[て]に入[い]れた。", "sentence_source": "generated"}, {"text": "医師の仕事を辞めた彼は、静かな島で安住の暮らしを始めた。", "target_word": "安住", "complexity_tier": "T3", "furigana": "医師[いし]の仕事[しごと]を辞[や]めた彼[かれ]は、静[しず]かな島[しま]で安住[あんじゅう]の暮[く]らしを始[はじ]めた。", "sentence_source": "generated"}, {"text": "家賃が急に上がったので、この町に安住するのは無理になった。", "target_word": "安住", "complexity_tier": "T3", "furigana": "家賃[やちん]が急[きゅう]に上[あ]がったので、この町[まち]に安住[あんじゅう]するのは無理[むり]になった。", "sentence_source": "generated"}, {"text": "彼女は各地を転々としたあと、山あいの村を安住の地に選んだ。", "target_word": "安住", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は各地[かくち]を転々[てんてん]としたあと、山[やま]あいの村[むら]を安住[あんじゅう]の地[ち]に選[えら]んだ。", "sentence_source": "generated"}, {"text": "騒音のない静かな環境こそ、私にとっての安住の条件だ。", "target_word": "安住", "complexity_tier": "T3", "furigana": "騒音[そうおん]のない静[しず]かな環境[かんきょう]こそ、私[わたし]にとっての安住[あんじゅう]の条件[じょうけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安住する", "label": "サ変動詞・辞書形"}, {"form": "安住した", "label": "過去形"}, {"form": "安住して", "label": "て形"}, {"form": "安住できる", "label": "可能形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "不安なく落ち着いて暮らせる場所に身を置いて住み続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安住", "is_correct": true, "explanation": "「確立された安住の地」で、落ち着いて住める場所を指す語として自然。"}, {"text": "不安", "is_correct": false, "explanation": "心配を表す語で、「確立された」に続けると場所の意味にならない。"}, {"text": "混乱", "is_correct": false, "explanation": "秩序が乱れた状態を指し、「の地」を修飾すると意味が通らない。"}, {"text": "失業", "is_correct": false, "explanation": "仕事がない状態を指し、「の地」に続けると不自然。"}], "explanations": {"安住": "「確立された安住の地」で、落ち着いて住める場所を指す語として自然。", "不安": "心配を表す語で、「確立された」に続けると場所の意味にならない。", "混乱": "秩序が乱れた状態を指し、「の地」を修飾すると意味が通らない。", "失業": "仕事がない状態を指し、「の地」に続けると不自然。"}, "sentence_index": 0, "correct_answer": "安住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんは、ぐっすり安住していた。", "explanation": "ここは〈安眠〉（安らかに眠ること）の意味。安住は住む場所に関する語なので、眠りには使わない。"}, {"text": "彼はホテルに一週間、安住した。", "explanation": "ここは〈滞在〉（一時的に泊まること）の意味。安住は長く落ち着いて住み続けることなので、短期の滞在には使わない。"}, {"text": "株価が安住して、ずっと同じ値段を保っている。", "explanation": "ここは〈安定〉（変化せず保たれること）の意味。安住は場所に落ち着いて住むことで、株価の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安住", "is_correct": true, "explanation": "静かな島で落ち着いて暮らす意味で、「安住の暮らし」として自然。"}, {"text": "調査", "is_correct": false, "explanation": "事実を調べる行為で、暮らしの様子を表す語ではない。"}, {"text": "演奏", "is_correct": false, "explanation": "音楽を奏でる行為で、暮らしには結びつかない。"}, {"text": "交渉", "is_correct": false, "explanation": "条件を話し合って決める行為で、「の暮らし」とは続かない。"}], "explanations": {"安住": "静かな島で落ち着いて暮らす意味で、「安住の暮らし」として自然。", "調査": "事実を調べる行為で、暮らしの様子を表す語ではない。", "演奏": "音楽を奏でる行為で、暮らしには結びつかない。", "交渉": "条件を話し合って決める行為で、「の暮らし」とは続かない。"}, "sentence_index": 6, "correct_answer": "安住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験に合格して、彼は安住のため息をついた。", "explanation": "ここは〈安堵〉（ほっとすること）の意味。安住は落ち着いて住み続けることなので、ため息には使わない。"}, {"text": "このビルは安住で、地震の揺れにも強い。", "explanation": "ここは〈安全〉（危険がないこと）の意味。安住は落ち着いて暮らすことなので、ビルには使わない。"}, {"text": "昼休みに、しばらく安住した。", "explanation": "ここは〈休憩〉の意味。安住は長く住み続けることなので、短い休みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族は、郊外の静かな町を安住することを決めた。", "corrected_sentence": "家族は、郊外の静かな町に安住することを決めた。", "error_description": "「安住する」の場所は「に」で示す。「を」は目的語を取る形で誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は海辺の町に安住して。", "corrected_sentence": "祖父は海辺の町に安住している。", "error_description": "文末が「安住して。」では述語が完成していない。「安住している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『公開初日に見に行く』と時点を示し、文意に合う。"}, {"text": "と", "is_correct": false, "explanation": "『公開初日と見に行く』は並列の関係になり、行動の時を表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の〈で〉は『公開初日で見に行く』となり、時点の表現として不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語の〈が〉は『公開初日が見に行く』となり、人が行動する文の主語にならない。"}], "correct_answer": "に", "explanations": {"に": "『公開初日に見に行く』と時点を示し、文意に合う。", "と": "『公開初日と見に行く』は並列の関係になり、行動の時を表せない。", "で": "手段・場所の〈で〉は『公開初日で見に行く』となり、時点の表現として不自然。", "が": "主語の〈が〉は『公開初日が見に行く』となり、人が行動する文の主語にならない。"}, "error_tags": {"と": "並列・相手の格", "で": "手段・場所の格", "が": "主語の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
