INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まる最初の日。", "primary_collocate": null, "pronunciation": "しょにち", "ipa": "ɕonit͡ɕi", "syllable_count": 3, "sentences": [{"text": "展覧会の初日には、朝から長い列ができた。", "target_word": "初日", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]の初日[しょにち]には、朝[あさ]から長[なが]い列[れつ]ができた。", "sentence_source": "generated"}, {"text": "映画は公開初日に見に行くつもりだ。", "target_word": "初日", "complexity_tier": "T3", "furigana": "映画[えいが]は公開[こうかい]初日[しょにち]に見[み]に行[い]くつもりだ。", "sentence_source": "generated"}, {"text": "大会の初日は、雨のため試合が中止になった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "大会[たいかい]の初日[しょにち]は、雨[あめ]のため試合[しあい]が中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "新商品の発売初日に、店の在庫がなくなった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "新商品[しんしょうひん]の発売[はつばい]初日[しょにち]に、店[みせ]の在庫[ざいこ]がなくなった。", "sentence_source": "generated"}, {"text": "舞台の初日は、役者も客席も特別な空気に包まれる。", "target_word": "初日", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の初日[しょにち]は、役者[やくしゃ]も客席[きゃくせき]も特別[とくべつ]な空気[くうき]に包[つつ]まれる。", "sentence_source": "generated"}, {"text": "旅行の初日から天気に恵まれ、気分がよかった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "旅行[りょこう]の初日[しょにち]から天気[てんき]に恵[めぐ]まれ、気分[きぶん]がよかった。", "sentence_source": "generated"}, {"text": "工事の初日に、近所へあいさつ回りをした。", "target_word": "初日", "complexity_tier": "T3", "furigana": "工事[こうじ]の初日[しょにち]に、近所[きんじょ]へあいさつ回[まわ]りをした。", "sentence_source": "generated"}, {"text": "セールの初日だけ、全品が半額になる。", "target_word": "初日", "complexity_tier": "T3", "furigana": "セールの初日[しょにち]だけ、全品[ぜんぴん]が半額[はんがく]になる。", "sentence_source": "generated"}, {"text": "裁判の初日、傍聴席はほぼ満席だった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "裁判[さいばん]の初日[しょにち]、傍聴席[ぼうちょうせき]はほぼ満席[まんせき]だった。", "sentence_source": "generated"}, {"text": "祭りの初日は子ども向けの催しが中心だ。", "target_word": "初日", "complexity_tier": "T3", "furigana": "祭[まつ]りの初日[しょにち]は子[こ]ども向[む]けの催[もよお]しが中心[ちゅうしん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初日", "label": "基本形"}, {"form": "初日の", "label": "連体形（の）"}, {"form": "初日に", "label": "時を表す形（に）"}, {"form": "初日から", "label": "起点を表す形（から）"}], "register": "標準", "sense_fingerprint": "催しや期間など何かが始まる最初の日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: あいさつ回り (Zipf 1.44)']::text[], '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初日", "is_correct": true, "explanation": "『展覧会の初日には』と時を示し、朝から長い列ができたという文に合う。"}, {"text": "図録", "is_correct": false, "explanation": "『図録には朝から長い列ができた』は意味が通らず、列を作る主体にならない。"}, {"text": "照明", "is_correct": false, "explanation": "『照明には朝から長い列ができた』は不自然で、列の文脈と結びつかない。"}, {"text": "作品", "is_correct": false, "explanation": "『作品には朝から長い列ができた』は主語として不自然で、『展覧会の〜には』の時の指定にも合わない。"}], "explanations": {"初日": "『展覧会の初日には』と時を示し、朝から長い列ができたという文に合う。", "図録": "『図録には朝から長い列ができた』は意味が通らず、列を作る主体にならない。", "照明": "『照明には朝から長い列ができた』は不自然で、列の文脈と結びつかない。", "作品": "『作品には朝から長い列ができた』は主語として不自然で、『展覧会の〜には』の時の指定にも合わない。"}, "sentence_index": 0, "correct_answer": "初日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この催しの初日は、開幕の前日に終わった。", "explanation": "〈前日〉の意味で使っているが、初日は始まりの日なので、開幕より前に終わるという表現は成り立たない。"}, {"text": "展覧会の初日に、閉幕前の駆け込みで客が集中した。", "explanation": "〈駆け込み〉は〈最終日〉の語感で、初日には閉幕前の混雑は起きない。語の取り違え。"}, {"text": "今月の初日は、十日間にわたって続いた。", "explanation": "〈上旬〉の意味を取り違えた用法。初日は一日を指し、十日間の期間は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初日", "is_correct": true, "explanation": "『工事の初日に』と時点を示し、近所へあいさつ回りをした文脈に合う。"}, {"text": "看板", "is_correct": false, "explanation": "『看板に、近所へあいさつ回りをした』は主体にならず、意味が通らない。"}, {"text": "重機", "is_correct": false, "explanation": "『重機に、近所へあいさつ回りをした』は主語・行動の関係が成立しない。"}, {"text": "資材", "is_correct": false, "explanation": "『資材に、近所へあいさつ回りをした』は行為の主体として不自然で、文脈にも合わない。"}], "explanations": {"初日": "『工事の初日に』と時点を示し、近所へあいさつ回りをした文脈に合う。", "看板": "『看板に、近所へあいさつ回りをした』は主体にならず、意味が通らない。", "重機": "『重機に、近所へあいさつ回りをした』は主語・行動の関係が成立しない。", "資材": "『資材に、近所へあいさつ回りをした』は行為の主体として不自然で、文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "初日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この歌の初日は一九八〇年代だ。", "explanation": "〈初出〉の意味を取り違えた用法。初日は物事の始まりの日を指し、作品が初めて世に出た時期は表せない。"}, {"text": "この祭りの初日は、最後の花火で幕を閉じた。", "explanation": "〈最終日〉の意味で使っているが、初日は始まりの日なので、終わりを表す場面では使えない。"}, {"text": "初日に、三年分の宿題をまとめて終えた。", "explanation": "〈初日〉は始まりの日。三年分をまとめて終えるのは〈最後の日〉の内容で、初日とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "映画の公開初日が、友だちと見に行った。", "corrected_sentence": "映画の公開初日に、友だちと見に行った。", "error_description": "〈初日〉は時点を表すので〈に〉が正しい。〈が〉だと初日が主語になり、見に行く人が成り立たないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52491, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "セールの初日を、店で服を買った。", "corrected_sentence": "セールの初日に、店で服を買った。", "error_description": "〈初日〉は時点を表すので〈に〉が正しいが、〈を〉を使っているため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
