INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『アルバイトの初日は』と主題を示し、文全体の話題として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "『初日を、仕事の流れを覚えるだけで精いっぱいだった』は目的語の関係が成り立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す〈へ〉は『初日へ』となり、時を表す語に続けられない。"}, {"text": "と", "is_correct": false, "explanation": "並列の〈と〉は『初日と、仕事の流れを覚える』となり、文の述語と結びつかない。"}], "correct_answer": "は", "explanations": {"は": "『アルバイトの初日は』と主題を示し、文全体の話題として自然に続く。", "を": "『初日を、仕事の流れを覚えるだけで精いっぱいだった』は目的語の関係が成り立たず不自然。", "へ": "方向を示す〈へ〉は『初日へ』となり、時を表す語に続けられない。", "と": "並列の〈と〉は『初日と、仕事の流れを覚える』となり、文の述語と結びつかない。"}, "error_tags": {"を": "目的語の格", "へ": "方向の格", "と": "並列・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まる最初の日。特に、学校や仕事など、新しい生活の始まりの日を指す。", "primary_collocate": null, "pronunciation": "しょにち", "ipa": "ɕonit͡ɕi", "syllable_count": 3, "sentences": [{"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "初日", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の人生[じんせい]におけるこの学校[がっこう]の初日[しょにち]は、単[たん]なる物理的[ぶつりてき]な場所[ばしょ]の移動[いどう]を意味[いみ]するものではない。", "sentence_source": "mined"}, {"text": "入社初日、私は緊張して朝早く会社に着いた。", "target_word": "初日", "complexity_tier": "T3", "furigana": "入社[にゅうしゃ]初日[しょにち]、私[わたし]は緊張[きんちょう]して朝[あさ]早[はや]く会社[かいしゃ]に着[つ]いた。", "sentence_source": "generated"}, {"text": "初日の授業は自己紹介だけで終わった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "初日[しょにち]の授業[じゅぎょう]は自己[じこ]紹介[しょうかい]だけで終[お]わった。", "sentence_source": "generated"}, {"text": "新しい仕事の初日に、先輩が丁寧に案内してくれた。", "target_word": "初日", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]の初日[しょにち]に、先輩[せんぱい]が丁寧[ていねい]に案内[あんない]してくれた。", "sentence_source": "generated"}, {"text": "初日からいきなり遅刻してしまい、とても恥ずかしかった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "初日[しょにち]からいきなり遅刻[ちこく]してしまい、とても恥[は]ずかしかった。", "sentence_source": "generated"}, {"text": "中学校の初日、知らない顔ばかりで不安だった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "中学校[ちゅうがっこう]の初日[しょにち]、知[し]らない顔[かお]ばかりで不安[ふあん]だった。", "sentence_source": "generated"}, {"text": "転校初日に友だちができたので、息子は安心したようだ。", "target_word": "初日", "complexity_tier": "T3", "furigana": "転校[てんこう]初日[しょにち]に友[とも]だちができたので、息子[むすこ]は安心[あんしん]したようだ。", "sentence_source": "generated"}, {"text": "アルバイトの初日は、仕事の流れを覚えるだけで精いっぱいだった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "アルバイトの初日[しょにち]は、仕事[しごと]の流[なが]れを覚[おぼ]えるだけで精[せい]いっぱいだった。", "sentence_source": "generated"}, {"text": "初日の夜、新しい寮でなかなか眠れなかった。", "target_word": "初日", "complexity_tier": "T3", "furigana": "初日[しょにち]の夜[よる]、新[あたら]しい寮[りょう]でなかなか眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "留学の初日、道に迷って学校に着くのが遅れた。", "target_word": "初日", "complexity_tier": "T3", "furigana": "留学[りゅうがく]の初日[しょにち]、道[みち]に迷[まよ]って学校[がっこう]に着[つ]くのが遅[おく]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初日", "label": "基本形"}, {"form": "初日の", "label": "連体形（の）"}, {"form": "初日に", "label": "時を表す形（に）"}, {"form": "初日から", "label": "起点を表す形（から）"}], "register": "標準", "sense_fingerprint": "学校や仕事など新生活の最初の日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初日", "is_correct": true, "explanation": "文の主語として『この学校の初日』となり、学校の新生活の始まりを表して文意に合う。"}, {"text": "天気", "is_correct": false, "explanation": "『この学校の天気は』では主語として成り立たず、『移動を意味する』という述語とも合わない。"}, {"text": "体重", "is_correct": false, "explanation": "『この学校の体重』は意味が通らず、文の主題にならない。"}, {"text": "血液型", "is_correct": false, "explanation": "『この学校の血液型』は意味が通らず、文の主題にならない。"}], "explanations": {"初日": "文の主語として『この学校の初日』となり、学校の新生活の始まりを表して文意に合う。", "天気": "『この学校の天気は』では主語として成り立たず、『移動を意味する』という述語とも合わない。", "体重": "『この学校の体重』は意味が通らず、文の主題にならない。", "血液型": "『この学校の血液型』は意味が通らず、文の主題にならない。"}, "sentence_index": 0, "correct_answer": "初日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この研修の初日は、三週間にわたって続いた。", "explanation": "〈研修期間〉の意味で使っているが、初日は一日を指すので、三週間にわたる期間は表せない。"}, {"text": "この連続ドラマの初日は、特別番組として一時間放送された。", "explanation": "〈初回〉の意味を取り違えた用法。初日は日単位の始まりを指すので、連続番組の第一回には使えない。"}, {"text": "この雑誌の初日は一九九五年だ。", "explanation": "ここは〈初出〉の意味を取り違えた用法。初日は日単位の始まりの日を指すので、刊行の初めての時期には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初日", "is_correct": true, "explanation": "『転校初日に』の形で、転校の始まりの日を表し、文意に合う。"}, {"text": "通学路", "is_correct": false, "explanation": "『転校通学路に友だちができた』は意味が通らず、時を表す場所名として不自然。"}, {"text": "出席簿", "is_correct": false, "explanation": "『転校出席簿に友だちができた』は意味が通らず、友だちができる場面と合わない。"}, {"text": "校庭", "is_correct": false, "explanation": "『転校校庭に』は時を表さず、『友だちができたので安心した』という因果の流れに合わない。"}], "explanations": {"初日": "『転校初日に』の形で、転校の始まりの日を表し、文意に合う。", "通学路": "『転校通学路に友だちができた』は意味が通らず、時を表す場所名として不自然。", "出席簿": "『転校出席簿に友だちができた』は意味が通らず、友だちができる場面と合わない。", "校庭": "『転校校庭に』は時を表さず、『友だちができたので安心した』という因果の流れに合わない。"}, "sentence_index": 6, "correct_answer": "初日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "留学の初日、帰国の準備を全部終えた。", "explanation": "〈最終日〉を使う場面（最終日に帰国準備を終える）の語感。初日は最初の日なので、ここでは合わない。"}, {"text": "来月の初日は、十日間続く繁忙期だった。", "explanation": "〈上旬〉の意味を取り違えた用法。初日は一日を指し、十日間にわたる期間は表せない。"}, {"text": "この大会の初日は、決勝戦の翌日に行われた。", "explanation": "〈翌日〉の意味で使っているが、初日は大会の始まりの日なので、決勝の後の日とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社での初日が、緊張しながら自己紹介をした。", "corrected_sentence": "会社での初日に、緊張しながら自己紹介をした。", "error_description": "〈初日〉は時点を表すので〈に〉が正しい。〈が〉だと初日が主語になり、自己紹介をする人にならないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52492, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "留学先の初日が、現地の友だちと昼食を食べた。", "corrected_sentence": "留学先の初日に、現地の友だちと昼食を食べた。", "error_description": "〈初日〉は時点を表すので〈に〉が正しい。〈が〉だと初日が主語になり、食事をする人にならないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
