INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52493, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "気持ちや力が、いっぱいになること。", "primary_collocate": null, "pronunciation": "みなぎる", "ipa": "minaɡiɾɯ", "syllable_count": 4, "sentences": [{"text": "試合の朝、チーム全体に闘志が漲っていた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "試合[しあい]の朝[あさ]、チーム全体[ぜんたい]に闘志[とうし]が漲[みなぎ]っていた。", "sentence_source": "generated"}, {"text": "休みを取ったおかげで、体中に元気が漲る。", "target_word": "漲る", "complexity_tier": "T3", "furigana": "休[やす]みを取[と]ったおかげで、体中[からだじゅう]に元気[げんき]が漲[みなぎ]る。", "sentence_source": "generated"}, {"text": "新入社員の目には、やる気が漲っていた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]の目[め]には、やる気[き]が漲[みなぎ]っていた。", "sentence_source": "generated"}, {"text": "彼女の演奏には、強い情熱が漲っている。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の演奏[えんそう]には、強[つよ]い情熱[じょうねつ]が漲[みなぎ]っている。", "sentence_source": "generated"}, {"text": "合格の知らせを聞いて、全身に力が漲ってきた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "合格[ごうかく]の知[し]らせを聞[き]いて、全身[ぜんしん]に力[ちから]が漲[みなぎ]ってきた。", "sentence_source": "generated"}, {"text": "決勝戦を前に、選手たちは自信が漲った表情で入場した。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "決勝戦[けっしょうせん]を前[まえ]に、選手[せんしゅ]たちは自信[じしん]が漲[みなぎ]った表情[ひょうじょう]で入場[にゅうじょう]した。", "sentence_source": "generated"}, {"text": "初めての舞台に立つ少年は、勇気が漲って堂々としていた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "初[はじ]めての舞台[ぶたい]に立[た]つ少年[しょうねん]は、勇気[ゆうき]が漲[みなぎ]って堂々[どうどう]としていた。", "sentence_source": "generated"}, {"text": "朝のラジオ体操のあと、体に活力が漲るのを感じた。", "target_word": "漲る", "complexity_tier": "T3", "furigana": "朝[あさ]のラジオ体操[たいそう]のあと、体[からだ]に活力[かつりょく]が漲[みなぎ]るのを感[かん]じた。", "sentence_source": "generated"}, {"text": "会場には、開幕を待つ観客の期待が漲っていた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "会場[かいじょう]には、開幕[かいまく]を待[ま]つ観客[かんきゃく]の期待[きたい]が漲[みなぎ]っていた。", "sentence_source": "generated"}, {"text": "彼の言葉には、国を守る覚悟が漲っていた。", "target_word": "漲っ", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]には、国[くに]を守[まも]る覚悟[かくご]が漲[みなぎ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "漲る", "label": "辞書形"}, {"form": "漲った", "label": "過去形"}, {"form": "漲って", "label": "て形"}, {"form": "漲らない", "label": "否定形"}, {"form": "漲り", "label": "連用形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "気持ちや力が体や場に満ちあふれる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漲っ", "is_correct": true, "explanation": "『闘志が漲っていた』の形で、気持ちが満ちあふれている状態を表し、文意に合う。"}, {"text": "漲る", "is_correct": false, "explanation": "『漲るていた』となり、て形の接続が成立せず空欄に入らない。"}, {"text": "漲り", "is_correct": false, "explanation": "『漲りていた』となり、連用形に〈て〉が続く形として不自然。"}, {"text": "漲れ", "is_correct": false, "explanation": "命令形の『漲れ』は『ていた』と続かず、過去の状態の文に入らない。"}], "explanations": {"漲っ": "『闘志が漲っていた』の形で、気持ちが満ちあふれている状態を表し、文意に合う。", "漲る": "『漲るていた』となり、て形の接続が成立せず空欄に入らない。", "漲り": "『漲りていた』となり、連用形に〈て〉が続く形として不自然。", "漲れ": "命令形の『漲れ』は『ていた』と続かず、過去の状態の文に入らない。"}, "sentence_index": 0, "correct_answer": "漲っ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の中には、お菓子が漲っていた。", "explanation": "〈詰まる〉の場面。〈漲る〉は気持ちや力が満ちあふれる意味で、物がいっぱい詰まる様子には使わない。"}, {"text": "食べすぎて、お腹が漲った。", "explanation": "お腹が膨れる場面では〈膨れる〉を使う。〈漲る〉の語感とは合わない。"}, {"text": "部屋にガスが漲った。", "explanation": "〈充満〉の場面。〈漲る〉は水や気持ちが満ちる時に使い、気体が広がる時には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漲っ", "is_correct": true, "explanation": "『勇気が漲って堂々としていた』の形で、気持ちが満ちている状態を表し、文意に合う。"}, {"text": "漲ら", "is_correct": false, "explanation": "『漲らて』となり、未然形に〈て〉が続く形として成立しない。"}, {"text": "漲ろ", "is_correct": false, "explanation": "意志形の『漲ろ』は『て堂々としていた』と続かず、状態を述べる文に入らない。"}, {"text": "漲らず", "is_correct": false, "explanation": "『漲らずて』は接続が成立せず、『堂々としていた』と続く文の流れにも合わない。"}], "explanations": {"漲っ": "『勇気が漲って堂々としていた』の形で、気持ちが満ちている状態を表し、文意に合う。", "漲ら": "『漲らて』となり、未然形に〈て〉が続く形として成立しない。", "漲ろ": "意志形の『漲ろ』は『て堂々としていた』と続かず、状態を述べる文に入らない。", "漲らず": "『漲らずて』は接続が成立せず、『堂々としていた』と続く文の流れにも合わない。"}, "sentence_index": 6, "correct_answer": "漲っ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "借金が漲って、返済が遅れた。", "explanation": "〈かさむ〉の意味で使っているが、〈漲る〉は気持ちや力が満ちあふれる意味で、借金の増加には〈かさむ〉を使う。"}, {"text": "窓の外に霧が漲った。", "explanation": "〈立ちこめる〉の場面。霧が広がる様子に〈漲る〉を使うのは不自然で、語の取り違えになる。"}, {"text": "この店の売上は漲っている。", "explanation": "〈伸びる〉の場面。売上の増加には〈漲る〉を使わず、語の意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝、体中に元気が漲りていた。", "corrected_sentence": "朝、体中に元気が漲っていた。", "error_description": "〈漲る〉のて形は〈漲って〉が正しい。〈漲りて〉は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "漲る", "is_correct": true, "explanation": "『元気が漲る。』と文を言い切る辞書形で、現在の状態を述べる文に合う。"}, {"text": "漲れ", "is_correct": false, "explanation": "命令形の『漲れ』は文を命令で言い切る形となり、休みの結果を述べる文に合わない。"}, {"text": "漲って", "is_correct": false, "explanation": "て形は文を言い切らず、『元気が漲って。』では文が終わらない。"}, {"text": "漲らない", "is_correct": false, "explanation": "否定形は『元気が漲らない』となり、休みの効果を述べる文の内容と反する。"}], "correct_form": "漲る", "base_form": "漲る", "form_label": "辞書形（終止形）", "sentence_index": 1, "explanations": {"漲る": "『元気が漲る。』と文を言い切る辞書形で、現在の状態を述べる文に合う。", "漲れ": "命令形の『漲れ』は文を命令で言い切る形となり、休みの結果を述べる文に合わない。", "漲って": "て形は文を言い切らず、『元気が漲って。』では文が終わらない。", "漲らない": "否定形は『元気が漲らない』となり、休みの効果を述べる文の内容と反する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52493, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舞台の袖には、緊張を漲っていた。", "corrected_sentence": "舞台の袖には、緊張が漲っていた。", "error_description": "〈漲る〉の主語（緊張）には主格の〈が〉が正しい。〈を〉は目的語を示すため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "漲る", "is_correct": true, "explanation": "『活力が漲るのを感じた』の形で、名詞句（〜のを）を修飾する辞書形として正しい。"}, {"text": "漲れ", "is_correct": false, "explanation": "命令形の『漲れ』は『漲れのを感じた』となり、名詞を修飾できない。"}, {"text": "漲ら", "is_correct": false, "explanation": "未然形の『漲ら』は名詞を修飾できず、『漲らのを感じた』は成立しない。"}, {"text": "漲ろう", "is_correct": false, "explanation": "意志形の『漲ろう』は『漲ろうのを感じた』となり、名詞を修飾できない。"}], "correct_form": "漲る", "base_form": "漲る", "form_label": "辞書形（体言修飾）", "sentence_index": 7, "explanations": {"漲る": "『活力が漲るのを感じた』の形で、名詞句（〜のを）を修飾する辞書形として正しい。", "漲れ": "命令形の『漲れ』は『漲れのを感じた』となり、名詞を修飾できない。", "漲ら": "未然形の『漲ら』は名詞を修飾できず、『漲らのを感じた』は成立しない。", "漲ろう": "意志形の『漲ろう』は『漲ろうのを感じた』となり、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「近所の教室でピアノを習う」で、習う場所を表す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「教室がピアノを習う」では教室が習う主体になり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「教室をピアノを習う」は目的語が重なり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「教室のピアノを習う」では教室がピアノの所有者になり、意味が合わない。"}], "correct_answer": "で", "explanations": {"で": "「近所の教室でピアノを習う」で、習う場所を表す正しい助詞。", "が": "「教室がピアノを習う」では教室が習う主体になり、不自然。", "を": "「教室をピアノを習う」は目的語が重なり、文が成り立たない。", "の": "「教室のピアノを習う」では教室がピアノの所有者になり、意味が合わない。"}, "error_tags": {"で": "動作の場所", "が": "主語", "を": "目的語", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「水泳の教室に通い始める」で、通う先を表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「教室を通い始める」は目的語として不自然で、「通う」の行き先を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「教室が通い始める」では教室が主語になり、意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「教室と通い始める」は並列の形になり、通う先の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「水泳の教室に通い始める」で、通う先を表す正しい助詞。", "を": "「教室を通い始める」は目的語として不自然で、「通う」の行き先を示せない。", "が": "「教室が通い始める」では教室が主語になり、意味が合わない。", "と": "「教室と通い始める」は並列の形になり、通う先の意味にならない。"}, "error_tags": {"に": "行き先", "を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が集まって勉強するところです。", "primary_collocate": null, "pronunciation": "きょうしつ", "ipa": "kʲoːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "仕事のあと、駅前の教室で中国語を勉強しています。", "target_word": "教室", "complexity_tier": "T3", "furigana": "仕事[しごと]のあと、駅前[えきまえ]の教室[きょうしつ]で中国語[ちゅうごくご]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "私は週に一回、近所の教室でピアノを習っています。", "target_word": "教室", "complexity_tier": "T3", "furigana": "私[わたし]は週[しゅう]に一回[いっかい]、近所[きんじょ]の教室[きょうしつ]でピアノを習[なら]っています。", "sentence_source": "generated"}, {"text": "この教室では、大人も子どもも一緒に絵を学べます。", "target_word": "教室", "complexity_tier": "T3", "furigana": "この教室[きょうしつ]では、大人[おとな]も子[こ]どもも一緒[いっしょ]に絵[え]を学[まな]べます。", "sentence_source": "generated"}, {"text": "駅の近くに、英語を教える小さな教室がある。", "target_word": "教室", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、英語[えいご]を教[おし]える小[ちい]さな教室[きょうしつ]がある。", "sentence_source": "generated"}, {"text": "日曜日の朝は、料理を習う人たちで教室がにぎわう。", "target_word": "教室", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]は、料理[りょうり]を習[なら]う人[ひと]たちで教室[きょうしつ]がにぎわう。", "sentence_source": "generated"}, {"text": "初めてその教室に通った日は、少し緊張しました。", "target_word": "教室", "complexity_tier": "T3", "furigana": "初[はじ]めてその教室[きょうしつ]に通[かよ]った日[ひ]は、少[すこ]し緊張[きんちょう]しました。", "sentence_source": "generated"}, {"text": "母は書道の教室を開いて、近所の子どもたちに教えている。", "target_word": "教室", "complexity_tier": "T3", "furigana": "母[はは]は書道[しょどう]の教室[きょうしつ]を開[ひら]いて、近所[きんじょ]の子[こ]どもたちに教[おし]えている。", "sentence_source": "generated"}, {"text": "水泳の教室に通い始めてから、泳ぐのが楽しくなった。", "target_word": "教室", "complexity_tier": "T3", "furigana": "水泳[すいえい]の教室[きょうしつ]に通[かよ]い始[はじ]めてから、泳[およ]ぐのが楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "この教室は月謝が安いので、学生にも人気がある。", "target_word": "教室", "complexity_tier": "T3", "furigana": "この教室[きょうしつ]は月謝[げっしゃ]が安[やす]いので、学生[がくせい]にも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "友達に誘われて、週末の絵の教室を見学した。", "target_word": "教室", "complexity_tier": "T3", "furigana": "友達[ともだち]に誘[さそ]われて、週末[しゅうまつ]の絵[え]の教室[きょうしつ]を見学[けんがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教室", "label": "基本形"}], "register": "中立", "sense_fingerprint": "習い事などを学ぶために人が集まる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: にぎわう (Zipf 2.48)','sentence 8 above tier T2: contains vocabulary far above tier T2: 月謝 (Zipf 2.27)']::text[], 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "「駅前の教室で中国語を勉強する」と続き、習い事の場所を指す正しい語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は場所ではないので、「駅前の天気で勉強する」は成り立たない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は場所ではなく、「駅前の電話で中国語を勉強」は不自然。"}, {"text": "鉛筆", "is_correct": false, "explanation": "道具の名前で、学ぶ場所には使えない。"}], "explanations": {"教室": "「駅前の教室で中国語を勉強する」と続き、習い事の場所を指す正しい語。", "天気": "天気は場所ではないので、「駅前の天気で勉強する」は成り立たない。", "電話": "電話は場所ではなく、「駅前の電話で中国語を勉強」は不自然。", "鉛筆": "道具の名前で、学ぶ場所には使えない。"}, "sentence_index": 0, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事のあと、駅前の教室で貯金を下ろした。", "explanation": "ここは銀行（お金を預けたり下ろしたりする場所）の意味。教室は人が学ぶ場所で、お金の出し入れには使わない。"}, {"text": "週末は、駅前の教室に車を止めた。", "explanation": "ここは駐車場（車を止める場所）の意味。教室は人が学ぶ場所で、車を止める場所には使わない。"}, {"text": "週末は、駅前の教室で観覧車に乗って遊んだ。", "explanation": "ここは遊園地（乗り物で遊ぶ施設）の意味。教室は学ぶ場所で、乗り物で遊ぶ場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "「母は書道の教室を開いて」と続き、教えるための場所を指す正しい語。"}, {"text": "天井", "is_correct": false, "explanation": "天井は場所を開くものではなく、「天井を開く」は成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空のもので、「書道の雲を開く」は意味をなさない。"}, {"text": "湖", "is_correct": false, "explanation": "湖は自然の地形で、教えるための場所を開く文には合わない。"}], "explanations": {"教室": "「母は書道の教室を開いて」と続き、教えるための場所を指す正しい語。", "天井": "天井は場所を開くものではなく、「天井を開く」は成り立たない。", "雲": "雲は空のもので、「書道の雲を開く」は意味をなさない。", "湖": "湖は自然の地形で、教えるための場所を開く文には合わない。"}, "sentence_index": 6, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お正月は、駅前の教室で初詣をした。", "explanation": "ここは神社（参拝する場所）の意味。教室は学ぶ場所で、参拝には使わない。"}, {"text": "この教室は朝七時に店を開く。", "explanation": "ここは店の意味。開店は店が行うことで、学びの場である教室には使わない。"}, {"text": "父は病院の教室で患者の手当てをしている。", "explanation": "ここは病院の意味。医療行為は病院で行うので、学ぶ場所の教室とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年から、母は書道の教室を通い始めた。", "corrected_sentence": "今年から、母は書道の教室に通い始めた。", "error_description": "「通う」は行き先を「に」で示す。「を」は目的語になり、「通う」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の間、弟は水泳の教室が通っていた。", "corrected_sentence": "夏の間、弟は水泳の教室に通っていた。", "error_description": "「通う」の行き先は「に」で示す。「が」は主語になり、弟が教室に通うという関係が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「隣の教室から歌声が聞こえる」で、音の出どころを表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「聞こえる」は目的語をとらないので、「を」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「教室が歌声が聞こえる」となり、主語が二つになって不自然。"}, {"text": "と", "is_correct": false, "explanation": "「教室と歌声」は並列として不自然で、音の出どころを示せない。"}], "correct_answer": "から", "explanations": {"から": "「隣の教室から歌声が聞こえる」で、音の出どころを表す正しい助詞。", "を": "「聞こえる」は目的語をとらないので、「を」は合わない。", "が": "「教室が歌声が聞こえる」となり、主語が二つになって不自然。", "と": "「教室と歌声」は並列として不自然で、音の出どころを示せない。"}, "error_tags": {"から": "起点", "を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校の中で、先生と生徒が勉強するための部屋。", "primary_collocate": null, "pronunciation": "きょうしつ", "ipa": "kʲoːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "教室という微型社会において、彼女は未知の友達とどのように接し、どのようになじんでいくのだろうか。", "target_word": "教室", "complexity_tier": "T4", "furigana": "教室[きょうしつ]という微型[びけい]社会[しゃかい]において、彼女[かのじょ]は未知[みち]の友達[ともだち]とどのように接[せっ]し、どのようになじんでいくのだろうか。", "sentence_source": "mined"}, {"text": "毎朝、わたしは八時に教室に入って、友達にあいさつをします。", "target_word": "教室", "complexity_tier": "T2", "furigana": "毎朝[まいあさ]、わたしは八時[はちじ]に教室[きょうしつ]に入[はい]って、友達[ともだち]にあいさつをします。", "sentence_source": "generated"}, {"text": "雨が降っていたので、昼休みは教室で本を読んだ。", "target_word": "教室", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っていたので、昼休[ひるやす]みは教室[きょうしつ]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "先生が教室に入ると、生徒たちはすぐに静かになった。", "target_word": "教室", "complexity_tier": "T3", "furigana": "先生[せんせい]が教室[きょうしつ]に入[はい]ると、生徒[せいと]たちはすぐに静[しず]かになった。", "sentence_source": "generated"}, {"text": "この教室は広くて明るいので、授業を受けやすい。", "target_word": "教室", "complexity_tier": "T3", "furigana": "この教室[きょうしつ]は広[ひろ]くて明[あか]るいので、授業[じゅぎょう]を受[う]けやすい。", "sentence_source": "generated"}, {"text": "忘れ物に気づいて、急いで教室へ戻った。", "target_word": "教室", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]に気[き]づいて、急[いそ]いで教室[きょうしつ]へ戻[もど]った。", "sentence_source": "generated"}, {"text": "教室の後ろには、生徒が描いた絵がたくさん貼ってある。", "target_word": "教室", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の後[うし]ろには、生徒[せいと]が描[か]いた絵[え]がたくさん貼[は]ってある。", "sentence_source": "generated"}, {"text": "隣の教室から、楽しそうな歌声が聞こえてきた。", "target_word": "教室", "complexity_tier": "T3", "furigana": "隣[となり]の教室[きょうしつ]から、楽[たの]しそうな歌声[うたごえ]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "掃除の時間に、みんなで教室の机を運んだ。", "target_word": "教室", "complexity_tier": "T3", "furigana": "掃除[そうじ]の時間[じかん]に、みんなで教室[きょうしつ]の机[つくえ]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "テストが始まる前、教室の中は緊張した空気に包まれていた。", "target_word": "教室", "complexity_tier": "T4", "furigana": "テストが始[はじ]まる前[まえ]、教室[きょうしつ]の中[なか]は緊張[きんちょう]した空気[くうき]に包[つつ]まれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教室", "label": "基本形"}], "register": "中立", "sense_fingerprint": "学校で授業を行う部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "「教室という微型社会」と続き、学校の部屋を指す正しい語。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は部屋ではないので、「黒板という微型社会」は成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本であり、社会の比喩として文が成立しない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は部屋の一部で、「窓という微型社会」は意味をなさない。"}], "explanations": {"教室": "「教室という微型社会」と続き、学校の部屋を指す正しい語。", "黒板": "黒板は部屋ではないので、「黒板という微型社会」は成り立たない。", "教科書": "教科書は本であり、社会の比喩として文が成立しない。", "窓": "窓は部屋の一部で、「窓という微型社会」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食の準備が整うと、家族は教室に集まって食卓を囲んだ。", "explanation": "ここは食堂（食事をする部屋）の意味。教室は学ぶための部屋で、食卓を囲む場所には使わない。"}, {"text": "週末は、教室の庭で家族とバーベキューを楽しんだ。", "explanation": "ここは庭（屋外の庭園）の意味。教室は室内の部屋なので、庭を持つ場所としては使わない。"}, {"text": "この学校の教室は三階建てで、運動場が広い。", "explanation": "ここは校舎（建物全体）の意味。教室は一つの部屋なので、三階建てにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "「教室の後ろには絵が貼ってある」と続く、教室を指す正しい語。"}, {"text": "天気", "is_correct": false, "explanation": "天気には後ろも絵もないので、「天気の後ろ」は意味をなさない。"}, {"text": "電話", "is_correct": false, "explanation": "電話の後ろに絵が貼ってあるとは言えず、文が成り立たない。"}, {"text": "数学", "is_correct": false, "explanation": "教科の名前で、場所ではないので「数学の後ろ」は成り立たない。"}], "explanations": {"教室": "「教室の後ろには絵が貼ってある」と続く、教室を指す正しい語。", "天気": "天気には後ろも絵もないので、「天気の後ろ」は意味をなさない。", "電話": "電話の後ろに絵が貼ってあるとは言えず、文が成り立たない。", "数学": "教科の名前で、場所ではないので「数学の後ろ」は成り立たない。"}, "sentence_index": 6, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室で全校生徒が集まって、校長先生の話を聞いた。", "explanation": "ここは講堂（全校が集まる広い部屋）の意味。教室は一学級分の部屋なので、全校は入らない。"}, {"text": "祖父は昨日から教室に入院している。", "explanation": "ここは病室（入院する部屋）の意味。教室は学ぶための部屋で、入院の場所には使わない。"}, {"text": "雨の日は教室でバスケットボールの試合をする。", "explanation": "ここは体育館の意味。教室は試合をする広さがないので、体育館の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、昼休みに教室を本を読む生徒が多い。", "corrected_sentence": "雨の日は、昼休みに教室で本を読む生徒が多い。", "error_description": "場所を表す「で」が正しいが「を」になっている。「を」は教室を動作の対象にしてしまい不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休み時間、生徒は教室へ騒いでいた。", "corrected_sentence": "休み時間、生徒は教室で騒いでいた。", "error_description": "動作の場所を表す「で」が正しいが「へ」になっている。「へ」は方向を表し、「騒ぐ」の場所には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
