INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52497, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "感覚で辛うじて感じ取れるほど、弱くかすかなさま。", "primary_collocate": null, "pronunciation": "かすか", "ipa": "kasɯka", "syllable_count": 3, "sentences": [{"text": "窓を開けると、海の微かな匂いがした。", "target_word": "微か", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、海[うみ]の微[かす]かな匂[にお]いがした。", "sentence_source": "generated"}, {"text": "部屋の中から、微かな寝息が聞こえる。", "target_word": "微か", "complexity_tier": "T3", "furigana": "部屋[へや]の中[なか]から、微[かす]かな寝息[ねいき]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "彼の声は微かに震えていて、緊張しているのがわかった。", "target_word": "微か", "complexity_tier": "T3", "furigana": "彼[かれ]の声[こえ]は微[かす]かに震[ふる]えていて、緊張[きんちょう]しているのがわかった。", "sentence_source": "generated"}, {"text": "朝になって、耳鳴りが微かに和らいだ。", "target_word": "微かに", "complexity_tier": "T3", "furigana": "朝[あさ]になって、耳鳴[みみな]りが微[かす]かに和[やわ]らいだ。", "sentence_source": "generated"}, {"text": "霧の向こうに、島の影が微かに見えた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "霧[きり]の向[む]こうに、島[しま]の影[かげ]が微[かす]かに見[み]えた。", "sentence_source": "generated"}, {"text": "母は微かな笑みを浮かべて、私の話を聞いていた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "母[はは]は微[かす]かな笑[え]みを浮[う]かべて、私[わたし]の話[はなし]を聞[き]いていた。", "sentence_source": "generated"}, {"text": "この水は、微かに甘い味がする。", "target_word": "微か", "complexity_tier": "T3", "furigana": "この水[みず]は、微[かす]かに甘[あま]い味[あじ]がする。", "sentence_source": "generated"}, {"text": "古い写真を見ると、祖父の顔が微かに思い出される。", "target_word": "微か", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]ると、祖父[そふ]の顔[かお]が微[かす]かに思[おも]い出[だ]される。", "sentence_source": "generated"}, {"text": "風が止んで、葉の揺れも微かになった。", "target_word": "微か", "complexity_tier": "T3", "furigana": "風[かぜ]が止[や]んで、葉[は]の揺[ゆ]れも微[かす]かになった。", "sentence_source": "generated"}, {"text": "電話の向こうで、微かに雨の音がした。", "target_word": "微か", "complexity_tier": "T3", "furigana": "電話[でんわ]の向[む]こうで、微[かす]かに雨[あめ]の音[おと]がした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微か", "label": "基本形"}, {"form": "微かな", "label": "連体形"}, {"form": "微かに", "label": "連用形"}], "register": "中立", "sense_fingerprint": "音・光・匂いなどが辛うじて感じ取れるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52497, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微か", "is_correct": true, "explanation": "〈微か〉は少しだけ感じ取れるさまを表し、「海の〜な匂い」に入る。"}, {"text": "速やか", "is_correct": false, "explanation": "〈速やか〉は動作のすばやさを表すので、匂いの程度には合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "〈乱暴〉は荒々しい振る舞いを指し、匂いを修飾しても意味が通らない。"}, {"text": "派手", "is_correct": false, "explanation": "〈派手〉は目立つ様子で、「少し感じる」という意味の〈微か〉とは逆になる。"}], "explanations": {"微か": "〈微か〉は少しだけ感じ取れるさまを表し、「海の〜な匂い」に入る。", "速やか": "〈速やか〉は動作のすばやさを表すので、匂いの程度には合わない。", "乱暴": "〈乱暴〉は荒々しい振る舞いを指し、匂いを修飾しても意味が通らない。", "派手": "〈派手〉は目立つ様子で、「少し感じる」という意味の〈微か〉とは逆になる。"}, "sentence_index": 0, "correct_answer": "微か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会費は微かに千円だった。", "explanation": "ここは〈僅か（わずか）〉の意味。微かは感覚で感じ取れるほど弱い様子を表し、金額の少なさには使わない。"}, {"text": "彼は微かに大声で叫んだ。", "explanation": "ここは〈声が大きく響く〉の意味で使う場面。微かは弱さを表すので、大声で叫ぶ様子とは噛み合わない。"}, {"text": "その計画は、微かに大規模で、資金が足りなかった。", "explanation": "ここは〈規模が大きい〉の意味。微かは弱さを表すので、大規模な計画とは噛み合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52497, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微か", "is_correct": true, "explanation": "ここは〈微か〉の連用形（微かに）。少しだけ甘いという意味で「甘い」を修飾する。"}, {"text": "鮮明", "is_correct": false, "explanation": "〈鮮明〉は輪郭や色がはっきりしていることで、味の程度には使わない。"}, {"text": "厳密", "is_correct": false, "explanation": "〈厳密〉は細かく正確な様子で、味の程度を表す語としては合わない。"}, {"text": "盛大", "is_correct": false, "explanation": "〈盛大〉は規模が大きく華やかな様子で、味の弱さを表す文脈と合わない。"}], "explanations": {"微か": "ここは〈微か〉の連用形（微かに）。少しだけ甘いという意味で「甘い」を修飾する。", "鮮明": "〈鮮明〉は輪郭や色がはっきりしていることで、味の程度には使わない。", "厳密": "〈厳密〉は細かく正確な様子で、味の程度を表す語としては合わない。", "盛大": "〈盛大〉は規模が大きく華やかな様子で、味の弱さを表す文脈と合わない。"}, "sentence_index": 6, "correct_answer": "微か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の天気は微かだった。", "explanation": "ここは〈どちらとも言えない（微妙）〉の意味。微かは感覚で感じ取れるほどの弱さを表し、天気の状態には使わない。"}, {"text": "彼の声は微かにどっしりと響いた。", "explanation": "ここは〈重々しく響く〉の意味。微かは弱さを表すので、〈どっしり〉の重さとは噛み合わない。"}, {"text": "このパーティーは微かに盛大に開かれた。", "explanation": "〈盛大〉は規模の大きさを表すので、〈微か〉の弱さとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52497, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の公園で、微かの鈴の音が聞こえた。", "corrected_sentence": "夜の公園で、微かな鈴の音が聞こえた。", "error_description": "「微か」は形状動詞なので、名詞「鈴の音」を修飾するときは「微かな」とする。「微かの」は誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微か", "is_correct": true, "explanation": "連体形「微かな」の語幹部分。「な」は文中に残り、「寝息」を修飾する。"}, {"text": "微かに", "is_correct": false, "explanation": "連用形で、名詞「寝息」を直接修飾できないので不可。"}, {"text": "微かだ", "is_correct": false, "explanation": "終止形で、名詞を修飾する形として使えないので不可。"}, {"text": "微かで", "is_correct": false, "explanation": "中止形・て形で、名詞を修飾する形として使えないので不可。"}], "correct_form": "微か", "base_form": "微か", "form_label": "連体形（〜な）", "sentence_index": 1, "explanations": {"微か": "連体形「微かな」の語幹部分。「な」は文中に残り、「寝息」を修飾する。", "微かに": "連用形で、名詞「寝息」を直接修飾できないので不可。", "微かだ": "終止形で、名詞を修飾する形として使えないので不可。", "微かで": "中止形・て形で、名詞を修飾する形として使えないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52497, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道の街灯が微かだ見えた。", "corrected_sentence": "夜道の街灯が微かに見えた。", "error_description": "「微か」は形状動詞なので、動詞「見えた」を修飾するには連用形「微かに」が必要。「微かだ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微か", "is_correct": true, "explanation": "ここは〈微か〉の連用形（微かに）の語幹部分。「に」に続けて動詞を修飾する形で使う。"}, {"text": "微かな", "is_correct": false, "explanation": "連体形で、動詞「思い出される」を修飾できないので不可。"}, {"text": "微であった", "is_correct": false, "explanation": "過去の形で、「に」に続かないので不可。"}, {"text": "微かでない", "is_correct": false, "explanation": "否定の形で、「に」に続けて動詞を修飾する形にはならないので不可。"}], "correct_form": "微か", "base_form": "微か", "form_label": "連用形（〜に）", "sentence_index": 7, "explanations": {"微か": "ここは〈微か〉の連用形（微かに）の語幹部分。「に」に続けて動詞を修飾する形で使う。", "微かな": "連体形で、動詞「思い出される」を修飾できないので不可。", "微であった": "過去の形で、「に」に続かないので不可。", "微かでない": "否定の形で、「に」に続けて動詞を修飾する形にはならないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
