INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52498, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量や程度が小さいこと。わずかであることを表す。", "primary_collocate": null, "pronunciation": "かすか", "ipa": "kasɯka", "syllable_count": 3, "sentences": [{"text": "夕暮れの空に、微かな星の光が見えた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "夕暮[ゆうぐ]れの空[そら]に、微[かす]かな星[ほし]の光[ひかり]が見[み]えた。", "sentence_source": "generated"}, {"text": "遠くから、微かな音楽が聞こえてきた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "遠[とお]くから、微[かす]かな音楽[おんがく]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "暗い部屋の奥に、微かな光が見えた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]の奥[おく]に、微[かす]かな光[ひかり]が見[み]えた。", "sentence_source": "generated"}, {"text": "花の微かな香りが、風に乗って届いた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "花[はな]の微[かす]かな香[かお]りが、風[かぜ]に乗[の]って届[とど]いた。", "sentence_source": "generated"}, {"text": "彼は寒さで、微かに震えていた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "彼[かれ]は寒[さむ]さで、微[かす]かに震[ふる]えていた。", "sentence_source": "generated"}, {"text": "子どものころの記憶が、微かに残っている。", "target_word": "微か", "complexity_tier": "T3", "furigana": "子[こ]どものころの記憶[きおく]が、微[かす]かに残[のこ]っている。", "sentence_source": "generated"}, {"text": "試験に受かる可能性は微かだが、あきらめない。", "target_word": "微か", "complexity_tier": "T3", "furigana": "試験[しけん]に受[う]かる可能性[かのうせい]は微[かす]かだが、あきらめない。", "sentence_source": "generated"}, {"text": "彼女は私を見て、微かに笑った。", "target_word": "微か", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]を見[み]て、微[かす]かに笑[わら]った。", "sentence_source": "generated"}, {"text": "まだ微かな希望があるので、探すのを続けた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "まだ微[かす]かな希望[きぼう]があるので、探[さが]すのを続[つづ]けた。", "sentence_source": "generated"}, {"text": "夜の静けさの中で、虫の声が微かに聞こえた。", "target_word": "微か", "complexity_tier": "T3", "furigana": "夜[よる]の静[しず]けさの中[なか]で、虫[むし]の声[こえ]が微[かす]かに聞[き]こえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微か", "label": "基本形"}, {"form": "微かな", "label": "連体形"}, {"form": "微かに", "label": "連用形"}], "register": "中立", "sense_fingerprint": "数量や程度がわずかで、はっきりしないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微か", "is_correct": true, "explanation": "〈微か〉は光がごくわずかに見える様子を表し、「微かな星の光」に入る。"}, {"text": "厳密", "is_correct": false, "explanation": "〈厳密〉は細かく正確な様子で、光の弱さを表す文脈には合わない。"}, {"text": "盛大", "is_correct": false, "explanation": "〈盛大〉は規模が大きく華やかな様子で、星の光には使わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "〈乱暴〉は荒々しい振る舞いを指し、光の様子は表せない。"}], "explanations": {"微か": "〈微か〉は光がごくわずかに見える様子を表し、「微かな星の光」に入る。", "厳密": "〈厳密〉は細かく正確な様子で、光の弱さを表す文脈には合わない。", "盛大": "〈盛大〉は規模が大きく華やかな様子で、星の光には使わない。", "乱暴": "〈乱暴〉は荒々しい振る舞いを指し、光の様子は表せない。"}, "sentence_index": 0, "correct_answer": "微か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遠くから、微かな大声が聞こえてきた。", "explanation": "ここは〈大きく強い〉の意味。微かは弱くわずかなさまを表すので、この意味では使えない。"}, {"text": "道の先に、微かな大きな山がそびえていた。", "explanation": "ここは〈大きい〉の意味。微かは小さく弱い程度を表すので、この意味では使えない。"}, {"text": "机の上に、微かな紙を重ねた。", "explanation": "「微か」は音や光、匂いなど感じ取れるものに使う。紙の薄さには、薄いを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微か", "is_correct": true, "explanation": "「可能性はわずかだが」と続き、かすかで小さい程度を表す正しい語。"}, {"text": "静か", "is_correct": false, "explanation": "「可能性は静かだが」では意味が通らず、程度を表す語にならない。"}, {"text": "元気", "is_correct": false, "explanation": "「可能性は元気だが」は文として成立しない。"}, {"text": "派手", "is_correct": false, "explanation": "「可能性は派手だが」は意味が合わず、程度を表せない。"}], "explanations": {"微か": "「可能性はわずかだが」と続き、かすかで小さい程度を表す正しい語。", "静か": "「可能性は静かだが」では意味が通らず、程度を表す語にならない。", "元気": "「可能性は元気だが」は文として成立しない。", "派手": "「可能性は派手だが」は意味が合わず、程度を表せない。"}, "sentence_index": 6, "correct_answer": "微か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の中は、微かな人で埋め尽くされていた。", "explanation": "「微か」は少量を表す。埋め尽くされるほどの多さとは合わない。"}, {"text": "小さな公園で、微かな子どもが遊んでいた。", "explanation": "「微か」は量や程度のわずかさを表す。人の体格には使わない。"}, {"text": "試合の後、チームは微かに大騒ぎして喜んだ。", "explanation": "「微か」は控えめな程度を表す。大騒ぎするほどの盛り上がりとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遠くから、微かの音が聞こえてきた。", "corrected_sentence": "遠くから、微かな音が聞こえてきた。", "error_description": "形容動詞の連体形は「微かな」で、「微かの」は誤り。「な」が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微か", "is_correct": true, "explanation": "ここは〈微か〉の連体形（微かな）。「音楽」を修飾する形で、語幹が入る。"}, {"text": "微かだ", "is_correct": false, "explanation": "終止形で、名詞「音楽」を直接修飾できないので不可。"}, {"text": "微かで", "is_correct": false, "explanation": "中止形・て形で、名詞を修飾する位置には入らないので不可。"}, {"text": "微かだった", "is_correct": false, "explanation": "過去の終止形で、名詞を修飾する位置には入らないので不可。"}], "correct_form": "微か", "base_form": "微か", "form_label": "連体形（〜な）", "sentence_index": 1, "explanations": {"微か": "ここは〈微か〉の連体形（微かな）。「音楽」を修飾する形で、語幹が入る。", "微かだ": "終止形で、名詞「音楽」を直接修飾できないので不可。", "微かで": "中止形・て形で、名詞を修飾する位置には入らないので不可。", "微かだった": "過去の終止形で、名詞を修飾する位置には入らないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "星の光が、微かで揺れていた。", "corrected_sentence": "星の光が、微かに揺れていた。", "error_description": "動詞「揺れる」を修飾する形は連用形の「微かに」。「で」は活用形として誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微か", "is_correct": true, "explanation": "ここは〈微か〉の連用形（微かに）。動詞「笑った」を修飾する形で、語幹が入る。"}, {"text": "微かな", "is_correct": false, "explanation": "連体形で、動詞「笑った」を修飾できないので不可。"}, {"text": "微かであった", "is_correct": false, "explanation": "過去の形で、動詞を修飾する位置には入らないので不可。"}, {"text": "微かでない", "is_correct": false, "explanation": "否定の形で、「に」に続けて動詞を修飾する形にはならないので不可。"}], "correct_form": "微か", "base_form": "微か", "form_label": "連用形（〜に）", "sentence_index": 7, "explanations": {"微か": "ここは〈微か〉の連用形（微かに）。動詞「笑った」を修飾する形で、語幹が入る。", "微かな": "連体形で、動詞「笑った」を修飾できないので不可。", "微かであった": "過去の形で、動詞を修飾する位置には入らないので不可。", "微かでない": "否定の形で、「に」に続けて動詞を修飾する形にはならないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「町に馴染みたい」の〈に〉。馴染む対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉は、対象を示す〈馴染む〉の用法には入らない。"}, {"text": "が", "is_correct": false, "explanation": "主語の〈が〉は、この位置には入らない。"}, {"text": "の", "is_correct": false, "explanation": "連体の〈の〉は、名詞同士をつなぐもので、対象を示す位置には合わない。"}], "correct_answer": "に", "explanations": {"に": "「町に馴染みたい」の〈に〉。馴染む対象を示す。", "を": "目的語の〈を〉は、対象を示す〈馴染む〉の用法には入らない。", "が": "主語の〈が〉は、この位置には入らない。", "の": "連体の〈の〉は、名詞同士をつなぐもので、対象を示す位置には合わない。"}, "error_tags": {"を": "目的語用法", "が": "主語用法", "の": "連体用法"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この家に馴染んで」の〈に〉。馴染む対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉は、対象を示す〈馴染む〉の用法には入らない。"}, {"text": "と", "is_correct": false, "explanation": "相手を示す〈と〉は、この文脈では不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体の〈の〉は、この位置に入らない。"}], "correct_answer": "に", "explanations": {"に": "「この家に馴染んで」の〈に〉。馴染む対象を示す。", "を": "目的語の〈を〉は、対象を示す〈馴染む〉の用法には入らない。", "と": "相手を示す〈と〉は、この文脈では不自然。", "の": "連体の〈の〉は、この位置に入らない。"}, "error_tags": {"を": "目的語用法", "と": "相手用法", "の": "連体用法"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "新しい場所や人にだんだん慣れて、安心して過ごせるようになること。", "primary_collocate": null, "pronunciation": "なじむ", "ipa": "nadʑimɯ", "syllable_count": 3, "sentences": [{"text": "新しい学校にも、一か月たつうちにすっかり馴染んでいった。", "target_word": "馴染んで", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]にも、一[いっ]か月[げつ]たつうちにすっかり馴染[なじ]んでいった。", "sentence_source": "generated"}, {"text": "引っ越したばかりの町に早く馴染みたいと思っている。", "target_word": "馴染みたい", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]したばかりの町[まち]に早[はや]く馴染[なじ]みたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "彼は人見知りだが、新しい職場の人たちにすぐ馴染んだ。", "target_word": "馴染んだ", "complexity_tier": "T3", "furigana": "彼[かれ]は人見知[ひとみし]りだが、新[あたら]しい職場[しょくば]の人[ひと]たちにすぐ馴染[なじ]んだ。", "sentence_source": "generated"}, {"text": "転校生がクラスに馴染めず、毎日一人で昼ご飯を食べていた。", "target_word": "馴染めず", "complexity_tier": "T3", "furigana": "転校生[てんこうせい]がクラスに馴染[なじ]めず、毎日[まいにち]一人[ひとり]で昼[ひる]ご飯[はん]を食[た]べていた。", "sentence_source": "generated"}, {"text": "留学して三か月で、ようやくこの国の暮らしに馴染みつつある。", "target_word": "馴染み", "complexity_tier": "T3", "furigana": "留学[りゅうがく]して三[さん]か月[げつ]で、ようやくこの国[くに]の暮[く]らしに馴染[なじ]みつつある。", "sentence_source": "generated"}, {"text": "新入社員が会社に馴染むまで、先輩たちは優しく声をかけ続けた。", "target_word": "馴染む", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]が会社[かいしゃ]に馴染[なじ]むまで、先輩[せんぱい]たちは優[やさ]しく声[こえ]をかけ続[つづ]けた。", "sentence_source": "generated"}, {"text": "新しい場所に馴染むのに時間がかかる人もいるので、焦る必要はない。", "target_word": "馴染む", "complexity_tier": "T3", "furigana": "新[あたら]しい場所[ばしょ]に馴染[なじ]むのに時間[じかん]がかかる人[ひと]もいるので、焦[あせ]る必要[ひつよう]はない。", "sentence_source": "generated"}, {"text": "初めは寂しかったが、今ではこの家にすっかり馴染んでいる。", "target_word": "馴染んで", "complexity_tier": "T3", "furigana": "初[はじ]めは寂[さび]しかったが、今[いま]ではこの家[いえ]にすっかり馴染[なじ]んでいる。", "sentence_source": "generated"}, {"text": "新しい環境に馴染めるかどうか、入学前は不安でたまらなかった。", "target_word": "馴染める", "complexity_tier": "T3", "furigana": "新[あたら]しい環境[かんきょう]に馴染[なじ]めるかどうか、入学前[にゅうがくまえ]は不安[ふあん]でたまらなかった。", "sentence_source": "generated"}, {"text": "田舎から出てきた彼女は、都会の忙しい生活に馴染むまでずいぶん苦労した。", "target_word": "馴染む", "complexity_tier": "T3", "furigana": "田舎[いなか]から出[で]てきた彼女[かのじょ]は、都会[とかい]の忙[いそが]しい生活[せいかつ]に馴染[なじ]むまでずいぶん苦労[くろう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "馴染む", "label": "辞書形"}, {"form": "馴染みます", "label": "ます形"}, {"form": "馴染んだ", "label": "た形"}, {"form": "馴染んで", "label": "て形"}, {"form": "馴染まない", "label": "ない形"}, {"form": "馴染めない", "label": "可能否定形"}, {"form": "馴染みたい", "label": "たい形"}], "register": "中立", "sense_fingerprint": "新しい環境や人に慣れて、違和感なく過ごせるようになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "馴染んで", "is_correct": true, "explanation": "「すっかり〜いった」に入り、〈馴染む〉の て形で変化を表す。"}, {"text": "馴染もう", "is_correct": false, "explanation": "意向形で、「〜ていった」と続かず文が成り立たない。"}, {"text": "馴染まず", "is_correct": false, "explanation": "否定の連用形で、「〜いった」と続かない。"}, {"text": "馴染みたく", "is_correct": false, "explanation": "願望の連用形で、「〜いった」と続かない。"}], "explanations": {"馴染んで": "「すっかり〜いった」に入り、〈馴染む〉の て形で変化を表す。", "馴染もう": "意向形で、「〜ていった」と続かず文が成り立たない。", "馴染まず": "否定の連用形で、「〜いった」と続かない。", "馴染みたく": "願望の連用形で、「〜いった」と続かない。"}, "sentence_index": 0, "correct_answer": "馴染んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は仕事の書類に馴染んで、昼食を忘れた。", "explanation": "ここは〈仕事に没頭する〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、書類には使わない。"}, {"text": "彼は締め切りの時間に馴染んで、ゆっくり寝ていた。", "explanation": "ここは〈時間を守る〉の意味。〈馴染む〉は人や環境に溶け込むことで、締め切りの時間には使わない。"}, {"text": "彼は昼休みの時間に馴染んで、仕事を始めた。", "explanation": "ここは〈時間どおりに始める〉の意味。〈馴染む〉は人や環境に溶け込むことで、時間帯を表す語には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "馴染む", "is_correct": true, "explanation": "辞書形「馴染む」＋「のに」で、「時間がかかる」に続く動詞の形。"}, {"text": "焦り", "is_correct": false, "explanation": "名詞で、「〜のに時間がかかる」の形に入らない。"}, {"text": "寄り道", "is_correct": false, "explanation": "名詞で、「〜のに時間がかかる」の形に入らない。"}, {"text": "騒ぎ", "is_correct": false, "explanation": "名詞で、「〜のに時間がかかる」の形に入らない。"}], "explanations": {"馴染む": "辞書形「馴染む」＋「のに」で、「時間がかかる」に続く動詞の形。", "焦り": "名詞で、「〜のに時間がかかる」の形に入らない。", "寄り道": "名詞で、「〜のに時間がかかる」の形に入らない。", "騒ぎ": "名詞で、「〜のに時間がかかる」の形に入らない。"}, "sentence_index": 6, "correct_answer": "馴染む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その鉛筆は、消しゴムに馴染んで短くなった。", "explanation": "ここは〈鉛筆が消しゴムと擦れて短くなる〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、物どうしの摩耗には使わない。"}, {"text": "子どもたちの悲鳴に馴染んで、すぐ笑い出した。", "explanation": "ここは〈平気になって笑う〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、悲鳴のような一時的な音には使わない。"}, {"text": "会議の議題に馴染んで、昼食を注文した。", "explanation": "ここは〈議題を理解して扱う〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、議題には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田舎から来た彼は、まだこの町を馴染めずにいる。", "corrected_sentence": "田舎から来た彼は、まだこの町に馴染めずにいる。", "error_description": "「馴染む」は「〜に馴染む」と助詞「に」をとる。「町を」は誤った助詞。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "馴染みたい", "is_correct": true, "explanation": "願望形で、「早く〜と思っている」の形に入る。"}, {"text": "馴染みます", "is_correct": false, "explanation": "丁寧形で、「と思っている」の引用の形に入らない。"}, {"text": "馴染み", "is_correct": false, "explanation": "語幹のみで、「と思っている」に続かず文が成り立たない。"}, {"text": "馴染んで", "is_correct": false, "explanation": "て形で、「と思っている」の引用の形に入らない。"}], "correct_form": "馴染みたい", "base_form": "馴染む", "form_label": "たい形（願望）", "sentence_index": 1, "explanations": {"馴染みたい": "願望形で、「早く〜と思っている」の形に入る。", "馴染みます": "丁寧形で、「と思っている」の引用の形に入らない。", "馴染み": "語幹のみで、「と思っている」に続かず文が成り立たない。", "馴染んで": "て形で、「と思っている」の引用の形に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転勤して三か月たつが、彼はまだこの支店に馴染めでいる。", "corrected_sentence": "転勤して三か月たつが、彼はまだこの支店に馴染めずにいる。", "error_description": "「馴染めない」の継続形は「馴染めずにいる」。「馴染めでいる」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "馴染んで", "is_correct": true, "explanation": "て形で、「〜いる」の進行・結果の形に入る。"}, {"text": "馴染みます", "is_correct": false, "explanation": "丁寧形で、「〜いる」と続かない。"}, {"text": "馴染まない", "is_correct": false, "explanation": "否定形で、「家にすっかり〜いる」の肯定の文脈と逆になる。"}, {"text": "馴染みたい", "is_correct": false, "explanation": "願望形で、「〜いる」と続かない。"}], "correct_form": "馴染んで", "base_form": "馴染む", "form_label": "て形（〜ている）", "sentence_index": 7, "explanations": {"馴染んで": "て形で、「〜いる」の進行・結果の形に入る。", "馴染みます": "丁寧形で、「〜いる」と続かない。", "馴染まない": "否定形で、「家にすっかり〜いる」の肯定の文脈と逆になる。", "馴染みたい": "願望形で、「〜いる」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「クラスに馴染む」の〈に〉。馴染む対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉は他動詞に使うので、〈馴染む〉の対象には不可。"}, {"text": "から", "is_correct": false, "explanation": "起点の〈から〉。「クラスから馴染んだ」は起点を表すことになり、〈馴染む〉の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語の〈が〉は、ここでは対象を示す位置に入らない。"}], "correct_answer": "に", "explanations": {"に": "「クラスに馴染む」の〈に〉。馴染む対象を示す。", "を": "目的語の〈を〉は他動詞に使うので、〈馴染む〉の対象には不可。", "から": "起点の〈から〉。「クラスから馴染んだ」は起点を表すことになり、〈馴染む〉の対象を示せない。", "が": "主語の〈が〉は、ここでは対象を示す位置に入らない。"}, "error_tags": {"を": "目的語用法", "から": "起点用法", "が": "主語用法"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「食べ物に馴染めなかった」の〈に〉。馴染む対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す〈へ〉は、「食べ物へ馴染めなかった」のように〈馴染む〉の対象を示せず、文の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す〈から〉は、「食べ物から馴染めなかった」では出どころになり、〈馴染む〉の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞どうしをつなぐもので、「食べ物の馴染めなかった」のように動詞の前には入らない。"}], "correct_answer": "に", "explanations": {"に": "「食べ物に馴染めなかった」の〈に〉。馴染む対象を示す。", "へ": "方向を示す〈へ〉は、「食べ物へ馴染めなかった」のように〈馴染む〉の対象を示せず、文の意味が通らない。", "から": "起点を示す〈から〉は、「食べ物から馴染めなかった」では出どころになり、〈馴染む〉の対象を示せない。", "の": "〈の〉は名詞どうしをつなぐもので、「食べ物の馴染めなかった」のように動詞の前には入らない。"}, "error_tags": {"へ": "方向用法", "から": "起点用法", "の": "名詞連結用法"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "新しい環境や人間関係に次第に慣れ、自然に溶け込むこと。", "primary_collocate": null, "pronunciation": "なじむ", "ipa": "nadʑimɯ", "syllable_count": 3, "sentences": [{"text": "教室という微型社会において、彼女は未知の友達とどのように接し、どのようになじんでいくのだろうか。", "target_word": "なじん", "complexity_tier": "T4", "furigana": "教室[きょうしつ]という微型[びけい]社会[しゃかい]において、彼女[かのじょ]は未知[みち]の友達[ともだち]とどのように接[せっ]し、どのようになじんでいくのだろうか。", "sentence_source": "mined"}, {"text": "転校した彼は、一か月でクラスに馴染んだ。", "target_word": "馴染ん", "complexity_tier": "T3", "furigana": "転校[てんこう]した彼[かれ]は、一[いっ]か月[げつ]でクラスに馴染[なじ]んだ。", "sentence_source": "generated"}, {"text": "転勤先の支社での生活に、少しずつ馴染んでいった。", "target_word": "馴染んで", "complexity_tier": "T3", "furigana": "転勤先[てんきんさき]の支社[ししゃ]での生活[せいかつ]に、少[すこ]しずつ馴染[なじ]んでいった。", "sentence_source": "generated"}, {"text": "この町の暮らしに、やっと馴染んできました。", "target_word": "馴染ん", "complexity_tier": "T3", "furigana": "この町[まち]の暮[く]らしに、やっと馴染[なじ]んできました。", "sentence_source": "generated"}, {"text": "彼女は誰とでもすぐに馴染む性格だ。", "target_word": "馴染む", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]とでもすぐに馴染[なじ]む性格[せいかく]だ。", "sentence_source": "generated"}, {"text": "新入社員が職場に馴染めるよう、先輩が声をかけた。", "target_word": "馴染め", "complexity_tier": "T4", "furigana": "新入社員[しんにゅうしゃいん]が職場[しょくば]に馴染[なじ]めるよう、先輩[せんぱい]が声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "新しいチームのやり方に、彼女はまだ馴染めずにいる。", "target_word": "馴染めず", "complexity_tier": "T3", "furigana": "新[あたら]しいチームのやり方[かた]に、彼女[かのじょ]はまだ馴染[なじ]めずにいる。", "sentence_source": "generated"}, {"text": "最初は外国の食べ物に馴染めなかったが、今は大好きだ。", "target_word": "馴染め", "complexity_tier": "T4", "furigana": "最初[さいしょ]は外国[がいこく]の食[た]べ物[もの]に馴染[なじ]めなかったが、今[いま]は大好[だいす]きだ。", "sentence_source": "generated"}, {"text": "転任してきた上司は、部署の人たちともうすっかり馴染んでいる。", "target_word": "馴染んで", "complexity_tier": "T3", "furigana": "転任[てんにん]してきた上司[じょうし]は、部署[ぶしょ]の人[ひと]たちともうすっかり馴染[なじ]んでいる。", "sentence_source": "generated"}, {"text": "引っ越したばかりで、まだ近所に馴染んでいない。", "target_word": "馴染ん", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]したばかりで、まだ近所[きんじょ]に馴染[なじ]んでいない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "馴染む", "label": "終止形"}, {"form": "馴染んで", "label": "て形"}, {"form": "馴染んだ", "label": "過去形"}, {"form": "馴染まない", "label": "否定形"}, {"form": "馴染め", "label": "可能・仮定語幹"}], "register": "中立", "sense_fingerprint": "環境や人、物に慣れて自然に溶け込む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "なじん", "is_correct": true, "explanation": "「どのように〜でいく」に入る動詞の連用形で、〈馴染む〉の意味に合う。"}, {"text": "抱え", "is_correct": false, "explanation": "〈抱え〉は物や問題を抱える意味で、「〜でいく」の形に入らない。"}, {"text": "怠け", "is_correct": false, "explanation": "〈怠ける〉の連用形。「どのように〜でいく」の形には入るが、友達との関係の文脈では「怠けていく」は意味が通らない。"}, {"text": "なじみ", "is_correct": false, "explanation": "名詞形で、動詞の連用形を要する「〜でいく」の形に入らない。"}], "explanations": {"なじん": "「どのように〜でいく」に入る動詞の連用形で、〈馴染む〉の意味に合う。", "抱え": "〈抱え〉は物や問題を抱える意味で、「〜でいく」の形に入らない。", "怠け": "〈怠ける〉の連用形。「どのように〜でいく」の形には入るが、友達との関係の文脈では「怠けていく」は意味が通らない。", "なじみ": "名詞形で、動詞の連用形を要する「〜でいく」の形に入らない。"}, "sentence_index": 0, "correct_answer": "なじん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の議題にすっかり馴染んで、すぐに発言を終えた。", "explanation": "ここは〈議題を理解して扱う〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、議題の理解には使わない。"}, {"text": "彼は約束の時間に馴染んで、遅刻した。", "explanation": "ここは〈時間を守る・合わせる〉の意味。〈馴染む〉は人や環境に溶け込むことで、約束の時間には使えず、遅刻する流れとも合わない。"}, {"text": "彼女は怒りに馴染んで、笑い出した。", "explanation": "ここは〈気持ちが静まる〉の意味。〈馴染む〉は人や環境に溶け込むことで、怒りという感情には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "馴染めず", "is_correct": true, "explanation": "「まだ〜にいる」に入り、〈馴染めない〉の否定の形で意味が通る。"}, {"text": "迷い", "is_correct": false, "explanation": "名詞形で、「まだ〜にいる」の形に入らない。"}, {"text": "驚き", "is_correct": false, "explanation": "名詞形で、「まだ〜にいる」の形に入らない。"}, {"text": "落ち着き", "is_correct": false, "explanation": "名詞形で、「まだ〜にいる」の形に入らない。"}], "explanations": {"馴染めず": "「まだ〜にいる」に入り、〈馴染めない〉の否定の形で意味が通る。", "迷い": "名詞形で、「まだ〜にいる」の形に入らない。", "驚き": "名詞形で、「まだ〜にいる」の形に入らない。", "落ち着き": "名詞形で、「まだ〜にいる」の形に入らない。"}, "sentence_index": 6, "correct_answer": "馴染めず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大きな音に馴染んで、すぐに驚いてしまった。", "explanation": "ここは〈音に反応して驚く〉の意味。〈馴染む〉は人や環境に溶け込むことで、驚く反応とは矛盾する。"}, {"text": "彼女は悲鳴に馴染んで、すぐに笑い出した。", "explanation": "ここは〈平気になって笑う〉の意味。〈馴染む〉は人や環境に慣れて溶け込むことで、悲鳴のような一時的な音には使わない。"}, {"text": "彼は期末試験の内容に馴染んで、昼寝を始めた。", "explanation": "ここは〈気にせず休む〉の意味。〈馴染む〉は人や環境に溶け込むことで、試験の内容には使えず、昼寝との流れも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初めてのバイト先に、彼はまだ馴染めでいた。", "corrected_sentence": "初めてのバイト先に、彼はまだ馴染めずにいた。", "error_description": "〈馴染めない〉の否定の形は「馴染めず」。「馴染めで」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "馴染ん", "is_correct": true, "explanation": "ここは〈馴染む〉の連用形の語幹で、過去形「馴染んだ」を作る。"}, {"text": "馴染め", "is_correct": false, "explanation": "可能形の語幹で、「一か月で〜」の過去の出来事には合わない。"}, {"text": "馴染む", "is_correct": false, "explanation": "辞書形で、過去の出来事を述べる文脈に合わない。"}, {"text": "馴染まない", "is_correct": false, "explanation": "否定形で、「馴染んだ」（肯定の過去）と逆の意味になる。"}], "correct_form": "馴染ん", "base_form": "馴染む", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"馴染ん": "ここは〈馴染む〉の連用形の語幹で、過去形「馴染んだ」を作る。", "馴染め": "可能形の語幹で、「一か月で〜」の過去の出来事には合わない。", "馴染む": "辞書形で、過去の出来事を述べる文脈に合わない。", "馴染まない": "否定形で、「馴染んだ」（肯定の過去）と逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52500, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初めて会ったとき、彼女はすぐに馴染めたなかった。", "corrected_sentence": "初めて会ったとき、彼女はすぐに馴染めなかった。", "error_description": "〈馴染める〉の否定過去は「馴染めなかった」。「馴染めたなかった」は誤った活用の組み合わせ。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "馴染め", "is_correct": true, "explanation": "可能形の語幹で、「〜なかった」に続けて否定過去になる。"}, {"text": "馴染まず", "is_correct": false, "explanation": "否定の連用形で、「〜なかった」に続けると不自然になる。"}, {"text": "馴染んで", "is_correct": false, "explanation": "て形で、「〜なかった」と続かない。"}, {"text": "馴染んだ", "is_correct": false, "explanation": "た形で、「〜なかった」と続かない。"}], "correct_form": "馴染め", "base_form": "馴染む", "form_label": "可能形（〜める）", "sentence_index": 7, "explanations": {"馴染め": "可能形の語幹で、「〜なかった」に続けて否定過去になる。", "馴染まず": "否定の連用形で、「〜なかった」に続けると不自然になる。", "馴染んで": "て形で、「〜なかった」と続かない。", "馴染んだ": "た形で、「〜なかった」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「からの離脱」の〈の〉。〈から〉を受けて名詞〈離脱〉を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉は、名詞修飾の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "方向・対象の〈に〉は、「から」の後の名詞修飾には合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語の〈が〉は、ここでは名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「からの離脱」の〈の〉。〈から〉を受けて名詞〈離脱〉を修飾する。", "を": "目的語の〈を〉は、名詞修飾の位置には入らない。", "に": "方向・対象の〈に〉は、「から」の後の名詞修飾には合わない。", "が": "主語の〈が〉は、ここでは名詞を修飾できない。"}, "error_tags": {"を": "目的語用法", "に": "方向・対象用法", "が": "主語用法"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "〈離脱〉の対義語として、組織や集団に入る意味で、ここでは対になる。"}, {"text": "維持", "is_correct": false, "explanation": "〈維持〉は状態を保つ意味で、〈離脱〉の対義語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "〈継続〉は続けることで、〈離脱〉の対義語ではない。"}, {"text": "上達", "is_correct": false, "explanation": "腕前が上がること。〈離脱〉とは関係がなく、対義語にはならない。"}], "correct_answer": "加入", "explanations": {"加入": "〈離脱〉の対義語として、組織や集団に入る意味で、ここでは対になる。", "維持": "〈維持〉は状態を保つ意味で、〈離脱〉の対義語ではない。", "継続": "〈継続〉は続けることで、〈離脱〉の対義語ではない。", "上達": "腕前が上がること。〈離脱〉とは関係がなく、対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「慣習からの離脱」の〈の〉。〈から〉を受けて名詞〈離脱〉を修飾する。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の〈で〉は、「から」に続けて名詞を修飾する形には入らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す〈と〉は、「から」の後に続けると名詞修飾の形にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉は、「慣習からより」の後で名詞を修飾する形に合わない。"}], "correct_answer": "の", "explanations": {"の": "「慣習からの離脱」の〈の〉。〈から〉を受けて名詞〈離脱〉を修飾する。", "で": "場所や手段の〈で〉は、「から」に続けて名詞を修飾する形には入らない。", "と": "並列や相手を示す〈と〉は、「から」の後に続けると名詞修飾の形にならない。", "より": "比較の〈より〉は、「慣習からより」の後で名詞を修飾する形に合わない。"}, "error_tags": {"で": "場所・手段用法", "と": "並列・相手用法", "より": "比較用法"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "〈離脱〉の対義語として、組織や集団に入る意味で、ここでは対になる。"}, {"text": "集合", "is_correct": false, "explanation": "〈集合〉は人が一か所に集まることで、組織を抜ける〈離脱〉の対義語ではない。"}, {"text": "継承", "is_correct": false, "explanation": "〈継承〉は前の代の物事を受け継ぐことで、〈離脱〉の対義語ではない。"}, {"text": "献身", "is_correct": false, "explanation": "〈献身〉は自分を捧げて尽くすことで、〈離脱〉の対義語ではない。"}], "correct_answer": "加入", "explanations": {"加入": "〈離脱〉の対義語として、組織や集団に入る意味で、ここでは対になる。", "集合": "〈集合〉は人が一か所に集まることで、組織を抜ける〈離脱〉の対義語ではない。", "継承": "〈継承〉は前の代の物事を受け継ぐことで、〈離脱〉の対義語ではない。", "献身": "〈献身〉は自分を捧げて尽くすことで、〈離脱〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今までいた場所や集団から、自分から進んで去ること。特に、安定した状況から新しい環境へ移ることを言う。", "primary_collocate": null, "pronunciation": "りだつ", "ipa": "ɾidat͡sɯ", "syllable_count": 3, "sentences": [{"text": "それは、確立された安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "離脱", "complexity_tier": "T4", "furigana": "それは、確立[かくりつ]された安住[あんじゅう]の地[ち]からの離脱[りだつ]であり、新[あら]たな社会的文脈[しゃかいてきぶんみゃく]における自己[じこ]の再構築[さいこうちく]を迫[せま]られる、極[きわ]めて重要[じゅうよう]な通過儀礼[つうかぎれい]なのである。", "sentence_source": "mined"}, {"text": "彼は安定した会社からの離脱を決め、小さな農園を始めた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "彼[かれ]は安定[あんてい]した会社[かいしゃ]からの離脱[りだつ]を決[き]め、小[ちい]さな農園[のうえん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "長年いた劇団を離脱して、彼女は海外で新しい挑戦を始めた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "長年[ながねん]いた劇団[げきだん]を離脱[りだつ]して、彼女[かのじょ]は海外[かいがい]で新[あたら]しい挑戦[ちょうせん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "親元からの離脱は不安だったが、一人暮らしが自分を成長させてくれた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "親元[おやもと]からの離脱[りだつ]は不安[ふあん]だったが、一人暮[ひとりぐ]らしが自分[じぶん]を成長[せいちょう]させてくれた。", "sentence_source": "generated"}, {"text": "彼が研究室から離脱して起業すると言い出したとき、仲間は驚いた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "彼[かれ]が研究室[けんきゅうしつ]から離脱[りだつ]して起業[きぎょう]すると言[い]い出[だ]したとき、仲間[なかま]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "安定した職場から離脱する勇気がなく、転職の話を断った。", "target_word": "離脱する", "complexity_tier": "T3", "furigana": "安定[あんてい]した職場[しょくば]から離脱[りだつ]する勇気[ゆうき]がなく、転職[てんしょく]の話[はなし]を断[ことわ]った。", "sentence_source": "generated"}, {"text": "彼はバンドを離脱し、ソロで活動することにした。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "彼[かれ]はバンドを離脱[りだつ]し、ソロで活動[かつどう]することにした。", "sentence_source": "generated"}, {"text": "古い慣習からの離脱を訴えて、若い社員たちは新しい制度を提案した。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "古[ふる]い慣習[かんしゅう]からの離脱[りだつ]を訴[うった]えて、若[わか]い社員[しゃいん]たちは新[あたら]しい制度[せいど]を提案[ていあん]した。", "sentence_source": "generated"}, {"text": "故郷からの離脱を決めた兄は、東京で小さな店を開いた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "故郷[こきょう]からの離脱[りだつ]を決[き]めた兄[あに]は、東京[とうきょう]で小[ちい]さな店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "離脱を決めた理由を聞かれて、彼は「もっと自由に働きたかったからだ」と答えた。", "target_word": "離脱", "complexity_tier": "T3", "furigana": "離脱[りだつ]を決[き]めた理由[りゆう]を聞[き]かれて、彼[かれ]は「もっと自由[じゆう]に働[はたら]きたかったからだ」と答[こた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "離脱", "label": "基本形（名詞）"}, {"form": "離脱する", "label": "サ変動詞・辞書形"}, {"form": "離脱した", "label": "た形"}, {"form": "離脱し", "label": "連用形"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "安定した場所や集団から自ら進んで抜け、新しい環境へ移ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "離脱", "is_correct": true, "explanation": "「安住の地からの〜であり」に入り、今いた場所から去るという意味で文が通る。"}, {"text": "確立", "is_correct": false, "explanation": "〈確立〉は制度や基盤を立てる意味で、「からの」に続けると意味が通らない。"}, {"text": "接近", "is_correct": false, "explanation": "〈接近〉は近づくことで、「安住の地からの」の文脈では逆の動きになる。"}, {"text": "発見", "is_correct": false, "explanation": "〈発見〉は見つけることで、「安住の地からの」の文脈に合わない。"}], "explanations": {"離脱": "「安住の地からの〜であり」に入り、今いた場所から去るという意味で文が通る。", "確立": "〈確立〉は制度や基盤を立てる意味で、「からの」に続けると意味が通らない。", "接近": "〈接近〉は近づくことで、「安住の地からの」の文脈では逆の動きになる。", "発見": "〈発見〉は見つけることで、「安住の地からの」の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "離脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議室の隅から離脱して、資料を読み込んだ。", "explanation": "ここは〈一時的に部屋を出る〉の意味。〈離脱〉は組織や安定した状況から抜ける語で、〈退出〉に当たる場面には合わない。"}, {"text": "夏休みの宿題を離脱して、海へ遊びに行った。", "explanation": "ここは〈さぼる・放り出す〉の意味。〈離脱〉は組織や安定した状況から去ることで、宿題を放り出す行動には使わない。"}, {"text": "祖母は昔話の途中で離脱して、お茶を入れ直した。", "explanation": "〈離脱〉は組織や安定した状況から抜ける語で、話の途中で席を離れる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "離脱", "is_correct": true, "explanation": "「バンドを〜し、ソロで活動」に入り、バンドから抜けるという意味で文が通る。"}, {"text": "作曲", "is_correct": false, "explanation": "〈作曲〉は曲を作ることで、「バンドを〜し」の文脈に合わない。"}, {"text": "修繕", "is_correct": false, "explanation": "〈修繕〉は直すことで、「バンドを〜し」の文脈に合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "〈撮影〉は写真や映像を撮ることで、「バンドを〜し」の文脈に合わない。"}], "explanations": {"離脱": "「バンドを〜し、ソロで活動」に入り、バンドから抜けるという意味で文が通る。", "作曲": "〈作曲〉は曲を作ることで、「バンドを〜し」の文脈に合わない。", "修繕": "〈修繕〉は直すことで、「バンドを〜し」の文脈に合わない。", "撮影": "〈撮影〉は写真や映像を撮ることで、「バンドを〜し」の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "離脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は割れたコップから離脱して、新しいものを買った。", "explanation": "ここは〈取り替える・捨てる〉の意味。〈離脱〉は人や組織が安定した場所から去ることで、物には使わない。"}, {"text": "彼女は昼食の店を、混雑から離脱して選び直した。", "explanation": "〈離脱〉は組織や安定した状況から抜ける語で、混雑を避ける行動の説明には合わない。"}, {"text": "この古い家具は、部屋の隅から離脱して新しく生まれ変わった。", "explanation": "ここは〈取り除く・処分する〉の意味。〈離脱〉は人や組織が離れることに使い、物を処分する説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は組織を離脱に、一人で活動を続けた。", "corrected_sentence": "彼は組織を離脱して、一人で活動を続けた。", "error_description": "「離脱して」は動詞「離脱する」のて形。「離脱に」は動詞の活用形ではないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52502, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チームから離脱たが、その後も仲間と連絡を取った。", "corrected_sentence": "チームから離脱したが、その後も仲間と連絡を取った。", "error_description": "動詞「離脱する」の過去形は「離脱した」。「離脱た」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「教師は」で、文の話題として教師を示す。"}, {"text": "を", "is_correct": false, "explanation": "「教師を」と置くと、教師が集められる対象になり、文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「教師に宿題を集めて」では、教師が受け取り先になり、文の意味が変わって不自然。"}, {"text": "で", "is_correct": false, "explanation": "「教師で」は手段の意味になり、文の主語を示さないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「教師は」で、文の話題として教師を示す。", "を": "「教師を」と置くと、教師が集められる対象になり、文の意味が合わない。", "に": "「教師に宿題を集めて」では、教師が受け取り先になり、文の意味が変わって不自然。", "で": "「教師で」は手段の意味になり、文の主語を示さないので合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「教師も」で、子どもたちと同じく走った人を加える意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は行き先に付くもので、一緒に走った関係には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、教師を出発点に走る意味になり合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる文脈が必要で、ここでは成り立たない。"}], "correct_answer": "も", "explanations": {"も": "「教師も」で、子どもたちと同じく走った人を加える意味になる。", "へ": "方向の「へ」は行き先に付くもので、一緒に走った関係には合わない。", "から": "起点の「から」では、教師を出発点に走る意味になり合わない。", "より": "比較の「より」は比べる文脈が必要で、ここでは成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校で、子どもにものを教える人のこと。", "primary_collocate": null, "pronunciation": "きょうし", "ipa": "kʲoːɕi", "syllable_count": 3, "sentences": [{"text": "私の担任の教師は、毎朝教室で笑顔であいさつしてくれる。", "target_word": "教師", "complexity_tier": "T3", "furigana": "私[わたし]の担任[たんにん]の教師[きょうし]は、毎朝[まいあさ]教室[きょうしつ]で笑顔[えがお]であいさつしてくれる。", "sentence_source": "generated"}, {"text": "教師は宿題を集めて、一人ずつ丁寧に確認した。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]は宿題[しゅくだい]を集[あつ]めて、一人[ひとり]ずつ丁寧[ていねい]に確認[かくにん]した。", "sentence_source": "generated"}, {"text": "兄は小学校の教師をしていて、毎日たくさんのテストを採点している。", "target_word": "教師", "complexity_tier": "T3", "furigana": "兄[あに]は小学校[しょうがっこう]の教師[きょうし]をしていて、毎日[まいにち]たくさんのテストを採点[さいてん]している。", "sentence_source": "generated"}, {"text": "遠足の日、教師は子どもたちが迷わないように何度も人数を数えた。", "target_word": "教師", "complexity_tier": "T3", "furigana": "遠足[えんそく]の日[ひ]、教師[きょうし]は子[こ]どもたちが迷[まよ]わないように何度[なんど]も人数[にんずう]を数[かぞ]えた。", "sentence_source": "generated"}, {"text": "優しい教師に出会えたおかげで、算数が好きになった。", "target_word": "教師", "complexity_tier": "T3", "furigana": "優[やさ]しい教師[きょうし]に出会[であ]えたおかげで、算数[さんすう]が好[す]きになった。", "sentence_source": "generated"}, {"text": "教師が大きな声で本を読むと、一年生は静かに聞き入った。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]が大[おお]きな声[こえ]で本[ほん]を読[よ]むと、一年生[いちねんせい]は静[しず]かに聞[き]き入[い]った。", "sentence_source": "generated"}, {"text": "母は長年、教師として町の小学校に勤めてきた。", "target_word": "教師", "complexity_tier": "T3", "furigana": "母[はは]は長年[ながねん]、教師[きょうし]として町[まち]の小学校[しょうがっこう]に勤[つと]めてきた。", "sentence_source": "generated"}, {"text": "運動会では、教師も子どもたちといっしょに走った。", "target_word": "教師", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]では、教師[きょうし]も子[こ]どもたちといっしょに走[はし]った。", "sentence_source": "generated"}, {"text": "卒業式で、子どもたちは教師に花束を渡して感謝を伝えた。", "target_word": "教師", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]で、子[こ]どもたちは教師[きょうし]に花束[はなたば]を渡[わた]して感謝[かんしゃ]を伝[つた]えた。", "sentence_source": "generated"}, {"text": "教師の話をよく聞かないと、宿題の内容がわからなくなる。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]の話[はなし]をよく聞[き]かないと、宿題[しゅくだい]の内容[ないよう]がわからなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教師", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "学校で子どもに勉強を教える人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 聞き入っ (Zipf 2.26)']::text[], '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黒板", "is_correct": false, "explanation": "黒板は物で、担任として笑顔であいさつすることはない。"}, {"text": "教師", "is_correct": true, "explanation": "担任として笑顔であいさつする人が主語になる。"}, {"text": "校庭", "is_correct": false, "explanation": "場所で、あいさつをする主語にはならない。"}, {"text": "給食", "is_correct": false, "explanation": "食べ物で、あいさつができないので主語として成り立たない。"}], "explanations": {"黒板": "黒板は物で、担任として笑顔であいさつすることはない。", "教師": "担任として笑顔であいさつする人が主語になる。", "校庭": "場所で、あいさつをする主語にはならない。", "給食": "食べ物で、あいさつができないので主語として成り立たない。"}, "sentence_index": 0, "correct_answer": "教師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前の店で、教師が商品の場所を案内してくれた。", "explanation": "ここは〈店員〉の意味。店で客を案内するのは店員で、子どもに教える教師とは違うので合わない。"}, {"text": "この教師は、漢字の読み方を楽しく覚えられるように絵を添えて印刷されている。", "explanation": "ここは〈教科書〉の意味。印刷されて作られるのは教科書なので、人を指す教師には使えないので合わない。"}, {"text": "ジムで、教師が正しいフォームを一人ずつ確認した。", "explanation": "ここは〈指導員〉の意味。体の使い方を見る人は指導員で、学校で子どもに教える教師とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花壇", "is_correct": false, "explanation": "物で、勤めることはできない。"}, {"text": "教師", "is_correct": true, "explanation": "「〜として」で教える立場に就き、勤める人を表す。"}, {"text": "体育館", "is_correct": false, "explanation": "場所で、勤める立場の人にはならない。"}, {"text": "弁当", "is_correct": false, "explanation": "食べ物で、勤める立場として文が成り立たない。"}], "explanations": {"花壇": "物で、勤めることはできない。", "教師": "「〜として」で教える立場に就き、勤める人を表す。", "体育館": "場所で、勤める立場の人にはならない。", "弁当": "食べ物で、勤める立場として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "教師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国際会議で、教師が三か国の発言をその場で訳した。", "explanation": "ここは〈通訳〉の意味。発言を訳す人は通訳で、教える人の教師とは違うので合わない。"}, {"text": "熱が続いたので、教師に診てもらい、薬を出された。", "explanation": "ここは〈医師〉の意味。病気を診るのは医師で、教師は学校で教える人なので合わない。"}, {"text": "町の教師では、毎週土曜日に大人たちがダンスを練習している。", "explanation": "ここは〈教室〉（場所）の意味。人を指す教師は、練習する場所には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は去年、小学校の教師を採用された。", "corrected_sentence": "彼女は去年、小学校の教師として採用された。", "error_description": "「採用された」は受身で、「を」は目的語を示すため残せない。立場を示すには「として」を使う。正しくは「教師として採用された」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52503, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は教師を目指す、毎日勉強している。", "corrected_sentence": "妹は教師を目指し、毎日勉強している。", "error_description": "読点の前で文を続けるには連用形「目指し」が要る。終止形「目指す」のままでは文が切れて、後ろの述語とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「理科の教師」は、理科を担当する教師という名詞修飾。"}, {"text": "を", "is_correct": false, "explanation": "教師は名詞で目的語を取れないので、「理科を教師」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「理科に教師」では理科が帰着点にならず、文の関係が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は場所や方向に付くもので、理科と教師の関係には合わない。"}], "correct_answer": "の", "explanations": {"の": "「理科の教師」は、理科を担当する教師という名詞修飾。", "を": "教師は名詞で目的語を取れないので、「理科を教師」は成り立たない。", "に": "「理科に教師」では理科が帰着点にならず、文の関係が合わない。", "へ": "方向を示す「へ」は場所や方向に付くもので、理科と教師の関係には合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「新任の教師」は、新任である教師という名詞修飾。"}, {"text": "で", "is_correct": false, "explanation": "「新任で」は手段や場所の意味になり、教師を修飾できない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、新任の人から教師へという意味になり合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象が文に合わず、成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「新任の教師」は、新任である教師という名詞修飾。", "で": "「新任で」は手段や場所の意味になり、教師を修飾できない。", "から": "起点の「から」では、新任の人から教師へという意味になり合わない。", "より": "比較の「より」は比べる対象が文に合わず、成り立たない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校などで、児童や生徒に対して学問や技術などを教える人。", "primary_collocate": null, "pronunciation": "きょうし", "ipa": "kʲoːɕi", "syllable_count": 3, "sentences": [{"text": "教師の指示のもと、生徒たちは静かに頭脳をフル回転させて学習の時間を過ごした。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]の指示[しじ]のもと、生徒[せいと]たちは静[しず]かに頭脳[ずのう]をフル回転[かいてん]させて学習[がくしゅう]の時間[じかん]を過[す]ごした。", "sentence_source": "generated"}, {"text": "田中先生は二十年間、中学校で理科の教師として働いてきた。", "target_word": "教師", "complexity_tier": "T3", "furigana": "田中[たなか]先生[せんせい]は二十年間[にじゅうねんかん]、中学校[ちゅうがっこう]で理科[りか]の教師[きょうし]として働[はたら]いてきた。", "sentence_source": "generated"}, {"text": "教師が黒板に問題を書くと、生徒たちはいっせいにノートを開いた。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]が黒板[こくばん]に問題[もんだい]を書[か]くと、生徒[せいと]たちはいっせいにノートを開[ひら]いた。", "sentence_source": "generated"}, {"text": "姉は大学を出て、小学校の教師になった。", "target_word": "教師", "complexity_tier": "T3", "furigana": "姉[あね]は大学[だいがく]を出[で]て、小学校[しょうがっこう]の教師[きょうし]になった。", "sentence_source": "generated"}, {"text": "あの教師は説明が丁寧なので、生徒からとても人気がある。", "target_word": "教師", "complexity_tier": "T3", "furigana": "あの教師[きょうし]は説明[せつめい]が丁寧[ていねい]なので、生徒[せいと]からとても人気[にんき]がある。", "sentence_source": "generated"}, {"text": "将来は教師になって、子どもたちに英語を教えたいと思っている。", "target_word": "教師", "complexity_tier": "T3", "furigana": "将来[しょうらい]は教師[きょうし]になって、子[こ]どもたちに英語[えいご]を教[おし]えたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "教師は生徒の質問に一つずつ答えてから、次の単元に進んだ。", "target_word": "教師", "complexity_tier": "T3", "furigana": "教師[きょうし]は生徒[せいと]の質問[しつもん]に一[ひと]つずつ答[こた]えてから、次[つぎ]の単元[たんげん]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "新任の教師は、初日に緊張して眠れなかった。", "target_word": "教師", "complexity_tier": "T3", "furigana": "新任[しんにん]の教師[きょうし]は、初日[しょにち]に緊張[きんちょう]して眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "職員室で教師たちが来月の行事について話し合っている。", "target_word": "教師", "complexity_tier": "T3", "furigana": "職員室[しょくいんしつ]で教師[きょうし]たちが来月[らいげつ]の行事[ぎょうじ]について話[はな]し合[あ]っている。", "sentence_source": "generated"}, {"text": "父は書道の教師で、週末には近所の子どもに筆の使い方を教えている。", "target_word": "教師", "complexity_tier": "T3", "furigana": "父[ちち]は書道[しょどう]の教師[きょうし]で、週末[しゅうまつ]には近所[きんじょ]の子[こ]どもに筆[ふで]の使[つか]い方[かた]を教[おし]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教師", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "学校などで学問や技術を教える職業の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黒板", "is_correct": false, "explanation": "黒板は物で、指示を出す主体にはならない。"}, {"text": "教師", "is_correct": true, "explanation": "「〜の指示のもと」で指示を出す人を表す語。学習の場を指示する主体として合う。"}, {"text": "校庭", "is_correct": false, "explanation": "場所を表す語で、指示を出すことはできない。"}, {"text": "教室", "is_correct": false, "explanation": "場所なので、指示の主体として文が成り立たない。"}], "explanations": {"黒板": "黒板は物で、指示を出す主体にはならない。", "教師": "「〜の指示のもと」で指示を出す人を表す語。学習の場を指示する主体として合う。", "校庭": "場所を表す語で、指示を出すことはできない。", "教室": "場所なので、指示の主体として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "教師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教習所で、教師が路上教習の注意点を一つずつ説明した。", "explanation": "ここは〈教官〉の意味。教習所で運転を指導する人は教官と呼び、学校の教師とは言わないので合わない。"}, {"text": "彼女は地元のサッカークラブで、新人選手の練習メニューを組む教師を務めている。", "explanation": "ここは〈指導者〉の意味。スポーツの指導役は指導者・コーチと言い、教師とは言わないので合わない。"}, {"text": "この教師は、子どもが数字に親しめるように色や形を工夫して作られている。", "explanation": "ここは〈教材〉の意味。人を指す教師は、工夫して作られる物には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科書", "is_correct": false, "explanation": "本は質問に答えられず、主語として成り立たない。"}, {"text": "時計", "is_correct": false, "explanation": "物で、質問に答えて単元を進めることはできない。"}, {"text": "教師", "is_correct": true, "explanation": "生徒の質問に答え、単元を進める人が主語になる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は質問に答えず、主語として文が成り立たない。"}], "explanations": {"教科書": "本は質問に答えられず、主語として成り立たない。", "時計": "物で、質問に答えて単元を進めることはできない。", "教師": "生徒の質問に答え、単元を進める人が主語になる。", "窓": "窓は質問に答えず、主語として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "教師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議では、教師が両国の発言を訳して、話し合いを助けた。", "explanation": "ここは〈通訳〉の意味。発言を訳す人は通訳で、教える人の教師とは違うので合わない。"}, {"text": "風邪をひいたので、近所の教師に診てもらい、薬をもらった。", "explanation": "ここは〈医師〉の意味。病気を診るのは医師で、教師は学校で教える人なので合わない。"}, {"text": "駅前の教師では、毎週水曜日に子どもたちが集まって英会話を楽しむ。", "explanation": "ここは〈教室〉（場所）の意味。人を指す教師は、集まる場所には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は去年から高校の教師をなった。", "corrected_sentence": "叔父は去年から高校の教師になった。", "error_description": "「なる」（変化）には「に」が付く。「を」は他動詞の目的語に使うので、なるには合わない。正しくは「教師になった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は教師を志せ、大学で教育学を学んだ。", "corrected_sentence": "彼は教師を志し、大学で教育学を学んだ。", "error_description": "「志す」は連用形「志し」で文を続ける。「志せ」は命令形・仮定形で、ここでは文が続かず不自然。正しくは「志し」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
