INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52505, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人と話したり、遊んだりすること。", "primary_collocate": null, "pronunciation": "せっする", "ipa": "sesːɯɾɯ", "syllable_count": 4, "sentences": [{"text": "休み時間に、クラスの友達と接する時間が増えた。", "target_word": "接する", "complexity_tier": "T3", "furigana": "休[やす]み時間[じかん]に、クラスの友達[ともだち]と接[せっ]する時間[じかん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "留学して、いろいろな国の人と接するうちに、英語に自信がついた。", "target_word": "接する", "complexity_tier": "T3", "furigana": "留学[りゅうがく]して、いろいろな国[くに]の人[ひと]と接[せっ]するうちに、英語[えいご]に自信[じしん]がついた。", "sentence_source": "generated"}, {"text": "祖父母と接する機会が少ないので、夏休みは会いに行くつもりだ。", "target_word": "接する", "complexity_tier": "T3", "furigana": "祖父母[そふぼ]と接[せっ]する機会[きかい]が少[すく]ないので、夏休[なつやす]みは会[あ]いに行[い]くつもりだ。", "sentence_source": "generated"}, {"text": "保育士の仕事は、毎日子どもたちと接して遊ぶことが中心だ。", "target_word": "接して", "complexity_tier": "T3", "furigana": "保育士[ほいくし]の仕事[しごと]は、毎日[まいにち]子[こ]どもたちと接[せっ]して遊[あそ]ぶことが中心[ちゅうしん]だ。", "sentence_source": "generated"}, {"text": "近所のお年寄りと接するうちに、昔の町の話をたくさん聞いた。", "target_word": "接する", "complexity_tier": "T3", "furigana": "近所[きんじょ]のお年寄[としよ]りと接[せっ]するうちに、昔[むかし]の町[まち]の話[はなし]をたくさん聞[き]いた。", "sentence_source": "generated"}, {"text": "転校生と接してみると、思っていたより話しやすい人だった。", "target_word": "接して", "complexity_tier": "T3", "furigana": "転校生[てんこうせい]と接[せっ]してみると、思[おも]っていたより話[はな]しやすい人[ひと]だった。", "sentence_source": "generated"}, {"text": "人と接するのが好きなので、接客の仕事を選んだ。", "target_word": "接する", "complexity_tier": "T3", "furigana": "人[ひと]と接[せっ]するのが好[す]きなので、接客[せっきゃく]の仕事[しごと]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "一人暮らしを始めてから、家族と接する時間の大切さに気づいた。", "target_word": "接する", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしを始[はじ]めてから、家族[かぞく]と接[せっ]する時間[じかん]の大切[たいせつ]さに気[き]づいた。", "sentence_source": "generated"}, {"text": "ボランティアで高齢者と接し、いっしょに歌ったり話したりした。", "target_word": "接し", "complexity_tier": "T3", "furigana": "ボランティアで高齢者[こうれいしゃ]と接[せっ]し、いっしょに歌[うた]ったり話[はな]したりした。", "sentence_source": "generated"}, {"text": "初めて同年代の外国人と接して、たくさん話せて楽しかった。", "target_word": "接して", "complexity_tier": "T3", "furigana": "初[はじ]めて同年代[どうねんだい]の外国人[がいこくじん]と接[せっ]して、たくさん話[はな]せて楽[たの]しかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接する", "label": "辞書形"}, {"form": "接し", "label": "連用形"}, {"form": "接して", "label": "て形"}, {"form": "接した", "label": "過去形"}, {"form": "接しない", "label": "否定形"}], "register": "標準（中立）", "sense_fingerprint": "人と話したり遊んだりして触れ合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52505, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接する", "is_correct": true, "explanation": "「友達と接する時間」で、後ろの名詞「時間」を修飾する辞書形。"}, {"text": "接して", "is_correct": false, "explanation": "て形は名詞を直接修飾できないので、「接して時間」は成り立たない。"}, {"text": "眠り", "is_correct": false, "explanation": "「眠る」は寝ることで、友達との関わりの文には入らない。"}, {"text": "叩き", "is_correct": false, "explanation": "「叩く」は打つ意味で、友達と時間を過ごす文では意味が通らない。"}], "explanations": {"接する": "「友達と接する時間」で、後ろの名詞「時間」を修飾する辞書形。", "接して": "て形は名詞を直接修飾できないので、「接して時間」は成り立たない。", "眠り": "「眠る」は寝ることで、友達との関わりの文には入らない。", "叩き": "「叩く」は打つ意味で、友達と時間を過ごす文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "接する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スマホを充電器に接して、充電を始めた。", "explanation": "ここは〈接続する〉の意味。接するは人と話したり遊んだりすることなので、機器をつなぐ文には使わない。"}, {"text": "この精密機器には、乱暴に接しないでください。", "explanation": "ここは〈扱う〉の意味。接するは人と関わることなので、機器を取り扱う文には合わない。"}, {"text": "割れた皿を、のりで接して元に戻した。", "explanation": "ここは〈接着する〉の意味。接するは人と話す・遊ぶことを指すので、物をくっつける文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52505, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接する", "is_correct": true, "explanation": "「人と接するのが好き」で、「の」の前に来る辞書形。"}, {"text": "接し", "is_correct": false, "explanation": "連用形は「のが好き」と続かないので、文が成り立たない。"}, {"text": "凍え", "is_correct": false, "explanation": "「凍える」は寒さで体が冷えることで、人との関わりの文には入らない。"}, {"text": "煮詰め", "is_correct": false, "explanation": "「煮詰める」は煮て水分を減らす意味で、人との関わりの文では意味が通らない。"}], "explanations": {"接する": "「人と接するのが好き」で、「の」の前に来る辞書形。", "接し": "連用形は「のが好き」と続かないので、文が成り立たない。", "凍え": "「凍える」は寒さで体が冷えることで、人との関わりの文には入らない。", "煮詰め": "「煮詰める」は煮て水分を減らす意味で、人との関わりの文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "接する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次の行事について、みんなで接して決めた。", "explanation": "ここは〈話し合う〉の意味。接するは人と関わる態度を指すので、話し合って決める場面には合わない。"}, {"text": "取引先と値段に接して、契約の条件を決めた。", "explanation": "ここは〈交渉する〉の意味。接するは人との関わり方を指すので、値段の取り決めには使わない。"}, {"text": "先生に進路を接して、考えを整理した。", "explanation": "ここは〈相談する〉の意味。接するは人と話す態度の意味で、進路を話す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父を接する機会が少ないので、寂しい。", "corrected_sentence": "祖父と接する機会が少ないので、寂しい。", "error_description": "「を」は誤り。人を相手にする「接する」は「と」で示すのが自然で、正しくは「祖父と接する機会」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "接する", "is_correct": true, "explanation": "「いろいろな国の人と接するうちに」で、「うちに」の前は辞書形の「接する」が入る。"}, {"text": "接し", "is_correct": false, "explanation": "連用形は「うちに」の前に置けず、「接しうちに」は不自然。"}, {"text": "接して", "is_correct": false, "explanation": "て形は「うちに」に続かないので、「接してうちに」は文が成り立たない。"}, {"text": "接しろ", "is_correct": false, "explanation": "命令形は「うちに」の前に置けず、「接しろうちに」は成り立たない。"}], "correct_form": "接する", "base_form": "接する", "form_label": "辞書形", "sentence_index": 1, "explanations": {"接する": "「いろいろな国の人と接するうちに」で、「うちに」の前は辞書形の「接する」が入る。", "接し": "連用形は「うちに」の前に置けず、「接しうちに」は不自然。", "接して": "て形は「うちに」に続かないので、「接してうちに」は文が成り立たない。", "接しろ": "命令形は「うちに」の前に置けず、「接しろうちに」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52505, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父と接しる時間が好きだ。", "corrected_sentence": "祖父と接する時間が好きだ。", "error_description": "「接する」はサ変動詞なので、「接しる」は誤った活用。正しくは辞書形「接する」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "接する", "is_correct": true, "explanation": "「家族と接する時間」で、後ろの名詞「時間」を修飾する辞書形。"}, {"text": "接せ", "is_correct": false, "explanation": "未然形「接せ」は名詞を直接修飾できず、「接せ時間」は成り立たない。"}, {"text": "接させ", "is_correct": false, "explanation": "使役の語幹「接させ」は名詞を修飾できず、「接させ時間」は文として成り立たない。"}, {"text": "接すれ", "is_correct": false, "explanation": "仮定形の語幹「接すれ」は「ば」を伴わないと続かず、「接すれ時間」は成り立たない。"}], "correct_form": "接する", "base_form": "接する", "form_label": "辞書形", "sentence_index": 7, "explanations": {"接する": "「家族と接する時間」で、後ろの名詞「時間」を修飾する辞書形。", "接せ": "未然形「接せ」は名詞を直接修飾できず、「接せ時間」は成り立たない。", "接させ": "使役の語幹「接させ」は名詞を修飾できず、「接させ時間」は文として成り立たない。", "接すれ": "仮定形の語幹「接すれ」は「ば」を伴わないと続かず、「接すれ時間」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
