INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52506, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人と関わること。特に、相手に対してある態度や行動をとること。", "primary_collocate": null, "pronunciation": "せっする", "ipa": "sesːɯɾɯ", "syllable_count": 4, "sentences": [{"text": "教室という微型社会において、彼女は未知の友達とどのように接し、どのようになじんでいくのだろうか。", "target_word": "接し", "complexity_tier": "T3", "furigana": "教室[きょうしつ]という微型[びけい]社会[しゃかい]において、彼女[かのじょ]は未知[みち]の友達[ともだち]とどのように接[せっ]し、どのようになじんでいくのだろうか。", "sentence_source": "mined"}, {"text": "新人には、できるだけ優しく接するようにしている。", "target_word": "接する", "complexity_tier": "T3", "furigana": "新人[しんじん]には、できるだけ優[やさ]しく接[せっ]するようにしている。", "sentence_source": "generated"}, {"text": "店員は客に丁寧に接するので、この店は評判がいい。", "target_word": "接する", "complexity_tier": "T3", "furigana": "店員[てんいん]は客[きゃく]に丁寧[ていねい]に接[せっ]するので、この店[みせ]は評判[ひょうばん]がいい。", "sentence_source": "generated"}, {"text": "先生は生徒一人ひとりに公平に接している。", "target_word": "接し", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]一人[ひとり]ひとりに公平[こうへい]に接[せっ]している。", "sentence_source": "generated"}, {"text": "彼は誰に対しても誠実に接する人だ。", "target_word": "接する", "complexity_tier": "T3", "furigana": "彼[かれ]は誰[だれ]に対[たい]しても誠実[せいじつ]に接[せっ]する人[ひと]だ。", "sentence_source": "generated"}, {"text": "年上の人に接するときは、言葉づかいに気をつけたい。", "target_word": "接する", "complexity_tier": "T3", "furigana": "年上[としうえ]の人[ひと]に接[せっ]するときは、言葉[ことば]づかいに気[き]をつけたい。", "sentence_source": "generated"}, {"text": "親が冷たく接したせいで、子どもは心を閉ざしてしまった。", "target_word": "接し", "complexity_tier": "T3", "furigana": "親[おや]が冷[つめ]たく接[せっ]したせいで、子[こ]どもは心[こころ]を閉[と]ざしてしまった。", "sentence_source": "generated"}, {"text": "外国から来た同僚にも、普通の友達と同じように接してほしい。", "target_word": "接して", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た同僚[どうりょう]にも、普通[ふつう]の友達[ともだち]と同[おな]じように接[せっ]してほしい。", "sentence_source": "generated"}, {"text": "患者に温かく接する看護師の姿に、多くの人が感動した。", "target_word": "接する", "complexity_tier": "T3", "furigana": "患者[かんじゃ]に温[あたた]かく接[せっ]する看護師[かんごし]の姿[すがた]に、多[おお]くの人[ひと]が感動[かんどう]した。", "sentence_source": "generated"}, {"text": "部下に接する態度が変わってから、職場の雰囲気がよくなった。", "target_word": "接する", "complexity_tier": "T3", "furigana": "部下[ぶか]に接[せっ]する態度[たいど]が変[か]わってから、職場[しょくば]の雰囲気[ふんいき]がよくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接する", "label": "辞書形"}, {"form": "接し", "label": "連用形"}, {"form": "接して", "label": "て形"}, {"form": "接した", "label": "過去形"}, {"form": "接しない", "label": "否定形"}], "register": "標準（中立）", "sense_fingerprint": "相手に対してある態度で関わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接し", "is_correct": true, "explanation": "「どのように接し」で、人への態度を表す連用形として空欄に入る唯一の形。"}, {"text": "凍え", "is_correct": false, "explanation": "「凍える」は寒さで体が冷えることで、人への態度の意味にならない。"}, {"text": "尽き", "is_correct": false, "explanation": "「尽きる」は「なくなる」の意味で、人を相手にする文には入らない。"}, {"text": "煮詰め", "is_correct": false, "explanation": "「煮詰める」は煮て水分を減らす意味で、人との関わり方の文では意味が通らない。"}], "explanations": {"接し": "「どのように接し」で、人への態度を表す連用形として空欄に入る唯一の形。", "凍え": "「凍える」は寒さで体が冷えることで、人への態度の意味にならない。", "尽き": "「尽きる」は「なくなる」の意味で、人を相手にする文には入らない。", "煮詰め": "「煮詰める」は煮て水分を減らす意味で、人との関わり方の文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "接し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーブルをパソコンに接して、データを移した。", "explanation": "ここは〈接続する〉の意味。接するは人との関わりや隣り合う状態を指すので、機器をつなぐ意味では使わない。"}, {"text": "壊れやすい陶器に、乱暴に接しないでください。", "explanation": "ここは〈扱う〉の意味。接するは人への態度を表すので、物を取り扱う文には使わない。"}, {"text": "割れた皿を、のりで接して元に戻した。", "explanation": "ここは〈接着する〉の意味。接するは人との関わり方を指すので、物をくっつける意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接し", "is_correct": true, "explanation": "「冷たく接したせいで」の「接し」（＋「た」）。態度を表す動詞の連用形として唯一入る。"}, {"text": "溶け", "is_correct": false, "explanation": "「溶ける」は物が液体になることで、人への態度には使わない。"}, {"text": "沸か", "is_correct": false, "explanation": "「沸かす」は湯などを熱して沸騰させることで、ここでは意味が通らない。"}, {"text": "焦がし", "is_correct": false, "explanation": "「焦がす」は表面を焦がす意味で、人への態度の文では成り立たない。"}], "explanations": {"接し": "「冷たく接したせいで」の「接し」（＋「た」）。態度を表す動詞の連用形として唯一入る。", "溶け": "「溶ける」は物が液体になることで、人への態度には使わない。", "沸か": "「沸かす」は湯などを熱して沸騰させることで、ここでは意味が通らない。", "焦がし": "「焦がす」は表面を焦がす意味で、人への態度の文では成り立たない。"}, "sentence_index": 6, "correct_answer": "接し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械の故障には、専門の技術者が二時間以内に接している。", "explanation": "ここは〈対応する〉の意味。接するは人と関わる態度を指すので、故障の処理には合わない。"}, {"text": "壊れた冷蔵庫に、すぐ接して直した。", "explanation": "ここは〈修理する〉の意味。接するは人との関わりを指すので、機械を直す文には合わない。"}, {"text": "届いた注文には、その日のうちに接する決まりだ。", "explanation": "ここは〈処理する〉の意味。接するは人との関わりを指すので、注文の処理には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩を厳しく接するのは、本当の指導ではない。", "corrected_sentence": "先輩に厳しく接するのは、本当の指導ではない。", "error_description": "「を」は誤り。態度を向ける相手は「に」で示すのが自然で、正しくは「先輩に厳しく接する」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "接する", "is_correct": true, "explanation": "「優しく接するようにしている」で、「ようにしている」の前に来る辞書形。"}, {"text": "接し", "is_correct": false, "explanation": "連用形は「ようにしている」と続けられないので、文が成り立たない。"}, {"text": "接して", "is_correct": false, "explanation": "て形は「ようにしている」の前に置けず、文が成り立たない。"}, {"text": "接しろ", "is_correct": false, "explanation": "命令形は「ようにしている」の前に置けず、「接しろようにしている」は成り立たない。"}], "correct_form": "接する", "base_form": "接する", "form_label": "辞書形", "sentence_index": 1, "explanations": {"接する": "「優しく接するようにしている」で、「ようにしている」の前に来る辞書形。", "接し": "連用形は「ようにしている」と続けられないので、文が成り立たない。", "接して": "て形は「ようにしている」の前に置けず、文が成り立たない。", "接しろ": "命令形は「ようにしている」の前に置けず、「接しろようにしている」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は後輩に温かく接して人だ。", "corrected_sentence": "彼女は後輩に温かく接する人だ。", "error_description": "名詞「人」を修飾する位置は辞書形（連体形）の「接する」。「接して」は て形で、名詞を修飾できない。正しくは「温かく接する人」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "接して", "is_correct": true, "explanation": "「優しく接してほしい」で、「ほしい」に続くて形。"}, {"text": "接する", "is_correct": false, "explanation": "辞書形は「ほしい」に直接続かず、「接するほしい」は不自然になる。"}, {"text": "接しない", "is_correct": false, "explanation": "否定形は「接しないでほしい」のように「で」を挟むので、「接しないほしい」は文が成り立たない。"}, {"text": "接した", "is_correct": false, "explanation": "過去形は「接したほしい」の形で続けられず、文が成り立たない。"}], "correct_form": "接して", "base_form": "接する", "form_label": "て形", "sentence_index": 7, "explanations": {"接して": "「優しく接してほしい」で、「ほしい」に続くて形。", "接する": "辞書形は「ほしい」に直接続かず、「接するほしい」は不自然になる。", "接しない": "否定形は「接しないでほしい」のように「で」を挟むので、「接しないほしい」は文が成り立たない。", "接した": "過去形は「接したほしい」の形で続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
