INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52507, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まったく音がなくて、しずかなこと。", "primary_collocate": null, "pronunciation": "せいじゃく", "ipa": "seːdʑakɯ", "syllable_count": 4, "sentences": [{"text": "停電した瞬間、部屋は完全な静寂になった。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "停電[ていでん]した瞬間[しゅんかん]、部屋[へや]は完全[かんぜん]な静寂[せいじゃく]になった。", "sentence_source": "generated"}, {"text": "宇宙は空気がないため、音のない静寂の世界だ。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]は空気[くうき]がないため、音[おと]のない静寂[せいじゃく]の世界[せかい]だ。", "sentence_source": "generated"}, {"text": "彼の発言のあと、会議室に重い静寂が流れた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]のあと、会議室[かいぎしつ]に重[おも]い静寂[せいじゃく]が流[なが]れた。", "sentence_source": "generated"}, {"text": "雪の積もった夜は、物音ひとつしない静寂が広がる。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "雪[ゆき]の積[つ]もった夜[よる]は、物音[ものおと]ひとつしない静寂[せいじゃく]が広[ひろ]がる。", "sentence_source": "generated"}, {"text": "演奏が終わっても、会場はしばらく静寂のままだった。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "演奏[えんそう]が終[お]わっても、会場[かいじょう]はしばらく静寂[せいじゃく]のままだった。", "sentence_source": "generated"}, {"text": "突然の静寂に驚いて、赤ちゃんが泣きやんだ。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "突然[とつぜん]の静寂[せいじゃく]に驚[おどろ]いて、赤[あか]ちゃんが泣[な]きやんだ。", "sentence_source": "generated"}, {"text": "洞窟の奥は、水の落ちる音も消える静寂だった。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]は、水[みず]の落[お]ちる音[おと]も消[き]える静寂[せいじゃく]だった。", "sentence_source": "generated"}, {"text": "黙とうの合図とともに、会場は静寂に包まれた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "黙[もく]とうの合図[あいず]とともに、会場[かいじょう]は静寂[せいじゃく]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "静寂を破るように、遠くで犬が吠えた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "静寂[せいじゃく]を破[やぶ]るように、遠[とお]くで犬[いぬ]が吠[ほ]えた。", "sentence_source": "generated"}, {"text": "防音室に入ると、耳が痛くなるほどの静寂を感じる。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "防音室[ぼうおんしつ]に入[はい]ると、耳[みみ]が痛[いた]くなるほどの静寂[せいじゃく]を感[かん]じる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静寂", "label": "基本形"}, {"form": "静寂に", "label": "に格"}, {"form": "静寂の", "label": "連体"}], "register": "中立（常体）", "sense_fingerprint": "物音ひとつしない、完全な無音のしずけさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静寂", "is_correct": true, "explanation": "「部屋は完全な静寂になった」で、停電後の物音ひとつしない状態を表す唯一の語。"}, {"text": "脱落", "is_correct": false, "explanation": "「脱落」は抜け落ちることで、部屋の状態を表す文では意味が通らない。"}, {"text": "充血", "is_correct": false, "explanation": "「充血」は血液が集まることで、部屋の状態を表す語ではない。"}, {"text": "分岐", "is_correct": false, "explanation": "「分岐」は枝分かれすることで、部屋の状態には使えない。"}], "explanations": {"静寂": "「部屋は完全な静寂になった」で、停電後の物音ひとつしない状態を表す唯一の語。", "脱落": "「脱落」は抜け落ちることで、部屋の状態を表す文では意味が通らない。", "充血": "「充血」は血液が集まることで、部屋の状態を表す語ではない。", "分岐": "「分岐」は枝分かれすることで、部屋の状態には使えない。"}, "sentence_index": 0, "correct_answer": "静寂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は静寂の声で、みんなに挨拶した。", "explanation": "ここは〈静かだ〉の意味。静寂は音がない状態を指す語で、声の大きさを表す語ではない。"}, {"text": "子どもたちの静寂が部屋に響いた。", "explanation": "ここは〈笑い声〉の意味。静寂は音がない状態を指し、響く音を表す語ではない。"}, {"text": "彼女は静寂に笑いながら、部屋を出ていった。", "explanation": "ここは〈静かに〉の意味。静寂は名詞で、笑い方を表す副詞の働きはしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静寂", "is_correct": true, "explanation": "「音も消える静寂だった」で、洞窟の音のない状態を表す唯一の語。"}, {"text": "融解", "is_correct": false, "explanation": "「融解」は固体が溶けることで、洞窟の状態を表す語ではない。"}, {"text": "混線", "is_correct": false, "explanation": "「混線」は通信が混ざることで、音が消える状態には合わない。"}, {"text": "浸透", "is_correct": false, "explanation": "「浸透」は液体などが染み込むことで、洞窟の状態を表す文では意味が通らない。"}], "explanations": {"静寂": "「音も消える静寂だった」で、洞窟の音のない状態を表す唯一の語。", "融解": "「融解」は固体が溶けることで、洞窟の状態を表す語ではない。", "混線": "「混線」は通信が混ざることで、音が消える状態には合わない。", "浸透": "「浸透」は液体などが染み込むことで、洞窟の状態を表す文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "静寂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場が静寂に盛り上がった。", "explanation": "ここは〈にぎやか〉の意味。静寂は音がない状態なので、盛り上がるという様子とは合わない。"}, {"text": "彼女は静寂の抗議を続けた。", "explanation": "ここは〈無言〉の意味。静寂は場の状態を指すので、無言で抗議するという人の態度には合わない。"}, {"text": "彼女の静寂は、いつも周りを明るくする。", "explanation": "ここは〈明るい〉の意味。静寂は音のない状態を指すので、人を明るくする性質を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を閉めると、部屋は完全な静寂を包まれた。", "corrected_sentence": "窓を閉めると、部屋は完全な静寂に包まれた。", "error_description": "「包まれる」は「に」で受けるので、「を」は誤り。正しくは「静寂に包まれた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "真夜中の静寂を山道が包まれた。", "corrected_sentence": "真夜中の静寂に山道が包まれた。", "error_description": "「包まれる」は「に」で受けるので、「を」は誤り。正しくは「静寂に山道が包まれた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
