INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音がなく、おだやかでしずかな状態。", "primary_collocate": null, "pronunciation": "せいじゃく", "ipa": "seːdʑakɯ", "syllable_count": 4, "sentences": [{"text": "教師の指示のもと、静寂を保ちつつ、生徒たちは頭脳をフル回転させて学ぶ時間だ。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "教師[きょうし]の指示[しじ]のもと、静寂[せいじゃく]を保[たも]ちつつ、生徒[せいと]たちは頭脳[ずのう]をフル回転[かいてん]させて学[まな]ぶ時間[じかん]だ。", "sentence_source": "generated"}, {"text": "雪が降り続く夜、町は深い静寂に包まれていた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]り続[つづ]く夜[よる]、町[まち]は深[ふか]い静寂[せいじゃく]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "朝の森には、鳥の声さえ遠く聞こえるほどの静寂があった。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "朝[あさ]の森[もり]には、鳥[とり]の声[こえ]さえ遠[とお]く聞[き]こえるほどの静寂[せいじゃく]があった。", "sentence_source": "generated"}, {"text": "嵐が去ったあとの静寂の中で、漁師たちはほっと息をついた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "嵐[あらし]が去[さ]ったあとの静寂[せいじゃく]の中[なか]で、漁師[りょうし]たちはほっと息[いき]をついた。", "sentence_source": "generated"}, {"text": "図書館の静寂を乱さないように、そっと本を閉じた。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "図書館[としょかん]の静寂[せいじゃく]を乱[みだ]さないように、そっと本[ほん]を閉[と]じた。", "sentence_source": "generated"}, {"text": "祭りが終わると、神社はいつもの静寂を取り戻した。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "祭[まつ]りが終[お]わると、神社[じんじゃ]はいつもの静寂[せいじゃく]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "湖に映る山を眺めていると、心まで静寂に満たされる。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "湖[みずうみ]に映[うつ]る山[やま]を眺[なが]めていると、心[こころ]まで静寂[せいじゃく]に満[み]たされる。", "sentence_source": "generated"}, {"text": "都会の騒音から離れ、静寂のなかで一日を過ごした。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "都会[とかい]の騒音[そうおん]から離[はな]れ、静寂[せいじゃく]のなかで一日[いちにち]を過[す]ごした。", "sentence_source": "generated"}, {"text": "修行僧たちは、お堂の静寂を大切にして毎朝座禅を組む。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "修行僧[しゅぎょうそう]たちは、お堂[どう]の静寂[せいじゃく]を大切[たいせつ]にして毎朝[まいあさ]座禅[ざぜん]を組[く]む。", "sentence_source": "generated"}, {"text": "夕立がやむと、公園は穏やかな静寂に戻った。", "target_word": "静寂", "complexity_tier": "T3", "furigana": "夕立[ゆうだち]がやむと、公園[こうえん]は穏[おだ]やかな静寂[せいじゃく]に戻[もど]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静寂", "label": "基本形"}, {"form": "静寂に", "label": "に格"}, {"form": "静寂の", "label": "連体"}], "register": "中立（常体）", "sense_fingerprint": "音がなくおだやかで落ち着いた、しずかな状態や雰囲気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静寂", "is_correct": true, "explanation": "「静寂を保ちつつ」で、音のない落ち着いた状態を保つという意味が通る唯一の語。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音を保つ」は意味が逆で、学習の静かな環境の文に合わない。"}, {"text": "雑踏", "is_correct": false, "explanation": "「雑踏」は人混みのことで、保つ対象として意味が通らない。"}, {"text": "散乱", "is_correct": false, "explanation": "「散乱」は散らばることで、学習の環境を保つ文には合わない。"}], "explanations": {"静寂": "「静寂を保ちつつ」で、音のない落ち着いた状態を保つという意味が通る唯一の語。", "騒音": "「騒音を保つ」は意味が逆で、学習の静かな環境の文に合わない。", "雑踏": "「雑踏」は人混みのことで、保つ対象として意味が通らない。", "散乱": "「散乱」は散らばることで、学習の環境を保つ文には合わない。"}, "sentence_index": 0, "correct_answer": "静寂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は静寂な計算で、会議の予算を決めた。", "explanation": "ここは〈正確さ〉の意味になるが、静寂は音や雰囲気の語で、計算の正確さは表さない。"}, {"text": "彼は静寂な早口で、みんなに説明した。", "explanation": "ここは〈速さ〉の意味になるが、静寂は音や雰囲気の語で、話す速さは表さない。"}, {"text": "彼は静寂に判断した。", "explanation": "ここは〈冷静〉の意味。静寂は音がない状態で、判断の仕方を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静寂", "is_correct": true, "explanation": "「心まで静寂に満たされる」で、静かで穏やかな状態に満たされるという意味が通る。"}, {"text": "溶解", "is_correct": false, "explanation": "「溶解」は物質が溶けることで、心を満たす文では成り立たない。"}, {"text": "混濁", "is_correct": false, "explanation": "「混濁」は濁って混ざることで、心の状態を満たす文には合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "「沈殿」は液体の中で物質が沈むことで、心を満たす文では意味が通らない。"}], "explanations": {"静寂": "「心まで静寂に満たされる」で、静かで穏やかな状態に満たされるという意味が通る。", "溶解": "「溶解」は物質が溶けることで、心を満たす文では成り立たない。", "混濁": "「混濁」は濁って混ざることで、心の状態を満たす文には合わない。", "沈殿": "「沈殿」は液体の中で物質が沈むことで、心を満たす文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "静寂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の資料を静寂にまとめた。", "explanation": "ここは〈まとめる〉の意味になるが、静寂は場の状態を表す語で、資料を整理する動作には使わない。"}, {"text": "この機械は静寂の材料で作られている。", "explanation": "ここは〈材料〉の意味になるが、静寂は状態を表す語で、素材を表す用法はない。"}, {"text": "彼女は怒りを静寂の箱に入れて運んだ。", "explanation": "ここは〈運ぶ〉の意味になるが、静寂は周囲の状態を表す語で、容器にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の森は静寂で包まれている。", "corrected_sentence": "夜の森は静寂に包まれている。", "error_description": "「包まれる」は「に」で受けるので、「で」は誤り。正しくは「静寂に包まれている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深い静寂を包まれた夜に、星がよく見えた。", "corrected_sentence": "深い静寂に包まれた夜に、星がよく見えた。", "error_description": "「包まれる」は「に」で受けるので、「を」は誤り。正しくは「静寂に包まれた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「頭脳が働かない」と、主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「働かない」は目的語をとらないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「頭脳へ働かない」では意味がつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「頭脳と働かない」では述語とつながらない。"}], "correct_answer": "が", "explanations": {"が": "「頭脳が働かない」と、主語を示す「が」。", "を": "「を」は目的語を示す。「働かない」は目的語をとらないので合わない。", "へ": "「へ」は方向を示す。「頭脳へ働かない」では意味がつながらない。", "と": "「と」は並列や相手を示す。「頭脳と働かない」では述語とつながらない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「頭脳に自信がある」と、自信の根拠を示す「に」。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「頭脳で自信がある」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「頭脳から自信がある」では不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「頭脳より自信がある」では比べる対象が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「頭脳に自信がある」と、自信の根拠を示す「に」。", "で": "「で」は手段を示す。「頭脳で自信がある」では意味が通らない。", "から": "「から」は起点を示す。「頭脳から自信がある」では不自然。", "より": "「より」は比較を示す。「頭脳より自信がある」では比べる対象が成立しない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あたまのなかで、ものをかんがえるちから。", "primary_collocate": null, "pronunciation": "ずのう", "ipa": "zɯnoː", "syllable_count": 3, "sentences": [{"text": "子どもの頭脳は、遊びを通してどんどん育つ。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "子[こ]どもの頭脳[ずのう]は、遊[あそ]びを通[とお]してどんどん育[そだ]つ。", "sentence_source": "generated"}, {"text": "疲れていて、頭脳がうまく働かない。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "疲[つか]れていて、頭脳[ずのう]がうまく働[はたら]かない。", "sentence_source": "generated"}, {"text": "彼は頭脳が鋭く、先生の質問にすぐ答える。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "彼[かれ]は頭脳[ずのう]が鋭[するど]く、先生[せんせい]の質問[しつもん]にすぐ答[こた]える。", "sentence_source": "generated"}, {"text": "夜によく寝ると、朝の頭脳がすっきりする。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "夜[よる]によく寝[ね]ると、朝[あさ]の頭脳[ずのう]がすっきりする。", "sentence_source": "generated"}, {"text": "パズルをして頭脳を使うのが好きだ。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "パズルをして頭脳[ずのう]を使[つか]うのが好[す]きだ。", "sentence_source": "generated"}, {"text": "祖父は年を取っても頭脳が明晰で、新聞の話題に詳しい。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "祖父[そふ]は年[とし]を取[と]っても頭脳[ずのう]が明晰[めいせき]で、新聞[しんぶん]の話題[わだい]に詳[くわ]しい。", "sentence_source": "generated"}, {"text": "試験の前は、頭脳を休ませるために早く寝る。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、頭脳[ずのう]を休[やす]ませるために早[はや]く寝[ね]る。", "sentence_source": "generated"}, {"text": "兄は頭脳に自信があり、いつも成績が一番だ。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "兄[あに]は頭脳[ずのう]に自信[じしん]があり、いつも成績[せいせき]が一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "朝の散歩は、頭脳を目覚めさせてくれる。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "朝[あさ]の散歩[さんぽ]は、頭脳[ずのう]を目覚[めざ]めさせてくれる。", "sentence_source": "generated"}, {"text": "科学者は、自分の頭脳で新しい答えを探し続ける。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、自分[じぶん]の頭脳[ずのう]で新[あたら]しい答[こた]えを探[さが]し続[つづ]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭脳", "label": "基本形"}, {"form": "頭脳を", "label": "を格"}, {"form": "頭脳が", "label": "が格"}], "register": "中立（常体）", "sense_fingerprint": "あたまの中でものを考える力。考える働きそのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頭脳", "is_correct": true, "explanation": "遊びを通して育つ、考える力としての頭脳が入る。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表すので、遊びを通して育つ対象としては不自然。"}, {"text": "年齢", "is_correct": false, "explanation": "生きてきた年数を表すので、育つ対象にはならない。"}, {"text": "給料", "is_correct": false, "explanation": "働いて得る金銭を表すので、遊びを通して育つ対象にはならない。"}], "explanations": {"頭脳": "遊びを通して育つ、考える力としての頭脳が入る。", "体重": "体の重さを表すので、遊びを通して育つ対象としては不自然。", "年齢": "生きてきた年数を表すので、育つ対象にはならない。", "給料": "働いて得る金銭を表すので、遊びを通して育つ対象にはならない。"}, "sentence_index": 0, "correct_answer": "頭脳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さで指先の頭脳がなくなった。", "explanation": "ここは〈感覚〉の意味。頭脳は考える力で、指先で感じる働きを指さないので、「指先の感覚」の代わりには合わない。"}, {"text": "ぶつけた頭脳がまだ痛い。", "explanation": "ここは〈頭〉の意味。頭脳は体の部分ではなく考える力なので、ぶつけて痛む対象ではない。"}, {"text": "嬉しさで頭脳が湧き上がった。", "explanation": "ここは〈感情〉の意味。頭脳は感情ではなく考える働きなので、湧き上がるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭脳", "is_correct": true, "explanation": "「頭脳を休ませる」は、考える力を休ませるという意味で自然。"}, {"text": "教科書", "is_correct": false, "explanation": "紙の本を指すので、休ませる対象としては不自然。"}, {"text": "辞書", "is_correct": false, "explanation": "調べるための本を指すので、休ませる対象にはならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書くための道具を指すので、休ませる対象にはならない。"}], "explanations": {"頭脳": "「頭脳を休ませる」は、考える力を休ませるという意味で自然。", "教科書": "紙の本を指すので、休ませる対象としては不自然。", "辞書": "調べるための本を指すので、休ませる対象にはならない。", "鉛筆": "書くための道具を指すので、休ませる対象にはならない。"}, "sentence_index": 6, "correct_answer": "頭脳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風呂上がりに頭脳をドライヤーでよく乾かした。", "explanation": "ここは〈髪〉を表す場面。頭脳は思考の働きを指すので、ドライヤーで乾かす対象ではない。"}, {"text": "長い一日で頭脳がたまった。", "explanation": "ここは〈疲れ〉の意味。頭脳は疲労を表さないので、疲れのように「たまる」とは合わない。"}, {"text": "額から頭脳が流れた。", "explanation": "ここは〈汗〉の意味。頭脳は体から流れ出るものではないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は頭脳に鍛えるため、毎日パズルをする。", "corrected_sentence": "彼は頭脳を鍛えるため、毎日パズルをする。", "error_description": "「鍛える」の対象は「を」で示す。「頭脳に」は誤りで、正しくは「頭脳を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52509, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パズルを解くと、頭脳が鍛える。", "corrected_sentence": "パズルを解くと、頭脳が鍛えられる。", "error_description": "「頭脳が」に続くのは受け身の「鍛えられる」。能動の「鍛える」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
