INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「頭脳が優れている」と、主語の頭脳を優れていると述べる「が」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「優れている」は目的語をとらないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「頭脳と優れている」では述語とつながらない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「頭脳から優れている」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「頭脳が優れている」と、主語の頭脳を優れていると述べる「が」。", "を": "「を」は目的語を示す。「優れている」は目的語をとらないので合わない。", "と": "「と」は並列や相手を示す。「頭脳と優れている」では述語とつながらない。", "から": "「から」は起点を示す。「頭脳から優れている」では意味が通らない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "思考や判断、知能などの働き。また、その能力。", "primary_collocate": null, "pronunciation": "ずのう", "ipa": "zɯnoː", "syllable_count": 3, "sentences": [{"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "教師[きょうし]の指示[しじ]のもと、静寂[せいじゃく]を保[たも]ちつつも頭脳[ずのう]をフル回転[かいてん]させる学習[がくしゅう]の時間[じかん]。", "sentence_source": "mined"}, {"text": "将棋の名人は、長い時間でも頭脳の働きが衰えない。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]の名人[めいじん]は、長[なが]い時間[じかん]でも頭脳[ずのう]の働[はたら]きが衰[おとろ]えない。", "sentence_source": "generated"}, {"text": "試験前に徹夜すると、頭脳が十分に働かなくなる。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]に徹夜[てつや]すると、頭脳[ずのう]が十分[じゅうぶん]に働[はたら]かなくなる。", "sentence_source": "generated"}, {"text": "彼女は頭脳を使う仕事が好きで、数学者になった。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は頭脳[ずのう]を使[つか]う仕事[しごと]が好[す]きで、数学者[すうがくしゃ]になった。", "sentence_source": "generated"}, {"text": "この問題は体力ではなく頭脳で勝負するしかない。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "この問題[もんだい]は体力[たいりょく]ではなく頭脳[ずのう]で勝負[しょうぶ]するしかない。", "sentence_source": "generated"}, {"text": "新しい計画は、チーム全員の頭脳を結集して作り上げた。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "新しい計画[あたらしいけいかく]は、チーム全員[ぜんいん]の頭脳[ずのう]を結集[けっしゅう]して作り上げた。", "sentence_source": "generated"}, {"text": "朝食をとらないと、頭脳の動きが鈍くなることがある。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "朝食[ちょうしょく]をとらないと、頭脳[ずのう]の動[うご]きが鈍[にぶ]くなることがある。", "sentence_source": "generated"}, {"text": "彼は頭脳が優れていて、難しい問題もすぐに解く。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "彼[かれ]は頭脳[ずのう]が優[すぐ]れていて、難[むずか]しい問題[もんだい]もすぐに解[と]く。", "sentence_source": "generated"}, {"text": "詰め将棋は、頭脳を鍛えるのにちょうどいい遊びだ。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "詰[つ]め将棋[しょうぎ]は、頭脳[ずのう]を鍛[きた]えるのにちょうどいい遊[あそ]びだ。", "sentence_source": "generated"}, {"text": "長い会議で頭脳を使い果たし、帰りは何も考えられなかった。", "target_word": "頭脳", "complexity_tier": "T3", "furigana": "長[なが]い会議[かいぎ]で頭脳[ずのう]を使[つか]い果[は]たし、帰[かえ]りは何[なに]も考[かんが]えられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭脳", "label": "基本形"}, {"form": "頭脳を", "label": "を格"}, {"form": "頭脳で", "label": "で格"}], "register": "中立（常体）", "sense_fingerprint": "思考・判断・知能の働きやその能力。体力や腕力と対比される知的な力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 詰め将棋 (Zipf 1.87)']::text[], '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頭脳", "is_correct": true, "explanation": "「フル回転させる」の対象として、思考の働きを指す頭脳が入る。"}, {"text": "視力", "is_correct": false, "explanation": "目で物を見分ける力を指すので、フル回転させる対象にはならない。"}, {"text": "聴力", "is_correct": false, "explanation": "音を聞き取る力を指すので、フル回転させる対象としては不自然。"}, {"text": "握力", "is_correct": false, "explanation": "手で握る力を指すので、フル回転させる対象にはならない。"}], "explanations": {"頭脳": "「フル回転させる」の対象として、思考の働きを指す頭脳が入る。", "視力": "目で物を見分ける力を指すので、フル回転させる対象にはならない。", "聴力": "音を聞き取る力を指すので、フル回転させる対象としては不自然。", "握力": "手で握る力を指すので、フル回転させる対象にはならない。"}, "sentence_index": 0, "correct_answer": "頭脳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は絵の頭脳があって、若くして賞を取った。", "explanation": "ここは〈才能〉の意味。頭脳は考える働きそのもので、特定の分野の才能を指さないので、「絵の才能」の代わりには合わない。"}, {"text": "彼は頭脳が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。頭脳は考える働きやその能力で、豊富さを量で表す対象ではないので合わない。"}, {"text": "寝起きに頭脳をかきむしって、髪がぼさぼさになった。", "explanation": "ここは〈頭〉の意味。頭脳は体の部分ではないので、かきむしる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭脳", "is_correct": true, "explanation": "「頭脳の動きが鈍くなる」は、考える働きが衰えることを表すので自然。"}, {"text": "嗅覚", "is_correct": false, "explanation": "匂いを感じる感覚で、「動きが鈍くなる」対象としては不自然。"}, {"text": "味覚", "is_correct": false, "explanation": "味を感じる感覚で、「動きが鈍くなる」対象としては不自然。"}, {"text": "触覚", "is_correct": false, "explanation": "触れた感じを捉える感覚で、「動きが鈍くなる」対象にはならない。"}], "explanations": {"頭脳": "「頭脳の動きが鈍くなる」は、考える働きが衰えることを表すので自然。", "嗅覚": "匂いを感じる感覚で、「動きが鈍くなる」対象としては不自然。", "味覚": "味を感じる感覚で、「動きが鈍くなる」対象としては不自然。", "触覚": "触れた感じを捉える感覚で、「動きが鈍くなる」対象にはならない。"}, "sentence_index": 6, "correct_answer": "頭脳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風呂上がりに頭脳をドライヤーでよく乾かした。", "explanation": "ここは〈髪〉を表す場面。頭脳は思考の働きを指すので、ドライヤーで乾かす対象ではない。"}, {"text": "試合に勝って、頭脳が大きく湧き上がった。", "explanation": "ここは〈感情〉の意味。頭脳は感情ではなく考える働きなので、湧き上がるものではない。"}, {"text": "長い一日で、頭脳がたまった。", "explanation": "ここは〈疲れ〉の意味。頭脳は疲労を表さないので、疲れのように「たまる」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は頭脳に活かせる仕事を選んだ。", "corrected_sentence": "彼女は頭脳を活かせる仕事を選んだ。", "error_description": "「活かす」の対象は「を」で示す。「頭脳に」は誤りで、正しくは「頭脳を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "頭脳を優れた人は、難しい問題もすぐに解く。", "corrected_sentence": "頭脳が優れた人は、難しい問題もすぐに解く。", "error_description": "「優れた」の主語は「が」で示す。「頭脳を」は誤りで、正しくは「頭脳が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
