INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52511, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いっぱい。ぜんぶ。", "primary_collocate": null, "pronunciation": "ふる", "ipa": "ɸɯɾɯ", "syllable_count": 2, "sentences": [{"text": "携帯電話の電池がフルになるまで、一時間かかる。", "target_word": "フル", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の電池[でんち]がフルになるまで、一時間[いちじかん]かかる。", "sentence_source": "generated"}, {"text": "好きな曲を、短くない完全版でフルで聞きたい。", "target_word": "フル", "complexity_tier": "T3", "furigana": "好[す]きな曲[きょく]を、短[みじか]くない完全版[かんぜんばん]でフルで聞[き]きたい。", "sentence_source": "generated"}, {"text": "ラジオの音量をフルにしたら、近所から苦情が来た。", "target_word": "フル", "complexity_tier": "T3", "furigana": "ラジオの音量[おんりょう]をフルにしたら、近所[きんじょ]から苦情[くじょう]が来[き]た。", "sentence_source": "generated"}, {"text": "昨日は朝から夜まで、予定がフルだった。", "target_word": "フル", "complexity_tier": "T3", "furigana": "昨日[きのう]は朝[あさ]から夜[よる]まで、予定[よてい]がフルだった。", "sentence_source": "generated"}, {"text": "車のガソリンをフルにして、長い旅に出た。", "target_word": "フル", "complexity_tier": "T3", "furigana": "車[くるま]のガソリンをフルにして、長[なが]い旅[たび]に出[で]た。", "sentence_source": "generated"}, {"text": "この動画は、フルで見ると二時間ある。", "target_word": "フル", "complexity_tier": "T3", "furigana": "この動画[どうが]は、フルで見[み]ると二時間[にじかん]ある。", "sentence_source": "generated"}, {"text": "水道の蛇口をフルに開けると、水が勢いよく出た。", "target_word": "フル", "complexity_tier": "T3", "furigana": "水道[すいどう]の蛇口[じゃぐち]をフルに開[あ]けると、水[みず]が勢[いきお]いよく出[で]た。", "sentence_source": "generated"}, {"text": "今月は予定がフルで、休める日がない。", "target_word": "フル", "complexity_tier": "T3", "furigana": "今月[こんげつ]は予定[よてい]がフルで、休[やす]める日[ひ]がない。", "sentence_source": "generated"}, {"text": "彼女はその歌を、最初から最後までフルで歌った。", "target_word": "フル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はその歌[うた]を、最初[さいしょ]から最後[さいご]までフルで歌[うた]った。", "sentence_source": "generated"}, {"text": "部屋の照明をフルにしたら、まぶしかった。", "target_word": "フル", "complexity_tier": "T3", "furigana": "部屋[へや]の照明[しょうめい]をフルにしたら、まぶしかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フル", "label": "基本形"}, {"form": "フルに", "label": "に形"}, {"form": "フルで", "label": "で形"}], "register": "口語（常体）", "sense_fingerprint": "満タン・最大・省略なしの全部であるさま（フルで聞く・音量をフルにする）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: まぶしかっ (Zipf 1.88)']::text[], '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52511, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フル", "is_correct": true, "explanation": "「電池がフルになる」は、満タンになるという意味で自然。"}, {"text": "ダブル", "is_correct": false, "explanation": "二重を表すので、電池の状態を示す語としては合わない。"}, {"text": "ミニ", "is_correct": false, "explanation": "小さい規模を表すので、電池の状態を示す語としては合わない。"}, {"text": "ライト", "is_correct": false, "explanation": "軽い、薄いを表すので、電池の充電状態を示す語としては合わない。"}], "explanations": {"フル": "「電池がフルになる」は、満タンになるという意味で自然。", "ダブル": "二重を表すので、電池の状態を示す語としては合わない。", "ミニ": "小さい規模を表すので、電池の状態を示す語としては合わない。", "ライト": "軽い、薄いを表すので、電池の充電状態を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "フル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は貯金のフルを寄付した。", "explanation": "ここは〈全額〉の意味。フルは金額を表す名詞ではないので、貯金の全額を寄付する意味の表現としては合わない。"}, {"text": "彼女は荷物のフルを運んだ。", "explanation": "ここは〈全部〉の意味。フルは荷物の全体を指す名詞ではないので、「荷物の全部」の代わりには合わない。"}, {"text": "フルが集まった。", "explanation": "ここは〈全員〉の意味。「フル」は人の集まりを数える語ではないので、「全員が集まった」の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52511, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フル", "is_correct": true, "explanation": "「蛇口をフルに開ける」は、いっぱいまで開くという意味で自然。"}, {"text": "スーパー", "is_correct": false, "explanation": "すごいという形容語なので、蛇口の開け方を示す語としては合わない。"}, {"text": "ツイン", "is_correct": false, "explanation": "二つ組を表すので、蛇口の開け方を示す語としては合わない。"}, {"text": "シングル", "is_correct": false, "explanation": "単一を表すので、蛇口の開け方を示す語としては合わない。"}], "explanations": {"フル": "「蛇口をフルに開ける」は、いっぱいまで開くという意味で自然。", "スーパー": "すごいという形容語なので、蛇口の開け方を示す語としては合わない。", "ツイン": "二つ組を表すので、蛇口の開け方を示す語としては合わない。", "シングル": "単一を表すので、蛇口の開け方を示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "フル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋のフルを消して、勉強した。", "explanation": "ここは〈明かり〉の意味。フルは明かりを指す名詞ではないので、消す対象の代わりには合わない。"}, {"text": "明かりがフルに消えた。", "explanation": "ここは〈完全に〉の意味。「フル」は量がいっぱいの状態を表す語で、消え方を示す語としては合わない。"}, {"text": "フルが汗だくだ。", "explanation": "ここは〈全身〉の意味。「フル」は体の部分や人を指す語ではないので、「全身が汗だくだ」の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52511, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドラマを最後まで、フルを見た。", "corrected_sentence": "ドラマを最後まで、フルで見た。", "error_description": "「見る」の手段・方法は「で」で示す。「フルを」は誤りで、正しくは「フルで」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "フル", "is_correct": true, "explanation": "基本形の「フル」。満たされた状態・全部を表す語の原形で、この語の見出し形にあたる。"}, {"text": "フルの", "is_correct": false, "explanation": "「の」が続く形。「完全版でフルの聞きたい」は成り立たず、原形の答えにもならない。"}, {"text": "フルな", "is_correct": false, "explanation": "連体形。「フルな活躍」のように名詞を修飾する形で、原形を答える問いには合わない。"}, {"text": "フルだった", "is_correct": false, "explanation": "過去の断定の形。文末で状態を述べる形で、原形を答える問いには合わない。"}], "correct_form": "フル", "base_form": "フル", "form_label": "基本形", "sentence_index": 1, "explanations": {"フル": "基本形の「フル」。満たされた状態・全部を表す語の原形で、この語の見出し形にあたる。", "フルの": "「の」が続く形。「完全版でフルの聞きたい」は成り立たず、原形の答えにもならない。", "フルな": "連体形。「フルな活躍」のように名詞を修飾する形で、原形を答える問いには合わない。", "フルだった": "過去の断定の形。文末で状態を述べる形で、原形を答える問いには合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52511, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急な用事が入り、予定がフルにした。", "corrected_sentence": "急な用事が入り、予定がフルになった。", "error_description": "「フルになる」は自動詞の形。「フルにした」は他動詞の形で、主語の「予定が」と合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "フル", "is_correct": true, "explanation": "基本形の「フル」。見出し語そのもので、いっぱい・全部の意味を持つ原形。"}, {"text": "フルだ", "is_correct": false, "explanation": "断定の形。文末で状態を言い切る形で、原形を答える問いには合わない。"}, {"text": "フルの", "is_correct": false, "explanation": "「の」が続く形。原形ではないので、この問いの答えにはならない。"}, {"text": "フルではない", "is_correct": false, "explanation": "否定の形。「予定がフルではない」のように打ち消す語形で、原形を答える問いには合わない。"}], "correct_form": "フル", "base_form": "フル", "form_label": "基本形", "sentence_index": 7, "explanations": {"フル": "基本形の「フル」。見出し語そのもので、いっぱい・全部の意味を持つ原形。", "フルだ": "断定の形。文末で状態を言い切る形で、原形を答える問いには合わない。", "フルの": "「の」が続く形。原形ではないので、この問いの答えにはならない。", "フルではない": "否定の形。「予定がフルではない」のように打ち消す語形で、原形を答える問いには合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
