INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52512, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いっぱいであること。最大限であること。", "primary_collocate": null, "pronunciation": "ふる", "ipa": "ɸɯɾɯ", "syllable_count": 2, "sentences": [{"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "フル", "complexity_tier": "T3", "furigana": "教師[きょうし]の指示[しじ]のもと、静寂[せいじゃく]を保[たも]ちつつも頭脳[ずのう]をフル回転[かいてん]させる学習[がくしゅう]の時間[じかん]。", "sentence_source": "mined"}, {"text": "新しい工場は、休みなしでフルに稼働している。", "target_word": "フル", "complexity_tier": "T3", "furigana": "新しい工場[あたらしいこうじょう]は、休[やす]みなしでフルに稼働[かどう]している。", "sentence_source": "generated"}, {"text": "宿題を終えるため、残りの三日間は時間をフルに使った。", "target_word": "フル", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を終[お]えるため、残[のこ]りの三日間[みっかかん]は時間[じかん]をフルに使[つか]った。", "sentence_source": "generated"}, {"text": "このパソコンの性能をフルに発揮するには、電源をつなぐ必要がある。", "target_word": "フル", "complexity_tier": "T3", "furigana": "このパソコンの性能[せいのう]をフルに発揮[はっき]するには、電源[でんげん]をつなぐ必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "試合の最後、選手たちは体をフルに使って走り抜けた。", "target_word": "フル", "complexity_tier": "T3", "furigana": "試合[しあい]の最後[さいご]、選手[せんしゅ]たちは体[からだ]をフルに使[つか]って走り抜[はしりぬ]けた。", "sentence_source": "generated"}, {"text": "車はエンジンをフルに吹かして、急な山道を登った。", "target_word": "フル", "complexity_tier": "T3", "furigana": "車[くるま]はエンジンをフルに吹[ふ]かして、急[きゅう]な山道[やまみち]を登[のぼ]った。", "sentence_source": "generated"}, {"text": "母は忙しい週末でも、台所の道具をフルに活用する。", "target_word": "フル", "complexity_tier": "T3", "furigana": "母[はは]は忙[いそが]しい週末[しゅうまつ]でも、台所[だいどころ]の道具[どうぐ]をフルに活用[かつよう]する。", "sentence_source": "generated"}, {"text": "彼は今月、睡眠時間を削ってフルに働いている。", "target_word": "フル", "complexity_tier": "T3", "furigana": "彼[かれ]は今月[こんげつ]、睡眠[すいみん]時間[じかん]を削[けず]ってフルに働[はたら]いている。", "sentence_source": "generated"}, {"text": "締め切り前は、スタッフ全員がフルに動いた。", "target_word": "フル", "complexity_tier": "T3", "furigana": "締[し]め切[き]り前[まえ]は、スタッフ全員[ぜんいん]がフルに動[うご]いた。", "sentence_source": "generated"}, {"text": "暑い日は、エアコンをフルに効かせても部屋が冷えない。", "target_word": "フル", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、エアコンをフルに効[き]かせても部屋[へや]が冷[ひ]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フル", "label": "基本形"}, {"form": "フルに", "label": "に形"}, {"form": "フルな", "label": "連体形"}], "register": "口語（常体）", "sense_fingerprint": "力や時間、機能などを余すところなく最大限に使うさま（フル回転・フルに活用）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フル", "is_correct": true, "explanation": "「頭脳をフル回転させる」は、力を最大限に使う意味で自然。"}, {"text": "ゼロ", "is_correct": false, "explanation": "何もないことを表すので、「頭脳を回転させる」の前に置くと意味が成り立たない。"}, {"text": "ミニ", "is_correct": false, "explanation": "小さい規模を表すので、回転の程度を示す語としては合わない。"}, {"text": "ライト", "is_correct": false, "explanation": "軽い、薄いなどを表すので、回転の程度を示す語としては合わない。"}], "explanations": {"フル": "「頭脳をフル回転させる」は、力を最大限に使う意味で自然。", "ゼロ": "何もないことを表すので、「頭脳を回転させる」の前に置くと意味が成り立たない。", "ミニ": "小さい規模を表すので、回転の程度を示す語としては合わない。", "ライト": "軽い、薄いなどを表すので、回転の程度を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "フル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さでフルがかじかんだ。", "explanation": "ここは〈全身〉の意味。フルは「いっぱい・最大限」の意味で、体の部分を指す名詞としては使わないので、「全身」の代わりには合わない。"}, {"text": "昨日のことは、フルに忘れてしまった。", "explanation": "ここは〈完全に〉の意味。「フルに」は力や機能を最大限に使う意味で、「忘れる」とは合わない。"}, {"text": "寝坊したことを、フルで謝った。", "explanation": "ここは〈全力で〉の意味。「フル」は最大限に使う働きの表現で、謝り方の強さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フル", "is_correct": true, "explanation": "「台所の道具をフルに活用する」は、道具を最大限に使う意味で自然。"}, {"text": "ツイン", "is_correct": false, "explanation": "二つ組を表すので、道具の使い方を示す語としては合わない。"}, {"text": "シングル", "is_correct": false, "explanation": "単一を表すので、活用の程度を示す語としては合わない。"}, {"text": "ダブル", "is_correct": false, "explanation": "二重を表すので、活用の程度を示す語としては合わない。"}], "explanations": {"フル": "「台所の道具をフルに活用する」は、道具を最大限に使う意味で自然。", "ツイン": "二つ組を表すので、道具の使い方を示す語としては合わない。", "シングル": "単一を表すので、活用の程度を示す語としては合わない。", "ダブル": "二重を表すので、活用の程度を示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "フル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はフルを出し切って、試合に勝った。", "explanation": "ここは〈全力〉の意味。フルは「いっぱい・最大限」の状態を表す語で、力そのものを名詞として出すものではないので、「全力を出す」の代わりには合わない。"}, {"text": "りんごをフルに食べた。", "explanation": "ここは〈丸ごと〉の意味。「フル」は最大限に使う意味で、食べ方の丸ごとの意味とは合わない。"}, {"text": "子どものいたずらに、フルで怒った。", "explanation": "ここは〈本気で〉の意味。「フル」は最大限に使う働きの表現で、怒りの度合いは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は手を抜かず、能力をフルを発揮した。", "corrected_sentence": "彼は手を抜かず、能力をフルに発揮した。", "error_description": "形状詞「フル」は「を」を取らず、「発揮した」を修飾する副詞「フルに」にする。「フルを」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "フルに", "is_correct": true, "explanation": "「新しい工場はフルに稼働している」で、動詞「稼働している」を修飾する形。"}, {"text": "フルな", "is_correct": false, "explanation": "連体形は名詞を修飾するので、動詞「稼働している」を修飾できず文が成り立たない。"}, {"text": "フルだ", "is_correct": false, "explanation": "断定の形は述語なので、「稼働している」の前に置いて修飾することができない。"}, {"text": "フルでない", "is_correct": false, "explanation": "否定の述語は「稼働している」を修飾できず、「フルでない稼働している」は文が成り立たない。"}], "correct_form": "フルに", "base_form": "フル", "form_label": "に形", "sentence_index": 1, "explanations": {"フルに": "「新しい工場はフルに稼働している」で、動詞「稼働している」を修飾する形。", "フルな": "連体形は名詞を修飾するので、動詞「稼働している」を修飾できず文が成り立たない。", "フルだ": "断定の形は述語なので、「稼働している」の前に置いて修飾することができない。", "フルでない": "否定の述語は「稼働している」を修飾できず、「フルでない稼働している」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい機械は、性能をフルな引き出せる設定がある。", "corrected_sentence": "新しい機械は、性能をフルに引き出せる設定がある。", "error_description": "「引き出せる」を修飾する副詞の形は「フルに」。連体形「フルな」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "フルに", "is_correct": true, "explanation": "「睡眠時間を削ってフルに働いている」で、動詞「働いている」を修飾する形。"}, {"text": "フル", "is_correct": false, "explanation": "基本形は動詞を直接修飾できず、「フル働いている」は文が成り立たない。"}, {"text": "フルな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、動詞「働いている」を修飾できず文が成り立たない。"}, {"text": "フルじゃない", "is_correct": false, "explanation": "否定の述語は「働いている」を修飾できず、文が成り立たない。"}], "correct_form": "フルに", "base_form": "フル", "form_label": "に形", "sentence_index": 7, "explanations": {"フルに": "「睡眠時間を削ってフルに働いている」で、動詞「働いている」を修飾する形。", "フル": "基本形は動詞を直接修飾できず、「フル働いている」は文が成り立たない。", "フルな": "連体形。名詞を修飾する形で、動詞「働いている」を修飾できず文が成り立たない。", "フルじゃない": "否定の述語は「働いている」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「養分が少ない」で、主語として状態を述べるため正解。"}, {"text": "で", "is_correct": false, "explanation": "「養分で少ない」は手段や場所を表し、状態を述べる文として成り立たないため不適。"}, {"text": "に", "is_correct": false, "explanation": "「養分に少ない」は方向や結果を示し、状態を述べる文として成り立たないため不適。"}, {"text": "へ", "is_correct": false, "explanation": "「養分へ少ない」は方向を示し、状態を述べる文として成り立たないため不適。"}], "correct_answer": "が", "explanations": {"が": "「養分が少ない」で、主語として状態を述べるため正解。", "で": "「養分で少ない」は手段や場所を表し、状態を述べる文として成り立たないため不適。", "に": "「養分に少ない」は方向や結果を示し、状態を述べる文として成り立たないため不適。", "へ": "「養分へ少ない」は方向を示し、状態を述べる文として成り立たないため不適。"}, "error_tags": {"で": "手段・場所の格助詞", "に": "方向・結果の格助詞", "へ": "方向の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「溶けた養分を運んでいる」で、運ばれる対象を示すため正解。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示し、運ぶ対象を表せないため不適。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示し、運ぶ対象を表せないため不適。"}, {"text": "が", "is_correct": false, "explanation": "「養分が」は主語を示すが、「茎が運んでいる」と主語が重なり文として成り立たないため不適。"}], "correct_answer": "を", "explanations": {"を": "「溶けた養分を運んでいる」で、運ばれる対象を示すため正解。", "より": "「より」は比較や起点を示し、運ぶ対象を表せないため不適。", "の": "「の」は連体修飾を示し、運ぶ対象を表せないため不適。", "が": "「養分が」は主語を示すが、「茎が運んでいる」と主語が重なり文として成り立たないため不適。"}, "error_tags": {"より": "比較・起点の格助詞", "の": "連体修飾の格助詞", "が": "主語の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物や植物が育つのに必要なもの。", "primary_collocate": null, "pronunciation": "ようぶん", "ipa": "joːbɯɴ", "syllable_count": 4, "sentences": [{"text": "植物は根から土の養分を吸い上げて育つ。", "target_word": "養分", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は根[ね]から土[つち]の養分[ようぶん]を吸[す]い上[あ]げて育[そだ]つ。", "sentence_source": "generated"}, {"text": "この土は養分が少ないので、肥料を入れた。", "target_word": "養分", "complexity_tier": "T3", "furigana": "この土[つち]は養分[ようぶん]が少[すく]ないので、肥料[ひりょう]を入[い]れた。", "sentence_source": "generated"}, {"text": "雨が少なく、畑の作物に十分な養分が届かなかった。", "target_word": "養分", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なく、畑[はたけ]の作物[さくもつ]に十分[じゅうぶん]な養分[ようぶん]が届[とど]かなかった。", "sentence_source": "generated"}, {"text": "赤ちゃんは母乳から成長に必要な養分をとっている。", "target_word": "養分", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは母乳[ぼにゅう]から成長[せいちょう]に必要[ひつよう]な養分[ようぶん]をとっている。", "sentence_source": "generated"}, {"text": "落ち葉が腐ると、土に養分がもどる。", "target_word": "養分", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]が腐[くさ]ると、土[つち]に養分[ようぶん]がもどる。", "sentence_source": "generated"}, {"text": "養分をたっぷり含んだ土で、トマトが大きく育った。", "target_word": "養分", "complexity_tier": "T3", "furigana": "養分[ようぶん]をたっぷり含[ふく]んだ土[つち]で、トマトが大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "木が枯れたのは、根が傷んで養分を運べなくなったからだ。", "target_word": "養分", "complexity_tier": "T3", "furigana": "木[き]が枯[か]れたのは、根[ね]が傷[いた]んで養分[ようぶん]を運[はこ]べなくなったからだ。", "sentence_source": "generated"}, {"text": "水に溶けた養分を、葉の先まで茎が運んでいる。", "target_word": "養分", "complexity_tier": "T3", "furigana": "水[みず]に溶[と]けた養分[ようぶん]を、葉[は]の先[さき]まで茎[くき]が運[はこ]んでいる。", "sentence_source": "generated"}, {"text": "池に肥料が流れこむと、藻が養分を得て急に増える。", "target_word": "養分", "complexity_tier": "T3", "furigana": "池[いけ]に肥料[ひりょう]が流[なが]れこむと、藻[も]が養分[ようぶん]を得[え]て急[きゅう]に増[ふ]える。", "sentence_source": "generated"}, {"text": "毎日の食事で、体に必要な養分をバランスよくとろう。", "target_word": "養分", "complexity_tier": "T3", "furigana": "毎日[まいにち]の食事[しょくじ]で、体[からだ]に必要[ひつよう]な養分[ようぶん]をバランスよくとろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養分", "label": "基本形"}, {"form": "養分を", "label": "を格"}, {"form": "養分が", "label": "が格"}], "register": "標準（話し言葉・書き言葉とも可）", "sense_fingerprint": "実際の養分。土・水・食べ物などから植物や動物が取り込む栄養分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "養分", "is_correct": true, "explanation": "「土の〜を吸い上げる」で、植物が取り込む栄養分を表すため正解。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える部品で、土から吸い上げるものではないため不適。"}, {"text": "家具", "is_correct": false, "explanation": "室内に置く道具で、土から吸い上げることはできないため不適。"}, {"text": "機械", "is_correct": false, "explanation": "動力で動く装置で、植物が土から吸い上げる対象にはならないため不適。"}], "explanations": {"養分": "「土の〜を吸い上げる」で、植物が取り込む栄養分を表すため正解。", "電池": "電気を蓄える部品で、土から吸い上げるものではないため不適。", "家具": "室内に置く道具で、土から吸い上げることはできないため不適。", "機械": "動力で動く装置で、植物が土から吸い上げる対象にはならないため不適。"}, "sentence_index": 0, "correct_answer": "養分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は養分で動く。", "explanation": "養分（栄養）の意味では機械の動力にならず、機械は動かせないので不適。"}, {"text": "エレベーターの養分を押した。", "explanation": "押せるのはボタンなどで、養分（栄養）は押す対象にならないので不適。"}, {"text": "庭の隅に養分を並べて、花壇を作った。", "explanation": "花壇の材料として並べるのは石などで、養分（栄養）は並べる対象にならないので不適。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "養分", "is_correct": true, "explanation": "「根が傷んで〜を運べなくなった」で、植物の体内を運ばれる栄養分を表すため正解。"}, {"text": "玩具", "is_correct": false, "explanation": "子どもが遊ぶ道具で、植物の根が運ぶものではないため不適。"}, {"text": "石鹸", "is_correct": false, "explanation": "体や物を洗う製品で、根が運ぶものではないため文意に合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "視力を補う道具で、植物の根が運ぶものではないため不適。"}], "explanations": {"養分": "「根が傷んで〜を運べなくなった」で、植物の体内を運ばれる栄養分を表すため正解。", "玩具": "子どもが遊ぶ道具で、植物の根が運ぶものではないため不適。", "石鹸": "体や物を洗う製品で、根が運ぶものではないため文意に合わない。", "眼鏡": "視力を補う道具で、植物の根が運ぶものではないため不適。"}, "sentence_index": 6, "correct_answer": "養分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙に養分を書く。", "explanation": "紙に書けるのは文字で、養分（栄養）は書けないので不適。"}, {"text": "玄関の養分を開ける。", "explanation": "開けるのは扉や鍵で、養分（栄養）は開ける対象にならないので不適。"}, {"text": "服の汚れを落とすため、養分を入れて洗濯機を回す。", "explanation": "汚れを落とすのは洗剤で、養分（栄養）では服の汚れは落ちないので不適。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この木は根から土の養分に吸い取って育つ。", "corrected_sentence": "この木は根から土の養分を吸い取って育つ。", "error_description": "「吸い取る」は対象を「を」で示す。「養分に」は誤りで、正しくは「養分を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "根は土から養分を吐き出す。", "corrected_sentence": "根は土から養分を吸い上げる。", "error_description": "「養分を」と結びつく動詞は「吸い上げる」。「吐き出す」は合わないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
