INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「養分になる」で、変化の結果の相手を示すため正解。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すが、「なった」の補語にはならないため不適。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示し、「なった」の補語としては成り立たないため不適。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示し、「なった」の補語にはならないため不適。"}], "correct_answer": "に", "explanations": {"に": "「養分になる」で、変化の結果の相手を示すため正解。", "へ": "「へ」は向かう先を示すが、「なった」の補語にはならないため不適。", "より": "「より」は比較や起点を示し、「なった」の補語としては成り立たないため不適。", "の": "「の」は連体修飾を示し、「なった」の補語にはならないため不適。"}, "error_tags": {"へ": "方向の格助詞", "より": "比較・起点の格助詞", "の": "連体修飾の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物が成長するために必要な栄養や、物事を発展させるための材料。", "primary_collocate": null, "pronunciation": "ようぶん", "ipa": "joːbɯɴ", "syllable_count": 4, "sentences": [{"text": "その一つひとつの動作が、彼女の認知能力と社会性を育む養分となる。", "target_word": "養分", "complexity_tier": "T4", "furigana": "その一[ひと]つひとつの動作[どうさ]が、彼女[かのじょ]の認知能力[にんちのうりょく]と社会性[しゃかいせい]を育[はぐく]む養分[ようぶん]となる。", "sentence_source": "mined"}, {"text": "失敗の経験は、次の挑戦に向かう私にとって大切な養分になった。", "target_word": "養分", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の経験[けいけん]は、次[つぎ]の挑戦[ちょうせん]に向[む]かう私[わたし]にとって大切[たいせつ]な養分[ようぶん]になった。", "sentence_source": "generated"}, {"text": "読書で得た知識は、心を豊かにする養分だと思う。", "target_word": "養分", "complexity_tier": "T3", "furigana": "読書[どくしょ]で得[え]た知識[ちしき]は、心[こころ]を豊[ゆた]かにする養分[ようぶん]だと思[おも]う。", "sentence_source": "generated"}, {"text": "彼は先輩の厳しい言葉さえ養分にして、大きく成長した。", "target_word": "養分", "complexity_tier": "T3", "furigana": "彼[かれ]は先輩[せんぱい]の厳[きび]しい言葉[ことば]さえ養分[ようぶん]にして、大[おお]きく成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "多くの人との出会いが、作家としての彼女の養分となっている。", "target_word": "養分", "complexity_tier": "T3", "furigana": "多[おお]くの人[ひと]との出会[であ]いが、作家[さっか]としての彼女[かのじょ]の養分[ようぶん]となっている。", "sentence_source": "generated"}, {"text": "地域の伝統文化は、新しい芸術を生み出す養分でもある。", "target_word": "養分", "complexity_tier": "T3", "furigana": "地域[ちいき]の伝統文化[でんとうぶんか]は、新[あたら]しい芸術[げいじゅつ]を生[う]み出[だ]す養分[ようぶん]でもある。", "sentence_source": "generated"}, {"text": "悔しさを養分にできる人は、負けてもすぐに立ち直る。", "target_word": "養分", "complexity_tier": "T3", "furigana": "悔[くや]しさを養分[ようぶん]にできる人[ひと]は、負[ま]けてもすぐに立[た]ち直[なお]る。", "sentence_source": "generated"}, {"text": "旅で見た景色が、この小説を育てる養分になった。", "target_word": "養分", "complexity_tier": "T3", "furigana": "旅[たび]で見[み]た景色[けしき]が、この小説[しょうせつ]を育[そだ]てる養分[ようぶん]になった。", "sentence_source": "generated"}, {"text": "批判を養分に変えて、会社は新製品を作り上げた。", "target_word": "養分", "complexity_tier": "T3", "furigana": "批判[ひはん]を養分[ようぶん]に変[か]えて、会社[かいしゃ]は新製品[しんせいひん]を作[つく]り上[あ]げた。", "sentence_source": "generated"}, {"text": "若い時の苦労は、のちの人生の養分になると祖父は言った。", "target_word": "養分", "complexity_tier": "T3", "furigana": "若[わか]い時[とき]の苦労[くろう]は、のちの人生[じんせい]の養分[ようぶん]になると祖父[そふ]は言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養分", "label": "基本形"}, {"form": "養分に", "label": "に格"}, {"form": "養分と", "label": "と格"}], "register": "標準（書き言葉寄り）", "sense_fingerprint": "比喩的な養分。経験・知識・出会いなど、人や物事を成長・発展させる材料。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "養分", "is_correct": true, "explanation": "「育む」の目的語で、社会性などを育てる材料を表し、「〜となる」ともつながるため正解。"}, {"text": "反発", "is_correct": false, "explanation": "押し返す力や抵抗を指し、人の能力や社会性を育てる材料にはならないため不適。"}, {"text": "日程", "is_correct": false, "explanation": "予定の順序を指す語で、認知能力を育てる材料にはならないため不適。"}, {"text": "税金", "is_correct": false, "explanation": "国や自治体に納める金銭を指し、能力を育てる材料ではないため文意に合わない。"}], "explanations": {"養分": "「育む」の目的語で、社会性などを育てる材料を表し、「〜となる」ともつながるため正解。", "反発": "押し返す力や抵抗を指し、人の能力や社会性を育てる材料にはならないため不適。", "日程": "予定の順序を指す語で、認知能力を育てる材料にはならないため不適。", "税金": "国や自治体に納める金銭を指し、能力を育てる材料ではないため文意に合わない。"}, "sentence_index": 0, "correct_answer": "養分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は養分が豊富で、どんな機械でも直してしまう。", "explanation": "機械を直す腕前は技術で、養分（栄養）では表せないので不適。"}, {"text": "三年前、彼女は親戚の家の養分に迎えられた。", "explanation": "家に迎えられるのは人であり、養分（栄養）は人を表さないので不適。"}, {"text": "この車は養分を入れれば、どこまでも走れる。", "explanation": "車を走らせるのは燃料で、養分（栄養）では走らせられないので不適。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "養分", "is_correct": true, "explanation": "「悔しさを〜にできる」で、立ち直る力の材料を表すため正解。"}, {"text": "費用", "is_correct": false, "explanation": "お金の支払いを指し、悔しさを材料にするという文脈には合わないため不適。"}, {"text": "予定", "is_correct": false, "explanation": "日時の計画を指し、立ち直る力の材料にはならないため不適。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具で、悔しさを材料にできるという文意に合わないため不適。"}], "explanations": {"養分": "「悔しさを〜にできる」で、立ち直る力の材料を表すため正解。", "費用": "お金の支払いを指し、悔しさを材料にするという文脈には合わないため不適。", "予定": "日時の計画を指し、立ち直る力の材料にはならないため不適。", "寝具": "寝るための道具で、悔しさを材料にできるという文意に合わないため不適。"}, "sentence_index": 6, "correct_answer": "養分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は歴史の養分が豊富で、質問にすぐ答える。", "explanation": "質問に答えられるのは知識で、養分（栄養）では答えられないので不適。"}, {"text": "パソコンの養分を交換した。", "explanation": "交換するのは部品で、養分（栄養）は交換できる物ではないので不適。"}, {"text": "大会で優勝して、養分のメダルを首にかけた。", "explanation": "首にかけるのはメダルで、養分（栄養）は首にかけられる物ではないので不適。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その言葉は、私の成長の養分をなった。", "corrected_sentence": "その言葉は、私の成長の養分になった。", "error_description": "「なる」は「に」を伴う。「養分を」は誤りで、正しくは「養分に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "読書は、心を豊かに育ぶ養分だ。", "corrected_sentence": "読書は、心を豊かに育む養分だ。", "error_description": "正しい形は「育む」。「育ぶ」という動詞はないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「勇気がある人」の「が」。勇気を持っている、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は「が」と結びつくので、「勇気をある人」とは言えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「勇気にある人」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「勇気とある人」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「勇気がある人」の「が」。勇気を持っている、という意味になる。", "を": "「ある」は「が」と結びつくので、「勇気をある人」とは言えない。", "に": "「に」は場所や相手を示すが、「勇気にある人」は意味が通らない。", "と": "「と」は並列や相手を示すが、「勇気とある人」は不自然。"}, "error_tags": {"を": "対象", "に": "帰着・存在の場所", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "臆病", "is_correct": true, "explanation": "勇気の対義語。こわいことから逃げてしまう気持ちを表し、勇気と反対になる。"}, {"text": "親切", "is_correct": false, "explanation": "人にやさしくすることを表す語で、勇気の反対語ではない。"}, {"text": "正直", "is_correct": false, "explanation": "うそをつかないことを表す語で、勇気の反対語にはならない。"}, {"text": "元気", "is_correct": false, "explanation": "体や心が元気なことを表す語で、勇気の反対語ではない。"}], "correct_answer": "臆病", "explanations": {"臆病": "勇気の対義語。こわいことから逃げてしまう気持ちを表し、勇気と反対になる。", "親切": "人にやさしくすることを表す語で、勇気の反対語ではない。", "正直": "うそをつかないことを表す語で、勇気の反対語にはならない。", "元気": "体や心が元気なことを表す語で、勇気の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「勇気がいる」の「が」。勇気が必要だ、という意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」だが、「勇気へいる」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」だが、「勇気からいる」とは言えない。"}, {"text": "より", "is_correct": false, "explanation": "比べる意味の「より」だが、「勇気よりいる」は文の意味に合わない。"}], "correct_answer": "が", "explanations": {"が": "「勇気がいる」の「が」。勇気が必要だ、という意味になる。", "へ": "方向を示す「へ」だが、「勇気へいる」は意味が通らない。", "から": "起点を示す「から」だが、「勇気からいる」とは言えない。", "より": "比べる意味の「より」だが、「勇気よりいる」は文の意味に合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "臆病", "is_correct": true, "explanation": "勇気の対義語。こわくて前に出られない気持ちを表し、勇気と反対になる。"}, {"text": "熱意", "is_correct": false, "explanation": "物事に打ち込む強い気持ちを表す語で、勇気の反対語ではない。"}, {"text": "誠意", "is_correct": false, "explanation": "真心を表す語で、勇気の反対語にはならない。"}, {"text": "感謝", "is_correct": false, "explanation": "ありがたく思う気持ちを表す語で、勇気の反対語ではない。"}], "correct_answer": "臆病", "explanations": {"臆病": "勇気の対義語。こわくて前に出られない気持ちを表し、勇気と反対になる。", "熱意": "物事に打ち込む強い気持ちを表す語で、勇気の反対語ではない。", "誠意": "真心を表す語で、勇気の反対語にはならない。", "感謝": "ありがたく思う気持ちを表す語で、勇気の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "こわいことやむずかしいことがあっても、それをがんばってやろうとする気持ちのこと。", "primary_collocate": null, "pronunciation": "ゆうき", "ipa": "jɯːki", "syllable_count": 3, "sentences": [{"text": "犬がこわかったけれど、勇気を出してなでてみた。", "target_word": "勇気", "complexity_tier": "T2", "furigana": "犬[いぬ]がこわかったけれど、勇気[ゆうき]を出[だ]してなでてみた。", "sentence_source": "generated"}, {"text": "勇気がある人は、こわくてもあきらめない。", "target_word": "勇気", "complexity_tier": "T2", "furigana": "勇気[ゆうき]がある人[ひと]は、こわくてもあきらめない。", "sentence_source": "generated"}, {"text": "先生に質問する勇気がなくて、ずっと黙っていた。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "先生[せんせい]に質問[しつもん]する勇気[ゆうき]がなくて、ずっと黙[だま]っていた。", "sentence_source": "generated"}, {"text": "一人でお使いに行けた弟は、とても勇気があると思う。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "一人[ひとり]でお使[つか]いに行[い]けた弟[おとうと]は、とても勇気[ゆうき]があると思[おも]う。", "sentence_source": "generated"}, {"text": "高いすべり台から、勇気を出してすべった。", "target_word": "勇気", "complexity_tier": "T2", "furigana": "高[たか]いすべり台[だい]から、勇気[ゆうき]を出[だ]してすべった。", "sentence_source": "generated"}, {"text": "友だちにごめんねと言う勇気が、なかなか出なかった。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "友[とも]だちにごめんねと言[い]う勇気[ゆうき]が、なかなか出[で]なかった。", "sentence_source": "generated"}, {"text": "注射がこわいけれど、勇気をふりしぼってがまんした。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "注射[ちゅうしゃ]がこわいけれど、勇気[ゆうき]をふりしぼってがまんした。", "sentence_source": "generated"}, {"text": "みんなの前で歌うのは勇気がいる。", "target_word": "勇気", "complexity_tier": "T2", "furigana": "みんなの前[まえ]で歌[うた]うのは勇気[ゆうき]がいる。", "sentence_source": "generated"}, {"text": "絵本の主人公は、勇気を出してドラゴンに立ち向かった。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "絵本[えほん]の主人公[しゅじんこう]は、勇気[ゆうき]を出[だ]してドラゴンに立[た]ち向[む]かった。", "sentence_source": "generated"}, {"text": "お母さんの「だいじょうぶ」の声で、勇気がわいてきた。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "お母[かあ]さんの「だいじょうぶ」の声[こえ]で、勇気[ゆうき]がわいてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勇気", "label": "基本形"}, {"form": "勇気を", "label": "を格"}, {"form": "勇気が", "label": "が格"}], "register": "平易（子ども向けの話し言葉）", "sense_fingerprint": "こわさや難しさに負けず、がんばってやってみようとする気持ち。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: すべり台 (Zipf 2.43)','sentence 6 above tier T2: contains vocabulary far above tier T2: ふりしぼっ (Zipf 1.46)']::text[], '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勇気", "is_correct": true, "explanation": "「勇気を出して」で、こわさに負けず行動する気持ちを表す。文の意味に合う。"}, {"text": "平和", "is_correct": false, "explanation": "争いがない状態を表す語で、「平和を出して」とは言わない。"}, {"text": "自由", "is_correct": false, "explanation": "しばられないことを表す語で、「自由を出して」は不自然で意味が通らない。"}, {"text": "友情", "is_correct": false, "explanation": "友だちとの心のつながりを表す語で、「友情を出して」とは言えない。"}], "explanations": {"勇気": "「勇気を出して」で、こわさに負けず行動する気持ちを表す。文の意味に合う。", "平和": "争いがない状態を表す語で、「平和を出して」とは言わない。", "自由": "しばられないことを表す語で、「自由を出して」は不自然で意味が通らない。", "友情": "友だちとの心のつながりを表す語で、「友情を出して」とは言えない。"}, "sentence_index": 0, "correct_answer": "勇気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い箱をみんなで勇気を合わせて運んだ。", "explanation": "勇気は一人の心の強さを指し、人と合わせて重い物を運ぶものではない。"}, {"text": "お母さんは勇気の野菜を選んで買う。", "explanation": "ここは〈有機〉（化学肥料を使わない）の意味。同じ読みの別の語で、勇気は野菜の種類を表さない。"}, {"text": "先生の勇気をよく聞いてください。", "explanation": "勇気は聞くものではないので、「聞く」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇気", "is_correct": true, "explanation": "「勇気をふりしぼって」で、こわさに立ち向かう心の力を表す。文の意味に合う。"}, {"text": "約束", "is_correct": false, "explanation": "前もって決めて守ることを表す語で、「約束をふりしぼる」とは言わない。"}, {"text": "思い出", "is_correct": false, "explanation": "過去の出来事を覚えていることを表す語で、「思い出をふりしぼる」は意味が通らない。"}, {"text": "笑顔", "is_correct": false, "explanation": "にっこりした顔を表す語で、「笑顔をふりしぼる」は不自然。"}], "explanations": {"勇気": "「勇気をふりしぼって」で、こわさに立ち向かう心の力を表す。文の意味に合う。", "約束": "前もって決めて守ることを表す語で、「約束をふりしぼる」とは言わない。", "思い出": "過去の出来事を覚えていることを表す語で、「思い出をふりしぼる」は意味が通らない。", "笑顔": "にっこりした顔を表す語で、「笑顔をふりしぼる」は不自然。"}, "sentence_index": 6, "correct_answer": "勇気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合前の円陣で、キャプテンは大声で勇気を入れた。", "explanation": "勇気は心の強さで、入れるものではない。"}, {"text": "運動のあとは、勇気をふいて休むといい。", "explanation": "ふくものは汗などで、勇気はふけるものではない。"}, {"text": "友だちに勇気をかけて、いっしょに帰った。", "explanation": "勇気は人にかけるものではないので、「声をかける」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ぼくは勇気が出して、高い木に登った。", "corrected_sentence": "ぼくは勇気を出して、高い木に登った。", "error_description": "「勇気を出す」の「勇気」に付く助詞は「を」。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ぼくは勇気を出させて、川を渡った。", "corrected_sentence": "ぼくは勇気を出して、川を渡った。", "error_description": "自分で勇気を出す場面なので、使役の「出させて」は誤り。正しくは「出して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
