INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52516, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "危険や困難を恐れずに、自分の信念や正しいと思うことに向かって進む心の力。", "primary_collocate": null, "pronunciation": "ゆうき", "ipa": "jɯːki", "syllable_count": 3, "sentences": [{"text": "親である私にできるのは、その勇気ある第一歩を、ただ静かに、そして確かな祈りを込めて見守ることだけだ。", "target_word": "勇気", "complexity_tier": "T4", "furigana": "親[おや]である私[わたし]にできるのは、その勇気[ゆうき]ある第一歩[だいいっぽ]を、ただ静[しず]かに、そして確[たし]かな祈[いの]りを込[こ]めて見守[みまも]ることだけだ。", "sentence_source": "mined"}, {"text": "彼は不正を告発する勇気を持っていた。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "彼[かれ]は不正[ふせい]を告発[こくはつ]する勇気[ゆうき]を持[も]っていた。", "sentence_source": "generated"}, {"text": "失敗を恐れずに挑戦する勇気こそ、若者に必要なものだ。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を恐[おそ]れずに挑戦[ちょうせん]する勇気[ゆうき]こそ、若者[わかもの]に必要[ひつよう]なものだ。", "sentence_source": "generated"}, {"text": "彼女は周囲の反対に負けず、自分の意見を述べる勇気を示した。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は周囲[しゅうい]の反対[はんたい]に負[ま]けず、自分[じぶん]の意見[いけん]を述[の]べる勇気[ゆうき]を示[しめ]した。", "sentence_source": "generated"}, {"text": "危険な火災現場に入った消防士の勇気に、市民は感謝した。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "危険[きけん]な火災現場[かさいげんば]に入[はい]った消防士[しょうぼうし]の勇気[ゆうき]に、市民[しみん]は感謝[かんしゃ]した。", "sentence_source": "generated"}, {"text": "本当のことを話すには、大きな勇気が要る。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "本当[ほんとう]のことを話[はな]すには、大[おお]きな勇気[ゆうき]が要[い]る。", "sentence_source": "generated"}, {"text": "彼の勇気ある行動が、多くの人を救った。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "彼[かれ]の勇気[ゆうき]ある行動[こうどう]が、多[おお]くの人[ひと]を救[すく]った。", "sentence_source": "generated"}, {"text": "間違いを認めて謝るのは、勇気のいることだ。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "間違[まちが]いを認[みと]めて謝[あやま]るのは、勇気[ゆうき]のいることだ。", "sentence_source": "generated"}, {"text": "長年の夢を追うため、会社を辞める勇気がやっと湧いた。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "長年[ながねん]の夢[ゆめ]を追[お]うため、会社[かいしゃ]を辞[や]める勇気[ゆうき]がやっと湧[わ]いた。", "sentence_source": "generated"}, {"text": "友人の励ましが、再び立ち上がる勇気をくれた。", "target_word": "勇気", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の励[はげ]ましが、再[ふたた]び立[た]ち上[あ]がる勇気[ゆうき]をくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勇気", "label": "基本形"}, {"form": "勇気ある", "label": "連体修飾"}, {"form": "勇気を", "label": "を格"}], "register": "標準（やや硬い書き言葉）", "sense_fingerprint": "信念や正義のために、危険や困難を恐れず行動する心の強さ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 長年の夢 (Zipf 2.36)']::text[], '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勇気", "is_correct": true, "explanation": "「勇気ある第一歩」で、危険や困難を恐れず踏み出す心の力を表す。文の意味に合う。"}, {"text": "期限", "is_correct": false, "explanation": "「期限ある第一歩」とは言えず、時間の区切りを表す語なので、文の意味に合わない。"}, {"text": "誤差", "is_correct": false, "explanation": "測定上のずれを表す語で、「誤差ある第一歩」は意味が通らない。"}, {"text": "雑音", "is_correct": false, "explanation": "音の混じりを表す語で、人が踏み出す一歩を修飾する意味にならない。"}], "explanations": {"勇気": "「勇気ある第一歩」で、危険や困難を恐れず踏み出す心の力を表す。文の意味に合う。", "期限": "「期限ある第一歩」とは言えず、時間の区切りを表す語なので、文の意味に合わない。", "誤差": "測定上のずれを表す語で、「誤差ある第一歩」は意味が通らない。", "雑音": "音の混じりを表す語で、人が踏み出す一歩を修飾する意味にならない。"}, "sentence_index": 0, "correct_answer": "勇気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三時間目になると、勇気が切れて集中できなくなる。", "explanation": "気力は使うと減って切れるものだが、勇気は危険や困難に立ち向かう心の力で、集中力の低下には使わない。"}, {"text": "この店は勇気栽培のトマトだけを扱っている。", "explanation": "ここは〈有機〉（化学肥料や農薬を使わない）の意味。同じ読みの別の語で、勇気（心の強さ）は栽培方法を表さない。"}, {"text": "社長は勇気を下し、工場の閉鎖を決めた。", "explanation": "決断は下すものだが、勇気は決断として下すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
